INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39750, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが正しいかどうかを調べることです。", "primary_collocate": null, "pronunciation": "てすと", "ipa": "tesɯto", "syllable_count": 3, "sentences": [{"text": "明日は数学のテストがあるので、今夜は勉強します。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "明日[あした]は数学[すうがく]のテストがあるので、今夜[こんや]は勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "テストで間違えた問題を、先生と一緒に直しました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "テストで間違[まちが]えた問題[もんだい]を、先生[せんせい]と一緒[いっしょ]に直[なお]しました。", "sentence_source": "generated"}, {"text": "漢字のテストで百点を取って、母が喜びました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "漢字[かんじ]のテストで百点[ひゃくてん]を取[と]って、母[はは]が喜[よろこ]びました。", "sentence_source": "generated"}, {"text": "テストの結果が悪かったので、少し落ち込んでいます。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "テストの結果[けっか]が悪[わる]かったので、少[すこ]し落[お]ち込[こ]んでいます。", "sentence_source": "generated"}, {"text": "先生はテストを配る前に、名前を書くように言いました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "先生[せんせい]はテストを配[くば]る前[まえ]に、名前[なまえ]を書[か]くように言[い]いました。", "sentence_source": "generated"}, {"text": "毎週金曜日に、英語の小さなテストがあります。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]金曜日[きんようび]に、英語[えいご]の小[ちい]さなテストがあります。", "sentence_source": "generated"}, {"text": "テストの前の日は、早く寝るようにしています。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "テストの前[まえ]の日[ひ]は、早[はや]く寝[ね]るようにしています。", "sentence_source": "generated"}, {"text": "このテストで、自分の答えが正しいかどうかが分かります。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "このテストで、自分[じぶん]の答[こた]えが正[ただ]しいかどうかが分[わ]かります。", "sentence_source": "generated"}, {"text": "テストの間は、隣の人と話してはいけません。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "テストの間[あいだ]は、隣[となり]の人[ひと]と話[はな]してはいけません。", "sentence_source": "generated"}, {"text": "来週のテストの範囲を、友達と確認しました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "来週[らいしゅう]のテストの範囲[はんい]を、友達[ともだち]と確認[かくにん]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テスト", "label": "基本形"}, {"form": "テストする", "label": "サ変動詞形"}], "register": "丁寧", "sense_fingerprint": "答えや内容が正しいかを調べる試験・確認としてのテスト", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39750, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テスト", "is_correct": true, "explanation": "「数学のテスト」として、試験の予定を表す正解。"}, {"text": "ドライブ", "is_correct": false, "explanation": "「数学のドライブ」は文として成り立たず、試験の意味が入らない。"}, {"text": "パーティー", "is_correct": false, "explanation": "「数学のパーティー」は不自然で、勉強が必要な予定という文脈に合わない。"}, {"text": "ペット", "is_correct": false, "explanation": "「数学のペット」は意味が通らず、空欄に入らない。"}], "explanations": {"テスト": "「数学のテスト」として、試験の予定を表す正解。", "ドライブ": "「数学のドライブ」は文として成り立たず、試験の意味が入らない。", "パーティー": "「数学のパーティー」は不自然で、勉強が必要な予定という文脈に合わない。", "ペット": "「数学のペット」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "テスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝三十分テストをして、ピアノの指使いが上手になった。", "explanation": "ここは〈練習〉の意味。テストは正誤を調べる試験のことで、繰り返して腕を磨く意味では使わない。"}, {"text": "誕生日の部屋を、ふうせんでテストして、いっぱいに飾った。", "explanation": "ここは〈飾り付け〉の意味。テストは正誤や状態を調べる行為で、部屋を飾る意味では使わない。"}, {"text": "夕食のため、レストランをテストしてから電話した。", "explanation": "ここは〈予約〉の意味。テストは内容の正誤を調べることで、店を押さえる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39750, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テスト", "is_correct": true, "explanation": "「テストの前の日」として、試験の前日を表す正解。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "「ハンカチの前の日」は意味が通らず、空欄に入らない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "「ケーキの前の日」は文脈に合わず、早く寝る理由にならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫の前の日」は不自然で、文の意味が成り立たない。"}], "explanations": {"テスト": "「テストの前の日」として、試験の前日を表す正解。", "ハンカチ": "「ハンカチの前の日」は意味が通らず、空欄に入らない。", "ケーキ": "「ケーキの前の日」は文脈に合わず、早く寝る理由にならない。", "冷蔵庫": "「冷蔵庫の前の日」は不自然で、文の意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "テスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日、庭の花をテストして、成長を記録した。", "explanation": "ここは〈観察〉の意味。テストは正誤を調べる試験で、植物の変化を見守る意味では使わない。"}, {"text": "引っ越しの前に、古い本をテストして、棚に分けた。", "explanation": "ここは〈整理〉の意味。テストは試験や確認のことで、物を分類する意味では使わない。"}, {"text": "贈り物を一つずつテストして、きれいに包んだ。", "explanation": "ここは〈包装〉の意味。テストは内容を確かめる行為で、物を包む意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39750, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日のテストに間違えた所を、先生に聞きました。", "corrected_sentence": "昨日のテストで間違えた所を、先生に聞きました。", "error_description": "「間違える」は「テストで間違える」と場面を表す「で」で続ける。「に」は誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
