INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39751, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の性能や状態を調べて、評価すること。", "primary_collocate": null, "pronunciation": "てすと", "ipa": "tesɯto", "syllable_count": 3, "sentences": [{"text": "新しいスマホが水に強いか、工場でテストしています。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "新[あたら]しいスマホが水[みず]に強[つよ]いか、工場[こうじょう]でテストしています。", "sentence_source": "generated"}, {"text": "発売の前に、車の安全性をテストします。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "発売[はつばい]の前[まえ]に、車[くるま]の安全性[あんぜんせい]をテストします。", "sentence_source": "generated"}, {"text": "プログラムが正しく動くか、公開前にテストをしました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "プログラムが正[ただ]しく動[うご]くか、公開前[こうかいまえ]にテストをしました。", "sentence_source": "generated"}, {"text": "この薬の効き目は、テストで詳しく評価されました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "この薬[くすり]の効[き]き目[め]は、テストで詳[くわ]しく評価[ひょうか]されました。", "sentence_source": "generated"}, {"text": "アプリの完成前に、百人の利用者にテストしてもらいました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "アプリの完成前[かんせいまえ]に、百人[ひゃくにん]の利用者[りようしゃ]にテストしてもらいました。", "sentence_source": "generated"}, {"text": "テストの結果、そのカメラは暗い場所でも使えると分かりました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "テストの結果[けっか]、そのカメラは暗[くら]い場所[ばしょ]でも使[つか]えると分[わ]かりました。", "sentence_source": "generated"}, {"text": "エンジンの性能を調べるテストは、一週間かかりました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "エンジンの性能[せいのう]を調[しら]べるテストは、一週間[いっしゅうかん]かかりました。", "sentence_source": "generated"}, {"text": "新しい靴を、山道でテストしてから売ることにしました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "新[あたら]しい靴[くつ]を、山道[やまみち]でテストしてから売[う]ることにしました。", "sentence_source": "generated"}, {"text": "橋の強さを確かめるため、重い車でテストを行いました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "橋[はし]の強[つよ]さを確[たし]かめるため、重[おも]い車[くるま]でテストを行[おこな]いました。", "sentence_source": "generated"}, {"text": "そのソフトはテストが足りなくて、発売後に問題が出ました。", "target_word": "テスト", "complexity_tier": "T3", "furigana": "そのソフトはテストが足[た]りなくて、発売後[はつばいご]に問題[もんだい]が出[で]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テスト", "label": "基本形"}, {"form": "テストする", "label": "サ変動詞形"}], "register": "丁寧", "sense_fingerprint": "機械・製品・薬などの性能や状態を調べて評価する試験", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a7c10f-7617-45e5-a3d0-bcfe1bdfc1f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39751, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テスト", "is_correct": true, "explanation": "「工場でテストしています」として、製品の性能を調べる意味の正解。"}, {"text": "ダンス", "is_correct": false, "explanation": "「工場でダンスしています」は意味が通らず、空欄に入らない。"}, {"text": "ピクニック", "is_correct": false, "explanation": "「工場でピクニックしています」は不自然で、性能を調べる文脈に合わない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "「工場でケーキしています」は動詞として成り立たない。"}], "explanations": {"テスト": "「工場でテストしています」として、製品の性能を調べる意味の正解。", "ダンス": "「工場でダンスしています」は意味が通らず、空欄に入らない。", "ピクニック": "「工場でピクニックしています」は不自然で、性能を調べる文脈に合わない。", "ケーキ": "「工場でケーキしています」は動詞として成り立たない。"}, "sentence_index": 0, "correct_answer": "テスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "美術館で有名な絵画をテストして、感動した。", "explanation": "ここは〈鑑賞〉の意味。テストは機械や製品の性能を調べることで、芸術作品を味わう意味では使わない。"}, {"text": "週末に、郵便物をテストして、近所の家に配った。", "explanation": "ここは〈配達〉の意味。テストは性能や状態を調べる行為で、物を届ける意味では使わない。"}, {"text": "机の上の本を一冊ずつテストして、棚に片付けた。", "explanation": "ここは〈片付け〉の意味。テストは調べて評価することで、物をしまう意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39751, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テスト", "is_correct": true, "explanation": "「エンジンの性能を調べるテスト」として、評価の作業を表す正解。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "「性能を調べるヨーグルト」は意味が通らず、空欄に入らない。"}, {"text": "カーテン", "is_correct": false, "explanation": "「性能を調べるカーテン」は文脈に合わず、一週間かかる作業にならない。"}, {"text": "ハンドバッグ", "is_correct": false, "explanation": "「性能を調べるハンドバッグ」は不自然で、文が成り立たない。"}], "explanations": {"テスト": "「エンジンの性能を調べるテスト」として、評価の作業を表す正解。", "ヨーグルト": "「性能を調べるヨーグルト」は意味が通らず、空欄に入らない。", "カーテン": "「性能を調べるカーテン」は文脈に合わず、一週間かかる作業にならない。", "ハンドバッグ": "「性能を調べるハンドバッグ」は不自然で、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "テスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末に部屋の窓を全部テストして、ぴかぴかにした。", "explanation": "ここは〈掃除〉の意味。テストは性能や状態を調べる行為で、窓をきれいにする意味では使わない。"}, {"text": "宿題の作文をテストして、先生に出した。", "explanation": "ここは〈作文〉の意味。テストは調べて評価することで、文章を書く行為には使わない。"}, {"text": "店で服をテストして、お釣りを受け取った。", "explanation": "ここは〈会計〉の意味。テストは性能や状態を調べる行為で、代金を払う意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39751, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機械のテストが、工場で行いました。", "corrected_sentence": "新しい機械のテストを、工場で行いました。", "error_description": "「行う」は「テストを行う」と目的語に「を」を取る。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39751, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その機械の耐久性テストに、工場で行いました。", "corrected_sentence": "その機械の耐久性テストを、工場で行いました。", "error_description": "「行う」は目的語に「を」を取る。「テストに行う」は誤りで、正しくは「テストを行う」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39752, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「おもちゃ」と「組み立て」を名詞としてつなぐ「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」を重ねると「おもちゃを組み立てを始めました」となり、目的語が二つになって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は名詞をつなげず、「おもちゃへ組み立て」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は名詞をつなげず、「おもちゃより組み立て」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「おもちゃ」と「組み立て」を名詞としてつなぐ「の」が正しい。", "を": "「を」を重ねると「おもちゃを組み立てを始めました」となり、目的語が二つになって不自然。", "へ": "方向を示す「へ」は名詞をつなげず、「おもちゃへ組み立て」は不自然。", "より": "比較の「より」は名詞をつなげず、「おもちゃより組み立て」は意味が通らない。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。"}, {"text": "修理", "is_correct": false, "explanation": "壊れた物を直す意味で、組み立ての対義語ではない。"}, {"text": "注文", "is_correct": false, "explanation": "商品を頼む意味で、組み立ての対義語ではない。"}, {"text": "包装", "is_correct": false, "explanation": "物を包む意味で、組み立ての対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。", "修理": "壊れた物を直す意味で、組み立ての対義語ではない。", "注文": "商品を頼む意味で、組み立ての対義語ではない。", "包装": "物を包む意味で、組み立ての対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39752, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「組み立て」が主語となり、「簡単」を述語にして「簡単なので」と続く。"}, {"text": "に", "is_correct": false, "explanation": "「に」を付けると「組み立てに簡単」となり、述語とつながらず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同を示すが、「組み立てと簡単」では文の述語が立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、「組み立てから簡単」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「組み立て」が主語となり、「簡単」を述語にして「簡単なので」と続く。", "に": "「に」を付けると「組み立てに簡単」となり、述語とつながらず、文が成り立たない。", "と": "「と」は共同を示すが、「組み立てと簡単」では文の述語が立たない。", "から": "起点の「から」は、「組み立てから簡単」では意味が通らない。"}, "error_tags": {"に": "帰着・結果", "と": "共同", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べる意味で、組み立ての対義語ではない。"}, {"text": "梱包", "is_correct": false, "explanation": "荷物を包んで箱に入れる意味で、組み立ての対義語ではない。"}, {"text": "解析", "is_correct": false, "explanation": "細かく分けて調べる意味で、組み立ての対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。", "点検": "状態を調べる意味で、組み立ての対義語ではない。", "梱包": "荷物を包んで箱に入れる意味で、組み立ての対義語ではない。", "解析": "細かく分けて調べる意味で、組み立ての対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39752, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを、決まった順番でくっつけて、一つのものにすること。", "primary_collocate": null, "pronunciation": "くみたて", "ipa": "kɯmitate", "syllable_count": 4, "sentences": [{"text": "棚の組み立てには、ドライバーが一つあれば十分です。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "棚[たな]の組[く]み立[た]てには、ドライバーが一[ひと]つあれば十分[じゅうぶん]です。", "sentence_source": "generated"}, {"text": "説明書を見ながら、おもちゃの組み立てを始めました。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を見[み]ながら、おもちゃの組[く]み立[た]てを始[はじ]めました。", "sentence_source": "generated"}, {"text": "組み立ては順番が大切なので、図の通りに進めてください。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "組[く]み立[た]ては順番[じゅんばん]が大切[たいせつ]なので、図[ず]の通[とお]りに進[すす]めてください。", "sentence_source": "generated"}, {"text": "兄は組み立てが得意で、三十分で本棚を完成させました。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "兄[あに]は組[く]み立[た]てが得意[とくい]で、三十分[さんじゅっぷん]で本棚[ほんだな]を完成[かんせい]させました。", "sentence_source": "generated"}, {"text": "部品が足りなかったため、机の組み立てが途中で止まってしまいました。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "部品[ぶひん]が足[た]りなかったため、机[つくえ]の組[く]み立[た]てが途中[とちゅう]で止[と]まってしまいました。", "sentence_source": "generated"}, {"text": "子どもたちは模型の組み立てに夢中になって、昼ごはんも忘れました。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "子[こ]どもたちは模型[もけい]の組[く]み立[た]てに夢中[むちゅう]になって、昼[ひる]ごはんも忘[わす]れました。", "sentence_source": "generated"}, {"text": "組み立てを間違えると、ドアがうまく閉まりません。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "組[く]み立[た]てを間違[まちが]えると、ドアがうまく閉[し]まりません。", "sentence_source": "generated"}, {"text": "このベッドは組み立てが簡単なので、一人でも作れます。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "このベッドは組[く]み立[た]てが簡単[かんたん]なので、一人[ひとり]でも作[つく]れます。", "sentence_source": "generated"}, {"text": "組み立ての前に、ねじの数を全部数えておきましょう。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "組[く]み立[た]ての前[まえ]に、ねじの数[かず]を全部[ぜんぶ]数[かぞ]えておきましょう。", "sentence_source": "generated"}, {"text": "引っ越しの日までに、新しい棚の組み立てを終えたいです。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]までに、新[あたら]しい棚[たな]の組[く]み立[た]てを終[お]えたいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み立て", "label": "基本形"}, {"form": "組立", "label": "送り仮名を省いた表記"}], "register": "neutral", "sense_fingerprint": "assembling things in a set order into one finished object (furniture, models)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39752, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み立て", "is_correct": true, "explanation": "名詞で、「棚の〜には」という名詞句を作り、文の主題として成り立つ。"}, {"text": "組み立てた", "is_correct": false, "explanation": "過去形の動詞なので、「の」の後に続かず、「棚の〜には」の名詞句が成り立たない。"}, {"text": "組む", "is_correct": false, "explanation": "動詞の辞書形で、「の」の後に動詞を置けず、名詞句にならない。"}, {"text": "組み立てない", "is_correct": false, "explanation": "否定形の動詞で、名詞句の一部にならず、「の」の後に続かない。"}], "explanations": {"組み立て": "名詞で、「棚の〜には」という名詞句を作り、文の主題として成り立つ。", "組み立てた": "過去形の動詞なので、「の」の後に続かず、「棚の〜には」の名詞句が成り立たない。", "組む": "動詞の辞書形で、「の」の後に動詞を置けず、名詞句にならない。", "組み立てない": "否定形の動詞で、名詞句の一部にならず、「の」の後に続かない。"}, "sentence_index": 0, "correct_answer": "組み立て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ご飯を組み立てた。", "explanation": "ここは〈炊く〉の意味。組み立ては部品を組み合わせることで、米を煮て食べられる状態にする場面には使えない。"}, {"text": "布団を組み立てた。", "explanation": "ここは〈畳む〉の意味。組み立ては部品を組み合わせることで、布団を折りたたむ場面には使えない。"}, {"text": "犬を組み立てた。", "explanation": "ここは〈散歩させる〉の意味。組み立ては部品を組み合わせることで、犬を外に連れて歩く場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39752, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み立て", "is_correct": true, "explanation": "名詞で、「〜を間違えると」の目的語として文が成り立つ。"}, {"text": "組み立てて", "is_correct": false, "explanation": "て形で、「〜て間違えると」とはつながらず、名詞句にならない。"}, {"text": "組み立てよう", "is_correct": false, "explanation": "意志形で、「〜よう間違えると」とは続かず、文が成り立たない。"}, {"text": "組み立てる", "is_correct": false, "explanation": "辞書形で、「組み立てるを」となり、目的語の名詞句にならない。"}], "explanations": {"組み立て": "名詞で、「〜を間違えると」の目的語として文が成り立つ。", "組み立てて": "て形で、「〜て間違えると」とはつながらず、名詞句にならない。", "組み立てよう": "意志形で、「〜よう間違えると」とは続かず、文が成り立たない。", "組み立てる": "辞書形で、「組み立てるを」となり、目的語の名詞句にならない。"}, "sentence_index": 6, "correct_answer": "組み立て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫を組み立てた。", "explanation": "ここは〈飼う〉の意味。組み立ては部品を組み合わせることで、生き物を世話する場面には使えない。"}, {"text": "お茶を組み立てた。", "explanation": "ここは〈入れる（湯を注いで淹れる）〉の意味。組み立ては部品を組み合わせることで、飲み物を淹れる場面には使えない。"}, {"text": "魚を組み立てた。", "explanation": "ここは〈釣る〉の意味。組み立ては部品を組み合わせることで、魚を捕まえる場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39752, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "椅子を組み立てには、ネジを四つ使います。", "corrected_sentence": "椅子の組み立てには、ネジを四つ使います。", "error_description": "誤りは「椅子を」の「を」。「組み立て」は名詞なので、前に「の」を付ける。「を」にすると「組み立てには」の名詞句が成り立たない。正しくは「椅子の組み立てには」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39752, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の組み立てるを、家族で手伝いました。", "corrected_sentence": "机の組み立てを、家族で手伝いました。", "error_description": "誤りは「組み立てる」の「る」。「組み立て」は名詞なので、動詞の語尾「る」は付かない。正しくは「組み立てを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39753, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「パソコン」と「組み立て」を名詞としてつなぐ「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」を付けると「パソコンを組み立てには」となり、名詞句が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は名詞句をつなげず、「パソコンへ組み立て」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は名詞句をつなげず、「パソコンより組み立て」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「パソコン」と「組み立て」を名詞としてつなぐ「の」が正しい。", "を": "「を」を付けると「パソコンを組み立てには」となり、名詞句が成り立たない。", "へ": "方向を示す「へ」は名詞句をつなげず、「パソコンへ組み立て」は不自然。", "より": "比較の「より」は名詞句をつなげず、「パソコンより組み立て」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。"}, {"text": "配送", "is_correct": false, "explanation": "商品を届ける意味で、組み立ての対義語ではない。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べる意味で、組み立ての対義語ではない。"}, {"text": "修繕", "is_correct": false, "explanation": "壊れた物を直す意味で、組み立ての対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。", "配送": "商品を届ける意味で、組み立ての対義語ではない。", "点検": "状態を調べる意味で、組み立ての対義語ではない。", "修繕": "壊れた物を直す意味で、組み立ての対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39753, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「組み立て」が主語として「遅れた」の主体になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同を示すが、「組み立てと遅れた」では述語が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、「組み立てから遅れた」では原因と結果の関係を表せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞をつなぐが、「組み立ての遅れた」は動詞の形と合わない。"}], "correct_answer": "が", "explanations": {"が": "「組み立て」が主語として「遅れた」の主体になる。", "と": "「と」は共同を示すが、「組み立てと遅れた」では述語が成り立たない。", "から": "起点の「から」は、「組み立てから遅れた」では原因と結果の関係を表せない。", "の": "連体修飾の「の」は名詞をつなぐが、「組み立ての遅れた」は動詞の形と合わない。"}, "error_tags": {"と": "共同", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。"}, {"text": "梱包", "is_correct": false, "explanation": "荷物を包んで箱に入れる意味で、組み立ての対義語ではない。"}, {"text": "解析", "is_correct": false, "explanation": "細かく分けて調べる意味で、組み立ての対義語ではない。"}, {"text": "製本", "is_correct": false, "explanation": "印刷物を綴じて本にする意味で、組み立ての対義語ではない。"}], "correct_answer": "分解", "explanations": {"分解": "組み立てたものを部品に戻す意味で、「組み立て」の対義語。", "梱包": "荷物を包んで箱に入れる意味で、組み立ての対義語ではない。", "解析": "細かく分けて調べる意味で、組み立ての対義語ではない。", "製本": "印刷物を綴じて本にする意味で、組み立ての対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39753, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の部品や要素を順序や方法に従って組み合わせて、一つのまとまったものにすること。", "primary_collocate": null, "pronunciation": "くみたて", "ipa": "kɯmitate", "syllable_count": 4, "sentences": [{"text": "この工場では、自動車の組み立てをロボットが行っています。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、自動車[じどうしゃ]の組[く]み立[た]てをロボットが行[おこな]っています。", "sentence_source": "generated"}, {"text": "パソコンの組み立てには、部品の相性を調べることが大切です。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "パソコンの組[く]み立[た]てには、部品[ぶひん]の相性[あいしょう]を調[しら]べることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "組み立ての方法は、製品によって少しずつ違います。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "組[く]み立[た]ての方法[ほうほう]は、製品[せいひん]によって少[すこ]しずつ違[ちが]います。", "sentence_source": "generated"}, {"text": "兄はプラモデルの組み立てを終え、棚に飾りました。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "兄[あに]はプラモデルの組[く]み立[た]てを終[お]え、棚[たな]に飾[かざ]りました。", "sentence_source": "generated"}, {"text": "組み立ての順序を変えると、部品が入らなくなります。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "組[く]み立[た]ての順序[じゅんじょ]を変[か]えると、部品[ぶひん]が入[はい]らなくなります。", "sentence_source": "generated"}, {"text": "時計の組み立てには、細かい部品を扱う技術が必要です。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "時計[とけい]の組[く]み立[た]てには、細[こま]かい部品[ぶひん]を扱[あつか]う技術[ぎじゅつ]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "教室で、ロボットの組み立てを班ごとに体験しました。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "教室[きょうしつ]で、ロボットの組[く]み立[た]てを班[はん]ごとに体験[たいけん]しました。", "sentence_source": "generated"}, {"text": "工場の組み立てが遅れたため、新製品の発売が来月になりました。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "工場[こうじょう]の組[く]み立[た]てが遅[おく]れたため、新製品[しんせいひん]の発売[はつばい]が来月[らいげつ]になりました。", "sentence_source": "generated"}, {"text": "組み立ての手順を正しく守れば、誰でも同じ製品を作れます。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "組[く]み立[た]ての手順[てじゅん]を正[ただ]しく守[まも]れば、誰[だれ]でも同[おな]じ製品[せいひん]を作[つく]れます。", "sentence_source": "generated"}, {"text": "自転車の組み立てを店に頼むと、少し料金がかかります。", "target_word": "組み立て", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]の組[く]み立[た]てを店[みせ]に頼[たの]むと、少[すこ]し料金[りょうきん]がかかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み立て", "label": "基本形"}, {"form": "組立", "label": "送り仮名を省いた表記"}], "register": "neutral", "sense_fingerprint": "putting multiple parts together by a set procedure into one product (factory, PC, robot)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39753, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み立て", "is_correct": true, "explanation": "名詞で、「自動車の〜をロボットが行う」の目的語として文が成り立つ。"}, {"text": "組み立てて", "is_correct": false, "explanation": "て形で、「の」の後に続けず、名詞句にならない。"}, {"text": "組み立てた", "is_correct": false, "explanation": "過去形の動詞で、「自動車の」の後に続かず、名詞句が成り立たない。"}, {"text": "組む", "is_correct": false, "explanation": "動詞の辞書形で、「の」の後に動詞を置けず、名詞句にならない。"}], "explanations": {"組み立て": "名詞で、「自動車の〜をロボットが行う」の目的語として文が成り立つ。", "組み立てて": "て形で、「の」の後に続けず、名詞句にならない。", "組み立てた": "過去形の動詞で、「自動車の」の後に続かず、名詞句が成り立たない。", "組む": "動詞の辞書形で、「の」の後に動詞を置けず、名詞句にならない。"}, "sentence_index": 0, "correct_answer": "組み立て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもの組み立てをした。", "explanation": "ここは〈叱る〉の意味。組み立ては部品を組み合わせることで、人を注意する場面には使えない。"}, {"text": "汚れた皿の組み立てをした。", "explanation": "ここは〈洗う〉の意味。組み立ては部品を組み合わせる作業で、汚れを落とす場面には使えない。"}, {"text": "赤ちゃんを組み立てた。", "explanation": "ここは〈寝かせる〉の意味。組み立ては部品を組み合わせることで、赤ちゃんを眠らせる場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39753, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み立て", "is_correct": true, "explanation": "名詞で、「ロボットの〜を班ごとに体験」の目的語として文が成り立つ。"}, {"text": "組み立てよう", "is_correct": false, "explanation": "意志形で、「の」の後に続かず、名詞句が成り立たない。"}, {"text": "組み立てない", "is_correct": false, "explanation": "否定形で、「の」の後に続かず、名詞句にならない。"}, {"text": "組み立てられた", "is_correct": false, "explanation": "受身の過去形で、「ロボットの〜を」の名詞句が成り立たない。"}], "explanations": {"組み立て": "名詞で、「ロボットの〜を班ごとに体験」の目的語として文が成り立つ。", "組み立てよう": "意志形で、「の」の後に続かず、名詞句が成り立たない。", "組み立てない": "否定形で、「の」の後に続かず、名詞句にならない。", "組み立てられた": "受身の過去形で、「ロボットの〜を」の名詞句が成り立たない。"}, "sentence_index": 6, "correct_answer": "組み立て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭に、バラの苗の組み立てをした。", "explanation": "ここは〈植える〉の意味。組み立ては部品を組み合わせることで、苗を土に植える場面には使えない。"}, {"text": "毎朝、台所の組み立てをしている。", "explanation": "ここは〈掃除する〉の意味。組み立ては部品を組み合わせる作業で、台所をきれいにする場面には使えない。"}, {"text": "友人の組み立てをした。", "explanation": "ここは〈招待する〉の意味。組み立ては部品を組み合わせることで、人を招き入れる場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39753, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機械を組み立てには、説明書の図を見ることが必要です。", "corrected_sentence": "新しい機械の組み立てには、説明書の図を見ることが必要です。", "error_description": "誤りは「機械を」の「を」。「組み立て」は名詞なので、前に「の」を付ける。「を」にすると「組み立てには」の名詞句が成り立たない。正しくは「機械の組み立てには」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39753, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "完成品の組み立てに、来週から始めます。", "corrected_sentence": "完成品の組み立てを、来週から始めます。", "error_description": "誤りは「組み立てに」の「に」。「始める」の目的語は「組み立て」なので「を」が必要。「に」にすると対象を示せず、文が成り立たない。正しくは「組み立てを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39754, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「包む」の対象を示す「を」。チョコレートのブロックを包むという意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。包むのは店の人なので、ブロックが主語になると意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。包む対象を示さず、ここには入らない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ「の」。ブロックの後に続く動詞句と結びつかず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「包む」の対象を示す「を」。チョコレートのブロックを包むという意味になる。", "が": "主語を示す「が」。包むのは店の人なので、ブロックが主語になると意味が通らない。", "へ": "方向を示す「へ」。包む対象を示さず、ここには入らない。", "の": "名詞をつなぐ「の」。ブロックの後に続く動詞句と結びつかず、文が成り立たない。"}, "error_tags": {"が": "主格", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39754, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「並べる」の対象を示す「を」。ブロックを一つずつ並べるという意味になる。"}, {"text": "と", "is_correct": false, "explanation": "「〜と並べる」は別のものとの並列を表し、並べる対象を直接示さないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。並べる対象の比較ではないので文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。ブロックを起点にすると並べる対象が示されず、文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「並べる」の対象を示す「を」。ブロックを一つずつ並べるという意味になる。", "と": "「〜と並べる」は別のものとの並列を表し、並べる対象を直接示さないので合わない。", "より": "比較を表す「より」。並べる対象の比較ではないので文が成り立たない。", "から": "起点を表す「から」。ブロックを起点にすると並べる対象が示されず、文に合わない。"}, "error_tags": {"と": "共同・並列", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39754, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ひとつの大きなかたまりのことです。", "primary_collocate": null, "pronunciation": "ぶろっく", "ipa": "bɯɾokkɯ", "syllable_count": 4, "sentences": [{"text": "大きな氷のブロックをクーラーボックスに入れました。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "大[おお]きな氷[こおり]のブロックをクーラーボックスに入[い]れました。", "sentence_source": "generated"}, {"text": "お店では、チョコレートのブロックを一つずつ包んで売っています。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "お店[みせ]では、チョコレートのブロックを一[ひと]つずつ包[つつ]んで売[う]っています。", "sentence_source": "generated"}, {"text": "庭の壁はコンクリートのブロックでできています。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "庭[にわ]の壁[かべ]はコンクリートのブロックでできています。", "sentence_source": "generated"}, {"text": "冷蔵庫からチーズのブロックを出して、小さく切りました。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]からチーズのブロックを出[だ]して、小[ちい]さく切[き]りました。", "sentence_source": "generated"}, {"text": "道の端に石のブロックが置いてあります。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "道[みち]の端[はし]に石[いし]のブロックが置[お]いてあります。", "sentence_source": "generated"}, {"text": "このブロックは重すぎて、一人では運べません。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "このブロックは重[おも]すぎて、一人[ひとり]では運[はこ]べません。", "sentence_source": "generated"}, {"text": "バターは四角いブロックの形で売られています。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "バターは四角[しかく]いブロックの形[かたち]で売[う]られています。", "sentence_source": "generated"}, {"text": "職人はブロックを一つずつ並べて、花壇を囲みました。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "職人[しょくにん]はブロックを一[ひと]つずつ並[なら]べて、花壇[かだん]を囲[かこ]みました。", "sentence_source": "generated"}, {"text": "粘土を大きなブロックにしてから、形を作ります。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "粘土[ねんど]を大[おお]きなブロックにしてから、形[かたち]を作[つく]ります。", "sentence_source": "generated"}, {"text": "倒れたブロックの下に、猫が隠れていました。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "倒[たお]れたブロックの下[した]に、猫[ねこ]が隠[かく]れていました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブロック", "label": "基本形"}], "register": "polite", "sense_fingerprint": "石・氷・コンクリート・チーズなど、ひとつにまとまった大きなかたまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブロック", "is_correct": true, "explanation": "「大きな氷のかたまり」を指し、クーラーボックスに入れられる物として文が自然に成り立つ。"}, {"text": "手紙", "is_correct": false, "explanation": "紙に書かれたもので、大きな氷とは結びつかず、クーラーボックスに入れる対象として不自然。"}, {"text": "歌", "is_correct": false, "explanation": "形のないもので、大きな氷の塊とは合わず、入れる対象にならない。"}, {"text": "花束", "is_correct": false, "explanation": "花を束ねたもので、大きな氷のかたまりを表さないので文に合わない。"}], "explanations": {"ブロック": "「大きな氷のかたまり」を指し、クーラーボックスに入れられる物として文が自然に成り立つ。", "手紙": "紙に書かれたもので、大きな氷とは結びつかず、クーラーボックスに入れる対象として不自然。", "歌": "形のないもので、大きな氷の塊とは合わず、入れる対象にならない。", "花束": "花を束ねたもので、大きな氷のかたまりを表さないので文に合わない。"}, "sentence_index": 0, "correct_answer": "ブロック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゴマのブロックを一つずつ数えました。", "explanation": "ここは〈粒〉の意味。ブロックは大きなかたまりを指し、ゴマの粒のような小さなものを一つずつ数える場面には合わない。"}, {"text": "ブロックが立ちのぼって、窓が白くなりました。", "explanation": "ここは〈湯気〉の意味。ブロックは固まったかたまりを指し、ふわりと立ちのぼる湯気には合わない。"}, {"text": "お菓子作りでは、小麦粉のブロックを一さじずつ量ります。", "explanation": "ここは〈粉〉の意味。ブロックは一つにまとまった大きなかたまりを指し、さらさらした粉を一さじずつ量る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブロック", "is_correct": true, "explanation": "四角いかたまりの形を表し、バターの売り方として自然に成り立つ。"}, {"text": "文字", "is_correct": false, "explanation": "文字は形を持たないので、「四角い文字の形」は成り立たない。"}, {"text": "音", "is_correct": false, "explanation": "音には形がなく、「四角い音の形」は不自然。"}, {"text": "色", "is_correct": false, "explanation": "色は形を持たず、「四角い色の形」は不自然。"}], "explanations": {"ブロック": "四角いかたまりの形を表し、バターの売り方として自然に成り立つ。", "文字": "文字は形を持たないので、「四角い文字の形」は成り立たない。", "音": "音には形がなく、「四角い音の形」は不自然。", "色": "色は形を持たず、「四角い色の形」は不自然。"}, "sentence_index": 6, "correct_answer": "ブロック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブロックを一枚ずつ並べて、押し花にしました。", "explanation": "ここは〈花びら〉の意味。ブロックは固まったかたまりを指し、一枚ずつ並べる薄い花びらには合わない。"}, {"text": "コーヒーのブロックが消えていきました。", "explanation": "ここは〈泡〉の意味。ブロックは固まったかたまりを指し、すぐ消えていく泡には合わない。"}, {"text": "道にブロックをまいて、歩きやすくしました。", "explanation": "ここは〈砂利〉の意味。ブロックは一つにまとまった大きな塊で、まいて使うような細かいものには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この塀はレンガのブロックに作られています。", "corrected_sentence": "この塀はレンガのブロックで作られています。", "error_description": "材料を表すには「で」を使う。「に」にすると「ブロックに作る」となり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きなブロックを運ばました。", "corrected_sentence": "大きなブロックを運びました。", "error_description": "「運ぶ」の過去形は「運びました」。「運ばました」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39755, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を示す「に」。ブロックに私の家がある、という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「ある」の場所は表せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "動作が行われる場所の「で」。存在を表す「ある」とは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。存在する場所ではないので文が合わない。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を示す「に」。ブロックに私の家がある、という意味になる。", "を": "目的語の「を」。「ある」の場所は表せず、文が成り立たない。", "で": "動作が行われる場所の「で」。存在を表す「ある」とは合わない。", "へ": "方向を示す「へ」。存在する場所ではないので文が合わない。"}, "error_tags": {"を": "対格", "で": "動作の場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
