INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39755, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "町や会場、地域などを区切った一つの区画のこと。", "primary_collocate": null, "pronunciation": "ぶろっく", "ipa": "bɯɾokkɯ", "syllable_count": 4, "sentences": [{"text": "この町は、四角いブロックに分かれています。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "この町[まち]は、四角[しかく]いブロックに分[わ]かれています。", "sentence_source": "generated"}, {"text": "駅から二つ先のブロックに、私の家があります。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "駅[えき]から二[ふた]つ先[さき]のブロックに、私[わたし]の家[いえ]があります。", "sentence_source": "generated"}, {"text": "同じブロックに住む人たちが、いっしょに掃除をしました。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "同[おな]じブロックに住[す]む人[ひと]たちが、いっしょに掃除[そうじ]をしました。", "sentence_source": "generated"}, {"text": "大会では、日本を五つのブロックに分けて予選を行います。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "大会[たいかい]では、日本[にほん]を五[いつ]つのブロックに分[わ]けて予選[よせん]を行[おこな]います。", "sentence_source": "generated"}, {"text": "客席は三つのブロックに分かれていて、私は真ん中のブロックにすわりました。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "客席[きゃくせき]は三[みっ]つのブロックに分[わ]かれていて、私[わたし]は真[ま]ん中[なか]のブロックにすわりました。", "sentence_source": "generated"}, {"text": "地図の右上のブロックに、大きな公園があります。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "地図[ちず]の右上[みぎうえ]のブロックに、大[おお]きな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "予選は、地区ごとのブロックで行われます。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "予選[よせん]は、地区[ちく]ごとのブロックで行[おこな]われます。", "sentence_source": "generated"}, {"text": "このフロアは、ブロックごとに別の会社が使っています。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "このフロアは、ブロックごとに別[べつ]の会社[かいしゃ]が使[つか]っています。", "sentence_source": "generated"}, {"text": "市役所は、この静かなブロックの中心にあります。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "市役所[しやくしょ]は、この静[しず]かなブロックの中心[ちゅうしん]にあります。", "sentence_source": "generated"}, {"text": "夜はこのブロックに街灯が少ないので、とても暗いです。", "target_word": "ブロック", "complexity_tier": "T3", "furigana": "夜[よる]はこのブロックに街灯[がいとう]が少[すく]ないので、とても暗[くら]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブロック", "label": "基本形"}], "register": "polite", "sense_fingerprint": "町や会場、地域などを分けた一つの区画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: すわり (Zipf 2.16)']::text[], '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39755, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブロック", "is_correct": true, "explanation": "町を区切った一つの区画を表し、四角く分かれた町の説明として自然。"}, {"text": "文字", "is_correct": false, "explanation": "文字は町を区切る単位ではないので、「文字に分かれています」は町の区分として成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "色は町を区切る単位にならないので、文の意味に合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は町を区切る単位にはならず、分け方として合わない。"}], "explanations": {"ブロック": "町を区切った一つの区画を表し、四角く分かれた町の説明として自然。", "文字": "文字は町を区切る単位ではないので、「文字に分かれています」は町の区分として成り立たない。", "色": "色は町を区切る単位にならないので、文の意味に合わない。", "音": "音は町を区切る単位にはならず、分け方として合わない。"}, "sentence_index": 0, "correct_answer": "ブロック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本のブロックを一枚めくりました。", "explanation": "ここは〈ページ〉の意味。ブロックは塊や区画を指し、紙を一枚ずつめくるページの意味では使えないので合わない。"}, {"text": "コーヒーのブロックを三つ洗いました。", "explanation": "ここは〈カップ〉の意味。ブロックは塊や区画を指し、洗う器のカップの意味では使えないので合わない。"}, {"text": "ピアノのブロックを三つ押しました。", "explanation": "ここは〈鍵盤〉の意味。ブロックは塊や区画を指し、ピアノの鍵を押す場面では使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39755, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブロック", "is_correct": true, "explanation": "地区ごとに分けた区画を指し、予選を行う単位として自然に成り立つ。"}, {"text": "歌", "is_correct": false, "explanation": "歌で予選が行われるとは言わず、地区との関係もない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙で予選を行うという言い方は不自然。"}, {"text": "花束", "is_correct": false, "explanation": "花束で予選を行う言い方は成り立たない。"}], "explanations": {"ブロック": "地区ごとに分けた区画を指し、予選を行う単位として自然に成り立つ。", "歌": "歌で予選が行われるとは言わず、地区との関係もない。", "手紙": "手紙で予選を行うという言い方は不自然。", "花束": "花束で予選を行う言い方は成り立たない。"}, "sentence_index": 6, "correct_answer": "ブロック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブロックを一本ずつ束ねました。", "explanation": "ここは〈ひも〉の意味。ブロックは塊や区画を指し、細長い一本ずつ束ねるひもには合わない。"}, {"text": "ブロックを一枚ずつ数えました。", "explanation": "ここは〈コイン〉の意味。ブロックは塊や区画を指し、一枚ずつ数える薄いコインには合わない。"}, {"text": "道にブロックをまいて、歩きやすくしました。", "explanation": "ここは〈砂利〉の意味。ブロックは地域の区画を指し、まいて使う細かいものとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39755, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この市は、北と南の二つのブロックへ分けられています。", "corrected_sentence": "この市は、北と南の二つのブロックに分けられています。", "error_description": "「分ける」は「〜に分ける」と使う。「へ」は方向を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39755, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は四つのブロックに分かりています。", "corrected_sentence": "町は四つのブロックに分かれています。", "error_description": "「分かれている」（区切られている）が正しい形。「分かる（理解する）」は意味が違い、ここでは使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39756, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「字を消す」の目的語を示す格助詞。消す対象が字であることを表す。"}, {"text": "に", "is_correct": false, "explanation": "「字に消す」は不自然。「に」は場所や相手を示し、消す対象を示さない。"}, {"text": "へ", "is_correct": false, "explanation": "「字へ消す」は方向を示す助詞で、消す対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「字と消す」は共同や引用を示すため、目的語には使えない。"}], "correct_answer": "を", "explanations": {"を": "「字を消す」の目的語を示す格助詞。消す対象が字であることを表す。", "に": "「字に消す」は不自然。「に」は場所や相手を示し、消す対象を示さない。", "へ": "「字へ消す」は方向を示す助詞で、消す対象を表せない。", "と": "「字と消す」は共同や引用を示すため、目的語には使えない。"}, "error_tags": {"に": "場所・相手", "へ": "方向", "と": "共同・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "点ける", "is_correct": true, "explanation": "「電気を消す」の対義語。テレビや電気をつける意味で、「テレビを消す」の反対の動作。"}, {"text": "書く", "is_correct": false, "explanation": "対義語ではない。消すことと書くことは反対の関係にない。"}, {"text": "拾う", "is_correct": false, "explanation": "対義語ではない。拾うは物を取り上げる動作で、消すの反対とは言えない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "対義語ではない。運ぶは物を移動させる動作で、消すの反対の関係にない。"}], "correct_answer": "点ける", "explanations": {"点ける": "「電気を消す」の対義語。テレビや電気をつける意味で、「テレビを消す」の反対の動作。", "書く": "対義語ではない。消すことと書くことは反対の関係にない。", "拾う": "対義語ではない。拾うは物を取り上げる動作で、消すの反対とは言えない。", "運ぶ": "対義語ではない。運ぶは物を移動させる動作で、消すの反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39756, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ガスを消す」の目的語を示す格助詞。消す対象がガスであることを表す。"}, {"text": "が", "is_correct": false, "explanation": "「ガスが消して」は自動詞の主語になり、「消して」の目的語としては成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ガスの消して」は名詞をつなぐ用法で、動詞の目的語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「ガスより消して」は比較の用法で、消す対象を示す文法的役割に合わない。"}], "correct_answer": "を", "explanations": {"を": "「ガスを消す」の目的語を示す格助詞。消す対象がガスであることを表す。", "が": "「ガスが消して」は自動詞の主語になり、「消して」の目的語としては成り立たない。", "の": "「ガスの消して」は名詞をつなぐ用法で、動詞の目的語を示せない。", "より": "「ガスより消して」は比較の用法で、消す対象を示す文法的役割に合わない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39756, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "見えているものを、なくなるようにする。", "primary_collocate": null, "pronunciation": "けす", "ipa": "kesɯ", "syllable_count": 2, "sentences": [{"text": "部屋を出るときは、電気を消してください。", "target_word": "消して", "complexity_tier": "T2", "furigana": "部屋[へや]を出[で]るときは、電気[でんき]を消[け]してください。", "sentence_source": "generated"}, {"text": "黒板の字を消して、新しい問題を書いた。", "target_word": "消して", "complexity_tier": "T3", "furigana": "黒板[こくばん]の字[じ]を消[け]して、新[あたら]しい問題[もんだい]を書[か]いた。", "sentence_source": "generated"}, {"text": "ろうそくの火を息で消した。", "target_word": "消した", "complexity_tier": "T2", "furigana": "ろうそくの火[ひ]を息[いき]で消[け]した。", "sentence_source": "generated"}, {"text": "寝る前にテレビを消す習慣があります。", "target_word": "消す", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]にテレビを消[け]す習慣[しゅうかん]があります。", "sentence_source": "generated"}, {"text": "間違えた答えを消して、正しい答えを書き直した。", "target_word": "消して", "complexity_tier": "T3", "furigana": "間違[まちが]えた答[こた]えを消[け]して、正[ただ]しい答[こた]えを書[か]き直[なお]した。", "sentence_source": "generated"}, {"text": "雨が強くなる前に、たき火の火を消した。", "target_word": "消した", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなる前[まえ]に、たき火[び]の火[ひ]を消[け]した。", "sentence_source": "generated"}, {"text": "白い絵の具で下書きの線を消しました。", "target_word": "消しました", "complexity_tier": "T3", "furigana": "白[しろ]い絵[え]の具[ぐ]で下書[したが]きの線[せん]を消[け]しました。", "sentence_source": "generated"}, {"text": "母は台所のガスを消してから出かけた。", "target_word": "消して", "complexity_tier": "T3", "furigana": "母[はは]は台所[だいどころ]のガスを消[け]してから出[で]かけた。", "sentence_source": "generated"}, {"text": "画面の文字を消すには、このボタンを押します。", "target_word": "消す", "complexity_tier": "T4", "furigana": "画面[がめん]の文字[もじ]を消[け]すには、このボタンを押[お]します。", "sentence_source": "generated"}, {"text": "ノートの落書きを消すのに、五分もかかった。", "target_word": "消す", "complexity_tier": "T4", "furigana": "ノートの落書[らくが]きを消[け]すのに、五分[ごふん]もかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "消す", "label": "終止形"}, {"form": "消さ", "label": "未然形"}, {"form": "消し", "label": "連用形"}, {"form": "消せ", "label": "仮定形・命令形"}, {"form": "消そう", "label": "意志形"}, {"form": "消して", "label": "て形"}, {"form": "消した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "火・明かり・文字・線など、目に見えているものをなくす。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: たき火 (Zipf 2.39)']::text[], '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39756, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消して", "is_correct": true, "explanation": "「電気を消す」のて形。部屋を出るときに電気を消す、という文脈に合う。"}, {"text": "消えて", "is_correct": false, "explanation": "自動詞「消える」は「電気が消えて」となり、「電気を」とは続かない。"}, {"text": "洗って", "is_correct": false, "explanation": "電気は洗うものではないので、「電気を洗って」は意味が成り立たない。"}, {"text": "書いて", "is_correct": false, "explanation": "電気は書くものではないので、「電気を書いて」は文脈に合わない。"}], "explanations": {"消して": "「電気を消す」のて形。部屋を出るときに電気を消す、という文脈に合う。", "消えて": "自動詞「消える」は「電気が消えて」となり、「電気を」とは続かない。", "洗って": "電気は洗うものではないので、「電気を洗って」は意味が成り立たない。", "書いて": "電気は書くものではないので、「電気を書いて」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "消して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食後に皿を消した。", "explanation": "ここは〈洗う〉の場面。皿は洗うものなので、〈消す〉とは言わない。"}, {"text": "ハンカチで涙を消した。", "explanation": "ここは〈拭う〉の場面。涙は拭うものなので、〈消す〉とは言わない。"}, {"text": "ドアを消した。", "explanation": "ここは〈閉める〉の場面。ドアは閉めるものなので、消すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39756, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消しました", "is_correct": true, "explanation": "「線を消す」の丁寧な過去形。下書きの線を消した、という文脈に合う。"}, {"text": "食べました", "is_correct": false, "explanation": "線は食べるものではないので、「線を食べました」は意味が成り立たない。"}, {"text": "眠りました", "is_correct": false, "explanation": "「眠る」は他動詞ではないので、「線を眠りました」は文として成り立たない。"}, {"text": "歌いました", "is_correct": false, "explanation": "線は歌うものではないので、「線を歌いました」は文脈に合わない。"}], "explanations": {"消しました": "「線を消す」の丁寧な過去形。下書きの線を消した、という文脈に合う。", "食べました": "線は食べるものではないので、「線を食べました」は意味が成り立たない。", "眠りました": "「眠る」は他動詞ではないので、「線を眠りました」は文として成り立たない。", "歌いました": "線は歌うものではないので、「線を歌いました」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "消しました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の前に、お茶の缶を消した。", "explanation": "ここは〈開ける〉の場面。缶は開けるものなので、〈消す〉とは言わない。"}, {"text": "壁の穴を消した。", "explanation": "ここは〈ふさぐ〉の場面。穴は消すものではなく、ふさぐものなので合わない。"}, {"text": "ゴミを消した。", "explanation": "ここは〈捨てる〉の場面。ゴミは捨てるものなので、消すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39756, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝る前に電気を消いて、ベッドに入った。", "corrected_sentence": "寝る前に電気を消して、ベッドに入った。", "error_description": "「消す」のて形は「消して」。「消いて」は活用の誤りで、正しい形は「消して」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "消して", "is_correct": true, "explanation": "て形。「字を消して、新しい問題を書いた」と動作を順に並べる形。"}, {"text": "消せ", "is_correct": false, "explanation": "命令形・仮定形。文中で「〜て」と続けて動作を並べることができない。"}, {"text": "消そう", "is_correct": false, "explanation": "意志形。後ろの動作を並べる文脈ではなく、「消そう」と決める意味になってしまう。"}, {"text": "消さ", "is_correct": false, "explanation": "未然形。「消さ、書いた」と文をつなげられず、文が成り立たない。"}], "correct_form": "消して", "base_form": "消す", "form_label": "て形", "sentence_index": 1, "explanations": {"消して": "て形。「字を消して、新しい問題を書いた」と動作を順に並べる形。", "消せ": "命令形・仮定形。文中で「〜て」と続けて動作を並べることができない。", "消そう": "意志形。後ろの動作を並べる文脈ではなく、「消そう」と決める意味になってしまう。", "消さ": "未然形。「消さ、書いた」と文をつなげられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39756, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前に明かりが消して、本を閉じた。", "corrected_sentence": "寝る前に明かりを消して、本を閉じた。", "error_description": "「消す」の目的語（明かり）は「を」で示す。「が」は自動詞「消える」の主語を示すため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "消して", "is_correct": true, "explanation": "て形。「ガスを消してから出かけた」と、先の動作を後ろに続ける形。"}, {"text": "消すな", "is_correct": false, "explanation": "禁止形。「消すなから出かけた」と続けられず、文が成り立たない。"}, {"text": "消すまい", "is_correct": false, "explanation": "否定意志形。「〜てから」や「〜から」と続けられず、文が崩れる。"}, {"text": "消しな", "is_correct": false, "explanation": "くだけた命令形。「消しなから出かけた」と続けられず、命令の語調にもなってしまう。"}], "correct_form": "消して", "base_form": "消す", "form_label": "て形", "sentence_index": 7, "explanations": {"消して": "て形。「ガスを消してから出かけた」と、先の動作を後ろに続ける形。", "消すな": "禁止形。「消すなから出かけた」と続けられず、文が成り立たない。", "消すまい": "否定意志形。「〜てから」や「〜から」と続けられず、文が崩れる。", "消しな": "くだけた命令形。「消しなから出かけた」と続けられず、命令の語調にもなってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39757, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雑音を消す」の目的語を示す格助詞。消す対象が雑音であることを表す。"}, {"text": "に", "is_correct": false, "explanation": "「雑音に消す」は不自然。「に」は場所や相手を示し、消す対象を示さない。"}, {"text": "へ", "is_correct": false, "explanation": "「雑音へ消す」は方向を示す助詞で、消す対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「雑音と消す」は共同や引用を示すため、目的語には使えない。"}], "correct_answer": "を", "explanations": {"を": "「雑音を消す」の目的語を示す格助詞。消す対象が雑音であることを表す。", "に": "「雑音に消す」は不自然。「に」は場所や相手を示し、消す対象を示さない。", "へ": "「雑音へ消す」は方向を示す助詞で、消す対象を表せない。", "と": "「雑音と消す」は共同や引用を示すため、目的語には使えない。"}, "error_tags": {"に": "場所・相手", "へ": "方向", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39757, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「足あとを消す」の目的語を示す格助詞。消す対象が足あとであることを表す。"}, {"text": "が", "is_correct": false, "explanation": "「足あとが消しながら」は主語を示すが、消す動作の目的語としては成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「足あとの消しながら」は名詞をつなぐ用法で、動詞の目的語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「足あとより消しながら」は比較の用法で、消す対象を示す役割に合わない。"}], "correct_answer": "を", "explanations": {"を": "「足あとを消す」の目的語を示す格助詞。消す対象が足あとであることを表す。", "が": "「足あとが消しながら」は主語を示すが、消す動作の目的語としては成り立たない。", "の": "「足あとの消しながら」は名詞をつなぐ用法で、動詞の目的語を示せない。", "より": "「足あとより消しながら」は比較の用法で、消す対象を示す役割に合わない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39757, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "取り除いたり、存在しなくしたりする。", "primary_collocate": null, "pronunciation": "けす", "ipa": "kesɯ", "syllable_count": 2, "sentences": [{"text": "犯人は証拠を消して、姿をくらました。", "target_word": "消して", "complexity_tier": "T3", "furigana": "犯人[はんにん]は証拠[しょうこ]を消[け]して、姿[すがた]をくらました。", "sentence_source": "generated"}, {"text": "このマイクは周りの雑音を消す機能がある。", "target_word": "消す", "complexity_tier": "T4", "furigana": "このマイクは周[まわ]りの雑音[ざつおん]を消[け]す機能[きのう]がある。", "sentence_source": "generated"}, {"text": "彼女の笑顔が、私の不安を消してくれた。", "target_word": "消して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑顔[えがお]が、私[わたし]の不安[ふあん]を消[け]してくれた。", "sentence_source": "generated"}, {"text": "画像の編集で、写真に写った通行人を消した。", "target_word": "消した", "complexity_tier": "T4", "furigana": "画像[がぞう]の編集[へんしゅう]で、写真[しゃしん]に写[うつ]った通行人[つうこうにん]を消[け]した。", "sentence_source": "generated"}, {"text": "名簿から退会した人の名前を消しておいてください。", "target_word": "消して", "complexity_tier": "T4", "furigana": "名簿[めいぼ]から退会[たいかい]した人[ひと]の名前[なまえ]を消[け]しておいてください。", "sentence_source": "generated"}, {"text": "薬のにおいを消すために、窓を開けて空気を入れかえた。", "target_word": "消す", "complexity_tier": "T4", "furigana": "薬[くすり]のにおいを消[け]すために、窓[まど]を開[あ]けて空気[くうき]を入[い]れかえた。", "sentence_source": "generated"}, {"text": "努力しても、過去の失敗を消すことはできない。", "target_word": "消す", "complexity_tier": "T4", "furigana": "努力[どりょく]しても、過去[かこ]の失敗[しっぱい]を消[け]すことはできない。", "sentence_source": "generated"}, {"text": "歩いた足あとを消しながら、森の奥へ進んだ。", "target_word": "消し", "complexity_tier": "T4", "furigana": "歩[ある]いた足[あし]あとを消[け]しながら、森[もり]の奥[おく]へ進[すす]んだ。", "sentence_source": "generated"}, {"text": "強い香水が、料理の香りを消してしまった。", "target_word": "消して", "complexity_tier": "T3", "furigana": "強[つよ]い香水[こうすい]が、料理[りょうり]の香[かお]りを消[け]してしまった。", "sentence_source": "generated"}, {"text": "彼は会議でわざと自分の気配を消して、座っていた。", "target_word": "消して", "complexity_tier": "T4", "furigana": "彼[かれ]は会議[かいぎ]でわざと自分[じぶん]の気配[けはい]を消[け]して、座[すわ]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "消す", "label": "終止形"}, {"form": "消さ", "label": "未然形"}, {"form": "消し", "label": "連用形"}, {"form": "消せ", "label": "仮定形・命令形"}, {"form": "消そう", "label": "意志形"}, {"form": "消して", "label": "て形"}, {"form": "消した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "音・におい・感情・痕跡・存在などを取り除いて、ないものにする。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 入れかえ (Zipf 1.6)']::text[], '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39757, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消して", "is_correct": true, "explanation": "「証拠を消す」のて形。証拠を消して姿をくらました、という文脈に合う。"}, {"text": "消えて", "is_correct": false, "explanation": "自動詞「消える」は「証拠が消えて」となり、「証拠を」とは続かない。"}, {"text": "書いて", "is_correct": false, "explanation": "証拠は書くものではないので、「証拠を書いて」は文脈に合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "証拠は眠るものではないので、「証拠を眠って」は意味が成り立たない。"}], "explanations": {"消して": "「証拠を消す」のて形。証拠を消して姿をくらました、という文脈に合う。", "消えて": "自動詞「消える」は「証拠が消えて」となり、「証拠を」とは続かない。", "書いて": "証拠は書くものではないので、「証拠を書いて」は文脈に合わない。", "眠って": "証拠は眠るものではないので、「証拠を眠って」は意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "消して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前に部屋の床を消した。", "explanation": "ここは〈拭く〉の場面。床は拭くもので、〈消す〉とは言わない。"}, {"text": "宿題を消した。", "explanation": "ここは〈済ませる〉の場面。宿題は消すものではなく、済ませる（やる）ものなので合わない。"}, {"text": "窓を消した。", "explanation": "ここは〈閉める〉の場面。窓は閉めるものなので、消すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39757, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消す", "is_correct": true, "explanation": "終止形。「過去の失敗を消すことはできない」と、名詞句として「こと」につながる形。"}, {"text": "食べる", "is_correct": false, "explanation": "失敗は食べるものではないので、「過去の失敗を食べることはできない」は意味が成り立たない。"}, {"text": "歌う", "is_correct": false, "explanation": "失敗は歌うものではないので、「過去の失敗を歌うことはできない」は文脈に合わない。"}, {"text": "踊る", "is_correct": false, "explanation": "失敗は踊るものではないので、「過去の失敗を踊る」は文として成り立たない。"}], "explanations": {"消す": "終止形。「過去の失敗を消すことはできない」と、名詞句として「こと」につながる形。", "食べる": "失敗は食べるものではないので、「過去の失敗を食べることはできない」は意味が成り立たない。", "歌う": "失敗は歌うものではないので、「過去の失敗を歌うことはできない」は文脈に合わない。", "踊る": "失敗は踊るものではないので、「過去の失敗を踊る」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "消す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に枕を消した。", "explanation": "ここは〈整える〉の場面。枕は消すものではなく、整えるものなので、〈消す〉とは言わない。"}, {"text": "布団を消した。", "explanation": "ここは〈たたむ〉の場面。布団は消すものではなく、たたむものなので合わない。"}, {"text": "お湯を消した。", "explanation": "ここは〈止める〉の場面。お湯は止めるもので、〈取り除く・存在をなくす〉の〈消す〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39757, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の前に、スマホの通知音を消いた。", "corrected_sentence": "会議の前に、スマホの通知音を消した。", "error_description": "「消す」の過去形は「消した」。「消いた」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "消す", "is_correct": true, "explanation": "連体形（終止形と同じ形）。「雑音を消す機能」と、後ろの名詞「機能」を修飾している。"}, {"text": "消し", "is_correct": false, "explanation": "連用形。「消し機能」とは名詞を修飾できず、文が成り立たない。"}, {"text": "消せ", "is_correct": false, "explanation": "命令形・仮定形。名詞「機能」を修飾する形ではない。"}, {"text": "消そう", "is_correct": false, "explanation": "意志形。「消そう機能」とは名詞を修飾できず、意味が通らない。"}], "correct_form": "消す", "base_form": "消す", "form_label": "連体形", "sentence_index": 1, "explanations": {"消す": "連体形（終止形と同じ形）。「雑音を消す機能」と、後ろの名詞「機能」を修飾している。", "消し": "連用形。「消し機能」とは名詞を修飾できず、文が成り立たない。", "消せ": "命令形・仮定形。名詞「機能」を修飾する形ではない。", "消そう": "意志形。「消そう機能」とは名詞を修飾できず、意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39757, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨で滲んだ文字に消して、書き直した。", "corrected_sentence": "雨で滲んだ文字を消して、書き直した。", "error_description": "「消す」の対象（文字）は「を」で示す。「に」は場所や相手を示すため、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "消し", "is_correct": true, "explanation": "連用形。「足あとを消しながら進んだ」と、同時の動作を表す形。"}, {"text": "消して", "is_correct": false, "explanation": "て形。「消してながら」とは続かず、同時動作の文にならない。"}, {"text": "消さ", "is_correct": false, "explanation": "未然形。「消さながら」とは接続せず、文が成り立たない。"}, {"text": "消した", "is_correct": false, "explanation": "過去形。「消したながら」とは続かず、同時動作の意味にならない。"}], "correct_form": "消し", "base_form": "消す", "form_label": "連用形", "sentence_index": 7, "explanations": {"消し": "連用形。「足あとを消しながら進んだ」と、同時の動作を表す形。", "消して": "て形。「消してながら」とは続かず、同時動作の文にならない。", "消さ": "未然形。「消さながら」とは接続せず、文が成り立たない。", "消した": "過去形。「消したながら」とは続かず、同時動作の意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39758, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「ゴムで結ぶ」の手段を表す〈で〉。"}, {"text": "が", "is_correct": false, "explanation": "「ゴムが結んで」ではゴムが結ぶ主体になり、文の意味が合わない。"}, {"text": "を", "is_correct": false, "explanation": "「髪を」と並んで「ゴムを」が続き、目的語が二つになって不自然。"}, {"text": "に", "is_correct": false, "explanation": "「ゴムに結んで」は結ぶ相手として不自然で、ここは手段の〈で〉が必要。"}], "correct_answer": "で", "explanations": {"で": "正解。「ゴムで結ぶ」の手段を表す〈で〉。", "が": "「ゴムが結んで」ではゴムが結ぶ主体になり、文の意味が合わない。", "を": "「髪を」と並んで「ゴムを」が続き、目的語が二つになって不自然。", "に": "「ゴムに結んで」は結ぶ相手として不自然で、ここは手段の〈で〉が必要。"}, "error_tags": {"が": "主語", "を": "目的語の重複", "に": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
