INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39758, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "のびたり ちぢんだり する もの。", "primary_collocate": null, "pronunciation": "ごむ", "ipa": "ɡomɯ", "syllable_count": 2, "sentences": [{"text": "ゴムは引っぱると伸びて、はなすと元にもどる。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "ゴムは引[ひ]っぱると伸[の]びて、はなすと元[もと]にもどる。", "sentence_source": "generated"}, {"text": "髪をゴムでむすんで、運動場に出た。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "髪[かみ]をゴムでむすんで、運動場[うんどうじょう]に出[で]た。", "sentence_source": "generated"}, {"text": "ズボンのゴムがゆるくなって、すぐにずり落ちる。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "ズボンのゴムがゆるくなって、すぐにずり落[お]ちる。", "sentence_source": "generated"}, {"text": "妹はゴムを使って、おもしろいおもちゃを作った。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "妹[いもうと]はゴムを使[つか]って、おもしろいおもちゃを作[つく]った。", "sentence_source": "generated"}, {"text": "このゴムは、のばしすぎるとちぎれてしまう。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "このゴムは、のばしすぎるとちぎれてしまう。", "sentence_source": "generated"}, {"text": "ゴムの入った帽子は、あごにぴったりつく。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "ゴムの入[はい]った帽子[ぼうし]は、あごにぴったりつく。", "sentence_source": "generated"}, {"text": "箱の口をゴムで止めて、かばんに入れた。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "箱[はこ]の口[くち]をゴムで止[と]めて、かばんに入[い]れた。", "sentence_source": "generated"}, {"text": "古いゴムは固くなって、もう伸びない。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "古[ふる]いゴムは固[かた]くなって、もう伸[の]びない。", "sentence_source": "generated"}, {"text": "私はゴムを指にかけて、ぱちんと飛ばして遊んだ。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "私[わたし]はゴムを指[ゆび]にかけて、ぱちんと飛[と]ばして遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "パンツのゴムが切れたので、母が新しいのを通した。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "パンツのゴムが切[き]れたので、母[はは]が新[あたら]しいのを通[とお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゴム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "のびたり縮んだりする、ひも状や輪状の身近な物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 引っぱる (Zipf 1.77)','sentence 2 above tier T3: contains vocabulary far above tier T3: ずり落ちる (Zipf 1.66)']::text[], '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39758, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゴム", "is_correct": true, "explanation": "正解。引っぱると伸びて、はなすと元にもどるのは伸縮するゴムの性質。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は引っぱってもほとんど伸びず、はなしても元にはもどらない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は引っぱると破れてしまい、伸びて元にもどることはない。"}, {"text": "石", "is_correct": false, "explanation": "石は引っぱっても伸びず、伸び縮みする性質をもたない。"}], "explanations": {"ゴム": "正解。引っぱると伸びて、はなすと元にもどるのは伸縮するゴムの性質。", "鉄": "鉄は引っぱってもほとんど伸びず、はなしても元にはもどらない。", "紙": "紙は引っぱると破れてしまい、伸びて元にもどることはない。", "石": "石は引っぱっても伸びず、伸び縮みする性質をもたない。"}, "sentence_index": 0, "correct_answer": "ゴム"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "ゴムを噛んで、口の中をさっぱりさせた。", "explanation": "ここは〈ガム〉の意味。ゴムは噛んで食べる物ではないので、ガムと取り違えた使い方は合わない。"}, {"text": "水をよく吸うゴムで、食器を洗った。", "explanation": "ここは〈スポンジ〉の意味。ゴムは水を吸わず、食器を洗う道具ではないので合わない。"}, {"text": "船をつなぐゴムが切れて、船は流されてしまった。", "explanation": "ここは〈ロープ〉の意味。船をつなぎ止めるには強い綱が必要で、伸び縮みするゴムでは役目を果たせない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39758, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゴム", "is_correct": true, "explanation": "正解。箱の口を止めるのに使う、伸縮するゴムの用法。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖では箱の口を止められず、「砂糖で止めて」は意味が通らない。"}, {"text": "水", "is_correct": false, "explanation": "水は箱の口を止める材料にはならず、この文に入らない。"}, {"text": "砂", "is_correct": false, "explanation": "砂は箱の口を止められず、「砂で止めて」は不自然。"}], "explanations": {"ゴム": "正解。箱の口を止めるのに使う、伸縮するゴムの用法。", "砂糖": "砂糖では箱の口を止められず、「砂糖で止めて」は意味が通らない。", "水": "水は箱の口を止める材料にはならず、この文に入らない。", "砂": "砂は箱の口を止められず、「砂で止めて」は不自然。"}, "sentence_index": 6, "correct_answer": "ゴム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゴムを強く蹴ったら、遠くまで飛んだ。", "explanation": "ここは〈ボール〉の意味。ゴムは蹴って飛ばす物ではないので、ボールと取り違えた使い方は合わない。"}, {"text": "ゴムを折って、飛行機を作った。", "explanation": "ここは〈紙〉の意味。ゴムは折って形を作る材料ではなく、伸び縮みする物なので合わない。"}, {"text": "ゴムと糸で、ボタンを縫いつけた。", "explanation": "ここは〈針〉の意味。ゴムは布を縫う道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39758, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "髪をゴムを結んで、出かけた。", "corrected_sentence": "髪をゴムで結んで、出かけた。", "error_description": "「ゴムで結ぶ」の手段を表す「で」が正しい。「を」は「髪を」が既に目的語にあるため、二つ続けられず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
