INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39759, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「ゴムが使われている」のゴムは主語。"}, {"text": "を", "is_correct": false, "explanation": "「ゴムを使われている」は受け身の主語に〈を〉は使えず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「強いゴムの使われている」は文として続かず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「強いゴムと使われている」は並列の〈と〉になり、意味が合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「ゴムが使われている」のゴムは主語。", "を": "「ゴムを使われている」は受け身の主語に〈を〉は使えず、不自然。", "の": "「強いゴムの使われている」は文として続かず、不自然。", "と": "「強いゴムと使われている」は並列の〈と〉になり、意味が合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
