INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39759, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゴムの木の樹液などから作る、よく伸び縮みする物質。", "primary_collocate": null, "pronunciation": "ごむ", "ipa": "ɡomɯ", "syllable_count": 2, "sentences": [{"text": "ゴムは、ゴムの木の樹液から作られる。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "ゴムは、ゴムの木[き]の樹液[じゅえき]から作[つく]られる。", "sentence_source": "generated"}, {"text": "タイヤには、強いゴムが使われている。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "タイヤには、強[つよ]いゴムが使[つか]われている。", "sentence_source": "generated"}, {"text": "ゴムは水を通さないので、長靴の材料になる。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "ゴムは水[みず]を通[とお]さないので、長靴[ながぐつ]の材料[ざいりょう]になる。", "sentence_source": "generated"}, {"text": "天然のゴムは、東南アジアの農園で多く作られる。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "天然[てんねん]のゴムは、東南[とうなん]アジアの農園[のうえん]で多[おお]く作[つく]られる。", "sentence_source": "generated"}, {"text": "工場では、ゴムに薬品を混ぜて強さを高める。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、ゴムに薬品[やくひん]を混[ま]ぜて強[つよ]さを高[たか]める。", "sentence_source": "generated"}, {"text": "ゴムは熱に弱く、夏は柔らかくなってべたつくことがある。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "ゴムは熱[ねつ]に弱[よわ]く、夏[なつ]は柔[やわ]らかくなってべたつくことがある。", "sentence_source": "generated"}, {"text": "医者は、ゴムの手袋をはめて手術をした。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、ゴムの手袋[てぶくろ]をはめて手術[しゅじゅつ]をした。", "sentence_source": "generated"}, {"text": "石油からも、ゴムに似た材料が作られる。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "石油[せきゆ]からも、ゴムに似[に]た材料[ざいりょう]が作[つく]られる。", "sentence_source": "generated"}, {"text": "靴の底は、すべりにくいゴムでできている。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "靴[くつ]の底[そこ]は、すべりにくいゴムでできている。", "sentence_source": "generated"}, {"text": "ゴムは電気を通しにくいので、電線のカバーにも使われる。", "target_word": "ゴム", "complexity_tier": "T3", "furigana": "ゴムは電気[でんき]を通[とお]しにくいので、電線[でんせん]のカバーにも使[つか]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゴム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ゴムの木の樹液などから作る、よく伸び縮みする材料（物質）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: べたつく (Zipf 1.37)']::text[], '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39759, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゴム", "is_correct": true, "explanation": "正解。ゴムの木の樹液から作られる材料がゴム。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は鉱石から作られ、樹液から作られることはない。"}, {"text": "石", "is_correct": false, "explanation": "石は地中の鉱物で、樹液から作られるものではない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は水が凍ったもので、樹液から作られるものではない。"}], "explanations": {"ゴム": "正解。ゴムの木の樹液から作られる材料がゴム。", "鉄": "鉄は鉱石から作られ、樹液から作られることはない。", "石": "石は地中の鉱物で、樹液から作られるものではない。", "氷": "氷は水が凍ったもので、樹液から作られるものではない。"}, "sentence_index": 0, "correct_answer": "ゴム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "髪のゴムが切れたので、新しいのに替えた。", "explanation": "ここは〈輪ゴム〉（髪を結ぶ製品）の意味。このゴムは樹液から作る物質のことで、製品を指す使い方は合わない。"}, {"text": "ズボンのゴムが伸びきったので、はき替えた。", "explanation": "ここは〈ゴムひも〉（衣類に入れる伸縮部品）の意味。物質の名前として使うと部品を指す意味になり、合わない。"}, {"text": "鉛筆の後ろについたゴムで、書き間違えた字を消した。", "explanation": "ここは〈消しゴム〉（鉛筆の先のゴム部分）の意味。ゴムは樹液から作る物質なので、製品の部品を指す使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39759, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゴム", "is_correct": true, "explanation": "正解。医療用の手袋は、ゴム製が多い。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖の手袋は存在せず、手術の文に合わない。"}, {"text": "水", "is_correct": false, "explanation": "水の手袋は手術に使えず、この文に合わない。"}, {"text": "砂", "is_correct": false, "explanation": "砂の手袋は手術に使えず、この文に合わない。"}], "explanations": {"ゴム": "正解。医療用の手袋は、ゴム製が多い。", "砂糖": "砂糖の手袋は存在せず、手術の文に合わない。", "水": "水の手袋は手術に使えず、この文に合わない。", "砂": "砂の手袋は手術に使えず、この文に合わない。"}, "sentence_index": 6, "correct_answer": "ゴム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "書類に、ゴムで日付を押した。", "explanation": "ここは〈ゴム印〉（スタンプ）の意味。ゴムは物質のことなので、判子を指す使い方は合わない。"}, {"text": "ゴムをかけて、友達と跳んで遊んだ。", "explanation": "ここは〈ゴム跳び〉に使う伸縮するひもの意味。物質の名前としては、遊び道具のひもを指すので合わない。"}, {"text": "ゴムを、窓辺の鉢に植えた。", "explanation": "ここは〈植物〉（ゴムの木）の意味。ゴムは物質を指すので、鉢に植える植物の使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39759, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゴムへ、樹液から作られる。", "corrected_sentence": "ゴムは、樹液から作られる。", "error_description": "主題を示す「は」が正しい。「へ」は方向を表すので、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39759, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電線のカバーには、ゴムに使われる。", "corrected_sentence": "電線のカバーには、ゴムが使われる。", "error_description": "「使われる」の主語は「が」。「に」は誤りで、ゴムを主語にする形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
