INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39760, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「もし」という意味で、仮定の話をするときに使う言葉。", "primary_collocate": null, "pronunciation": "もし", "ipa": "moɕi", "syllable_count": 2, "sentences": [{"text": "もし明日雨が降ったら、家で本を読みます。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし明日[あした]雨[あめ]が降[ふ]ったら、家[いえ]で本[ほん]を読[よ]みます。", "sentence_source": "generated"}, {"text": "もし時間があれば、一緒に映画を見に行きませんか。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし時間[じかん]があれば、一緒[いっしょ]に映画[えいが]を見[み]に行[い]きませんか。", "sentence_source": "generated"}, {"text": "もし道に迷ったら、この番号に電話してください。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし道[みち]に迷[まよ]ったら、この番号[ばんごう]に電話[でんわ]してください。", "sentence_source": "generated"}, {"text": "もし頭が痛いなら、今日は早く帰って休んでください。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし頭[あたま]が痛[いた]いなら、今日[きょう]は早[はや]く帰[かえ]って休[やす]んでください。", "sentence_source": "generated"}, {"text": "もし駅で友達に会ったら、よろしくと伝えてください。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし駅[えき]で友達[ともだち]に会[あ]ったら、よろしくと伝[つた]えてください。", "sentence_source": "generated"}, {"text": "もし私が先生だったら、毎日宿題を出しません。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし私[わたし]が先生[せんせい]だったら、毎日[まいにち]宿題[しゅくだい]を出[だ]しません。", "sentence_source": "generated"}, {"text": "もし日曜日が忙しくなければ、うちに遊びに来てください。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし日曜日[にちようび]が忙[いそが]しくなければ、うちに遊[あそ]びに来[き]てください。", "sentence_source": "generated"}, {"text": "もし分からない言葉があったら、辞書で調べてください。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし分[わ]からない言葉[ことば]があったら、辞書[じしょ]で調[しら]べてください。", "sentence_source": "generated"}, {"text": "もし電車が止まったら、タクシーで行きます。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし電車[でんしゃ]が止[と]まったら、タクシーで行[い]きます。", "sentence_source": "generated"}, {"text": "もしお金がたくさんあれば、世界中を旅行したいです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もしお金[かね]がたくさんあれば、世界中[せかいじゅう]を旅行[りょこう]したいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "もし", "label": "基本形"}, {"form": "若し", "label": "漢字表記"}], "register": "丁寧", "sense_fingerprint": "日常の仮定の話を始める副詞。「もし〜たら／ば」で条件を示す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39760, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "文頭で仮定の条件を示す副詞。後ろの「たら」と呼応する。"}, {"text": "やっと", "is_correct": false, "explanation": "時間をかけて実現したことを表すので、まだ起きていない仮定の雨には合わない。"}, {"text": "ずっと", "is_correct": false, "explanation": "継続を表す副詞で、仮定の条件を作る働きがないため、ここには入らない。"}, {"text": "なぜ", "is_correct": false, "explanation": "理由を問う語で、仮定の文の頭に置くと文が成り立たない。"}], "explanations": {"もし": "文頭で仮定の条件を示す副詞。後ろの「たら」と呼応する。", "やっと": "時間をかけて実現したことを表すので、まだ起きていない仮定の雨には合わない。", "ずっと": "継続を表す副詞で、仮定の条件を作る働きがないため、ここには入らない。", "なぜ": "理由を問う語で、仮定の文の頭に置くと文が成り立たない。"}, "sentence_index": 0, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もし夢のような一日でした。", "explanation": "「夢のような一日だった」と例える文に、条件を示す〈もし〉は合わない。"}, {"text": "もしほとんど終わりました。", "explanation": "「ほとんど終わった」と大部分を述べる文に、条件を示す〈もし〉は合わない。"}, {"text": "もしとても寒くてたまりません。", "explanation": "「とても寒くてたまらない」と程度を強める文に、条件を示す〈もし〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39760, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "文頭で仮定の条件を示す副詞。後ろの「なければ」と呼応する。"}, {"text": "ほとんど", "is_correct": false, "explanation": "程度や大部分を表す副詞で、仮定の条件を導く働きがないため合わない。"}, {"text": "ついに", "is_correct": false, "explanation": "ある時点で最終的に起きたことを表すので、仮定の文には入らない。"}, {"text": "なぜ", "is_correct": false, "explanation": "理由を問う語で、仮定の文の頭に置くと意味が通らない。"}], "explanations": {"もし": "文頭で仮定の条件を示す副詞。後ろの「なければ」と呼応する。", "ほとんど": "程度や大部分を表す副詞で、仮定の条件を導く働きがないため合わない。", "ついに": "ある時点で最終的に起きたことを表すので、仮定の文には入らない。", "なぜ": "理由を問う語で、仮定の文の頭に置くと意味が通らない。"}, "sentence_index": 6, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "もしその通りでした。", "explanation": "「その通りだった」と断定を強める文に、条件を示す〈もし〉は合わない。"}, {"text": "もし彼に会えました。", "explanation": "「彼に会えた」と実現した結果を報告する文に、条件を示す〈もし〉は合わない。"}, {"text": "もしついに夢が叶いました。", "explanation": "「夢が叶った」と結末を述べる文に、条件を示す〈もし〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39760, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "もし駅に着いたので、電話をください。", "corrected_sentence": "もし駅に着いたら、電話をください。", "error_description": "「もし」は「たら・ば・なら」と呼応する仮定の表現。「ので」は理由を表すため仮定の文には合わず、「着いたら」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39760, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "もし暑いでしょう、窓を開けてください。", "corrected_sentence": "もし暑ければ、窓を開けてください。", "error_description": "「もし」の仮定の文の末尾が推量の「でしょう」になっている。仮定の条件を表すには「暑ければ」の形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
