INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39761, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "仮定の条件を示す副詞。現実とは異なる事柄を仮定したり、可能性が低いことを想定したりする際に用いる。", "primary_collocate": null, "pronunciation": "もし", "ipa": "moɕi", "syllable_count": 2, "sentences": [{"text": "もし私が鳥だったら、今すぐあの山まで飛んで行きたいです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし私[わたし]が鳥[とり]だったら、今[いま]すぐあの山[やま]まで飛[と]んで行[い]きたいです。", "sentence_source": "generated"}, {"text": "もし宝くじで一億円が当たったら、大きい家を買います。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし宝[たから]くじで一億円[いちおくえん]が当[あ]たったら、大[おお]きい家[いえ]を買[か]います。", "sentence_source": "generated"}, {"text": "もし昨日の試合に勝っていたら、優勝できたのに、残念です。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし昨日[きのう]の試合[しあい]に勝[か]っていたら、優勝[ゆうしょう]できたのに、残念[ざんねん]です。", "sentence_source": "generated"}, {"text": "もし一年前に戻れるなら、もっと勉強したいです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし一年前[いちねんまえ]に戻[もど]れるなら、もっと勉強[べんきょう]したいです。", "sentence_source": "generated"}, {"text": "もし魔法が使えたら、まず空を飛んでみたいです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし魔法[まほう]が使[つか]えたら、まず空[そら]を飛[と]んでみたいです。", "sentence_source": "generated"}, {"text": "もし私が生まれていなかったら、この町は今と違っていたかもしれません。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし私[わたし]が生[う]まれていなかったら、この町[まち]は今[いま]と違[ちが]っていたかもしれません。", "sentence_source": "generated"}, {"text": "もし地球に水がなかったら、人は生きられません。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし地球[ちきゅう]に水[みず]がなかったら、人[ひと]は生[い]きられません。", "sentence_source": "generated"}, {"text": "もしあの時雨が降っていなかったら、私たちは出会わなかったでしょう。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もしあの時[とき]雨[あめ]が降[ふ]っていなかったら、私[わたし]たちは出会[であ]わなかったでしょう。", "sentence_source": "generated"}, {"text": "もし猫が話せたら、毎日いろいろ聞いてみたいです。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし猫[ねこ]が話[はな]せたら、毎日[まいにち]いろいろ聞[き]いてみたいです。", "sentence_source": "generated"}, {"text": "もし私がお金持ちなら、学校をたくさん作ります。", "target_word": "もし", "complexity_tier": "T3", "furigana": "もし私[わたし]がお金持[かねも]ちなら、学校[がっこう]をたくさん作[つく]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "もし", "label": "基本形"}, {"form": "若し", "label": "漢字表記"}], "register": "丁寧", "sense_fingerprint": "現実とは違うことや、起こりそうにないことを想像して仮定するときの「もし」。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39761, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "現実とは違う事柄を仮定する副詞。後ろの「だったら」と呼応する。"}, {"text": "ずっと", "is_correct": false, "explanation": "継続を表す副詞で、現実と違う仮定を作る働きがないため合わない。"}, {"text": "やっと", "is_correct": false, "explanation": "時間をかけて実現したことを表すので、鳥になるという仮定には合わない。"}, {"text": "なぜ", "is_correct": false, "explanation": "理由を問う語で、仮定の文の頭に置くと意味が通らない。"}], "explanations": {"もし": "現実とは違う事柄を仮定する副詞。後ろの「だったら」と呼応する。", "ずっと": "継続を表す副詞で、現実と違う仮定を作る働きがないため合わない。", "やっと": "時間をかけて実現したことを表すので、鳥になるという仮定には合わない。", "なぜ": "理由を問う語で、仮定の文の頭に置くと意味が通らない。"}, "sentence_index": 0, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "もし夢のような一日でした。", "explanation": "「夢のような一日だった」と例える文に、条件を示す〈もし〉は合わない。"}, {"text": "もしほとんど終わりました。", "explanation": "「ほとんど終わった」と大部分を述べる文に、条件を示す〈もし〉は合わない。"}, {"text": "もしとても寒くてたまりません。", "explanation": "「とても寒くてたまらない」と程度を強める文に、条件を示す〈もし〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39761, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もし", "is_correct": true, "explanation": "現実とは違う事柄を仮定する副詞。後ろの「なかったら」と呼応する。"}, {"text": "ほとんど", "is_correct": false, "explanation": "大部分を表す副詞で、仮定の条件を作らないので、ここには入らない。"}, {"text": "やっと", "is_correct": false, "explanation": "時間をかけて実現したことを表すので、水がないという仮定には合わない。"}, {"text": "ついに", "is_correct": false, "explanation": "最終的に起きたことを表すので、仮定の文には入らない。"}], "explanations": {"もし": "現実とは違う事柄を仮定する副詞。後ろの「なかったら」と呼応する。", "ほとんど": "大部分を表す副詞で、仮定の条件を作らないので、ここには入らない。", "やっと": "時間をかけて実現したことを表すので、水がないという仮定には合わない。", "ついに": "最終的に起きたことを表すので、仮定の文には入らない。"}, "sentence_index": 6, "correct_answer": "もし"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "もし彼に会えました。", "explanation": "「長い末に彼に会えた」と実現を報告する文に、仮定の〈もし〉は合わない。"}, {"text": "もしついに夢が叶いました。", "explanation": "「とうとう夢が叶った」と結末を述べる文に、仮定の〈もし〉は合わない。"}, {"text": "もしその通りでした。", "explanation": "「まさにその通りだった」と断定を強める文に、仮定の〈もし〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39761, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "もし雨で中止になったので、来週に延期します。", "corrected_sentence": "もし雨で中止になったら、来週に延期します。", "error_description": "「もし」は「たら」と呼応する仮定の表現。「ので」は理由を表すため、仮定の文では「中止になったら」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39761, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "もし明日暑いでしょう、冷たい水を飲みましょう。", "corrected_sentence": "もし明日暑ければ、冷たい水を飲みましょう。", "error_description": "「もし」に続く形が推量の「でしょう」になっている。仮定の条件を表すには「暑ければ」の形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39762, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「間違いに赤い線を引く」の「に」。線を引く対象の場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」を重ねると「作文の間違いを赤い線を引いてくれました」となり、目的語が二つになって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すので、線を引く対象には使わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、比べる文脈のないここでは合わない。"}], "correct_answer": "に", "explanations": {"に": "「間違いに赤い線を引く」の「に」。線を引く対象の場所を示す。", "を": "「を」を重ねると「作文の間違いを赤い線を引いてくれました」となり、目的語が二つになって不自然。", "へ": "「へ」は移動の方向を示すので、線を引く対象には使わない。", "より": "「より」は比較の基準を示すので、比べる文脈のないここでは合わない。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39762, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「間違いがあります」の「が」。存在する対象を示す格助詞で、ここで必要。"}, {"text": "の", "is_correct": false, "explanation": "「間違いのあります」は「の」が名詞を修飾する形で、「あります」に続かず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「間違いからあります」は起点を示す「から」が存在を表す文に続かず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「間違いとあります」は並列や引用の「と」が存在の文に続かず、意味を成さない。"}], "correct_answer": "が", "explanations": {"が": "「間違いがあります」の「が」。存在する対象を示す格助詞で、ここで必要。", "の": "「間違いのあります」は「の」が名詞を修飾する形で、「あります」に続かず不自然。", "から": "「間違いからあります」は起点を示す「から」が存在を表す文に続かず、成り立たない。", "と": "「間違いとあります」は並列や引用の「と」が存在の文に続かず、意味を成さない。"}, "error_tags": {"の": "修飾", "から": "起点", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39762, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "作ったものが正しくないこと。", "primary_collocate": null, "pronunciation": "まちがい", "ipa": "matɕiɡai", "syllable_count": 4, "sentences": [{"text": "レポートを出す前に、数字の間違いがないか確認しました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "レポートを出[だ]す前[まえ]に、数字[すうじ]の間違[まちが]いがないか確認[かくにん]しました。", "sentence_source": "generated"}, {"text": "先生は作文の間違いに赤い線を引いてくれました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "先生[せんせい]は作文[さくぶん]の間違[まちが]いに赤[あか]い線[せん]を引[ひ]いてくれました。", "sentence_source": "generated"}, {"text": "地図に間違いがあったため、私たちは違う駅に着いてしまいました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "地図[ちず]に間違[まちが]いがあったため、私[わたし]たちは違[ちが]う駅[えき]に着[つ]いてしまいました。", "sentence_source": "generated"}, {"text": "計算の間違いを直したら、答えが合いました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "計算[けいさん]の間違[まちが]いを直[なお]したら、答[こた]えが合[あ]いました。", "sentence_source": "generated"}, {"text": "料理の本に間違いがあり、塩の量が多すぎました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "料理[りょうり]の本[ほん]に間違[まちが]いがあり、塩[しお]の量[りょう]が多[おお]すぎました。", "sentence_source": "generated"}, {"text": "請求書の間違いに気づいて、すぐ会社に連絡しました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "請求書[せいきゅうしょ]の間違[まちが]いに気[き]づいて、すぐ会社[かいしゃ]に連絡[れんらく]しました。", "sentence_source": "generated"}, {"text": "翻訳の間違いを見つけたので、担当の人に伝えました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "翻訳[ほんやく]の間違[まちが]いを見[み]つけたので、担当[たんとう]の人[ひと]に伝[つた]えました。", "sentence_source": "generated"}, {"text": "この書類には、名前の漢字に間違いがあります。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "この書類[しょるい]には、名前[なまえ]の漢字[かんじ]に間違[まちが]いがあります。", "sentence_source": "generated"}, {"text": "間違いのない資料を作るために、二人で見直しました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "間違[まちが]いのない資料[しりょう]を作[つく]るために、二人[ふたり]で見直[みなお]しました。", "sentence_source": "generated"}, {"text": "説明書の間違いが多いと、使う人は不安になります。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の間違[まちが]いが多[おお]いと、使[つか]う人[ひと]は不安[ふあん]になります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "間違い", "label": "基本形"}, {"form": "間違え", "label": "動詞「間違える」の連用形"}], "register": "neutral", "sense_fingerprint": "an error in something produced (document, calculation, map, translation)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39762, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "間違い", "is_correct": true, "explanation": "「数字の間違い」は計算などの誤りを指し、「がないか確認」と合う。"}, {"text": "間違える", "is_correct": false, "explanation": "動詞の辞書形で、「数字の〜がないか」の名詞の位置に入らず、文が成り立たない。"}, {"text": "間違えて", "is_correct": false, "explanation": "て形の動詞で、名詞の位置に入らず、「数字の〜がないか確認」が成り立たない。"}, {"text": "感想", "is_correct": false, "explanation": "「感想」は感じたことを言う語で、確認すべき数字の誤りとは結びつかない。"}], "explanations": {"間違い": "「数字の間違い」は計算などの誤りを指し、「がないか確認」と合う。", "間違える": "動詞の辞書形で、「数字の〜がないか」の名詞の位置に入らず、文が成り立たない。", "間違えて": "て形の動詞で、名詞の位置に入らず、「数字の〜がないか確認」が成り立たない。", "感想": "「感想」は感じたことを言う語で、確認すべき数字の誤りとは結びつかない。"}, "sentence_index": 0, "correct_answer": "間違い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい料理に挑戦したが、間違いに終わった。", "explanation": "ここは〈失敗〉の意味。「〜に終わった」は試みの結果がうまくいかないことを言うので、作ったものの誤りを指す間違いは合わない。"}, {"text": "その言葉は、彼女に大きな間違いを与えた。", "explanation": "ここは〈誤解〉の意味。誤解を与えるとは言うが、誤りである間違いは与えるものではないので合わない。"}, {"text": "その映画を見た後も、なぜか間違いを感じた。", "explanation": "ここは〈違和感〉の意味。違和感を感じるとは言うが、誤りである間違いは感じるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39762, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "間違い", "is_correct": true, "explanation": "「翻訳の間違い」は訳の誤りを指し、見つけた対象として合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様なので、翻訳文の中から見つけるものではない。"}, {"text": "楽器", "is_correct": false, "explanation": "「楽器」は演奏の道具で、翻訳の中から見つけるものとしては合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「季節」は時期を指すので、翻訳の中の誤りを表すことはできない。"}], "explanations": {"間違い": "「翻訳の間違い」は訳の誤りを指し、見つけた対象として合う。", "天気": "「天気」は空模様なので、翻訳文の中から見つけるものではない。", "楽器": "「楽器」は演奏の道具で、翻訳の中から見つけるものとしては合わない。", "季節": "「季節」は時期を指すので、翻訳の中の誤りを表すことはできない。"}, "sentence_index": 6, "correct_answer": "間違い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店の料理は、一度食べたら忘れられない間違いだ。", "explanation": "ここは〈絶品〉の意味。絶品だと言うが、作ったものの誤りを表す間違いは褒め言葉にならないので合わない。"}, {"text": "チームは大事な試合で、大きな間違いを喫した。", "explanation": "ここは〈敗北〉の意味。敗北を喫すると言うが、誤りである間違いは喫するものではないので合わない。"}, {"text": "その言葉は、彼の心に深い間違いとして残った。", "explanation": "ここは〈傷〉の意味。心に残るものは傷と言い、間違いは作ったものの誤りを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39762, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は提出されたレポートの間違いに一つずつ確認した。", "corrected_sentence": "先生は提出されたレポートの間違いを一つずつ確認した。", "error_description": "「確認する」は目的語に「を」を取る。間違いには「を」が正しく、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39762, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "担当者は見積もりの間違いが直して、すぐに送り直した。", "corrected_sentence": "担当者は見積もりの間違いを直して、すぐに送り直した。", "error_description": "「直す」は目的語に「を」を取る。間違いには「を」が正しく、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
