INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39763, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "正しくないこと。誤り。", "primary_collocate": null, "pronunciation": "まちがい", "ipa": "matɕiɡai", "syllable_count": 4, "sentences": [{"text": "私は自分の間違いを認めて、みんなに謝りました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "私[わたし]は自分[じぶん]の間違[まちが]いを認[みと]めて、みんなに謝[あやま]りました。", "sentence_source": "generated"}, {"text": "私は人生の道を選ぶとき、大きな間違いをしてしまいました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "私[わたし]は人生[じんせい]の道[みち]を選[えら]ぶとき、大[おお]きな間違[まちが]いをしてしまいました。", "sentence_source": "generated"}, {"text": "先に結論を決めるのは間違いだと、先生は言いました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "先[さき]に結論[けつろん]を決[き]めるのは間違[まちが]いだと、先生[せんせい]は言[い]いました。", "sentence_source": "generated"}, {"text": "間違いを恐れていたら、新しいことは何も学べません。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "間違[まちが]いを恐[おそ]れていたら、新[あたら]しいことは何[なに]も学[まな]べません。", "sentence_source": "generated"}, {"text": "「地球は平らだ」という考えは間違いです。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "「地球[ちきゅう]は平[たい]らだ」という考[かんが]えは間違[まちが]いです。", "sentence_source": "generated"}, {"text": "友達の間違いを笑うのは、よくないことです。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "友達[ともだち]の間違[まちが]いを笑[わら]うのは、よくないことです。", "sentence_source": "generated"}, {"text": "彼は間違いに気づくと、すぐに考えを変えました。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "彼[かれ]は間違[まちが]いに気[き]づくと、すぐに考[かんが]えを変[か]えました。", "sentence_source": "generated"}, {"text": "その意見は、事実と合わないので間違いです。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "その意見[いけん]は、事実[じじつ]と合[あ]わないので間違[まちが]いです。", "sentence_source": "generated"}, {"text": "間違いから学ぶことも、成長には大切です。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "間違[まちが]いから学[まな]ぶことも、成長[せいちょう]には大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "若いころの間違いを、今でも時々思い出します。", "target_word": "間違い", "complexity_tier": "T3", "furigana": "若[わか]いころの間違[まちが]いを、今[いま]でも時々[ときどき]思[おも]い出[だ]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "間違い", "label": "基本形"}, {"form": "間違え", "label": "動詞「間違える」の連用形"}], "register": "neutral", "sense_fingerprint": "being incorrect or a mistake in general (a wrong idea, judgment, or act)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39763, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "間違い", "is_correct": true, "explanation": "「自分の間違いを認める」は自分の誤りを認めるという意味で、文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「自分の天気を認める」は意味が通らない。「天気」は空模様で、認める対象ではない。"}, {"text": "楽器", "is_correct": false, "explanation": "「楽器」は演奏の道具で、自分の過ちを認めるという文に入らない。"}, {"text": "駐車場", "is_correct": false, "explanation": "「駐車場」は車を停める場所で、自分の何かを認めるという文には合わない。"}], "explanations": {"間違い": "「自分の間違いを認める」は自分の誤りを認めるという意味で、文脈に合う。", "天気": "「自分の天気を認める」は意味が通らない。「天気」は空模様で、認める対象ではない。", "楽器": "「楽器」は演奏の道具で、自分の過ちを認めるという文に入らない。", "駐車場": "「駐車場」は車を停める場所で、自分の何かを認めるという文には合わない。"}, "sentence_index": 0, "correct_answer": "間違い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その映画は、一瞬で私の間違いを奪った。", "explanation": "ここは〈心を奪う〉の意味。心を奪うとは言うが、誤りである間違いは人の心を奪うものではないので合わない。"}, {"text": "昨夜は間違いにうなされた。", "explanation": "ここは〈悪夢〉の意味。うなされるのは悪夢で、間違いは誤りそのものを指すので合わない。"}, {"text": "私は甘い間違いに負けた。", "explanation": "ここは〈誘惑〉の意味。誘惑に負けると言い、誤りである間違いを負ける対象とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39763, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "間違い", "is_correct": true, "explanation": "「間違いに気づく」は誤りに気づくという意味で、考えを変える流れに合う。"}, {"text": "間違える", "is_correct": false, "explanation": "動詞の辞書形で、「彼は〜に気づく」の名詞の位置に入らず、文が成り立たない。"}, {"text": "間違えた", "is_correct": false, "explanation": "動詞の過去形で、名詞の位置に入らず、「〜に気づく」が成り立たない。"}, {"text": "間違えない", "is_correct": false, "explanation": "否定形の動詞で、名詞の位置に入らず、文が成り立たない。"}], "explanations": {"間違い": "「間違いに気づく」は誤りに気づくという意味で、考えを変える流れに合う。", "間違える": "動詞の辞書形で、「彼は〜に気づく」の名詞の位置に入らず、文が成り立たない。", "間違えた": "動詞の過去形で、名詞の位置に入らず、「〜に気づく」が成り立たない。", "間違えない": "否定形の動詞で、名詞の位置に入らず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "間違い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その会議は、間違いの合図で始まった。", "explanation": "ここは〈合図〉の意味。合図で始まるとは言うが、誤りである間違いは合図になるものではないので合わない。"}, {"text": "彼は合格の間違いをかみしめた。", "explanation": "ここは〈喜び〉の意味。かみしめるのは喜びや感慨で、誤りは合わない。"}, {"text": "その寒い冬は、私の心に温かい間違いを灯した。", "explanation": "ここは〈希望〉の意味。希望を灯すとは言うが、誤りである間違いは灯すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39763, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は自分の間違いに認めて、みんなに謝った。", "corrected_sentence": "彼は自分の間違いを認めて、みんなに謝った。", "error_description": "「認める」は目的語に「を」を取る。間違いには「を」が正しく、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39763, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ間違えを繰り返さないように、ノートに書いた。", "corrected_sentence": "同じ間違いを繰り返さないように、ノートに書いた。", "error_description": "誤りは「間違えを」。「間違え」は動詞「間違える」の連用形で、名詞の位置には「間違い」を使う。正しくは「間違いを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39764, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不確実", "is_correct": true, "explanation": "確実の対義語。間違いがなく、たしかであることの反対。"}, {"text": "簡単", "is_correct": false, "explanation": "形状詞だが、確実の対義語ではない。難しさを表す語で、この意味の反対語ではない。"}, {"text": "必要", "is_correct": false, "explanation": "形状詞だが、確実の対義語ではない。必要かどうかを表す語で、この意味の反対語ではない。"}, {"text": "穏やか", "is_correct": false, "explanation": "形状詞だが、確実の対義語ではない。性質や様子を表す語で、この意味の反対語ではない。"}], "correct_answer": "不確実", "explanations": {"不確実": "確実の対義語。間違いがなく、たしかであることの反対。", "簡単": "形状詞だが、確実の対義語ではない。難しさを表す語で、この意味の反対語ではない。", "必要": "形状詞だが、確実の対義語ではない。必要かどうかを表す語で、この意味の反対語ではない。", "穏やか": "形状詞だが、確実の対義語ではない。性質や様子を表す語で、この意味の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39764, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不確実", "is_correct": true, "explanation": "確実の対義語。間違いがなく、たしかであることの反対。"}, {"text": "豊富", "is_correct": false, "explanation": "形状詞だが、確実の対義語ではない。量が多いことを表す語で、この意味の反対語ではない。"}, {"text": "静か", "is_correct": false, "explanation": "形状詞だが、確実の対義語ではない。音や様子が穏やかなことを表す語で、この意味の反対語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "形状詞だが、確実の対義語ではない。注意深く行うことを表す語で、この意味の反対語ではない。"}], "correct_answer": "不確実", "explanations": {"不確実": "確実の対義語。間違いがなく、たしかであることの反対。", "豊富": "形状詞だが、確実の対義語ではない。量が多いことを表す語で、この意味の反対語ではない。", "静か": "形状詞だが、確実の対義語ではない。音や様子が穏やかなことを表す語で、この意味の反対語ではない。", "丁寧": "形状詞だが、確実の対義語ではない。注意深く行うことを表す語で、この意味の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39764, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "間違いがなく、たしかなことです。", "primary_collocate": null, "pronunciation": "かくじつ", "ipa": "kakɯdʑitsɯ", "syllable_count": 4, "sentences": [{"text": "この方法なら、確実に合格できます。", "target_word": "確実", "complexity_tier": "T3", "furigana": "この方法[ほうほう]なら、確実[かくじつ]に合格[ごうかく]できます。", "sentence_source": "generated"}, {"text": "確実な情報がないので、まだ発表しません。", "target_word": "確実", "complexity_tier": "T3", "furigana": "確実[かくじつ]な情報[じょうほう]がないので、まだ発表[はっぴょう]しません。", "sentence_source": "generated"}, {"text": "彼が来るかどうかは、まだ確実ではない。", "target_word": "確実", "complexity_tier": "T3", "furigana": "彼[かれ]が来[く]るかどうかは、まだ確実[かくじつ]ではない。", "sentence_source": "generated"}, {"text": "時間はかかるが、確実に進んでいる。", "target_word": "確実", "complexity_tier": "T3", "furigana": "時間[じかん]はかかるが、確実[かくじつ]に進[すす]んでいる。", "sentence_source": "generated"}, {"text": "確実な証拠が見つかり、事件は解決した。", "target_word": "確実", "complexity_tier": "T3", "furigana": "確実[かくじつ]な証拠[しょうこ]が見[み]つかり、事件[じけん]は解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "確実に届けたいので、速達で送ります。", "target_word": "確実", "complexity_tier": "T3", "furigana": "確実[かくじつ]に届[とど]けたいので、速達[そくたつ]で送[おく]ります。", "sentence_source": "generated"}, {"text": "薬を飲み続ければ、確実に良くなるでしょう。", "target_word": "確実", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]み続[つづ]ければ、確実[かくじつ]に良[よ]くなるでしょう。", "sentence_source": "generated"}, {"text": "天気予報は確実ではないから、傘を持っていこう。", "target_word": "確実", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]は確実[かくじつ]ではないから、傘[かさ]を持[も]っていこう。", "sentence_source": "generated"}, {"text": "確実に勝てるとは言えないが、全力で戦います。", "target_word": "確実", "complexity_tier": "T3", "furigana": "確実[かくじつ]に勝[か]てるとは言[い]えないが、全力[ぜんりょく]で戦[たたか]います。", "sentence_source": "generated"}, {"text": "彼女の計算は、いつも速くて確実だ。", "target_word": "確実", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の計算[けいさん]は、いつも速[はや]くて確実[かくじつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確実だ", "label": "終止形"}, {"form": "確実な", "label": "連体形"}, {"form": "確実に", "label": "連用形"}, {"form": "確実で", "label": "て形"}, {"form": "確実ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "間違いがなく、たしかであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39764, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "確実", "is_correct": true, "explanation": "「確実に合格できます」の形で、この方法なら間違いなく合格できるという意味に合う。"}, {"text": "必要", "is_correct": false, "explanation": "「必要に合格できます」となり、「必要に」は合格を修飾しないので文が成り立たない。"}, {"text": "大切", "is_correct": false, "explanation": "「大切に合格できます」となり、合格の様子を表す語として不自然で文に合わない。"}, {"text": "不明", "is_correct": false, "explanation": "「不明に合格できます」となり、方法の結果を表す文として意味が通らない。"}], "explanations": {"確実": "「確実に合格できます」の形で、この方法なら間違いなく合格できるという意味に合う。", "必要": "「必要に合格できます」となり、「必要に」は合格を修飾しないので文が成り立たない。", "大切": "「大切に合格できます」となり、合格の様子を表す語として不自然で文に合わない。", "不明": "「不明に合格できます」となり、方法の結果を表す文として意味が通らない。"}, "sentence_index": 0, "correct_answer": "確実"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "確実に、あの店は月曜日が休みだったと思う。", "explanation": "ここは〈確か〉の意味。記憶があいまいなときに使う副詞で、〈確実〉は確かだと言い切る意味なので「〜と思う」と合わない。"}, {"text": "彼は確実を持って答えた。", "explanation": "ここは〈確信〉の意味。〈確実〉は名詞として「持つ」の目的語にできず、〈確信〉を使う。"}, {"text": "彼は確実な身なりで面接に行った。", "explanation": "ここは〈きちんとした〉の意味。身なりは〈きちんとした〉で言い、〈確実〉は結果や情報の確かさを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39764, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "確実", "is_correct": true, "explanation": "「確実に良くなるでしょう」の形で、薬を飲み続ければ間違いなく良くなるという意味に合う。"}, {"text": "必死", "is_correct": false, "explanation": "「必死に良くなる」となり、必死は態度を表す語で、回復の様子には合わない。"}, {"text": "不器用", "is_correct": false, "explanation": "「不器用に良くなる」となり、性質を表す語で回復の様子に合わず、文が成り立たない。"}, {"text": "貴重", "is_correct": false, "explanation": "「貴重に良くなる」となり、価値を表す語で回復の様子には合わない。"}], "explanations": {"確実": "「確実に良くなるでしょう」の形で、薬を飲み続ければ間違いなく良くなるという意味に合う。", "必死": "「必死に良くなる」となり、必死は態度を表す語で、回復の様子には合わない。", "不器用": "「不器用に良くなる」となり、性質を表す語で回復の様子に合わず、文が成り立たない。", "貴重": "「貴重に良くなる」となり、価値を表す語で回復の様子には合わない。"}, "sentence_index": 6, "correct_answer": "確実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験に受かって、確実にうれしい。", "explanation": "ここは〈本当に〉の意味。感情の強さを表すのは〈本当に〉で、〈確実に〉は感情には使わない。"}, {"text": "不安で眠れず、確実な気持ちだった。", "explanation": "ここは〈確信〉の意味。確実は事柄について間違いがないことを表し、人の気持ちには使わない。"}, {"text": "彼は確実な服装で式に出た。", "explanation": "ここは〈きちんとした〉の意味。服装は〈きちんとした〉で言い、〈確実〉は結果や情報の確かさを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39764, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "確実の方法で、必ず合格します。", "corrected_sentence": "確実な方法で、必ず合格します。", "error_description": "「確実」は形状詞なので、名詞を修飾するには「な」が必要。「確実の」は誤りで、「確実な」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "確実", "is_correct": true, "explanation": "「確実な情報」の語幹。連体形「確実な」の形で、文中の正しい形。"}, {"text": "確実に", "is_correct": false, "explanation": "連用形。名詞の前に「な」で続けると文が成り立たず、「に」は文中の形と合わない。"}, {"text": "確実だ", "is_correct": false, "explanation": "終止形。名詞を修飾するには「な」の形が必要で、文に合わない。"}, {"text": "確実で", "is_correct": false, "explanation": "て形。名詞の前に置くと文が成り立たない。"}], "correct_form": "確実", "base_form": "確実だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"確実": "「確実な情報」の語幹。連体形「確実な」の形で、文中の正しい形。", "確実に": "連用形。名詞の前に「な」で続けると文が成り立たず、「に」は文中の形と合わない。", "確実だ": "終止形。名詞を修飾するには「な」の形が必要で、文に合わない。", "確実で": "て形。名詞の前に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39764, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この結果はまだ確実くないので、報告を待とう。", "corrected_sentence": "この結果はまだ確実ではないので、報告を待とう。", "error_description": "形状詞の否定は「確実ではない」。「確実くない」は形容詞の活用と混ざった誤りで、「確実ではない」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "確実", "is_correct": true, "explanation": "否定形「確実ではない」の語幹。文中の形の一部として正しい。"}, {"text": "確実な", "is_correct": false, "explanation": "連体形。「ではない」の前には置けず、文の形と合わない。"}, {"text": "確実じゃない", "is_correct": false, "explanation": "口語の否定形。文中の「ではない」とは形が異なり、この文の形に合わない。"}, {"text": "確実ではなかった", "is_correct": false, "explanation": "過去の否定形。現在の文脈「まだ確実ではない」に合わない。"}], "correct_form": "確実", "base_form": "確実だ", "form_label": "否定形", "sentence_index": 7, "explanations": {"確実": "否定形「確実ではない」の語幹。文中の形の一部として正しい。", "確実な": "連体形。「ではない」の前には置けず、文の形と合わない。", "確実じゃない": "口語の否定形。文中の「ではない」とは形が異なり、この文の形に合わない。", "確実ではなかった": "過去の否定形。現在の文脈「まだ確実ではない」に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39766, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「友だち」に頼んだ相手を示し、「チェックしてもらう」の相手として自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「してもらった」の相手にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、頼んだ相手を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「友だちを」は目的語になり、チェックされる対象として不自然。"}], "correct_answer": "に", "explanations": {"に": "「友だち」に頼んだ相手を示し、「チェックしてもらう」の相手として自然。", "が": "主語を示す助詞で、「してもらった」の相手にはならない。", "で": "手段や場所を示す助詞で、頼んだ相手を示せない。", "を": "「友だちを」は目的語になり、チェックされる対象として不自然。"}, "error_tags": {"が": "主語", "で": "手段", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39766, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「出発前に」と時点を示し、チェックする時を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、時点を示す文には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、時点を表せない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「出発前を」は時点の表現として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「出発前に」と時点を示し、チェックする時を表す。", "が": "主語を示す助詞で、時点を示す文には合わない。", "へ": "方向を示す助詞で、時点を表せない。", "を": "目的語を示す助詞で、「出発前を」は時点の表現として成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39766, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「チェック」は、何かが正しいかどうかを見ることです。", "primary_collocate": null, "pronunciation": "ちぇっく", "ipa": "tɕekːɯ", "syllable_count": 3, "sentences": [{"text": "出す前に、名前が書いてあるかチェックしてください。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "出[だ]す前[まえ]に、名前[なまえ]が書[か]いてあるかチェックしてください。", "sentence_source": "generated"}, {"text": "作文の間違いを、友だちにチェックしてもらった。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "作文[さくぶん]の間違[まちが]いを、友[とも]だちにチェックしてもらった。", "sentence_source": "generated"}, {"text": "家を出る前に、かぎをかけたかチェックする。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "家[いえ]を出[で]る前[まえ]に、かぎをかけたかチェックする。", "sentence_source": "generated"}, {"text": "先生は宿題をチェックして、赤いペンで丸をつけた。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "先生[せんせい]は宿題[しゅくだい]をチェックして、赤[あか]いペンで丸[まる]をつけた。", "sentence_source": "generated"}, {"text": "出かける前に、牛乳の期限が切れていないかチェックした。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "出[で]かける前[まえ]に、牛乳[ぎゅうにゅう]の期限[きげん]が切[き]れていないかチェックした。", "sentence_source": "generated"}, {"text": "答えが合っているか、もう一度チェックしよう。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "答[こた]えが合[あ]っているか、もう一度[いちど]チェックしよう。", "sentence_source": "generated"}, {"text": "メールを送る前に、字のまちがいをチェックする習慣がある。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "メールを送[おく]る前[まえ]に、字[じ]のまちがいをチェックする習慣[しゅうかん]がある。", "sentence_source": "generated"}, {"text": "荷物が全部あるか、出発前にチェックしておこう。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "荷物[にもつ]が全部[ぜんぶ]あるか、出発前[しゅっぱつまえ]にチェックしておこう。", "sentence_source": "generated"}, {"text": "自分の答案をチェックしたら、名前を書き忘れていた。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "自分[じぶん]の答案[とうあん]をチェックしたら、名前[なまえ]を書[か]き忘[わす]れていた。", "sentence_source": "generated"}, {"text": "毎朝、ガスの元栓が閉まっているかチェックしてから、出かける。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、ガスの元栓[もとせん]が閉[し]まっているかチェックしてから、出[で]かける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チェックする", "label": "基本形"}, {"form": "チェックして", "label": "て形"}, {"form": "チェックした", "label": "た形"}], "register": "neutral", "sense_fingerprint": "正しいかどうかを見て調べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: 元栓 (Zipf 2.2)']::text[], 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39766, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チェック", "is_correct": true, "explanation": "名前が書いてあるかを確かめる行為を表すので、「チェックしてください」で正解。"}, {"text": "掃除", "is_correct": false, "explanation": "場所をきれいにすることで、正しいかを見る行為とは合わない。"}, {"text": "注文", "is_correct": false, "explanation": "商品などを頼むことで、名前の記入を確かめる文には合わない。"}, {"text": "通話", "is_correct": false, "explanation": "電話で話すことで、書いてあるかを見る文脈では成り立たない。"}], "explanations": {"チェック": "名前が書いてあるかを確かめる行為を表すので、「チェックしてください」で正解。", "掃除": "場所をきれいにすることで、正しいかを見る行為とは合わない。", "注文": "商品などを頼むことで、名前の記入を確かめる文には合わない。", "通話": "電話で話すことで、書いてあるかを見る文脈では成り立たない。"}, "sentence_index": 0, "correct_answer": "チェック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "かばんのチェックを開けて、財布を取り出した。", "explanation": "ここは〈チャック〉（ファスナー）の意味。チェックは正誤を確かめる行為で、かばんを開け閉めする留め具ではない。"}, {"text": "音楽会で、チェックを弾いて拍手をもらった。", "explanation": "ここは〈チェロ〉（楽器）の意味。チェックは正誤を確かめる行為で、楽器を弾くことには使わない。"}, {"text": "ホテルのチェックを済ませて、部屋へ向かった。", "explanation": "ここは〈チェックイン（宿泊の受付）〉の意味。チェックは正誤を確かめる行為で、宿泊の受付は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39766, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チェック", "is_correct": true, "explanation": "まちがいを見つけるために見直す行為を表すので、「チェックする習慣」で正解。"}, {"text": "翻訳", "is_correct": false, "explanation": "別の言語に言い換える行為で、字のまちがいを見直す習慣とは合わない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ることで、字のまちがいを見直す行為とは結びつかない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届けることで、字のまちがいを見直す習慣には合わない。"}], "explanations": {"チェック": "まちがいを見つけるために見直す行為を表すので、「チェックする習慣」で正解。", "翻訳": "別の言語に言い換える行為で、字のまちがいを見直す習慣とは合わない。", "料理": "食べ物を作ることで、字のまちがいを見直す行為とは結びつかない。", "配達": "品物を届けることで、字のまちがいを見直す習慣には合わない。"}, "sentence_index": 6, "correct_answer": "チェック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ライブのチェックを買って、会場へ行った。", "explanation": "ここは〈チケット〉（入場券）の意味。チェックは正誤を確かめる行為で、ライブの入場券として買うものではない。"}, {"text": "車をチェックに出して、ブレーキを直してもらった。", "explanation": "ここは〈点検〉の意味。車は点検に出すと言い、チェックに出すとは言わない。"}, {"text": "テレビのチェックを変えて、ニュースを見た。", "explanation": "ここは〈チャンネル〉（放送の選び先）の意味。チェックは正誤を確かめる行為で、テレビの番組を切り替えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39766, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアの鍵がかかっているか、寝る前をチェックする。", "corrected_sentence": "ドアの鍵がかかっているか、寝る前にチェックする。", "error_description": "「チェック」の直前は時間を示す「に」が必要。「を」にすると「寝る前を見る」となり不自然。正しくは「寝る前に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39766, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出かける前に、窓の鍵にチェックしよう。", "corrected_sentence": "出かける前に、窓の鍵をチェックしよう。", "error_description": "「チェック」が目的語を取るので「を」を使う。「に」では「鍵にチェックする」となり不自然。正しくは「窓の鍵を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
