INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39767, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「チェック」は、物事が正しく行われているか、問題がないかを確認することを意味します。", "primary_collocate": null, "pronunciation": "ちぇっく", "ipa": "tɕekːɯ", "syllable_count": 3, "sentences": [{"text": "機械に問題がないか、毎日チェックしています。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "機械[きかい]に問題[もんだい]がないか、毎日[まいにち]チェックしています。", "sentence_source": "generated"}, {"text": "出荷の前に、商品に傷がないかチェックする決まりだ。", "target_word": "チェック", "complexity_tier": "T4", "furigana": "出荷[しゅっか]の前[まえ]に、商品[しょうひん]に傷[きず]がないかチェックする決[き]まりだ。", "sentence_source": "generated"}, {"text": "上司に書類をチェックしてもらってから、お客様に送った。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "上司[じょうし]に書類[しょるい]をチェックしてもらってから、お客様[おきゃくさま]に送[おく]った。", "sentence_source": "generated"}, {"text": "車を運転する前に、タイヤの空気をチェックした。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "車[くるま]を運転[うんてん]する前[まえ]に、タイヤの空気[くうき]をチェックした。", "sentence_source": "generated"}, {"text": "契約書の内容をチェックしたところ、数字の誤りが見つかった。", "target_word": "チェック", "complexity_tier": "T4", "furigana": "契約書[けいやくしょ]の内容[ないよう]をチェックしたところ、数字[すうじ]の誤[あやま]りが見[み]つかった。", "sentence_source": "generated"}, {"text": "工場では、作業がきちんと行われているかチェックしている。", "target_word": "チェック", "complexity_tier": "T4", "furigana": "工場[こうじょう]では、作業[さぎょう]がきちんと行[おこな]われているかチェックしている。", "sentence_source": "generated"}, {"text": "電気の配線に異常がないか、専門家がチェックしに来た。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "電気[でんき]の配線[はいせん]に異常[いじょう]がないか、専門家[せんもんか]がチェックしに来[き]た。", "sentence_source": "generated"}, {"text": "公開する前に、プログラムにエラーがないかチェックする。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "公開[こうかい]する前[まえ]に、プログラムにエラーがないかチェックする。", "sentence_source": "generated"}, {"text": "提出前のチェックが不十分で、同じミスをくり返してしまった。", "target_word": "チェック", "complexity_tier": "T4", "furigana": "提出前[ていしゅつまえ]のチェックが不十分[ふじゅうぶん]で、同[おな]じミスをくり返[かえ]してしまった。", "sentence_source": "generated"}, {"text": "点検表を使って、設備を一つずつチェックしていく。", "target_word": "チェック", "complexity_tier": "T3", "furigana": "点検表[てんけんひょう]を使[つか]って、設備[せつび]を一[ひと]つずつチェックしていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チェックする", "label": "基本形"}, {"form": "チェックして", "label": "て形"}, {"form": "チェックした", "label": "た形"}], "register": "neutral", "sense_fingerprint": "問題がないかを確認し点検すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39767, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チェック", "is_correct": true, "explanation": "問題がないかを確認する行為を表すので、「毎日チェックしています」で正解。"}, {"text": "配達", "is_correct": false, "explanation": "物を届ける行為で、機械の問題を確かめる文には合わない。"}, {"text": "予約", "is_correct": false, "explanation": "日時や席を前もって押さえることで、機械の点検とは結びつかない。"}, {"text": "入金", "is_correct": false, "explanation": "お金を口座に入れることで、機械の状態を確認する文には合わない。"}], "explanations": {"チェック": "問題がないかを確認する行為を表すので、「毎日チェックしています」で正解。", "配達": "物を届ける行為で、機械の問題を確かめる文には合わない。", "予約": "日時や席を前もって押さえることで、機械の点検とは結びつかない。", "入金": "お金を口座に入れることで、機械の状態を確認する文には合わない。"}, "sentence_index": 0, "correct_answer": "チェック"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テレビのチェックを変えて、ニュースを見た。", "explanation": "ここは〈チャンネル〉（放送の選び先）の意味。チェックは正誤を確かめる行為で、テレビの番組を切り替えるものではない。"}, {"text": "ポケットのチェックを開けて、鍵を探した。", "explanation": "ここは〈チャック〉（ファスナー）の意味。チェックは確認の行為で、ポケットを開け閉めする留め具ではない。"}, {"text": "ホテルのチェックを済ませて、部屋へ向かった。", "explanation": "ここは〈チェックイン（宿泊の受付）〉の意味。チェックは正誤を確かめる行為で、宿泊の受付は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39767, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チェック", "is_correct": true, "explanation": "配線に異常がないかを確かめる行為で、「しに来た」の目的として正解。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態で、「しに来る」の目的にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感覚で、来て行う行為とは結びつかない。"}, {"text": "空気", "is_correct": false, "explanation": "気体のことで、「しに来た」の目的として行為を表せない。"}], "explanations": {"チェック": "配線に異常がないかを確かめる行為で、「しに来た」の目的として正解。", "天気": "気象の状態で、「しに来る」の目的にはならない。", "眠気": "眠たい感覚で、来て行う行為とは結びつかない。", "空気": "気体のことで、「しに来た」の目的として行為を表せない。"}, "sentence_index": 6, "correct_answer": "チェック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "発表会の伴奏で、チェックを弾いた。", "explanation": "ここは〈チェロ〉（楽器）の意味。チェックは確認の行為で、楽器を弾くことには使わない。"}, {"text": "映画館の窓口で、チェックを一枚買った。", "explanation": "ここは〈チケット〉（入場券）の意味。チェックは正誤を確かめる行為で、映画の入場券として買うものではない。"}, {"text": "古いエアコンをチェックに出して、直してもらった。", "explanation": "ここは〈点検〉の意味。電化製品は点検に出すと言い、チェックに出すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39767, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "配線に異常がないか、毎朝チェックてしている。", "corrected_sentence": "配線に異常がないか、毎朝チェックしている。", "error_description": "「チェック」にはサ変動詞「する」を付けるので、「チェックして」「チェックしている」と活用する。「チェックてしている」は誤った活用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39767, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ホテルの予約に、前日にチェックしておく。", "corrected_sentence": "ホテルの予約を、前日にチェックしておく。", "error_description": "「チェック」の目的語は「を」で示す。「に」を使うと「予約にチェックする」となり不自然。正しくは「予約を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39768, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「手助けがあれば」で、手助けがあるという条件の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「手助けをあれば」は文が成り立たず、「ある」の目的語にもならない。"}, {"text": "に", "is_correct": false, "explanation": "「手助けにあれば」は不自然で、存在の条件を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「手助けのあれば」は文が続かず、名詞を修飾する形にもならない。"}], "correct_answer": "が", "explanations": {"が": "「手助けがあれば」で、手助けがあるという条件の主語を示す。", "を": "「手助けをあれば」は文が成り立たず、「ある」の目的語にもならない。", "に": "「手助けにあれば」は不自然で、存在の条件を示せない。", "の": "「手助けのあれば」は文が続かず、名詞を修飾する形にもならない。"}, "error_tags": {"を": "目的語の格", "に": "相手・方向の格", "の": "連体修飾の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39768, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「手助けをして」で、する動作の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「手助けがして」は不自然で、動詞の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「手助けにして」は「〜にする」の形になり、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「手助けでして」は文が成り立たず、手段の意味にもならない。"}], "correct_answer": "を", "explanations": {"を": "「手助けをして」で、する動作の目的語を示す。", "が": "「手助けがして」は不自然で、動詞の目的語にならない。", "に": "「手助けにして」は「〜にする」の形になり、意味が通らない。", "で": "「手助けでして」は文が成り立たず、手段の意味にもならない。"}, "error_tags": {"が": "主語の格", "に": "相手・方向の格", "で": "手段・場所の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39768, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "誰かが何かをするのを、もっと簡単にできるようにすること。", "primary_collocate": null, "pronunciation": "てだすけ", "ipa": "tedasɯke", "syllable_count": 4, "sentences": [{"text": "重い荷物を運ぶ母の手助けをした。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を運[はこ]ぶ母[はは]の手助[てだす]けをした。", "sentence_source": "generated"}, {"text": "少しの手助けがあれば、この仕事は早く終わります。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "少[すこ]しの手助[てだす]けがあれば、この仕事[しごと]は早[はや]く終[お]わります。", "sentence_source": "generated"}, {"text": "引っ越しの手助けに、友達が三人来てくれた。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの手助[てだす]けに、友達[ともだち]が三人[さんにん]来[き]てくれた。", "sentence_source": "generated"}, {"text": "彼は手助けを断って、一人で問題を解いた。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "彼[かれ]は手助[てだす]けを断[ことわ]って、一人[ひとり]で問題[もんだい]を解[と]いた。", "sentence_source": "generated"}, {"text": "外国人の観光客に道を教えるのも、小さな手助けです。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]の観光客[かんこうきゃく]に道[みち]を教[おし]えるのも、小[ちい]さな手助[てだす]けです。", "sentence_source": "generated"}, {"text": "宿題で分からないところは、先生が手助けしてくれる。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]で分[わ]からないところは、先生[せんせい]が手助[てだす]けしてくれる。", "sentence_source": "generated"}, {"text": "手助けが必要なときは、遠慮せずに言ってください。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "手助[てだす]けが必要[ひつよう]なときは、遠慮[えんりょ]せずに言[い]ってください。", "sentence_source": "generated"}, {"text": "足の悪いおばあさんの手助けをして、階段を上った。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "足[あし]の悪[わる]いおばあさんの手助[てだす]けをして、階段[かいだん]を上[のぼ]った。", "sentence_source": "generated"}, {"text": "この道具は料理の手助けになるので、毎日使っています。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は料理[りょうり]の手助[てだす]けになるので、毎日[まいにち]使[つか]っています。", "sentence_source": "generated"}, {"text": "弟は手助けされるのが嫌いで、何でも自分でやりたがる。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "弟[おとうと]は手助[てだす]けされるのが嫌[きら]いで、何[なん]でも自分[じぶん]でやりたがる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手助けする", "label": "サ変動詞"}, {"form": "手助けして", "label": "て形"}, {"form": "手助けした", "label": "た形"}, {"form": "手助けされる", "label": "受身形"}], "register": "普通", "sense_fingerprint": "相手の作業を楽にする手伝い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39768, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手助け", "is_correct": true, "explanation": "荷物を運ぶ手伝いの意味で、母の手助けをしたに合う。"}, {"text": "後悔", "is_correct": false, "explanation": "残念に思う気持ちの意味で、母の後悔をしたとは言わない。"}, {"text": "禁止", "is_correct": false, "explanation": "させないと決めることの意味で、母の禁止をしたは不自然。"}, {"text": "散歩", "is_correct": false, "explanation": "外を歩くことの意味で、母の散歩をしたでは意味が通らない。"}], "explanations": {"手助け": "荷物を運ぶ手伝いの意味で、母の手助けをしたに合う。", "後悔": "残念に思う気持ちの意味で、母の後悔をしたとは言わない。", "禁止": "させないと決めることの意味で、母の禁止をしたは不自然。", "散歩": "外を歩くことの意味で、母の散歩をしたでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "手助け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母の誕生日に、手助けを買ってプレゼントした。", "explanation": "ここは〈贈り物〉の意味。手助けは形のある物ではないので、買ってプレゼントすることはできない。"}, {"text": "雨が続いたことが、事故の手助けになった。", "explanation": "〈原因〉の意味は手助けにない。「事故の手助け」は事故を助けることになり、目標語の語義と合わず誤り。"}, {"text": "彼は上司の手助けに従って、報告書を書き直した。", "explanation": "ここは〈命令〉の意味。手助けは指示ではないので、従うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39768, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手助け", "is_correct": true, "explanation": "助けが必要だという意味で、「手助けが必要なときは」に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "朝遅く起きることの意味で、「寝坊が必要」とは言えない。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は道路が混むことで、「渋滞が必要なとき」は意味が通らない。"}, {"text": "叱責", "is_correct": false, "explanation": "強くしかることの意味で、「叱責が必要なときは言ってください」は意味が通らない。"}], "explanations": {"手助け": "助けが必要だという意味で、「手助けが必要なときは」に合う。", "寝坊": "朝遅く起きることの意味で、「寝坊が必要」とは言えない。", "渋滞": "渋滞は道路が混むことで、「渋滞が必要なとき」は意味が通らない。", "叱責": "強くしかることの意味で、「叱責が必要なときは言ってください」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "手助け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "運転中は前の車に手助けを払う。", "explanation": "ここは〈注意〉の意味。「注意を払う」の注意の代わりに手助けを使っているが、手助けは相手への援助で、払うものではない。"}, {"text": "彼は会議で大きな手助けを唱えた。", "explanation": "ここは〈反対〉の意味。「反対を唱える」の反対の代わりに手助けを使っているが、手助けは主張として唱えるものではない。"}, {"text": "その手助けを修理するのに、三日かかった。", "explanation": "ここは〈機械〉の意味。「機械を修理する」の機械の代わりに手助けを使っているが、手助けは物ではないので修理できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39768, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引っ越しの日、友達の手助けを感謝した。", "corrected_sentence": "引っ越しの日、友達の手助けに感謝した。", "error_description": "「感謝する」は「〜に感謝する」と言うので、「手助けを」は「手助けに」が正しい。誤りは「を」と「に」の一か所だけ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39768, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達に手助けを取ってもらった。", "corrected_sentence": "友達に手助けをしてもらった。", "error_description": "「手助けを取る」とは言わない。「手助けをする」に「してもらう」を続けるのが正しい。誤りは「取って」を「して」にする一か所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39769, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「兄の手助け」の最初の「の」（兄の＝手助けに付く連体修飾）。"}, {"text": "を", "is_correct": false, "explanation": "「手助けをおかげで」は文が続かず、意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「手助けがおかげで」は不自然で、「のおかげで」の形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「手助けにおかげで」は成り立たず、原因を示す形にならない。"}], "correct_answer": "の", "explanations": {"の": "「兄の手助け」の最初の「の」（兄の＝手助けに付く連体修飾）。", "を": "「手助けをおかげで」は文が続かず、意味が通らない。", "が": "「手助けがおかげで」は不自然で、「のおかげで」の形にならない。", "に": "「手助けにおかげで」は成り立たず、原因を示す形にならない。"}, "error_tags": {"を": "目的語の格", "が": "主語の格", "に": "相手・方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39769, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「だれかの手助けが必要だ」で、必要だの主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「手助けを必要だ」は「必要だ」が目的語を取らず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「だれかの手助けで必要だ」は手段の意味にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「手助けへ必要だ」は方向の意味にならず、不自然。"}], "correct_answer": "が", "explanations": {"が": "「だれかの手助けが必要だ」で、必要だの主語を示す格助詞。", "を": "「手助けを必要だ」は「必要だ」が目的語を取らず、文が成り立たない。", "で": "「だれかの手助けで必要だ」は手段の意味にならず、文が成り立たない。", "へ": "「手助けへ必要だ」は方向の意味にならず、不自然。"}, "error_tags": {"を": "目的語の格", "で": "手段・場所の格", "へ": "方向の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39769, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある人が何かをするのを、助けること。支援すること。", "primary_collocate": null, "pronunciation": "てだすけ", "ipa": "tedasɯke", "syllable_count": 4, "sentences": [{"text": "地震の後、多くの人が被災地の手助けに向かった。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "地震[じしん]の後[あと]、多[おお]くの人[ひと]が被災地[ひさいち]の手助[てだす]けに向[む]かった。", "sentence_source": "generated"}, {"text": "兄の手助けのおかげで、無事に店を開くことができた。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "兄[あに]の手助[てだす]けのおかげで、無事[ぶじ]に店[みせ]を開[ひら]くことができた。", "sentence_source": "generated"}, {"text": "困っている人に手助けをするのは、大切なことだ。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "困[こま]っている人[ひと]に手助[てだす]けをするのは、大切[たいせつ]なことだ。", "sentence_source": "generated"}, {"text": "引っ越したばかりで、近所の人の手助けがありがたかった。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]したばかりで、近所[きんじょ]の人[ひと]の手助[てだす]けがありがたかった。", "sentence_source": "generated"}, {"text": "言葉が通じなくて困っていたので、彼女が手助けしてくれた。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "言葉[ことば]が通[つう]じなくて困[こま]っていたので、彼女[かのじょ]が手助[てだす]けしてくれた。", "sentence_source": "generated"}, {"text": "手助けをしたいけれど、何をすればいいか分からない。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "手助[てだす]けをしたいけれど、何[なに]をすればいいか分[わ]からない。", "sentence_source": "generated"}, {"text": "町の人たちは、お互いに手助けをしながら暮らしている。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちは、お互[たが]いに手助[てだす]けをしながら暮[く]らしている。", "sentence_source": "generated"}, {"text": "病気の父には、毎日だれかの手助けが必要だ。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "病気[びょうき]の父[ちち]には、毎日[まいにち]だれかの手助[てだす]けが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "資金面で手助けしてくれた友人に、心からお礼を言った。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "資金面[しきんめん]で手助[てだす]けしてくれた友人[ゆうじん]に、心[こころ]からお礼[れい]を言[い]った。", "sentence_source": "generated"}, {"text": "彼は子どもたちの勉強を手助けするボランティアをしている。", "target_word": "手助け", "complexity_tier": "T3", "furigana": "彼[かれ]は子[こ]どもたちの勉強[べんきょう]を手助[てだす]けするボランティアをしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手助けする", "label": "サ変動詞"}, {"form": "手助けして", "label": "て形"}, {"form": "手助けした", "label": "た形"}, {"form": "手助けしたい", "label": "たい形"}], "register": "普通", "sense_fingerprint": "困っている人への援助・支援", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39769, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手助け", "is_correct": true, "explanation": "被災地を支援するために行くという意味で、「被災地の手助けに向かった」に合う。"}, {"text": "交代", "is_correct": false, "explanation": "役目を入れ替えることの意味で、「被災地の交代に向かった」は意味が通らない。"}, {"text": "予約", "is_correct": false, "explanation": "前もって取っておくことの意味で、「被災地の予約に向かった」は不自然。"}, {"text": "禁止", "is_correct": false, "explanation": "させないと決めることの意味で、「被災地の禁止に向かった」は成り立たない。"}], "explanations": {"手助け": "被災地を支援するために行くという意味で、「被災地の手助けに向かった」に合う。", "交代": "役目を入れ替えることの意味で、「被災地の交代に向かった」は意味が通らない。", "予約": "前もって取っておくことの意味で、「被災地の予約に向かった」は不自然。", "禁止": "させないと決めることの意味で、「被災地の禁止に向かった」は成り立たない。"}, "sentence_index": 0, "correct_answer": "手助け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "タクシーを降りて、運転手に手助けを払った。", "explanation": "ここは〈料金〉の意味。「料金を払う」の料金の代わりに手助けを使っているが、手助けは金銭ではないので払えない。"}, {"text": "彼女は美しい手助けを織って、母に贈った。", "explanation": "ここは〈布〉の意味。「布を織る」の布の代わりに手助けを使っているが、手助けは布ではないので織れない。"}, {"text": "ストーブの消し忘れが、大きな手助けを起こした。", "explanation": "ここは〈火事〉の意味。「火事を起こす」の火事の代わりに手助けを使っているが、手助けは災いではないので起こせない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39769, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手助け", "is_correct": true, "explanation": "互いに助け合うという意味で、「お互いに手助けをしながら」に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "朝遅く起きることの意味で、「お互いに寝坊をしながら暮らす」は意味が通らない。"}, {"text": "脱線", "is_correct": false, "explanation": "本筋から外れることの意味で、「お互いに脱線をしながら」は成り立たない。"}, {"text": "解雇", "is_correct": false, "explanation": "仕事を辞めさせることの意味で、「お互いに解雇をしながら暮らす」は不自然。"}], "explanations": {"手助け": "互いに助け合うという意味で、「お互いに手助けをしながら」に合う。", "寝坊": "朝遅く起きることの意味で、「お互いに寝坊をしながら暮らす」は意味が通らない。", "脱線": "本筋から外れることの意味で、「お互いに脱線をしながら」は成り立たない。", "解雇": "仕事を辞めさせることの意味で、「お互いに解雇をしながら暮らす」は不自然。"}, "sentence_index": 6, "correct_answer": "手助け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールが当たって、大切な手助けを割ってしまった。", "explanation": "ここは〈窓ガラス〉の意味。「窓ガラスを割る」の窓ガラスの代わりに手助けを使っているが、手助けは形がないので割れない。"}, {"text": "洗剤で服の手助けを落とした。", "explanation": "ここは〈汚れ〉の意味。「汚れを落とす」の汚れの代わりに手助けを使っているが、手助けは落とせるものではない。"}, {"text": "旅行先で景色の手助けを撮った。", "explanation": "ここは〈写真〉の意味。「写真を撮る」の写真の代わりに手助けを使っているが、手助けは撮影できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39769, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風の後、多くの人が避難所の手助けを向かった。", "corrected_sentence": "台風の後、多くの人が避難所の手助けに向かった。", "error_description": "「向かう」は「〜に向かう」と言うので、「手助けを」は「手助けに」が正しい。誤りは「を」と「に」の一か所だけ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39769, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "被災地の人たちに、ボランティアが手助けを作った。", "corrected_sentence": "被災地の人たちに、ボランティアが手助けをした。", "error_description": "「手助けを作る」とは言わない。「手助けをする」が正しい。誤りは「作った」を「した」にする一か所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
