INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39772, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生き物が元気に育つように、食べ物や世話をする。", "primary_collocate": null, "pronunciation": "やしなう", "ipa": "jaɕinaɯ", "syllable_count": 4, "sentences": [{"text": "親鳥は毎日えさを運んで、ひなを養う。", "target_word": "養う", "complexity_tier": "T3", "furigana": "親鳥[おやどり]は毎日[まいにち]えさを運[はこ]んで、ひなを養[やしな]う。", "sentence_source": "generated"}, {"text": "母は道で拾った子猫を養って、元気に育てた。", "target_word": "養って", "complexity_tier": "T3", "furigana": "母[はは]は道[みち]で拾[ひろ]った子猫[こねこ]を養[やしな]って、元気[げんき]に育[そだ]てた。", "sentence_source": "generated"}, {"text": "祖母は迷い込んだ子犬を、毎日えさをやって養っている。", "target_word": "養っている", "complexity_tier": "T3", "furigana": "祖母は迷(まよ)い込(こ)んだ子犬(こいぬ)を、毎日(まいにち)えさをやって養(やしな)っている。", "sentence_source": "generated"}, {"text": "この川は、たくさんの魚や水鳥を養っている。", "target_word": "養っている", "complexity_tier": "T3", "furigana": "この川(かわ)は、たくさんの魚(さかな)や水鳥(みずどり)を養(やしな)っている。", "sentence_source": "generated"}, {"text": "冬の間、野鳥を養うために庭にえさを置いている。", "target_word": "養う", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、野鳥[やちょう]を養[やしな]うために庭[にわ]にえさを置[お]いている。", "sentence_source": "generated"}, {"text": "牧場の人たちは、生まれた子牛を大切に養った。", "target_word": "養った", "complexity_tier": "T3", "furigana": "牧場[ぼくじょう]の人[ひと]たちは、生[う]まれた子牛[こうし]を大切[たいせつ]に養[やしな]った。", "sentence_source": "generated"}, {"text": "けがをした小鳥を家に連れて帰り、元気になるまで養った。", "target_word": "養った", "complexity_tier": "T3", "furigana": "けがをした小鳥[ことり]を家[いえ]に連[つ]れて帰[かえ]り、元気[げんき]になるまで養[やしな]った。", "sentence_source": "generated"}, {"text": "親を失った子ぎつねを、動物園の人が養うことになった。", "target_word": "養う", "complexity_tier": "T3", "furigana": "親[おや]を失[うしな]った子[こ]ぎつねを、動物園[どうぶつえん]の人[ひと]が養[やしな]うことになった。", "sentence_source": "generated"}, {"text": "病気の犬を養って、三か月でやっと走れるようになった。", "target_word": "養って", "complexity_tier": "T3", "furigana": "病気[びょうき]の犬[いぬ]を養[やしな]って、三[さん]か月[げつ]でやっと走[はし]れるようになった。", "sentence_source": "generated"}, {"text": "母ぐまがほかの子ぐまを養う話を、本で読んだ。", "target_word": "養う", "complexity_tier": "T3", "furigana": "母[はは]ぐまがほかの子[こ]ぐまを養[やしな]う話[はなし]を、本[ほん]で読[よ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "養う", "label": "辞書形"}, {"form": "養わない", "label": "ない形"}, {"form": "養います", "label": "ます形"}, {"form": "養って", "label": "て形"}, {"form": "養った", "label": "た形"}, {"form": "養える", "label": "可能形"}, {"form": "養われる", "label": "受身形"}], "register": "普通", "sense_fingerprint": "えさや世話で生き物を育てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39772, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "養う", "is_correct": true, "explanation": "えさや世話で生き物を育てる意味で、「ひなを養う」に合う。"}, {"text": "焦がす", "is_correct": false, "explanation": "火で焼きすぎる意味で、「ひなを焦がす」は意味が通らない。"}, {"text": "砕く", "is_correct": false, "explanation": "細かく割る意味で、生き物には使えず文が成り立たない。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をこすってきれいにする意味で、「ひなを磨く」は不自然。"}], "explanations": {"養う": "えさや世話で生き物を育てる意味で、「ひなを養う」に合う。", "焦がす": "火で焼きすぎる意味で、「ひなを焦がす」は意味が通らない。", "砕く": "細かく割る意味で、生き物には使えず文が成り立たない。", "磨く": "表面をこすってきれいにする意味で、「ひなを磨く」は不自然。"}, "sentence_index": 0, "correct_answer": "養う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その倉庫は、古い書類を養っている。", "explanation": "ここは〈保管〉の意味。「書類を保管する」の保管の代わりに養うを使っているが、書類は生き物ではないので養うとは言えない。"}, {"text": "その工場は、新しい製品を養っている。", "explanation": "ここは〈製造〉の意味。「製品を製造する」の製造の代わりに養うを使っているが、製品は生き物ではないので養うとは言えない。"}, {"text": "修理屋は、壊れた車を養った。", "explanation": "ここは〈修理〉の意味。「車を修理する」の修理の代わりに養うを使っているが、車は生き物ではないので養うとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39772, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "養った", "is_correct": true, "explanation": "世話をして育てたという意味で、「元気になるまで養った」に合う。"}, {"text": "殴った", "is_correct": false, "explanation": "強く打つ意味で、「元気になるまで殴った」は意味が通らない。"}, {"text": "割った", "is_correct": false, "explanation": "二つに分ける意味で、「元気になるまで割った」は成り立たない。"}, {"text": "焼いた", "is_correct": false, "explanation": "火で加熱する意味で、「元気になるまで焼いた」は不自然。"}], "explanations": {"養った": "世話をして育てたという意味で、「元気になるまで養った」に合う。", "殴った": "強く打つ意味で、「元気になるまで殴った」は意味が通らない。", "割った": "二つに分ける意味で、「元気になるまで割った」は成り立たない。", "焼いた": "火で加熱する意味で、「元気になるまで焼いた」は不自然。"}, "sentence_index": 6, "correct_answer": "養った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "経理係は毎月、売上を養っている。", "explanation": "ここは〈集計〉の意味。「売上を集計する」の集計の代わりに養うを使っているが、売上は生き物ではないので養うとは言えない。"}, {"text": "係の人は毎朝、工場を養っている。", "explanation": "ここは〈管理〉の意味。「工場を管理している」の管理の代わりに養うを使っているが、工場は生き物ではないので養うとは言えない。"}, {"text": "技術者はその機械を養った。", "explanation": "ここは〈点検〉の意味。「機械を点検した」の点検の代わりに養うを使っているが、機械は生き物ではないので養えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39772, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベランダに来る野鳥に、毎朝えさをやって養っている。", "corrected_sentence": "ベランダに来る野鳥を、毎朝えさをやって養っている。", "error_description": "「養う」は育てる対象を「を」で示すので、「に」は誤り。誤りは格助詞「に」と「を」の一か所だけ。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "養って", "is_correct": true, "explanation": "て形で、後の「元気に育てた」へ続けて動作をつなぐ。"}, {"text": "養え", "is_correct": false, "explanation": "命令形で、後ろの「元気に育てた」と続けると文として成り立たない。"}, {"text": "養わない", "is_correct": false, "explanation": "否定形では世話をしないことになり、育てたという内容と矛盾する。"}, {"text": "養われ", "is_correct": false, "explanation": "受身形で、「子猫を」と合わず、子猫が養われる文になってしまう。"}], "correct_form": "養って", "base_form": "養う", "form_label": "て形", "sentence_index": 1, "explanations": {"養って": "て形で、後の「元気に育てた」へ続けて動作をつなぐ。", "養え": "命令形で、後ろの「元気に育てた」と続けると文として成り立たない。", "養わない": "否定形では世話をしないことになり、育てたという内容と矛盾する。", "養われ": "受身形で、「子猫を」と合わず、子猫が養われる文になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39772, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "けがをした野鳥を家に連れて帰り、元気になるまで養いた。", "corrected_sentence": "けがをした野鳥を家に連れて帰り、元気になるまで養った。", "error_description": "「養いた」は活用が誤り。過去形は「養った」。誤りは「養いた」を「養った」にする一か所。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "養う", "is_correct": true, "explanation": "辞書形で、「〜ことになった」の前に置く形。"}, {"text": "養います", "is_correct": false, "explanation": "ます形は文を終える形で、「ことになった」へ続かない。"}, {"text": "養いたい", "is_correct": false, "explanation": "希望の形で、決まったという内容に合わない。"}, {"text": "養え", "is_correct": false, "explanation": "命令形で、「ことになった」に続かず意味も合わない。"}], "correct_form": "養う", "base_form": "養う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"養う": "辞書形で、「〜ことになった」の前に置く形。", "養います": "ます形は文を終える形で、「ことになった」へ続かない。", "養いたい": "希望の形で、決まったという内容に合わない。", "養え": "命令形で、「ことになった」に続かず意味も合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39773, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39773, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「家族を養うのが」で、養うの目的語を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「家族へ養うのが」は養う対象を示せず、方向の意味にもならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、「家族より養うのが大変だ」は文の内容に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すので、「家族から養うのが大変だ」は養う対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「家族を養うのが」で、養うの目的語を示す格助詞。", "へ": "「家族へ養うのが」は養う対象を示せず、方向の意味にもならない。", "より": "比較の意味になり、「家族より養うのが大変だ」は文の内容に合わない。", "から": "起点を示すので、「家族から養うのが大変だ」は養う対象を示せない。"}, "error_tags": {"へ": "方向の格", "より": "比較の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39773, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や動物などを育てるために、食べ物やお金、時間などを与えたり、世話をしたりすること。また、習慣や能力などを身につけさせること。", "primary_collocate": null, "pronunciation": "やしなう", "ipa": "jaɕinaɯ", "syllable_count": 4, "sentences": [{"text": "父は一人で家族五人を養っている。", "target_word": "養って", "complexity_tier": "T3", "furigana": "父[ちち]は一人[ひとり]で家族[かぞく]五人[ごにん]を養[やしな]っている。", "sentence_source": "generated"}, {"text": "大学を出たら、働いて両親を養いたい。", "target_word": "養い", "complexity_tier": "T3", "furigana": "大学[だいがく]を出[で]たら、働[はたら]いて両親[りょうしん]を養[やしな]いたい。", "sentence_source": "generated"}, {"text": "子どもを養うために、母は毎日夜まで働いた。", "target_word": "養う", "complexity_tier": "T3", "furigana": "子[こ]どもを養[やしな]うために、母[はは]は毎日[まいにち]夜[よる]まで働[はたら]いた。", "sentence_source": "generated"}, {"text": "読書は、考える力を養うのに役立つ。", "target_word": "養う", "complexity_tier": "T3", "furigana": "読書[どくしょ]は、考[かんが]える力[ちから]を養[やしな]うのに役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "外国で暮らして、広い視野を養った。", "target_word": "養った", "complexity_tier": "T3", "furigana": "外国[がいこく]で暮[く]らして、広[ひろ]い視野[しや]を養[やしな]った。", "sentence_source": "generated"}, {"text": "毎日の練習で、強い体と心を養う。", "target_word": "養う", "complexity_tier": "T3", "furigana": "毎日[まいにち]の練習[れんしゅう]で、強[つよ]い体[からだ]と心[こころ]を養[やしな]う。", "sentence_source": "generated"}, {"text": "祖母は孫たちを養って、立派に育て上げた。", "target_word": "養って", "complexity_tier": "T3", "furigana": "祖母[そぼ]は孫[まご]たちを養[やしな]って、立派[りっぱ]に育[そだ]て上[あ]げた。", "sentence_source": "generated"}, {"text": "給料が低くて、家族を養うのが大変だ。", "target_word": "養う", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が低[ひく]くて、家族[かぞく]を養[やしな]うのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "部活動を通して、協力する心を養ってほしい。", "target_word": "養って", "complexity_tier": "T3", "furigana": "部活動[ぶかつどう]を通[とお]して、協力[きょうりょく]する心[こころ]を養[やしな]ってほしい。", "sentence_source": "generated"}, {"text": "彼は集中力を養うために、毎朝座禅をしている。", "target_word": "養う", "complexity_tier": "T3", "furigana": "彼[かれ]は集中力[しゅうちゅうりょく]を養[やしな]うために、毎朝[まいあさ]座禅[ざぜん]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "養う", "label": "辞書形"}, {"form": "養わない", "label": "ない形"}, {"form": "養います", "label": "ます形"}, {"form": "養って", "label": "て形"}, {"form": "養った", "label": "た形"}, {"form": "養いたい", "label": "たい形"}, {"form": "養える", "label": "可能形"}], "register": "普通", "sense_fingerprint": "家族を扶養する、力や心を育てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39773, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "養って", "is_correct": true, "explanation": "家族の生活を支えるという意味で、「家族五人を養っている」に合う。"}, {"text": "焦がして", "is_correct": false, "explanation": "火で焼きすぎる意味で、「家族五人を焦がしている」は意味が通らない。"}, {"text": "割って", "is_correct": false, "explanation": "二つに分ける意味で、家族には使えず文が成り立たない。"}, {"text": "磨いて", "is_correct": false, "explanation": "表面をこすってきれいにする意味で、「家族五人を磨いている」は不自然。"}], "explanations": {"養って": "家族の生活を支えるという意味で、「家族五人を養っている」に合う。", "焦がして": "火で焼きすぎる意味で、「家族五人を焦がしている」は意味が通らない。", "割って": "二つに分ける意味で、家族には使えず文が成り立たない。", "磨いて": "表面をこすってきれいにする意味で、「家族五人を磨いている」は不自然。"}, "sentence_index": 0, "correct_answer": "養って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は新しいビルを養うため、資金を集めた。", "explanation": "ここは〈建設〉の意味。「ビルを建設する」の建設の代わりに養うを使っているが、ビルは能力や習慣を育てる対象ではなく、養うとは言えない。"}, {"text": "考古学者は古い遺跡を養った。", "explanation": "ここは〈修復〉の意味。「遺跡を修復する」の修復の代わりに養うを使っているが、遺跡は育てる対象ではない。"}, {"text": "その工場は、新しい部品を養っている。", "explanation": "ここは〈製造〉の意味。「部品を製造する」の製造の代わりに養うを使っているが、部品は能力や心ではないので養うとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39773, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "養って", "is_correct": true, "explanation": "育てるために世話をしたという意味で、「孫たちを養って、立派に育て上げた」に合う。"}, {"text": "凍らせて", "is_correct": false, "explanation": "冷やして固める意味で、孫たちには使えず文が成り立たない。"}, {"text": "煮詰めて", "is_correct": false, "explanation": "煮て量を減らす意味で、「孫たちを煮詰めて」は意味が通らない。"}, {"text": "砕いて", "is_correct": false, "explanation": "細かく割る意味で、人には使えず「孫たちを砕いて」は成り立たない。"}], "explanations": {"養って": "育てるために世話をしたという意味で、「孫たちを養って、立派に育て上げた」に合う。", "凍らせて": "冷やして固める意味で、孫たちには使えず文が成り立たない。", "煮詰めて": "煮て量を減らす意味で、「孫たちを煮詰めて」は意味が通らない。", "砕いて": "細かく割る意味で、人には使えず「孫たちを砕いて」は成り立たない。"}, "sentence_index": 6, "correct_answer": "養って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その店は新しい商品を養って、大量に売り出した。", "explanation": "ここは〈販売〉の意味。「商品を販売する」の販売の代わりに養うを使っているが、商品は生き物ではないので養うとは言えない。"}, {"text": "母は毎朝、部屋を養ってから出かける。", "explanation": "ここは〈掃除〉の意味。「部屋を掃除する」の掃除の代わりに養うを使っているが、部屋は生き物ではないので養うとは言えない。"}, {"text": "研究者は実験の温度を養った。", "explanation": "ここは〈測定〉の意味。「温度を測定する」の測定の代わりに養うを使っているが、温度は生き物ではないので養うとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39773, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は一人で弟二人を養いている。", "corrected_sentence": "姉は一人で弟二人を養っている。", "error_description": "「養う」のて形は「養って」で、「養いている」は活用が誤り。「養っている」が正しい。誤りは「養い」を「養っ」にする一か所。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "養い", "is_correct": true, "explanation": "連用形で、「〜たい」の前に置いて希望を表す形。"}, {"text": "養って", "is_correct": false, "explanation": "て形では「養ってたい」となり、希望の形にならない。"}, {"text": "養った", "is_correct": false, "explanation": "た形では「養ったたい」となり、「〜たい」に続かない。"}, {"text": "養える", "is_correct": false, "explanation": "可能形では「養えたい」となり、希望の意味が通らない。"}], "correct_form": "養い", "base_form": "養う", "form_label": "連用形", "sentence_index": 1, "explanations": {"養い": "連用形で、「〜たい」の前に置いて希望を表す形。", "養って": "て形では「養ってたい」となり、希望の形にならない。", "養った": "た形では「養ったたい」となり、「〜たい」に続かない。", "養える": "可能形では「養えたい」となり、希望の意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39773, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その子は読書の習慣に養うため、毎日本を読んでいる。", "corrected_sentence": "その子は読書の習慣を養うため、毎日本を読んでいる。", "error_description": "「養う」の対象は「を」で示すので、「に」は誤り。誤りは「に」を「を」にする一か所。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "養う", "is_correct": true, "explanation": "辞書形で、「養うのが大変だ」の形になる。"}, {"text": "養います", "is_correct": false, "explanation": "ます形は「養いますのが」となり、「のが大変だ」に続かない。"}, {"text": "養え", "is_correct": false, "explanation": "命令形で、「のが大変だ」に続かず、文として成り立たない。"}, {"text": "養われる", "is_correct": false, "explanation": "受身形では「家族を」と合わず、家族が養われる文になってしまう。"}], "correct_form": "養う", "base_form": "養う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"養う": "辞書形で、「養うのが大変だ」の形になる。", "養います": "ます形は「養いますのが」となり、「のが大変だ」に続かない。", "養え": "命令形で、「のが大変だ」に続かず、文として成り立たない。", "養われる": "受身形では「家族を」と合わず、家族が養われる文になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39774, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39774, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ベースの四隅」と名詞を続ける形で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「ベースを四隅を」は目的語が重なり、文として不自然。"}, {"text": "が", "is_correct": false, "explanation": "「ベースが四隅を」では主語が重なり、「止めました」の文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「ベースで四隅を」は手段を示す形になり、四隅を示す名詞として続かない。"}], "correct_answer": "の", "explanations": {"の": "「ベースの四隅」と名詞を続ける形で、正しい。", "を": "「ベースを四隅を」は目的語が重なり、文として不自然。", "が": "「ベースが四隅を」では主語が重なり、「止めました」の文として不自然。", "で": "「ベースで四隅を」は手段を示す形になり、四隅を示す名詞として続かない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39774, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "土台のこと。", "primary_collocate": null, "pronunciation": "べーす", "ipa": "beːsɯ", "syllable_count": 3, "sentences": [{"text": "この棚は、ベースが広いので倒れにくいです。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "この棚[たな]は、ベースが広[ひろ]いので倒[たお]れにくいです。", "sentence_source": "generated"}, {"text": "ランプのベースに、小さな電池が入っています。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "ランプのベースに、小[ちい]さな電池[でんち]が入[はい]っています。", "sentence_source": "generated"}, {"text": "家を建てる前に、コンクリートのベースをしっかり固めました。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "家[いえ]を建[た]てる前[まえ]に、コンクリートのベースをしっかり固[かた]めました。", "sentence_source": "generated"}, {"text": "ベースがぐらぐらしていて、このスタンドは安定しません。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "ベースがぐらぐらしていて、このスタンドは安定[あんてい]しません。", "sentence_source": "generated"}, {"text": "木のベースの上に、ガラスの置物を乗せました。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "木[き]のベースの上[うえ]に、ガラスの置物[おきもの]を乗[の]せました。", "sentence_source": "generated"}, {"text": "重いベースのおかげで、マイクスタンドは風でも倒れません。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "重[おも]いベースのおかげで、マイクスタンドは風[かぜ]でも倒[たお]れません。", "sentence_source": "generated"}, {"text": "工事の人が、機械を置くためのベースを作っています。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が、機械[きかい]を置[お]くためのベースを作[つく]っています。", "sentence_source": "generated"}, {"text": "ベースの四隅を、ねじで床に止めました。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "ベースの四隅[よすみ]を、ねじで床[ゆか]に止[と]めました。", "sentence_source": "generated"}, {"text": "ベースが傷つかないように、下にゴムのシートを敷きました。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "ベースが傷[きず]つかないように、下[した]にゴムのシートを敷[し]きました。", "sentence_source": "generated"}, {"text": "この模型は、ベースを外すと立てられません。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "この模型[もけい]は、ベースを外[はず]すと立[た]てられません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベース", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "物を支える下の部分、土台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ぐらぐら (Zipf 2.27)']::text[], '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39774, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ベース", "is_correct": true, "explanation": "棚の下の土台を指すので、「広いので倒れにくい」と文が成り立つ。"}, {"text": "ハンドル", "is_correct": false, "explanation": "握って操作する部分で、棚の広さや倒れにくさの説明には合わない。"}, {"text": "ポスター", "is_correct": false, "explanation": "壁に貼る印刷物で、倒れにくさの主語にはならない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓にかける布で、棚が倒れにくいことの説明には合わない。"}], "explanations": {"ベース": "棚の下の土台を指すので、「広いので倒れにくい」と文が成り立つ。", "ハンドル": "握って操作する部分で、棚の広さや倒れにくさの説明には合わない。", "ポスター": "壁に貼る印刷物で、倒れにくさの主語にはならない。", "カーテン": "窓にかける布で、棚が倒れにくいことの説明には合わない。"}, "sentence_index": 0, "correct_answer": "ベース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ナイフのベースが折れてしまいました。", "explanation": "ここは〈柄〉の意味。ベースは物の下の土台のことで、手で握る柄の意味とは合わない。"}, {"text": "この瓶はベースを開けると、中に粉が入っています。", "explanation": "ここは〈ふた〉の意味。ベースは物を下から支える土台で、上にかぶせるふたとは合わない。"}, {"text": "窓のベースが古くなったので、新しく取り替えました。", "explanation": "ここは〈枠〉の意味。ベースは物を支える土台で、窓を囲む枠とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39774, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ベース", "is_correct": true, "explanation": "機械を置くための土台を指すので、「作っています」と文が成り立つ。"}, {"text": "ドアノブ", "is_correct": false, "explanation": "扉を開け閉めする部品で、機械を置く土台にはならない。"}, {"text": "ハンガー", "is_correct": false, "explanation": "衣類を掛ける道具で、機械を置く土台の代わりにはならない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "歯を磨く道具で、機械を置くための土台にはならない。"}], "explanations": {"ベース": "機械を置くための土台を指すので、「作っています」と文が成り立つ。", "ドアノブ": "扉を開け閉めする部品で、機械を置く土台にはならない。", "ハンガー": "衣類を掛ける道具で、機械を置く土台の代わりにはならない。", "歯ブラシ": "歯を磨く道具で、機械を置くための土台にはならない。"}, "sentence_index": 6, "correct_answer": "ベース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "メーターのベースが見えにくいです。", "explanation": "ここは〈目盛り〉の意味。ベースは物の土台で、数値を示す目盛りとは合わない。"}, {"text": "リモコンのベースを押すと、テレビがつきます。", "explanation": "ここは〈ボタン〉の意味。ベースは物を支える土台で、押して操作するボタンとは合わない。"}, {"text": "ベースの音が大きすぎて、ボーカルの声が聞こえません。", "explanation": "ここは〈低音楽器〉の意味。ベースは物の土台のことで、楽器の音を指す使い方とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39774, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベースを小さな穴を開けてから、ねじを通します。", "corrected_sentence": "ベースに小さな穴を開けてから、ねじを通します。", "error_description": "穴を開ける場所には「に」を付ける。「を」を付けると目的語が重なり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39774, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベースをはずさて、中の電池を取り出します。", "corrected_sentence": "ベースをはずして、中の電池を取り出します。", "error_description": "「はずす」のて形は「はずして」。「はずさて」は活用の形が誤りで、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39775, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39775, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ベースに改良される」と基礎として使う形で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「設計をベースを改良された」は目的語が重なり、文として不自然。"}, {"text": "が", "is_correct": false, "explanation": "「ベースが改良された」では主語になり、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「ベースの改良された」の形では文が続かず、不自然。"}], "correct_answer": "に", "explanations": {"に": "「ベースに改良される」と基礎として使う形で、正しい。", "を": "「設計をベースを改良された」は目的語が重なり、文として不自然。", "が": "「ベースが改良された」では主語になり、意味が通らない。", "の": "「ベースの改良された」の形では文が続かず、不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39775, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の基礎や出発点となる部分。", "primary_collocate": null, "pronunciation": "べーす", "ipa": "beːsɯ", "syllable_count": 3, "sentences": [{"text": "この計画は、去年の調査をベースに作られました。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "この計画[けいかく]は、去年[きょねん]の調査[ちょうさ]をベースに作[つく]られました。", "sentence_source": "generated"}, {"text": "日本料理の味のベースは、昆布とかつおのだしです。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "日本料理[にほんりょうり]の味[あじ]のベースは、昆布[こんぶ]とかつおのだしです。", "sentence_source": "generated"}, {"text": "彼の考え方のベースには、家族への感謝があります。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]え方[かた]のベースには、家族[かぞく]への感謝[かんしゃ]があります。", "sentence_source": "generated"}, {"text": "このスープは、トマトをベースにして作ります。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "このスープは、トマトをベースにして作[つく]ります。", "sentence_source": "generated"}, {"text": "基本の文法がベースにあれば、新しい表現も覚えやすいです。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "基本[きほん]の文法[ぶんぽう]がベースにあれば、新[あたら]しい表現[ひょうげん]も覚[おぼ]えやすいです。", "sentence_source": "generated"}, {"text": "実際にあった話をベースにした映画が、人気です。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "実際[じっさい]にあった話[はなし]をベースにした映画[えいが]が、人気[にんき]です。", "sentence_source": "generated"}, {"text": "ベースがしっかりしているので、応用の問題も解けます。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "ベースがしっかりしているので、応用[おうよう]の問題[もんだい]も解[と]けます。", "sentence_source": "generated"}, {"text": "この製品は、古い設計をベースに改良されました。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "この製品[せいひん]は、古[ふる]い設計[せっけい]をベースに改良[かいりょう]されました。", "sentence_source": "generated"}, {"text": "経験をベースに、新しい方法を考えました。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "経験[けいけん]をベースに、新[あたら]しい方法[ほうほう]を考[かんが]えました。", "sentence_source": "generated"}, {"text": "チームの信頼関係がベースにあるから、意見を自由に言えます。", "target_word": "ベース", "complexity_tier": "T3", "furigana": "チームの信頼関係[しんらいかんけい]がベースにあるから、意見[いけん]を自由[じゆう]に言[い]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベース", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "物事の基礎や出発点になるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39775, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ベース", "is_correct": true, "explanation": "「調査をベースに作る」で、基礎として使うという意味に合い、文が成り立つ。"}, {"text": "ハンガー", "is_correct": false, "explanation": "衣類を掛ける道具で、調査を基礎にして計画を作ることはできない。"}, {"text": "ゴム", "is_correct": false, "explanation": "弾性のある材料で、調査を基礎に計画を作る意味には合わない。"}, {"text": "ドア", "is_correct": false, "explanation": "出入りする戸で、調査を基礎にして計画を作る意味には合わない。"}], "explanations": {"ベース": "「調査をベースに作る」で、基礎として使うという意味に合い、文が成り立つ。", "ハンガー": "衣類を掛ける道具で、調査を基礎にして計画を作ることはできない。", "ゴム": "弾性のある材料で、調査を基礎に計画を作る意味には合わない。", "ドア": "出入りする戸で、調査を基礎にして計画を作る意味には合わない。"}, "sentence_index": 0, "correct_answer": "ベース"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この話し合いのベースは、来週に出します。", "explanation": "ここは〈結論〉の意味。ベースは物事の出発点となる基礎で、話し合いの最後に出す結論とは合わない。"}, {"text": "先生がベースをくれたので、答えがわかりました。", "explanation": "ここは〈ヒント〉の意味。ベースは物事の基礎や出発点で、答えを探すための手がかりとは合わない。"}, {"text": "このバンドでは、ベースを弾く人が一番若いです。", "explanation": "ここは〈低音楽器〉の意味。ベースは物事の基礎や出発点の意味で、楽器の名前としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39775, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ベース", "is_correct": true, "explanation": "物事の土台として「しっかりしている」と言えるので、文が成り立つ。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓にかける布で、応用の問題を解く土台の意味にはならない。"}, {"text": "ポスター", "is_correct": false, "explanation": "掲示用の印刷物で、基礎としてしっかりしているとは言わない。"}, {"text": "ストーブ", "is_correct": false, "explanation": "暖房器具で、応用の問題を解く基礎にはならない。"}], "explanations": {"ベース": "物事の土台として「しっかりしている」と言えるので、文が成り立つ。", "カーテン": "窓にかける布で、応用の問題を解く土台の意味にはならない。", "ポスター": "掲示用の印刷物で、基礎としてしっかりしているとは言わない。", "ストーブ": "暖房器具で、応用の問題を解く基礎にはならない。"}, "sentence_index": 6, "correct_answer": "ベース"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小説のベースを、先に読んで確かめました。", "explanation": "ここは〈あらすじ〉の意味。ベースは物事の基礎で、内容を短くまとめた紹介文とは合わない。"}, {"text": "今後のベースは明るいです。", "explanation": "ここは〈見通し〉の意味。ベースは物事の出発点となる基礎で、これからの成り行きの見通しとは合わない。"}, {"text": "この料理は、味のベースがよく取れています。", "explanation": "ここは〈バランス〉の意味で使う言葉。「バランスがよく取れる」とは言うが、「ベースが取れる」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39775, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究は、古い理論をベースを進めました。", "corrected_sentence": "この研究は、古い理論をベースにして進めました。", "error_description": "「ベースにして」が正しい。「ベースを」では目的語の形になり、「進めました」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39775, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その考えがベースにして、新しい方法が生まれました。", "corrected_sentence": "その考えがベースになって、新しい方法が生まれました。", "error_description": "「ベースになって」が正しい。「ベースにして」は「する」の形で、主語の「考え」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39776, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「資料を追加する」で、足す対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「資料で追加する」は手段・場所の「で」になり、対象を示す「を」と合わず意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「資料と追加する」は共同の「と」で、文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "名詞に付く「の」で、動詞「追加する」の前に置くと文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「資料を追加する」で、足す対象を示す。", "で": "「資料で追加する」は手段・場所の「で」になり、対象を示す「を」と合わず意味が通らない。", "と": "「資料と追加する」は共同の「と」で、文脈に合わない。", "の": "名詞に付く「の」で、動詞「追加する」の前に置くと文として成り立たない。"}, "error_tags": {"で": "手段", "と": "共同", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "削除", "is_correct": true, "explanation": "「追加」の対義語。あとから足すことの反対で、既にあるものを取り除く意味。"}, {"text": "増加", "is_correct": false, "explanation": "同じ方向（増やす）の語で、対義語ではない。"}, {"text": "保存", "is_correct": false, "explanation": "残しておく意味で、足す・取る関係にはない。"}, {"text": "採用", "is_correct": false, "explanation": "選び取り入れる意味で、対義語ではない。"}], "correct_answer": "削除", "explanations": {"削除": "「追加」の対義語。あとから足すことの反対で、既にあるものを取り除く意味。", "増加": "同じ方向（増やす）の語で、対義語ではない。", "保存": "残しておく意味で、足す・取る関係にはない。", "採用": "選び取り入れる意味で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39776, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「予定を追加する」で、足す対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「予定が追加したので」は主語の「が」になり、追加の対象を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「予定より追加したので」は比較の「より」で、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「予定の追加したので」は名詞に付く「の」で、動詞「追加した」とは続かない。"}], "correct_answer": "を", "explanations": {"を": "「予定を追加する」で、足す対象を示す。", "が": "「予定が追加したので」は主語の「が」になり、追加の対象を示せず不自然。", "より": "「予定より追加したので」は比較の「より」で、意味が通らない。", "の": "「予定の追加したので」は名詞に付く「の」で、動詞「追加した」とは続かない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "削除", "is_correct": true, "explanation": "「追加」の対義語。新しく足すことの反対で、既存のものを取り除く意味。"}, {"text": "撤回", "is_correct": false, "explanation": "取り下げる意味で、対義語ではない。"}, {"text": "作成", "is_correct": false, "explanation": "新しく作る意味で、対義語ではない。"}, {"text": "修正", "is_correct": false, "explanation": "直す意味で、対義語ではない。"}], "correct_answer": "削除", "explanations": {"削除": "「追加」の対義語。新しく足すことの反対で、既存のものを取り除く意味。", "撤回": "取り下げる意味で、対義語ではない。", "作成": "新しく作る意味で、対義語ではない。", "修正": "直す意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39776, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あとから、何かを足すこと。", "primary_collocate": null, "pronunciation": "ついか", "ipa": "tsɯika", "syllable_count": 3, "sentences": [{"text": "注文を追加したいのですが、まだ間に合いますか。", "target_word": "追加", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]を追加[ついか]したいのですが、まだ間[ま]に合[あ]いますか。", "sentence_source": "generated"}, {"text": "会議のあとで、資料を追加することになった。", "target_word": "追加", "complexity_tier": "T3", "furigana": "会議[かいぎ]のあとで、資料[しりょう]を追加[ついか]することになった。", "sentence_source": "generated"}, {"text": "料理が足りなかったので、店員さんに追加を頼んだ。", "target_word": "追加", "complexity_tier": "T3", "furigana": "料理[りょうり]が足[た]りなかったので、店員[てんいん]さんに追加[ついか]を頼[たの]んだ。", "sentence_source": "generated"}, {"text": "申し込みの締め切り後は、追加はできません。", "target_word": "追加", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みの締[し]め切[き]り後[ご]は、追加[ついか]はできません。", "sentence_source": "generated"}, {"text": "授業の途中で追加された問題は、とても難しかった。", "target_word": "追加", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の途中[とちゅう]で追加[ついか]された問題[もんだい]は、とても難[むずか]しかった。", "sentence_source": "generated"}, {"text": "追加の説明は、来週の授業で行います。", "target_word": "追加", "complexity_tier": "T3", "furigana": "追加[ついか]の説明[せつめい]は、来週[らいしゅう]の授業[じゅぎょう]で行[おこな]います。", "sentence_source": "generated"}, {"text": "ご飯の追加は、百円かかります。", "target_word": "追加", "complexity_tier": "T3", "furigana": "ご飯[はん]の追加[ついか]は、百円[ひゃくえん]かかります。", "sentence_source": "generated"}, {"text": "メールで予定を追加したので、確認してください。", "target_word": "追加", "complexity_tier": "T3", "furigana": "メールで予定[よてい]を追加[ついか]したので、確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "旅行の日が増えたので、ホテルを一泊追加した。", "target_word": "追加", "complexity_tier": "T3", "furigana": "旅行[りょこう]の日[ひ]が増[ふ]えたので、ホテルを一泊[いっぱく]追加[ついか]した。", "sentence_source": "generated"}, {"text": "先生は黒板に例を追加して、もう一度説明した。", "target_word": "追加", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に例[れい]を追加[ついか]して、もう一度[いちど]説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "追加する", "label": "サ変動詞"}, {"form": "追加して", "label": "て形"}, {"form": "追加した", "label": "た形"}, {"form": "追加される", "label": "受身形"}, {"form": "追加しない", "label": "ない形"}], "register": "普通", "sense_fingerprint": "あとから足す(注文・資料など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39776, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追加", "is_correct": true, "explanation": "「注文を追加したい」となり、注文に品を足すという意味で文脈に合う。"}, {"text": "解説", "is_correct": false, "explanation": "「注文を解説したい」は意味が通らない。注文は説明の対象にならない。"}, {"text": "採点", "is_correct": false, "explanation": "「注文を採点したい」は不自然。注文は点数をつける対象ではない。"}, {"text": "出版", "is_correct": false, "explanation": "「注文を出版したい」は意味が通らない。注文は出版されるものではない。"}], "explanations": {"追加": "「注文を追加したい」となり、注文に品を足すという意味で文脈に合う。", "解説": "「注文を解説したい」は意味が通らない。注文は説明の対象にならない。", "採点": "「注文を採点したい」は不自然。注文は点数をつける対象ではない。", "出版": "「注文を出版したい」は意味が通らない。注文は出版されるものではない。"}, "sentence_index": 0, "correct_answer": "追加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犯人は国外に追加された。", "explanation": "ここは〈追放〉の意味。追加は物事を付け足す意味で、人を国外へ追い出す意味はない。"}, {"text": "来月から人口が追加する見込みだ。", "explanation": "ここは〈増加〉の意味。追加は物を足すことで、人口が増えるという意味では使わない。"}, {"text": "猟犬が獲物を追加した。", "explanation": "ここは〈追跡〉の意味。追加は付け足す意味で、獲物を追いかける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39776, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追加", "is_correct": true, "explanation": "「ご飯の追加」で、ご飯を後から注文して足すという意味になり文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「ご飯の翻訳は百円」は意味が通らない。ご飯は翻訳の対象にならない。"}, {"text": "暗記", "is_correct": false, "explanation": "「ご飯の暗記は百円」は意味が通らない。ご飯は覚える対象ではない。"}, {"text": "採掘", "is_correct": false, "explanation": "「ご飯の採掘は百円」は意味が通らない。ご飯は掘り出すものではない。"}], "explanations": {"追加": "「ご飯の追加」で、ご飯を後から注文して足すという意味になり文脈に合う。", "翻訳": "「ご飯の翻訳は百円」は意味が通らない。ご飯は翻訳の対象にならない。", "暗記": "「ご飯の暗記は百円」は意味が通らない。ご飯は覚える対象ではない。", "採掘": "「ご飯の採掘は百円」は意味が通らない。ご飯は掘り出すものではない。"}, "sentence_index": 6, "correct_answer": "追加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ランナーが先頭に追加した。", "explanation": "ここは〈追いつく〉の意味。追加は物を付け足す意味で、相手に並ぶ意味はない。"}, {"text": "細菌が一晩で追加した。", "explanation": "ここは〈増殖〉の意味。細菌が自分で増える意味で、外から物を足す追加とは合わない。"}, {"text": "前の車を追加した。", "explanation": "ここは〈追い越す〉の意味。追加は付け足す意味で、前の車を抜き去る意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
