INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39776, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "説明の最後に、例が追加する。", "corrected_sentence": "説明の最後に、例を追加する。", "error_description": "「追加する」の対象は「を」で示す。「例が追加する」は助詞の誤りで、主語と動詞が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
