INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39777, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「新しい行を追加する」で、足す対象を示す。"}, {"text": "から", "is_correct": false, "explanation": "「行から追加してから」は起点の「から」で、足す対象を示さず意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「行より追加してから」は比較の「より」で、文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「行の追加してから」は名詞に付く「の」で、動詞「追加して」とは続かない。"}], "correct_answer": "を", "explanations": {"を": "「新しい行を追加する」で、足す対象を示す。", "から": "「行から追加してから」は起点の「から」で、足す対象を示さず意味が通らない。", "より": "「行より追加してから」は比較の「より」で、文脈に合わない。", "の": "「行の追加してから」は名詞に付く「の」で、動詞「追加して」とは続かない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "削除", "is_correct": true, "explanation": "「追加」の対義語。新しく足すことの反対で、既存のものを取り除く意味。"}, {"text": "増加", "is_correct": false, "explanation": "同じ方向（増やす）の語で、対義語ではない。"}, {"text": "保存", "is_correct": false, "explanation": "残しておく意味で、対義語ではない。"}, {"text": "採用", "is_correct": false, "explanation": "選び取り入れる意味で、対義語ではない。"}], "correct_answer": "削除", "explanations": {"削除": "「追加」の対義語。新しく足すことの反対で、既存のものを取り除く意味。", "増加": "同じ方向（増やす）の語で、対義語ではない。", "保存": "残しておく意味で、対義語ではない。", "採用": "選び取り入れる意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39777, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "すでにあるものに、新しいものを付け加えること。", "primary_collocate": null, "pronunciation": "ついか", "ipa": "tsɯika", "syllable_count": 3, "sentences": [{"text": "このアプリに新しい機能が追加された。", "target_word": "追加", "complexity_tier": "T3", "furigana": "このアプリに新[あたら]しい機能[きのう]が追加[ついか]された。", "sentence_source": "generated"}, {"text": "チームに二人の選手を追加して、強くなった。", "target_word": "追加", "complexity_tier": "T3", "furigana": "チームに二人[ふたり]の選手[せんしゅ]を追加[ついか]して、強[つよ]くなった。", "sentence_source": "generated"}, {"text": "部屋にたなを追加したので、荷物が入るようになった。", "target_word": "追加", "complexity_tier": "T3", "furigana": "部屋[へや]にたなを追加[ついか]したので、荷物[にもつ]が入[はい]るようになった。", "sentence_source": "generated"}, {"text": "辞書に新しい言葉を追加する仕事をしている。", "target_word": "追加", "complexity_tier": "T3", "furigana": "辞書[じしょ]に新[あたら]しい言葉[ことば]を追加[ついか]する仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "古い家に、広い台所を追加した。", "target_word": "追加", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]に、広[ひろ]い台所[だいどころ]を追加[ついか]した。", "sentence_source": "generated"}, {"text": "メニューに季節のデザートが追加されました。", "target_word": "追加", "complexity_tier": "T3", "furigana": "メニューに季節[きせつ]のデザートが追加[ついか]されました。", "sentence_source": "generated"}, {"text": "今のプランにサービスを追加すると、料金が上がる。", "target_word": "追加", "complexity_tier": "T3", "furigana": "今[いま]のプランにサービスを追加[ついか]すると、料金[りょうきん]が上[あ]がる。", "sentence_source": "generated"}, {"text": "表に新しい行を追加してから、数字を入れてください。", "target_word": "追加", "complexity_tier": "T3", "furigana": "表[ひょう]に新[あたら]しい行[ぎょう]を追加[ついか]してから、数字[すうじ]を入[い]れてください。", "sentence_source": "generated"}, {"text": "駅前の道に、バス停が一つ追加される予定だ。", "target_word": "追加", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の道[みち]に、バス停[てい]が一[ひと]つ追加[ついか]される予定[よてい]だ。", "sentence_source": "generated"}, {"text": "計画に新しい案を追加したら、もっと良くなった。", "target_word": "追加", "complexity_tier": "T3", "furigana": "計画[けいかく]に新[あたら]しい案[あん]を追加[ついか]したら、もっと良[よ]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "追加する", "label": "サ変動詞"}, {"form": "追加して", "label": "て形"}, {"form": "追加した", "label": "た形"}, {"form": "追加される", "label": "受身形"}, {"form": "追加しない", "label": "ない形"}], "register": "普通", "sense_fingerprint": "既存のものに新しい要素を付け加える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6594844-572f-479f-92a0-dc80fd5f0199') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39777, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追加", "is_correct": true, "explanation": "「新しい機能が追加された」で、既存のアプリに機能を付け加えた意味になり文脈に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "「機能が採掘された」は意味が通らない。機能は掘り出すものではない。"}, {"text": "作曲", "is_correct": false, "explanation": "「機能が作曲された」は不自然。機能は曲を作る対象にならない。"}, {"text": "暗記", "is_correct": false, "explanation": "「機能が暗記された」は意味が通らない。機能は覚える対象ではない。"}], "explanations": {"追加": "「新しい機能が追加された」で、既存のアプリに機能を付け加えた意味になり文脈に合う。", "採掘": "「機能が採掘された」は意味が通らない。機能は掘り出すものではない。", "作曲": "「機能が作曲された」は不自然。機能は曲を作る対象にならない。", "暗記": "「機能が暗記された」は意味が通らない。機能は覚える対象ではない。"}, "sentence_index": 0, "correct_answer": "追加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "野良犬を追加した。", "explanation": "ここは〈追い払う〉の意味。追加は付け足す意味で、動物を追い散らす意味はない。"}, {"text": "ウイルスが追加した。", "explanation": "ここは〈増殖〉の意味。ウイルスが自分で増える意味で、外から物を加える追加とは合わない。"}, {"text": "犯人を追加した。", "explanation": "ここは〈追い詰める〉の意味。追加は付け足す意味で、相手を逃げ場のない所まで追う意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39777, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追加", "is_correct": true, "explanation": "「サービスを追加すると、料金が上がる」で、プランに項目を足す意味になり文脈に合う。"}, {"text": "出版", "is_correct": false, "explanation": "「サービスを出版すると」は意味が通らない。サービスは出版の対象にならない。"}, {"text": "採点", "is_correct": false, "explanation": "「サービスを採点すると料金が上がる」は意味が通らない。料金との関係が成り立たない。"}, {"text": "撮影", "is_correct": false, "explanation": "「サービスを撮影すると」は意味が通らない。サービスは撮影の対象にならない。"}], "explanations": {"追加": "「サービスを追加すると、料金が上がる」で、プランに項目を足す意味になり文脈に合う。", "出版": "「サービスを出版すると」は意味が通らない。サービスは出版の対象にならない。", "採点": "「サービスを採点すると料金が上がる」は意味が通らない。料金との関係が成り立たない。", "撮影": "「サービスを撮影すると」は意味が通らない。サービスは撮影の対象にならない。"}, "sentence_index": 6, "correct_answer": "追加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カラスが子猫を追加した。", "explanation": "ここは〈追いかける〉の意味。追加は付け足す意味で、動物が相手を追う意味はない。"}, {"text": "ウサギが追加して、数が増えた。", "explanation": "ここは〈繁殖〉の意味。ウサギが自然に増える意味で、外から物を足す追加とは合わない。"}, {"text": "訪問販売員を追加した。", "explanation": "ここは〈追い返す〉の意味。追加は付け足す意味で、人を追い払う意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39777, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ウェブサイトに新しい地図が追加した。", "corrected_sentence": "ウェブサイトに新しい地図を追加した。", "error_description": "「追加した」の対象（追加されるもの）は「を」で示す。「が」は誤り。主体が動作をするなら「追加した」、対象が主語なら「追加された」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39777, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表の下に合計の欄を追加ない。", "corrected_sentence": "表の下に合計の欄を追加しない。", "error_description": "「追加」はサ変動詞なので活用は「追加した」「追加しない」になる。「追加ない」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3407aff2-4c40-4fb3-aaae-62d6b6087b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39778, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す。「このカメラは」と話題として置くと、後ろの説明に自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す。「このカメラを小さくて軽いので」とは続かず、形容詞の文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点や相手を示す。「このカメラに小さくて軽い」と述語にならず不可。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「このカメラで小さくて軽い」と続かず、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す。「このカメラは」と話題として置くと、後ろの説明に自然につながる。", "を": "動作の対象を示す。「このカメラを小さくて軽いので」とは続かず、形容詞の文に合わない。", "に": "帰着点や相手を示す。「このカメラに小さくて軽い」と述語にならず不可。", "で": "手段や場所を示す。「このカメラで小さくて軽い」と続かず、文が成り立たない。"}, "error_tags": {"を": "目的語の格（動作の対象）", "に": "帰着点・相手の格", "で": "手段・場所の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39778, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「カメラがついていて」で、カメラが付いている主体として自然に続く。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す。「カメラとついていて」と続かず、取り付けの文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「カメラへついていて」は取り付けの意味にならず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「カメラからついていて」と続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「カメラがついていて」で、カメラが付いている主体として自然に続く。", "と": "並列や相手を示す。「カメラとついていて」と続かず、取り付けの文に合わない。", "へ": "方向を示す。「カメラへついていて」は取り付けの意味にならず、文が成り立たない。", "から": "起点を示す。「カメラからついていて」と続かず、文が成り立たない。"}, "error_tags": {"と": "並列・相手の格", "へ": "方向の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39778, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の形をうつすための道具です。", "primary_collocate": null, "pronunciation": "かめら", "ipa": "kamera", "syllable_count": 3, "sentences": [{"text": "旅行にカメラを持っていく。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "旅行[りょこう]にカメラを持[も]っていく。", "sentence_source": "generated"}, {"text": "このカメラは小さくて軽いので、かばんに入れやすい。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "このカメラは小[ちい]さくて軽[かる]いので、かばんに入[い]れやすい。", "sentence_source": "generated"}, {"text": "古いカメラを父からもらった。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "古[ふる]いカメラを父[ちち]からもらった。", "sentence_source": "generated"}, {"text": "カメラを向けると、犬は走って逃げてしまった。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "カメラを向[む]けると、犬[いぬ]は走[はし]って逃[に]げてしまった。", "sentence_source": "generated"}, {"text": "新しいカメラを買うために、お金をためている。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "新[あたら]しいカメラを買[か]うために、お金[かね]をためている。", "sentence_source": "generated"}, {"text": "カメラのレンズをきれいにふいた。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "カメラのレンズをきれいにふいた。", "sentence_source": "generated"}, {"text": "電池が切れて、カメラが動かなくなった。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "電池[でんち]が切[き]れて、カメラが動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "店の入り口にカメラがついていて、道が映る。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "店[みせ]の入[い]り口[ぐち]にカメラがついていて、道[みち]が映[うつ]る。", "sentence_source": "generated"}, {"text": "姉はカメラが好きで、毎週山へ出かける。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "姉[あね]はカメラが好[す]きで、毎週[まいしゅう]山[やま]へ出[で]かける。", "sentence_source": "generated"}, {"text": "カメラの前に立つと、緊張して声が出なかった。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "カメラの前[まえ]に立[た]つと、緊張[きんちょう]して声[こえ]が出[で]なかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カメラ", "label": "基本形"}], "register": "標準（日常語）", "sense_fingerprint": "物の形をうつす道具としての camera（装置そのもの）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39778, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カメラ", "is_correct": true, "explanation": "文中の形。旅行に持っていく道具として、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "持ち運べない現象。「旅行に天気を持っていく」は意味が成り立たず、空欄に入らない。"}, {"text": "海", "is_correct": false, "explanation": "持ち運べない場所。「旅行に海を持っていく」は意味が成り立たない。"}, {"text": "気温", "is_correct": false, "explanation": "持ち運べない数値。「旅行に気温を持っていく」は意味が成り立たず、空欄に入らない。"}], "explanations": {"カメラ": "文中の形。旅行に持っていく道具として、文に合う。", "天気": "持ち運べない現象。「旅行に天気を持っていく」は意味が成り立たず、空欄に入らない。", "海": "持ち運べない場所。「旅行に海を持っていく」は意味が成り立たない。", "気温": "持ち運べない数値。「旅行に気温を持っていく」は意味が成り立たず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "カメラ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カメラで風を送って、部屋を涼しくした。", "explanation": "ここは〈扇風機〉の意味。風を送って部屋を涼しくする道具は扇風機で、カメラからは風は出ないので合わない。"}, {"text": "カメラで食べ物を冷やして、長持ちさせた。", "explanation": "ここは〈冷蔵庫〉の意味。食べ物を冷やして保存する道具は冷蔵庫で、カメラには冷やす機能がないので合わない。"}, {"text": "カメラで床のごみを吸い取った。", "explanation": "ここは〈掃除機〉の意味。床のごみを吸い取る道具は掃除機で、カメラではごみは吸えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39778, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カメラ", "is_correct": true, "explanation": "文中の形。電池で動く機械の主語で、「動かなくなった」と合う。"}, {"text": "壁", "is_correct": false, "explanation": "動く機械ではない建材。電池の話の主語として不自然で、空欄に入らない。"}, {"text": "雨", "is_correct": false, "explanation": "自然現象で電池と結びつかない。電池が切れた話の主語にならない。"}, {"text": "天井", "is_correct": false, "explanation": "建物の一部で、電池で動く物ではないので、空欄に入らない。"}], "explanations": {"カメラ": "文中の形。電池で動く機械の主語で、「動かなくなった」と合う。", "壁": "動く機械ではない建材。電池の話の主語として不自然で、空欄に入らない。", "雨": "自然現象で電池と結びつかない。電池が切れた話の主語にならない。", "天井": "建物の一部で、電池で動く物ではないので、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "カメラ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カメラで手紙を書くと、気持ちが伝わる。", "explanation": "ここは〈ペン〉の意味。文字を書く道具はペンで、カメラでは手紙は書けない。"}, {"text": "カメラでスープを飲むと、体が温まる。", "explanation": "ここは〈スプーン〉の意味。スープをすくって飲む道具はスプーンで、カメラでは飲めない。"}, {"text": "カメラで庭に水をまいた。", "explanation": "ここは〈ホース〉の意味。水を遠くへ送って流す道具はホースで、カメラで水をまくことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39778, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行の日にカメラが持っていく。", "corrected_sentence": "旅行の日にカメラを持っていく。", "error_description": "目的語の助詞の誤り。「持っていく」の対象は「を」で示すので、「カメラが」ではなく「カメラを」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39778, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電池がなくなって、カメラを動かなくなった。", "corrected_sentence": "電池がなくなって、カメラが動かなくなった。", "error_description": "自動詞「動く」の主語に「を」を付けた誤り。「カメラが動かなくなった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
