INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39779, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「カメラを使ってはいけない」で、使う対象として自然。"}, {"text": "の", "is_correct": false, "explanation": "修飾・所有を示す。「カメラの使ってはいけない」と名詞が続かず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「カメラへ使ってはいけない」と続かず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「カメラから使ってはいけない」と続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「カメラを使ってはいけない」で、使う対象として自然。", "の": "修飾・所有を示す。「カメラの使ってはいけない」と名詞が続かず、文が成り立たない。", "へ": "方向を示す。「カメラへ使ってはいけない」と続かず、文が成り立たない。", "から": "起点を示す。「カメラから使ってはいけない」と続かず、文が成り立たない。"}, "error_tags": {"へ": "方向の格", "から": "起点の格", "の": "修飾・所有の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39779, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "写真を撮るための機械。写したい物にレンズを向けて、ボタンを押すと、その場面を記録できる。", "primary_collocate": null, "pronunciation": "かめら", "ipa": "kamera", "syllable_count": 3, "sentences": [{"text": "カメラのボタンを押すと、写真が撮れる。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "カメラのボタンを押[お]すと、写真[しゃしん]が撮[と]れる。", "sentence_source": "generated"}, {"text": "公園で花をカメラで撮った。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "公園[こうえん]で花[はな]をカメラで撮[と]った。", "sentence_source": "generated"}, {"text": "運動会の日は、早起きしてカメラを準備した。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の日[ひ]は、早起[はやお]きしてカメラを準備[じゅんび]した。", "sentence_source": "generated"}, {"text": "カメラの画面で、撮った写真をすぐ確認できる。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "カメラの画面[がめん]で、撮[と]った写真[しゃしん]をすぐ確認[かくにん]できる。", "sentence_source": "generated"}, {"text": "先生に頼んで、カメラで集合写真を撮ってもらった。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "先生[せんせい]に頼[たの]んで、カメラで集合写真[しゅうごうしゃしん]を撮[と]ってもらった。", "sentence_source": "generated"}, {"text": "このカメラは暗い場所でもきれいに写る。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "このカメラは暗[くら]い場所[ばしょ]でもきれいに写[うつ]る。", "sentence_source": "generated"}, {"text": "修理に出したカメラが、昨日やっと戻ってきた。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "修理[しゅうり]に出[だ]したカメラが、昨日[きのう]やっと戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "美術館の中では、カメラを使ってはいけない。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]の中[なか]では、カメラを使[つか]ってはいけない。", "sentence_source": "generated"}, {"text": "祖母はカメラを首にかけて、桜を見に行った。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "祖母[そぼ]はカメラを首[くび]にかけて、桜[さくら]を見[み]に行[い]った。", "sentence_source": "generated"}, {"text": "高いカメラを落として、レンズが割れてしまった。", "target_word": "カメラ", "complexity_tier": "T3", "furigana": "高[たか]いカメラを落[お]として、レンズが割[わ]れてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カメラ", "label": "基本形"}], "register": "標準（日常語）", "sense_fingerprint": "レンズを向けてボタンを押し、写真で場面を記録する機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d21cf5d-f729-4c5e-b9cd-2c0746b4a406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39779, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カメラ", "is_correct": true, "explanation": "文中の形。ボタンを押して写真を撮れる機械で、「カメラのボタンを押すと、写真が撮れる」として自然。"}, {"text": "本棚", "is_correct": false, "explanation": "写真を撮れる機械ではない家具。「本棚のボタンを押すと写真が撮れる」は意味が成り立たず、空欄に入らない。"}, {"text": "座布団", "is_correct": false, "explanation": "布製品でボタンはなく、写真とは結びつかない。空欄に入らない。"}, {"text": "窓", "is_correct": false, "explanation": "ボタンを押して写真が撮れる物ではない。「窓のボタンを押すと写真が撮れる」は成り立たない。"}], "explanations": {"カメラ": "文中の形。ボタンを押して写真を撮れる機械で、「カメラのボタンを押すと、写真が撮れる」として自然。", "本棚": "写真を撮れる機械ではない家具。「本棚のボタンを押すと写真が撮れる」は意味が成り立たず、空欄に入らない。", "座布団": "布製品でボタンはなく、写真とは結びつかない。空欄に入らない。", "窓": "ボタンを押して写真が撮れる物ではない。「窓のボタンを押すと写真が撮れる」は成り立たない。"}, "sentence_index": 0, "correct_answer": "カメラ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カメラの画面で、温め時間を確かめた。", "explanation": "ここは〈電子レンジ〉の意味。温め時間を表示して確かめるのは電子レンジで、カメラでは温め時間は分からない。"}, {"text": "カメラの画面で、買い物の合計金額を計算した。", "explanation": "ここは〈計算機〉の意味。金額を足し引きして計算するのは計算機で、カメラの画面では合計は出せないので合わない。"}, {"text": "カメラの画面で、買った野菜を冷やして保存した。", "explanation": "ここは〈冷蔵庫〉の意味。野菜を冷やして保存するのは冷蔵庫で、カメラは冷やすことができないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39779, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カメラ", "is_correct": true, "explanation": "文中の形。修理に出して戻ってくる物として、「修理に出したカメラが戻ってきた」と自然。"}, {"text": "夏休み", "is_correct": false, "explanation": "修理に出せない時期。「修理に出した夏休みが戻ってきた」は成り立たず、空欄に入らない。"}, {"text": "空", "is_correct": false, "explanation": "修理に出せない自然物。「修理に出した空が戻ってきた」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "修理に出せない現象。「修理に出した天気が戻ってきた」は意味が成り立たない。"}], "explanations": {"カメラ": "文中の形。修理に出して戻ってくる物として、「修理に出したカメラが戻ってきた」と自然。", "夏休み": "修理に出せない時期。「修理に出した夏休みが戻ってきた」は成り立たず、空欄に入らない。", "空": "修理に出せない自然物。「修理に出した空が戻ってきた」は成り立たない。", "天気": "修理に出せない現象。「修理に出した天気が戻ってきた」は意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "カメラ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "高いカメラを落として、骨が折れてしまった。", "explanation": "ここは〈傘〉の意味。骨が折れるのは傘などの道具で、カメラには骨にあたる部品はないので合わない。"}, {"text": "高いカメラを落として、お茶がこぼれてしまった。", "explanation": "ここは〈水筒〉の意味。中の飲み物がこぼれるのは水筒で、カメラには飲み物を入れることはできないので合わない。"}, {"text": "高いカメラを落として、ページが折れてしまった。", "explanation": "ここは〈辞書〉の意味。ページがあるのは本や辞書で、カメラにはページはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39779, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カメラにシャッターを押すと、写真が撮れる。", "corrected_sentence": "カメラのシャッターを押すと、写真が撮れる。", "error_description": "「カメラ」に付く助詞の誤り。所有や修飾を表す「の」を「に」にしたのが誤り。正しくは「カメラのシャッター」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39779, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修理に出したカメラを、昨日ようやく戻ってきた。", "corrected_sentence": "修理に出したカメラが、昨日ようやく戻ってきた。", "error_description": "主語「カメラ」の助詞の誤り。戻ってくる主体は「が」で示すので、「を」は不可。正しくは「カメラが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab34d665-f01a-4eba-b5e8-9aab20d6c140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
