INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39780, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "思いつき。新しいことを考えるときの心の中の絵や考え。", "primary_collocate": null, "pronunciation": "あいでぃあ", "ipa": "aidʲia", "syllable_count": 4, "sentences": [{"text": "いいアイディアが急に頭に浮かびました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "いいアイディアが急[きゅう]に頭[あたま]に浮[う]かびました。", "sentence_source": "generated"}, {"text": "シャワーを浴びているとき、新しいアイディアを思いつきました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "シャワーを浴[あ]びているとき、新[あたら]しいアイディアを思[おも]いつきました。", "sentence_source": "generated"}, {"text": "そのアイディアはおもしろいですが、お金がかかりすぎます。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "そのアイディアはおもしろいですが、お金[かね]がかかりすぎます。", "sentence_source": "generated"}, {"text": "夜中に、ふとアイディアがひらめいて、すぐ紙に書きました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "夜中[よなか]に、ふとアイディアがひらめいて、すぐ紙[かみ]に書[か]きました。", "sentence_source": "generated"}, {"text": "彼女のアイディアのおかげで、部屋が広く使えるようになりました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のアイディアのおかげで、部屋[へや]が広[ひろ]く使[つか]えるようになりました。", "sentence_source": "generated"}, {"text": "いいアイディアが出ないときは、散歩に行きます。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "いいアイディアが出[で]ないときは、散歩[さんぽ]に行[い]きます。", "sentence_source": "generated"}, {"text": "私のアイディアを、先生は「とてもおもしろい」と言ってくれました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "私[わたし]のアイディアを、先生[せんせい]は「とてもおもしろい」と言[い]ってくれました。", "sentence_source": "generated"}, {"text": "古い傘を植木鉢にするなんて、すてきなアイディアですね。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "古[ふる]い傘[かさ]を植木鉢[うえきばち]にするなんて、すてきなアイディアですね。", "sentence_source": "generated"}, {"text": "アイディアはあるのですが、まだ形にできていません。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "アイディアはあるのですが、まだ形[かたち]にできていません。", "sentence_source": "generated"}, {"text": "メモ帳には、思いついたアイディアをすぐ書いています。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "メモ帳[ちょう]には、思[おも]いついたアイディアをすぐ書[か]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アイディア", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "ふと頭に浮かぶ思いつき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39780, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アイディア", "is_correct": true, "explanation": "「いい思いつき」を表し、急に頭に浮かぶものとして自然に合う。"}, {"text": "疲れ", "is_correct": false, "explanation": "「いい疲れ」は体の感覚を指し、頭に浮かぶものではないので合わない。"}, {"text": "頭痛", "is_correct": false, "explanation": "「頭痛」は痛みの症状で、「いい頭痛」とは言わず、頭に浮かぶ対象にもならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は眠くなる感覚で、急に頭に浮かぶ考えとしては合わない。"}], "explanations": {"アイディア": "「いい思いつき」を表し、急に頭に浮かぶものとして自然に合う。", "疲れ": "「いい疲れ」は体の感覚を指し、頭に浮かぶものではないので合わない。", "頭痛": "「頭痛」は痛みの症状で、「いい頭痛」とは言わず、頭に浮かぶ対象にもならない。", "眠気": "「眠気」は眠くなる感覚で、急に頭に浮かぶ考えとしては合わない。"}, "sentence_index": 0, "correct_answer": "アイディア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の旅行のアイディアを立てました。", "explanation": "ここは〈計画〉の意味。アイディアは思いつきのことで、「立てる」ものではないので合わない。"}, {"text": "熱が出たので、アイディアを測りました。", "explanation": "ここは〈体温〉を測る文脈。アイディアは数値で測れないので、「測る」対象にならない。"}, {"text": "この服は、やわらかいアイディアで作られています。", "explanation": "ここは〈素材〉の意味。アイディアは形のない思いつきなので、布のように素材として使われるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39780, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アイディア", "is_correct": true, "explanation": "「私のアイディア」は自分が考えた案を指し、「おもしろい」と評価される対象として合う。"}, {"text": "不安", "is_correct": false, "explanation": "「不安」は感情で、先生が「おもしろい」と評価するものではないので合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹」は体の状態で、「おもしろい」と評価される対象ではない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足」は体調を表し、先生が「おもしろい」と評価するものではない。"}], "explanations": {"アイディア": "「私のアイディア」は自分が考えた案を指し、「おもしろい」と評価される対象として合う。", "不安": "「不安」は感情で、先生が「おもしろい」と評価するものではないので合わない。", "空腹": "「空腹」は体の状態で、「おもしろい」と評価される対象ではない。", "寝不足": "「寝不足」は体調を表し、先生が「おもしろい」と評価するものではない。"}, "sentence_index": 6, "correct_answer": "アイディア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月のアイディアが三万円上がりました。", "explanation": "ここは〈給料〉の意味。アイディアは金額ではないので、「三万円上がる」とは言えない。"}, {"text": "私のアイディアは、東京都です。", "explanation": "ここは〈住所〉の意味。アイディアには所在地がないので、「東京都です」とは言えない。"}, {"text": "このアイディアの営業時間は、十時から二十時です。", "explanation": "ここは〈営業時間〉の意味。アイディアは店ではないので、開いている時間を指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39780, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "よく寝たので、いいアイディアを頭に浮かびました。", "corrected_sentence": "よく寝たので、いいアイディアが頭に浮かびました。", "error_description": "助詞の誤り。「浮かぶ」は主語を「が」で示す自動詞なので、「を」ではなく「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39780, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、いいアイディアを思いつくので、びっくりしました。", "corrected_sentence": "昨日、いいアイディアを思いついたので、びっくりしました。", "error_description": "時制の誤り。「昨日」という過去の出来事なので、「思いつく」を過去形「思いついた」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39781, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は手段・原因を示す。アイディアによって売り上げが伸びた、という文になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「伸びる」は自動詞なので文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、売り上げが伸びる原因にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここでは比べる対象が文中にないので合わない。"}], "correct_answer": "で", "explanations": {"で": "「で」は手段・原因を示す。アイディアによって売り上げが伸びた、という文になる。", "を": "「を」は目的語を示すが、「伸びる」は自動詞なので文として成り立たない。", "へ": "「へ」は方向を示すので、売り上げが伸びる原因にはならない。", "より": "「より」は比較を示すが、ここでは比べる対象が文中にないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39781, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「歓迎する」の対象を示す「を」。新しいアイディアを歓迎する、という文になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、歓迎する動作の主体ではないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示し、歓迎する対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、歓迎する対象を示す語としては成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「歓迎する」の対象を示す「を」。新しいアイディアを歓迎する、という文になる。", "が": "「が」は主語を示すが、歓迎する動作の主体ではないので合わない。", "で": "「で」は手段・場所を示し、歓迎する対象にはならない。", "と": "「と」は並列や相手を示すが、歓迎する対象を示す語としては成り立たない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39781, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "新しい物事を考え出すこと。また、その考え。", "primary_collocate": null, "pronunciation": "あいでぃあ", "ipa": "aidʲia", "syllable_count": 4, "sentences": [{"text": "新商品のアイディアを、会議で三つ発表しました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "新商品[しんしょうひん]のアイディアを、会議[かいぎ]で三[みっ]つ発表[はっぴょう]しました。", "sentence_source": "generated"}, {"text": "社員から集めたアイディアで、店の売り上げが伸びました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "社員[しゃいん]から集[あつ]めたアイディアで、店[みせ]の売[う]り上[あ]げが伸[の]びました。", "sentence_source": "generated"}, {"text": "このアイディアは、まだ誰も試していません。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "このアイディアは、まだ誰[だれ]も試[ため]していません。", "sentence_source": "generated"}, {"text": "子どもたちの自由なアイディアが、新しい遊びを生みました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "子[こ]どもたちの自由[じゆう]なアイディアが、新[あたら]しい遊[あそ]びを生[う]みました。", "sentence_source": "generated"}, {"text": "彼は、ごみを減らすためのアイディアを考え出しました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "彼[かれ]は、ごみを減[へ]らすためのアイディアを考[かんが]え出[だ]しました。", "sentence_source": "generated"}, {"text": "アイディアを守るために、特許を申し込みました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "アイディアを守[まも]るために、特許[とっきょ]を申[もう]し込[こ]みました。", "sentence_source": "generated"}, {"text": "いいアイディアでも、実際に作ってみないと、うまくいくかわかりません。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "いいアイディアでも、実際[じっさい]に作[つく]ってみないと、うまくいくかわかりません。", "sentence_source": "generated"}, {"text": "古い考えにとらわれず、新しいアイディアを歓迎する会社です。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "古[ふる]い考[かんが]えにとらわれず、新[あたら]しいアイディアを歓迎[かんげい]する会社[かいしゃ]です。", "sentence_source": "generated"}, {"text": "二人のアイディアを組み合わせて、使いやすい道具ができました。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "二人[ふたり]のアイディアを組[く]み合[あ]わせて、使[つか]いやすい道具[どうぐ]ができました。", "sentence_source": "generated"}, {"text": "アイディアの数が多いほど、いい案を選びやすくなります。", "target_word": "アイディア", "complexity_tier": "T3", "furigana": "アイディアの数[かず]が多[おお]いほど、いい案[あん]を選[えら]びやすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アイディア", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "新しく考え出した案や工夫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39781, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アイディア", "is_correct": true, "explanation": "「新商品のアイディア」は新しく考え出した案を指し、会議で発表する内容として合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様で、新商品として発表する内容にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は体の感覚で、新商品として会議で発表するものではない。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息」は眠っている人の呼吸音で、新商品の発表内容にはならない。"}], "explanations": {"アイディア": "「新商品のアイディア」は新しく考え出した案を指し、会議で発表する内容として合う。", "天気": "「天気」は空模様で、新商品として発表する内容にはならない。", "眠気": "「眠気」は体の感覚で、新商品として会議で発表するものではない。", "寝息": "「寝息」は眠っている人の呼吸音で、新商品の発表内容にはならない。"}, "sentence_index": 0, "correct_answer": "アイディア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壊れたアイディアを三つ取り替えました。", "explanation": "ここは〈部品〉の意味。アイディアは機械の部品のように取り替えるものではない。"}, {"text": "沸騰したアイディアで麺をゆでました。", "explanation": "ここは〈お湯〉の意味。アイディアは熱くないので、麺をゆでる材料にはならない。"}, {"text": "アイディアをつけるために運動しました。", "explanation": "ここは〈体力〉の意味。アイディアは身につけて増やすものではなく、「つける」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39781, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アイディア", "is_correct": true, "explanation": "「いいアイディア」は良い思いつきを指し、「実際に作ってみないと」と続いて自然に合う。"}, {"text": "体重", "is_correct": false, "explanation": "「いい体重」は意味をなさず、うまくいくかどうかの話にはつながらない。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹」は体の状態で、作ってみてうまくいくかの話とは関係しない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足」は体調を表し、「いい寝不足」とは言わないので合わない。"}], "explanations": {"アイディア": "「いいアイディア」は良い思いつきを指し、「実際に作ってみないと」と続いて自然に合う。", "体重": "「いい体重」は意味をなさず、うまくいくかどうかの話にはつながらない。", "空腹": "「空腹」は体の状態で、作ってみてうまくいくかの話とは関係しない。", "寝不足": "「寝不足」は体調を表し、「いい寝不足」とは言わないので合わない。"}, "sentence_index": 6, "correct_answer": "アイディア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日のアイディアは、晴れでしょう。", "explanation": "ここは〈天気〉の意味。アイディアは空模様ではないので、「晴れでしょう」とは言えない。"}, {"text": "アイディアが百七十センチあります。", "explanation": "ここは〈身長〉の意味。アイディアには長さがないので、センチで表せない。"}, {"text": "このアイディアは、たたんでタンスにしまいました。", "explanation": "ここは〈衣類〉の意味。アイディアは布ではないので、たたんでしまうものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39781, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社員のアイディアを、店の売り上げが伸びました。", "corrected_sentence": "社員のアイディアで、店の売り上げが伸びました。", "error_description": "「伸びる」は自動詞で目的語を取らないので、「を」は誤り。原因・手段を示す「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39781, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、新しいアイディアを考え出なかったので、チームは困りました。", "corrected_sentence": "彼女は、新しいアイディアを考え出さなかったので、チームは困りました。", "error_description": "動詞の活用の誤り。「考え出す」の否定形は「考え出さない」で、未然形「考え出さ」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39782, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲しい", "is_correct": true, "explanation": "〈嬉しい〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。"}, {"text": "硬い", "is_correct": false, "explanation": "物の固さを表す形容詞で、感情の対義語ではない。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す形容詞で、感情の対義語ではない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す形容詞で、感情の対義語ではない。"}], "correct_answer": "悲しい", "explanations": {"悲しい": "〈嬉しい〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。", "硬い": "物の固さを表す形容詞で、感情の対義語ではない。", "眠い": "眠気を表す形容詞で、感情の対義語ではない。", "遅い": "速さを表す形容詞で、感情の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39782, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲しい", "is_correct": true, "explanation": "〈嬉しい〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。"}, {"text": "狭い", "is_correct": false, "explanation": "広さを表す形容詞で、感情の対義語ではない。"}, {"text": "濃い", "is_correct": false, "explanation": "色や味の濃さを表す形容詞で、感情の対義語ではない。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す形容詞で、感情の対義語ではない。"}], "correct_answer": "悲しい", "explanations": {"悲しい": "〈嬉しい〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。", "狭い": "広さを表す形容詞で、感情の対義語ではない。", "濃い": "色や味の濃さを表す形容詞で、感情の対義語ではない。", "細い": "太さを表す形容詞で、感情の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39782, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "うれしいは、心がとても気持ちいいことです。", "primary_collocate": null, "pronunciation": "うれしい", "ipa": "ɯɾeɕiː", "syllable_count": 4, "sentences": [{"text": "友達が誕生日に手紙をくれて、とても嬉しいです。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "友達[ともだち]が誕生日[たんじょうび]に手紙[てがみ]をくれて、とても嬉[うれ]しいです。", "sentence_source": "generated"}, {"text": "久しぶりに母の声が聞けて、嬉しかったです。", "target_word": "嬉しかった", "complexity_tier": "T3", "furigana": "久[ひさ]しぶりに母[はは]の声[こえ]が聞[き]けて、嬉[うれ]しかったです。", "sentence_source": "generated"}, {"text": "雨がやんで空が晴れたので、嬉しい気持ちで散歩に出ました。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "雨[あめ]がやんで空[そら]が晴[は]れたので、嬉[うれ]しい気持[きも]ちで散歩[さんぽ]に出[で]ました。", "sentence_source": "generated"}, {"text": "近所の人が毎朝あいさつしてくれるのは、嬉しいことです。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "近所[きんじょ]の人[ひと]が毎朝[まいあさ]あいさつしてくれるのは、嬉[うれ]しいことです。", "sentence_source": "generated"}, {"text": "「また会いたい」と言われて、嬉しくて笑ってしまいました。", "target_word": "嬉しくて", "complexity_tier": "T3", "furigana": "「また会[あ]いたい」と言[い]われて、嬉[うれ]しくて笑[わら]ってしまいました。", "sentence_source": "generated"}, {"text": "好きな先生にほめられて、嬉しい一日になりました。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "好[す]きな先生[せんせい]にほめられて、嬉[うれ]しい一日[いちにち]になりました。", "sentence_source": "generated"}, {"text": "宿題を手伝ってもらえるなら、嬉しいです。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を手伝[てつだ]ってもらえるなら、嬉[うれ]しいです。", "sentence_source": "generated"}, {"text": "一人で行くのは寂しいので、あなたが来てくれると嬉しいです。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "一人[ひとり]で行[い]くのは寂[さび]しいので、あなたが来[き]てくれると嬉[うれ]しいです。", "sentence_source": "generated"}, {"text": "試合には負けましたが、みんなが応援してくれたので嬉しかったです。", "target_word": "嬉しかった", "complexity_tier": "T3", "furigana": "試合[しあい]には負[ま]けましたが、みんなが応援[おうえん]してくれたので嬉[うれ]しかったです。", "sentence_source": "generated"}, {"text": "寒い日に温かいスープが出てきて、嬉しくなりました。", "target_word": "嬉しく", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]に温[あたた]かいスープが出[で]てきて、嬉[うれ]しくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嬉しい", "label": "終止形・連体形"}, {"form": "嬉しく", "label": "連用形"}, {"form": "嬉しかった", "label": "過去形"}, {"form": "嬉しくない", "label": "否定形"}, {"form": "嬉しければ", "label": "仮定形"}], "register": "丁寧", "sense_fingerprint": "人の親切や出来事によって、心が明るく気持ちよくなる感情を表す形容詞。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39782, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嬉しい", "is_correct": true, "explanation": "「友達が誕生日に手紙をくれて、とても___です」に入る形容詞。手紙をもらった喜びを表す。"}, {"text": "悲しい", "is_correct": false, "explanation": "手紙をもらった場面では悲しむ理由がなく、文脈と合わない。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す形容詞で、手紙をもらった気持ちとは合わない。"}, {"text": "忙しい", "is_correct": false, "explanation": "忙しさを表す形容詞で、喜びの感情を述べる文脈に合わない。"}], "explanations": {"嬉しい": "「友達が誕生日に手紙をくれて、とても___です」に入る形容詞。手紙をもらった喜びを表す。", "悲しい": "手紙をもらった場面では悲しむ理由がなく、文脈と合わない。", "眠い": "眠気を表す形容詞で、手紙をもらった気持ちとは合わない。", "忙しい": "忙しさを表す形容詞で、喜びの感情を述べる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "嬉しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大切にしていたペットが死んでしまい、嬉しかった。", "explanation": "大切なペットを失った場面は悲しい出来事で、喜びを表す〈嬉しい〉は合わない。"}, {"text": "机の角に足をぶつけて、嬉しかった。", "explanation": "足をぶつけた場面は痛みの出来事で、喜びを表す〈嬉しい〉は合わない。"}, {"text": "大事な書類をなくしてしまい、嬉しくてたまらない。", "explanation": "書類をなくした場面は残念な出来事で、喜びを表す〈嬉しい〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39782, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嬉しい", "is_correct": true, "explanation": "「宿題を手伝ってもらえるなら、___です」に入る形容詞。手伝ってもらう喜びを表す。"}, {"text": "痛い", "is_correct": false, "explanation": "体の痛みを表すので、宿題を手伝ってもらう場面の気持ちとは合わない。"}, {"text": "高い", "is_correct": false, "explanation": "値段や位置の高さを表すので、この文脈では意味が通らない。"}, {"text": "暑い", "is_correct": false, "explanation": "気温を表すので、宿題の手伝いへの気持ちとは合わない。"}], "explanations": {"嬉しい": "「宿題を手伝ってもらえるなら、___です」に入る形容詞。手伝ってもらう喜びを表す。", "痛い": "体の痛みを表すので、宿題を手伝ってもらう場面の気持ちとは合わない。", "高い": "値段や位置の高さを表すので、この文脈では意味が通らない。", "暑い": "気温を表すので、宿題の手伝いへの気持ちとは合わない。"}, "sentence_index": 6, "correct_answer": "嬉しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人前で大きく転んでしまい、嬉しくて顔を隠した。", "explanation": "転んで顔を隠す場面は恥ずかしい出来事で、喜びを表す〈嬉しい〉は合わない。"}, {"text": "風邪をひいて一日中寝込むことになり、嬉しい。", "explanation": "風邪で寝込む場面はつらい出来事で、喜びを表す〈嬉しい〉は合わない。"}, {"text": "彼の丁寧な仕事ぶりに、嬉しくてうんざりした。", "explanation": "うんざりする気持ちは喜びの〈嬉しい〉と両立せず、文が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39782, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "久しぶりの休みで、家族と出かけられて嬉しいかったです。", "corrected_sentence": "久しぶりの休みで、家族と出かけられて嬉しかったです。", "error_description": "形容詞「嬉しい」の過去形は「嬉しかった」。「嬉しいかった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "嬉しかった", "is_correct": true, "explanation": "過去形。「聞けて、〜です」の過去の出来事を表す正しい形。"}, {"text": "嬉しくない", "is_correct": false, "explanation": "否定形。声が聞けたことへの喜びが反対の意味になり、文の流れに合わない。"}, {"text": "嬉しければ", "is_correct": false, "explanation": "仮定形。「〜ば」の条件を作るので、過去の出来事を述べる文には合わない。"}, {"text": "嬉しく", "is_correct": false, "explanation": "連用形。「嬉しく」で文を終えられず、「です」と続けると不自然になる。"}], "correct_form": "嬉しかった", "base_form": "嬉しい", "form_label": "過去形", "sentence_index": 1, "explanations": {"嬉しかった": "過去形。「聞けて、〜です」の過去の出来事を表す正しい形。", "嬉しくない": "否定形。声が聞けたことへの喜びが反対の意味になり、文の流れに合わない。", "嬉しければ": "仮定形。「〜ば」の条件を作るので、過去の出来事を述べる文には合わない。", "嬉しく": "連用形。「嬉しく」で文を終えられず、「です」と続けると不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39782, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ずっと楽しみにしていた夏祭りに行けて、嬉しいの気持ちでいっぱいです。", "corrected_sentence": "ずっと楽しみにしていた夏祭りに行けて、嬉しい気持ちでいっぱいです。", "error_description": "形容詞「嬉しい」の後に「の」を付けるのは誤り。名詞「気持ち」を修飾するときは「嬉しい気持ち」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "嬉しい", "is_correct": true, "explanation": "終止形・連体形。「来てくれると、___です」の形として正しい。"}, {"text": "嬉しくて", "is_correct": false, "explanation": "連用形の「て」接続。「嬉しくて」で文を終えられず、「です」に続かない。"}, {"text": "嬉しかったら", "is_correct": false, "explanation": "過去の仮定形。「嬉しかったら」で文を終えられず、「です」に続かない。"}, {"text": "嬉しくなかった", "is_correct": false, "explanation": "否定の過去形。喜ぶ気持ちが反対の意味になり、文の意味に合わない。"}], "correct_form": "嬉しい", "base_form": "嬉しい", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"嬉しい": "終止形・連体形。「来てくれると、___です」の形として正しい。", "嬉しくて": "連用形の「て」接続。「嬉しくて」で文を終えられず、「です」に続かない。", "嬉しかったら": "過去の仮定形。「嬉しかったら」で文を終えられず、「です」に続かない。", "嬉しくなかった": "否定の過去形。喜ぶ気持ちが反対の意味になり、文の意味に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39783, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲しい", "is_correct": true, "explanation": "〈嬉しい〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。"}, {"text": "硬い", "is_correct": false, "explanation": "物の固さを表す形容詞で、感情の対義語ではない。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す形容詞で、感情の対義語ではない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す形容詞で、感情の対義語ではない。"}], "correct_answer": "悲しい", "explanations": {"悲しい": "〈嬉しい〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。", "硬い": "物の固さを表す形容詞で、感情の対義語ではない。", "眠い": "眠気を表す形容詞で、感情の対義語ではない。", "遅い": "速さを表す形容詞で、感情の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39783, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲しい", "is_correct": true, "explanation": "〈嬉しく〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。"}, {"text": "狭い", "is_correct": false, "explanation": "広さを表す形容詞で、感情の対義語ではない。"}, {"text": "濃い", "is_correct": false, "explanation": "色や味の濃さを表す形容詞で、感情の対義語ではない。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す形容詞で、感情の対義語ではない。"}], "correct_answer": "悲しい", "explanations": {"悲しい": "〈嬉しく〉の対義語。喜びと悲しみで、心が反対の方向に向く感情。", "狭い": "広さを表す形容詞で、感情の対義語ではない。", "濃い": "色や味の濃さを表す形容詞で、感情の対義語ではない。", "細い": "太さを表す形容詞で、感情の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39783, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "自分の願いがかなったり、よいことがあったりしたときに感じる、楽しくて満足な気持ち。", "primary_collocate": null, "pronunciation": "うれしい", "ipa": "ɯɾeɕiː", "syllable_count": 4, "sentences": [{"text": "ずっと欲しかった自転車を買ってもらって、嬉しいです。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "ずっと欲[ほ]しかった自転車[じてんしゃ]を買[か]ってもらって、嬉[うれ]しいです。", "sentence_source": "generated"}, {"text": "試験に合格したと知って、嬉しくて涙が出ました。", "target_word": "嬉しくて", "complexity_tier": "T3", "furigana": "試験[しけん]に合格[ごうかく]したと知[し]って、嬉[うれ]しくて涙[なみだ]が出[で]ました。", "sentence_source": "generated"}, {"text": "長い間の夢がかなって、本当に嬉しかったです。", "target_word": "嬉しかった", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]の夢[ゆめ]がかなって、本当[ほんとう]に嬉[うれ]しかったです。", "sentence_source": "generated"}, {"text": "好きな人から返事が来て、嬉しい気持ちでいっぱいです。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "好[す]きな人[ひと]から返事[へんじ]が来[き]て、嬉[うれ]しい気持[きも]ちでいっぱいです。", "sentence_source": "generated"}, {"text": "新しい仕事が決まったので、嬉しいニュースを家族に伝えました。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]が決[き]まったので、嬉[うれ]しいニュースを家族[かぞく]に伝[つた]えました。", "sentence_source": "generated"}, {"text": "初めて作ったケーキをほめられて、嬉しかったです。", "target_word": "嬉しかった", "complexity_tier": "T3", "furigana": "初[はじ]めて作[つく]ったケーキをほめられて、嬉[うれ]しかったです。", "sentence_source": "generated"}, {"text": "優勝のニュースを聞いたとき、嬉しくて飛び上がりました。", "target_word": "嬉しくて", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]のニュースを聞[き]いたとき、嬉[うれ]しくて飛[と]び上[あ]がりました。", "sentence_source": "generated"}, {"text": "くじで小さい賞が当たって、嬉しい一日でした。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "くじで小[ちい]さい賞[しょう]が当[あ]たって、嬉[うれ]しい一日[いちにち]でした。", "sentence_source": "generated"}, {"text": "長い病気が治ったので、また学校へ行けるのが嬉しいです。", "target_word": "嬉しい", "complexity_tier": "T3", "furigana": "長[なが]い病気[びょうき]が治[なお]ったので、また学校[がっこう]へ行[い]けるのが嬉[うれ]しいです。", "sentence_source": "generated"}, {"text": "一生懸命練習した曲が上手に弾けて、嬉しくなりました。", "target_word": "嬉しく", "complexity_tier": "T3", "furigana": "一生懸命[いっしょうけんめい]練習[れんしゅう]した曲[きょく]が上手[じょうず]に弾[ひ]けて、嬉[うれ]しくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嬉しい", "label": "終止形・連体形"}, {"form": "嬉しく", "label": "連用形"}, {"form": "嬉しかった", "label": "過去形"}, {"form": "嬉しくない", "label": "否定形"}, {"form": "嬉しければ", "label": "仮定形"}], "register": "丁寧", "sense_fingerprint": "願いがかなったり、よい知らせや成功があったりして感じる、楽しく満ち足りた気持ち。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 飛び上がり (Zipf 2.15)']::text[], 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39783, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嬉しい", "is_correct": true, "explanation": "「ずっと欲しかった自転車を買ってもらって、___です」に入る形容詞。願いがかなった喜びを表す。"}, {"text": "寂しい", "is_correct": false, "explanation": "自転車を買ってもらう喜びの場面では、寂しさを感じる理由がなく合わない。"}, {"text": "怖い", "is_correct": false, "explanation": "恐怖を表すので、欲しかったものを手に入れた文脈とは合わない。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表すので、自転車を買ってもらった気持ちとは合わない。"}], "explanations": {"嬉しい": "「ずっと欲しかった自転車を買ってもらって、___です」に入る形容詞。願いがかなった喜びを表す。", "寂しい": "自転車を買ってもらう喜びの場面では、寂しさを感じる理由がなく合わない。", "怖い": "恐怖を表すので、欲しかったものを手に入れた文脈とは合わない。", "眠い": "眠気を表すので、自転車を買ってもらった気持ちとは合わない。"}, "sentence_index": 0, "correct_answer": "嬉しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この古いパソコンは動きが遅くて、嬉しい。", "explanation": "動きが遅くて困る場面は残念な出来事で、喜びを表す〈嬉しい〉は合わない。"}, {"text": "夏休みの宿題が終わらず、嬉しくてたまらない。", "explanation": "宿題が終わらず慌てる場面は、喜びを表す〈嬉しい〉とは合わない。"}, {"text": "遊園地で子どもが迷子になり、嬉しかった。", "explanation": "子どもが迷子になった場面は心配な出来事で、喜びを表す〈嬉しい〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39783, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嬉しくて", "is_correct": true, "explanation": "「優勝のニュースを聞いたとき、___飛び上がりました」に入る連用形。喜びのあまり飛び上がったことを表す。"}, {"text": "痛くて", "is_correct": false, "explanation": "体の痛みを表すので、飛び上がるほどの喜びの理由として合わない。"}, {"text": "寒くて", "is_correct": false, "explanation": "寒さを表すので、優勝の知らせで飛び上がる理由として不自然。"}, {"text": "暑くて", "is_correct": false, "explanation": "気温を表すので、優勝のニュースを聞いた感情とは合わない。"}], "explanations": {"嬉しくて": "「優勝のニュースを聞いたとき、___飛び上がりました」に入る連用形。喜びのあまり飛び上がったことを表す。", "痛くて": "体の痛みを表すので、飛び上がるほどの喜びの理由として合わない。", "寒くて": "寒さを表すので、優勝の知らせで飛び上がる理由として不自然。", "暑くて": "気温を表すので、優勝のニュースを聞いた感情とは合わない。"}, "sentence_index": 6, "correct_answer": "嬉しくて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この地図は道が分かりにくくて、嬉しい。", "explanation": "道が分かりにくい地図は不都合な出来事で、喜びを表す〈嬉しい〉は合わない。"}, {"text": "寝坊して朝ごはんを抜き、嬉しくなった。", "explanation": "寝坊して朝食を抜く場面はがっかりする出来事で、喜びを表す〈嬉しい〉は合わない。"}, {"text": "大事な発表で言葉を忘れてしまい、嬉しくて固まった。", "explanation": "発表で言葉を忘れた場面は緊張する出来事で、〈嬉しくて〉の喜びとは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39783, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ずっと待っていた合格通知が届いて、嬉しいでした。", "corrected_sentence": "ずっと待っていた合格通知が届いて、嬉しかったです。", "error_description": "形容詞「嬉しい」の過去形は「嬉しかった」。「嬉しいでした」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "嬉しくて", "is_correct": true, "explanation": "連用形（て形）。「知って、〜涙が出ました」と続く正しい形。"}, {"text": "嬉しければ", "is_correct": false, "explanation": "仮定形。「〜ば」の条件を作るので、「知って、涙が出た」の流れに合わない。"}, {"text": "嬉しかろう", "is_correct": false, "explanation": "推量の形。「嬉しかろう涙」と名詞に続けると文が成り立たない。"}, {"text": "嬉しくない", "is_correct": false, "explanation": "否定形。喜んで涙が出た文脈と反対の意味になる。"}], "correct_form": "嬉しくて", "base_form": "嬉しい", "form_label": "連用形（て形）", "sentence_index": 1, "explanations": {"嬉しくて": "連用形（て形）。「知って、〜涙が出ました」と続く正しい形。", "嬉しければ": "仮定形。「〜ば」の条件を作るので、「知って、涙が出た」の流れに合わない。", "嬉しかろう": "推量の形。「嬉しかろう涙」と名詞に続けると文が成り立たない。", "嬉しくない": "否定形。喜んで涙が出た文脈と反対の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39783, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地道に続けた努力が実って、とても嬉しくでした。", "corrected_sentence": "地道に続けた努力が実って、とても嬉しかったです。", "error_description": "形容詞「嬉しい」の過去形は「嬉しかった」。「嬉しくでした」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "嬉しい", "is_correct": true, "explanation": "終止形・連体形。「くじで小さい賞が当たって、___一日でした」の名詞「一日」を修飾する正しい形。"}, {"text": "嬉しく", "is_correct": false, "explanation": "連用形。名詞「一日」を直接修飾できず、「嬉しく一日」は不自然。"}, {"text": "嬉しくなかった", "is_correct": false, "explanation": "否定の過去形。当たった喜びと反対の意味になり、文の意味に合わない。"}, {"text": "嬉しかったら", "is_correct": false, "explanation": "過去の仮定形。名詞「一日」を修飾する形として合わない。"}], "correct_form": "嬉しい", "base_form": "嬉しい", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"嬉しい": "終止形・連体形。「くじで小さい賞が当たって、___一日でした」の名詞「一日」を修飾する正しい形。", "嬉しく": "連用形。名詞「一日」を直接修飾できず、「嬉しく一日」は不自然。", "嬉しくなかった": "否定の過去形。当たった喜びと反対の意味になり、文の意味に合わない。", "嬉しかったら": "過去の仮定形。名詞「一日」を修飾する形として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
