INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39784, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「是非」は、「ぜひ」と読むとき、強くそうしたいと思う気持ちを表す言葉です。", "primary_collocate": null, "pronunciation": "ぜひ", "ipa": "dzeçi", "syllable_count": 2, "sentences": [{"text": "来年の夏は、是非北海道に行ってみたいです。", "target_word": "是非", "complexity_tier": "T3", "furigana": "来年[らいねん]の夏[なつ]は、是非[ぜひ]北海道[ほっかいどう]に行[い]ってみたいです。", "sentence_source": "generated"}, {"text": "この映画は評判がいいので、是非見たいと思っています。", "target_word": "是非", "complexity_tier": "T3", "furigana": "この映画[えいが]は評判[ひょうばん]がいいので、是非[ぜひ]見[み]たいと思[おも]っています。", "sentence_source": "generated"}, {"text": "一度でいいから、是非あの先生に会ってみたい。", "target_word": "是非", "complexity_tier": "T3", "furigana": "一度[いちど]でいいから、是非[ぜひ]あの先生[せんせい]に会[あ]ってみたい。", "sentence_source": "generated"}, {"text": "日本語がもっと上手になって、是非日本で働きたいです。", "target_word": "是非", "complexity_tier": "T3", "furigana": "日本語[にほんご]がもっと上手[じょうず]になって、是非[ぜひ]日本[にほん]で働[はたら]きたいです。", "sentence_source": "generated"}, {"text": "海のきれいな島があると聞いて、是非行ってみたくなった。", "target_word": "是非", "complexity_tier": "T3", "furigana": "海[うみ]のきれいな島[しま]があると聞[き]いて、是非[ぜひ]行[い]ってみたくなった。", "sentence_source": "generated"}, {"text": "私は是非この大学で勉強したいと考えています。", "target_word": "是非", "complexity_tier": "T3", "furigana": "私[わたし]は是非[ぜひ]この大学[だいがく]で勉強[べんきょう]したいと考[かんが]えています。", "sentence_source": "generated"}, {"text": "母の作った料理を、是非もう一度食べたい。", "target_word": "是非", "complexity_tier": "T3", "furigana": "母[はは]の作[つく]った料理[りょうり]を、是非[ぜひ]もう一度[いちど]食[た]べたい。", "sentence_source": "generated"}, {"text": "友だちが勧めてくれた本を、是非読んでみたいです。", "target_word": "是非", "complexity_tier": "T3", "furigana": "友[とも]だちが勧[すす]めてくれた本[ほん]を、是非[ぜひ]読[よ]んでみたいです。", "sentence_source": "generated"}, {"text": "発表会に出られるなら、是非歌いたいと思います。", "target_word": "是非", "complexity_tier": "T3", "furigana": "発表会[はっぴょうかい]に出[で]られるなら、是非[ぜひ]歌[うた]いたいと思[おも]います。", "sentence_source": "generated"}, {"text": "いつか是非、自分の店を持ちたいと思っています。", "target_word": "是非", "complexity_tier": "T3", "furigana": "いつか是非[ぜひ]、自分[じぶん]の店[みせ]を持[も]ちたいと思[おも]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "是非", "label": "base"}, {"form": "ぜひ", "label": "kana"}], "register": "neutral", "sense_fingerprint": "ぜひ: adverb expressing the speaker''s strong wish to do something (ぜひ〜たい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39784, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "「ぜひ〜たい」の形で、強い願望を表す副詞。「来年の夏は、___北海道に行ってみたい」に入る。"}, {"text": "全然", "is_correct": false, "explanation": "打ち消しの語と一緒に使う副詞なので、肯定の願望文には合わない。"}, {"text": "にっこり", "is_correct": false, "explanation": "笑う様子を表す擬態語で、願望を表す副詞ではない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す副詞で、旅行の願望を述べる文とは合わない。"}], "explanations": {"是非": "「ぜひ〜たい」の形で、強い願望を表す副詞。「来年の夏は、___北海道に行ってみたい」に入る。", "全然": "打ち消しの語と一緒に使う副詞なので、肯定の願望文には合わない。", "にっこり": "笑う様子を表す擬態語で、願望を表す副詞ではない。", "ぐっすり": "眠りの深さを表す副詞で、旅行の願望を述べる文とは合わない。"}, "sentence_index": 0, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の帰り道で是非友だちに会った。", "explanation": "是非は「ぜひ〜たい」の強い願望を表すので、すでに終わった偶然の出来事を述べる文には使えない。"}, {"text": "昨日の夜は是非雨が降っていた。", "explanation": "是非は自分の強い願望を表すので、すでに起きた天気の出来事を述べる文には使えない。"}, {"text": "うっかりお皿を割ったことを、是非後悔している。", "explanation": "是非は強く望む気持ちを表すので、後悔という感情を強める文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39784, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "「母の作った料理を、___もう一度食べたい」に入る副詞。強い願望を表す。"}, {"text": "少しも", "is_correct": false, "explanation": "打ち消しの語と一緒に使う副詞なので、肯定の願望文には合わない。"}, {"text": "ぐったり", "is_correct": false, "explanation": "疲れて力が抜けた様子を表す語で、ここでは意味が合わない。"}, {"text": "ぴったり", "is_correct": false, "explanation": "ぴたりと合う様子を表す語で、食べたい気持ちを表す副詞としては合わない。"}], "explanations": {"是非": "「母の作った料理を、___もう一度食べたい」に入る副詞。強い願望を表す。", "少しも": "打ち消しの語と一緒に使う副詞なので、肯定の願望文には合わない。", "ぐったり": "疲れて力が抜けた様子を表す語で、ここでは意味が合わない。", "ぴったり": "ぴたりと合う様子を表す語で、食べたい気持ちを表す副詞としては合わない。"}, "sentence_index": 6, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は昨日の会議に是非、出なかった。", "explanation": "是非は強い願望を表すので、出られなかった過去の事情を述べる文には使えない。"}, {"text": "この問題は是非簡単だと思う。", "explanation": "是非は強い願望を表すので、判断や推測を述べる文には使えない。"}, {"text": "彼は是非、約束を守らないつもりだ。", "explanation": "是非は望むことを表す副詞なので、望まない行為を述べる文とは噛み合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39784, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "次の休みには是非で映画を見に行きたい。", "corrected_sentence": "次の休みには是非映画を見に行きたい。", "error_description": "「是非」は副詞なので、助詞「で」は付けない。「是非映画を見に行きたい」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39784, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年は是非に行きたいと思っています。", "corrected_sentence": "来年は是非行きたいと思っています。", "error_description": "「是非」は副詞なので、助詞「に」は付けない。動詞の前に直接置くのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
