INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39785, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「是非」は副詞として、相手に強く勧めたり、ぜひそうしてほしいと頼んだりする気持ちを表し、「必ず」「どうしても」という意味で使われます。", "primary_collocate": null, "pronunciation": "ぜひ", "ipa": "dzeçi", "syllable_count": 2, "sentences": [{"text": "京都に来たら、是非うちに寄ってください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "京都[きょうと]に来[き]たら、是非[ぜひ]うちに寄[よ]ってください。", "sentence_source": "generated"}, {"text": "おいしいお店なので、是非食べてみてください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "おいしいお店[みせ]なので、是非[ぜひ]食[た]べてみてください。", "sentence_source": "generated"}, {"text": "来週のパーティーには、是非来てください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "来週[らいしゅう]のパーティーには、是非[ぜひ]来[き]てください。", "sentence_source": "generated"}, {"text": "この小説は面白いので、是非読んでみてください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は面白[おもしろ]いので、是非[ぜひ]読[よ]んでみてください。", "sentence_source": "generated"}, {"text": "展覧会は無料ですので、是非お越しください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]は無料[むりょう]ですので、是非[ぜひ]お越[こ]しください。", "sentence_source": "generated"}, {"text": "お時間があれば、是非ご参加ください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "お時間[じかん]があれば、是非[ぜひ]ご参加[さんか]ください。", "sentence_source": "generated"}, {"text": "この薬はよく効くので、是非試してみてください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "この薬[くすり]はよく効[き]くので、是非[ぜひ]試[ため]してみてください。", "sentence_source": "generated"}, {"text": "日本に来る機会があれば、是非連絡してください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "日本[にほん]に来[く]る機会[きかい]があれば、是非[ぜひ]連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "あの映画は是非見るべきだと友だちに言われた。", "target_word": "是非", "complexity_tier": "T3", "furigana": "あの映画[えいが]は是非[ぜひ]見[み]るべきだと友[とも]だちに言[い]われた。", "sentence_source": "generated"}, {"text": "この機会に、是非あなたの意見を聞かせてください。", "target_word": "是非", "complexity_tier": "T3", "furigana": "この機会[きかい]に、是非[ぜひ]あなたの意見[いけん]を聞[き]かせてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "是非", "label": "base"}, {"form": "ぜひ", "label": "kana"}], "register": "neutral", "sense_fingerprint": "ぜひ: adverb urging or recommending, ''by all means / without fail'' (ぜひ〜てください)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39785, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "「京都に来たら、___うちに寄ってください」に入る副詞。相手に強く勧める気持ちを表す。"}, {"text": "少しも", "is_correct": false, "explanation": "打ち消しの語と一緒に使う副詞なので、命令の文には合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す副詞で、寄るという行為とは合わない。"}, {"text": "にっこり", "is_correct": false, "explanation": "笑顔の様子を表す語で、勧める命令文の副詞としては合わない。"}], "explanations": {"是非": "「京都に来たら、___うちに寄ってください」に入る副詞。相手に強く勧める気持ちを表す。", "少しも": "打ち消しの語と一緒に使う副詞なので、命令の文には合わない。", "ぐっすり": "眠りの深さを表す副詞で、寄るという行為とは合わない。", "にっこり": "笑顔の様子を表す語で、勧める命令文の副詞としては合わない。"}, "sentence_index": 0, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は是非雨が降るらしい。", "explanation": "是非は相手に勧めたり自分が強く望んだりする言葉なので、天気の予想の文には使えない。"}, {"text": "この小説は是非読まないでください。", "explanation": "是非は相手に強く勧める言葉なので、「読まないでください」という禁止の文とは噛み合わない。"}, {"text": "先週この小説を是非読みました。", "explanation": "是非は勧めや願いを表す言葉なので、すでに終わった行動を述べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39785, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是非", "is_correct": true, "explanation": "「この薬はよく効くので、___試してみてください」に入る副詞。相手に強く勧める気持ちを表す。"}, {"text": "全然", "is_correct": false, "explanation": "打ち消しの語と一緒に使う副詞なので、勧める命令文には合わない。"}, {"text": "ぴったり", "is_correct": false, "explanation": "ぴたりと合う様子を表す語で、試す行為の副詞としては合わない。"}, {"text": "ぐったり", "is_correct": false, "explanation": "疲れて力が抜けた様子を表す語で、ここでは意味が合わない。"}], "explanations": {"是非": "「この薬はよく効くので、___試してみてください」に入る副詞。相手に強く勧める気持ちを表す。", "全然": "打ち消しの語と一緒に使う副詞なので、勧める命令文には合わない。", "ぴったり": "ぴたりと合う様子を表す語で、試す行為の副詞としては合わない。", "ぐったり": "疲れて力が抜けた様子を表す語で、ここでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "是非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日は是非、雨が止んでくれた。", "explanation": "是非は勧めや願いを表す言葉なので、天気の出来事を述べる文には使えない。"}, {"text": "彼は是非、約束を守らないつもりだ。", "explanation": "是非は勧めや望みを表す言葉なので、「守らないつもりだ」という行為の文とは噛み合わない。"}, {"text": "この料理は是非、塩辛いと思う。", "explanation": "是非は強い願いや勧めを表すので、料理の感想を述べる文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39785, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ご都合がよければ、是非をご出席ください。", "corrected_sentence": "ご都合がよければ、是非ご出席ください。", "error_description": "「是非」は副詞なので、直後に助詞「を」は付けない。「是非ご出席ください」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39785, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日の会議には是非に、出席してください。", "corrected_sentence": "明日の会議には是非、出席してください。", "error_description": "「是非」は副詞なので、直後に助詞「に」は付けない。「是非、出席してください」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39786, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「お土産を」の「を」は、くれた物（目的語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「お土産に」は帰着や位置を示すため、くれた物を示す文にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、お土産を与える対象の文にならない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語の助詞。すでに「社長が」があるため、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「お土産を」の「を」は、くれた物（目的語）を示す。", "に": "「お土産に」は帰着や位置を示すため、くれた物を示す文にならない。", "で": "「で」は手段や場所を示すため、お土産を与える対象の文にならない。", "が": "「が」は主語の助詞。すでに「社長が」があるため、文が成り立たない。"}, "error_tags": {"に": "帰着", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39786, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「手紙を」の「を」は、くれた物（目的語）を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、くれた物を示す文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、物を与える対象の文にならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、ここでは「手紙から下さった」と言えず成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「手紙を」の「を」は、くれた物（目的語）を示す。", "と": "「と」は並列や相手を示すため、くれた物を示す文にならない。", "へ": "「へ」は方向を示すため、物を与える対象の文にならない。", "から": "「から」は起点を示すが、ここでは「手紙から下さった」と言えず成り立たない。"}, "error_tags": {"と": "並列", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39786, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「くれる」のていねいな言い方で、目上の人が何かをくれるときに使う。", "primary_collocate": null, "pronunciation": "くださる", "ipa": "kɯdasaɾɯ", "syllable_count": 4, "sentences": [{"text": "先生が私に辞書を下さいました。", "target_word": "下さいました", "complexity_tier": "T3", "furigana": "先生[せんせい]が私[わたし]に辞書[じしょ]を下[くだ]さいました。", "sentence_source": "generated"}, {"text": "社長が旅行のお土産を下さった。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "社長[しゃちょう]が旅行[りょこう]のお土産[みやげ]を下[くだ]さった。", "sentence_source": "generated"}, {"text": "祖母は誕生日に、新しい時計を下さいました。", "target_word": "下さいました", "complexity_tier": "T3", "furigana": "祖母[そぼ]は誕生日[たんじょうび]に、新[あたら]しい時計[とけい]を下[くだ]さいました。", "sentence_source": "generated"}, {"text": "部長がきれいな花を下さって、とてもうれしかったです。", "target_word": "下さって", "complexity_tier": "T3", "furigana": "部長[ぶちょう]がきれいな花[はな]を下[くだ]さって、とてもうれしかったです。", "sentence_source": "generated"}, {"text": "先生は毎年、私たちに年賀状を下さる。", "target_word": "下さる", "complexity_tier": "T3", "furigana": "先生[せんせい]は毎年[まいとし]、私[わたし]たちに年賀状[ねんがじょう]を下[くだ]さる。", "sentence_source": "generated"}, {"text": "おじいさんがおいしいりんごを下さったので、家族で食べました。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "おじいさんがおいしいりんごを下[くだ]さったので、家族[かぞく]で食[た]べました。", "sentence_source": "generated"}, {"text": "校長先生が卒業のとき、本を下さいました。", "target_word": "下さいました", "complexity_tier": "T3", "furigana": "校長先生[こうちょうせんせい]が卒業[そつぎょう]のとき、本[ほん]を下[くだ]さいました。", "sentence_source": "generated"}, {"text": "お客様が手紙を下さったので、すぐに返事を書いた。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "お客様[きゃくさま]が手紙[てがみ]を下[くだ]さったので、すぐに返事[へんじ]を書[か]いた。", "sentence_source": "generated"}, {"text": "社長は私にペンを下さいましたが、まだ使っていません。", "target_word": "下さいました", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は私[わたし]にペンを下[くだ]さいましたが、まだ使[つか]っていません。", "sentence_source": "generated"}, {"text": "先生が下さった地図のおかげで、道に迷わなかった。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "先生[せんせい]が下[くだ]さった地図[ちず]のおかげで、道[みち]に迷[まよ]わなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下さる", "label": "dictionary form"}, {"form": "下さいます", "label": "polite form"}, {"form": "下さった", "label": "past form"}, {"form": "下さって", "label": "te-form"}, {"form": "下さらない", "label": "negative form"}], "register": "polite", "sense_fingerprint": "くださる: honorific ''give (to me)'', a superior gives the speaker a thing", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39786, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下さいました", "is_correct": true, "explanation": "目上の先生が私に辞書をくれた事実を表す丁寧な過去形で、空所にそのまま入る。"}, {"text": "下さって", "is_correct": false, "explanation": "て形は文を言い切れないため、「辞書を」の後で文が終わらない。"}, {"text": "差し上げました", "is_correct": false, "explanation": "「差し上げる」は話し手が目上に与えるへりくだり語。主語が先生だと向きが合わない。"}, {"text": "頂きました", "is_correct": false, "explanation": "「頂く」は受け取る側が主語になる語。先生が受け取る側になり、この文の意味と合わない。"}], "explanations": {"下さいました": "目上の先生が私に辞書をくれた事実を表す丁寧な過去形で、空所にそのまま入る。", "下さって": "て形は文を言い切れないため、「辞書を」の後で文が終わらない。", "差し上げました": "「差し上げる」は話し手が目上に与えるへりくだり語。主語が先生だと向きが合わない。", "頂きました": "「頂く」は受け取る側が主語になる語。先生が受け取る側になり、この文の意味と合わない。"}, "sentence_index": 0, "correct_answer": "下さいました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "後輩が感謝の手紙を下さった。", "explanation": "ここは〈くれる〉（目下が与える）の意味。下さるは目上が与える側に使う敬語なので、後輩が主語の文には合わない。"}, {"text": "私は先生に辞書を下さいました。", "explanation": "ここは〈差し上げる〉（私が目上に与える）の意味。下さるは目上の人が与える側の語なので、私が与える主語には合わない。"}, {"text": "友達が私に本を下さった。", "explanation": "ここは〈くれる〉の意味。下さるは目上の人からの贈り物に使う語なので、友達には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39786, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下さいました", "is_correct": true, "explanation": "目上の校長先生が本をくれた過去の出来事で、空所にそのまま入る。"}, {"text": "下さいません", "is_correct": false, "explanation": "否定になるため、卒業の時に本をもらった事実と逆の意味になる。"}, {"text": "下さいましょう", "is_correct": false, "explanation": "勧誘・意向の形で、既に起きた事実を述べる文と合わない。"}, {"text": "下さったら", "is_correct": false, "explanation": "条件の形で、文が言い切れず続きが必要になる。"}], "explanations": {"下さいました": "目上の校長先生が本をくれた過去の出来事で、空所にそのまま入る。", "下さいません": "否定になるため、卒業の時に本をもらった事実と逆の意味になる。", "下さいましょう": "勧誘・意向の形で、既に起きた事実を述べる文と合わない。", "下さったら": "条件の形で、文が言い切れず続きが必要になる。"}, "sentence_index": 6, "correct_answer": "下さいました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "社長が私から時計を下さった。", "explanation": "下さるは与える側が主語になる敬語なので、目上の社長が受け取る文には合わない。"}, {"text": "私は先生から地図を下さった。", "explanation": "下さるは与える側が主語になる語なので、私が受け取る側の文には合わない。"}, {"text": "先生から地図が下さった。", "explanation": "下さるは人が主語になる動詞なので、物を主語にした文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39786, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は毎年、私たちに年賀状を下さります。", "corrected_sentence": "先生は毎年、私たちに年賀状を下さいます。", "error_description": "「下さる」の丁寧形は「下さいます」。「下さります」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下さった", "is_correct": true, "explanation": "過去の「た形」で、くれた事実を表し文にそのまま入る。"}, {"text": "下さって", "is_correct": false, "explanation": "て形は文を言い切れず、過去の事実を述べる文にならない。"}, {"text": "下さらない", "is_correct": false, "explanation": "否定形になるため、くれなかったという逆の意味になる。"}, {"text": "下さいませ", "is_correct": false, "explanation": "丁寧な命令・依頼の形で、過去の出来事を述べる文と合わない。"}], "correct_form": "下さった", "base_form": "下さる", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"下さった": "過去の「た形」で、くれた事実を表し文にそのまま入る。", "下さって": "て形は文を言い切れず、過去の事実を述べる文にならない。", "下さらない": "否定形になるため、くれなかったという逆の意味になる。", "下さいませ": "丁寧な命令・依頼の形で、過去の出来事を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39786, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生が私に本を下さりて、うれしかった。", "corrected_sentence": "先生が私に本を下さって、うれしかった。", "error_description": "「下さる」のて形は「下さって」。「下さりて」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下さった", "is_correct": true, "explanation": "過去の「た形」で、手紙をくれた事実を表し、後の文に続く。"}, {"text": "下さろう", "is_correct": false, "explanation": "意志・推量の形で、既に起きた事実を述べる文と合わない。"}, {"text": "下さらず", "is_correct": false, "explanation": "否定の中止形で、くれなかったことになり、返事を書いた流れと合わない。"}, {"text": "下さらなかった", "is_correct": false, "explanation": "否定の過去形で、くれなかったという逆の意味になる。"}], "correct_form": "下さった", "base_form": "下さる", "form_label": "過去形（た形）", "sentence_index": 7, "explanations": {"下さった": "過去の「た形」で、手紙をくれた事実を表し、後の文に続く。", "下さろう": "意志・推量の形で、既に起きた事実を述べる文と合わない。", "下さらず": "否定の中止形で、くれなかったことになり、返事を書いた流れと合わない。", "下さらなかった": "否定の過去形で、くれなかったという逆の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
