INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39787, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「〜て下さる」の形で、目上の人が話し手のために何かをしてくれることを、敬意を込めて表す。", "primary_collocate": null, "pronunciation": "くださる", "ipa": "kɯdasaɾɯ", "syllable_count": 4, "sentences": [{"text": "先生が分かりやすく説明して下さいました。", "target_word": "下さいました", "complexity_tier": "T3", "furigana": "先生[せんせい]が分[わ]かりやすく説明[せつめい]して下[くだ]さいました。", "sentence_source": "generated"}, {"text": "部長が駅まで車で送って下さった。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "部長[ぶちょう]が駅[えき]まで車[くるま]で送[おく]って下[くだ]さった。", "sentence_source": "generated"}, {"text": "お忙しいところ、来て下さってありがとうございます。", "target_word": "下さって", "complexity_tier": "T3", "furigana": "お忙[いそが]しいところ、来[き]て下[くだ]さってありがとうございます。", "sentence_source": "generated"}, {"text": "店の人が親切に道を教えて下さいました。", "target_word": "下さいました", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]が親切[しんせつ]に道[みち]を教[おし]えて下[くだ]さいました。", "sentence_source": "generated"}, {"text": "社長が私の話を最後まで聞いて下さった。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "社長[しゃちょう]が私[わたし]の話[はなし]を最後[さいご]まで聞[き]いて下[くだ]さった。", "sentence_source": "generated"}, {"text": "先生は毎回、作文を丁寧に直して下さる。", "target_word": "下さる", "complexity_tier": "T3", "furigana": "先生[せんせい]は毎回[まいかい]、作文[さくぶん]を丁寧[ていねい]に直[なお]して下[くだ]さる。", "sentence_source": "generated"}, {"text": "先生が推薦状を書いて下さったので、入学できました。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "先生[せんせい]が推薦状[すいせんじょう]を書[か]いて下[くだ]さったので、入学[にゅうがく]できました。", "sentence_source": "generated"}, {"text": "お客様が荷物を運んで下さって、助かりました。", "target_word": "下さって", "complexity_tier": "T3", "furigana": "お客様[きゃくさま]が荷物[にもつ]を運[はこ]んで下[くだ]さって、助[たす]かりました。", "sentence_source": "generated"}, {"text": "課長が会議の資料を用意して下さったので、準備が楽でした。", "target_word": "下さった", "complexity_tier": "T3", "furigana": "課長[かちょう]が会議[かいぎ]の資料[しりょう]を用意[ようい]して下[くだ]さったので、準備[じゅんび]が楽[らく]でした。", "sentence_source": "generated"}, {"text": "いつも見守って下さる両親に感謝しています。", "target_word": "下さる", "complexity_tier": "T3", "furigana": "いつも見守[みまも]って下[くだ]さる両親[りょうしん]に感謝[かんしゃ]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下さる", "label": "dictionary form"}, {"form": "下さいます", "label": "polite form"}, {"form": "下さった", "label": "past form"}, {"form": "下さって", "label": "te-form"}, {"form": "下さらない", "label": "negative form"}], "register": "polite", "sense_fingerprint": "くださる: honorific ''do for me'', a respected person does a favour for the speaker (〜て下さる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39787, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下さいました", "is_correct": true, "explanation": "目上の先生が説明してくれた（してくださった）事実を表す丁寧な過去形で、そのまま入る。"}, {"text": "下さったら", "is_correct": false, "explanation": "条件の形で、文が言い切れず続きが必要になる。"}, {"text": "差し上げました", "is_correct": false, "explanation": "へりくだる語。主語が先生だと、話し手が目上にしたことになり向きが合わない。"}, {"text": "頂きました", "is_correct": false, "explanation": "受け取る側が主語の語。先生が受け取る立場になり、この文の意味と合わない。"}], "explanations": {"下さいました": "目上の先生が説明してくれた（してくださった）事実を表す丁寧な過去形で、そのまま入る。", "下さったら": "条件の形で、文が言い切れず続きが必要になる。", "差し上げました": "へりくだる語。主語が先生だと、話し手が目上にしたことになり向きが合わない。", "頂きました": "受け取る側が主語の語。先生が受け取る立場になり、この文の意味と合わない。"}, "sentence_index": 0, "correct_answer": "下さいました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私が部長の荷物を運んで下さった。", "explanation": "ここは〈〜てあげる〉（自分がしてやる）の意味。尊敬語は相手の行為に使うので、自分が主語の文には合わない。"}, {"text": "私は先生に手伝って下さった。", "explanation": "ここは〈もらう〉（受け取る）の意味。下さるはしてくれる人が主語なので、私が受ける側の主語には合わない。"}, {"text": "友達が手伝って下さった。", "explanation": "ここは〈くれる〉（親しい人が手伝う）の意味。下さるは目上の人に使う敬語なので、友達には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39787, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下さった", "is_correct": true, "explanation": "過去形で、推薦状を書いてくれた事実を表し、後の「ので」と因果がつながる。"}, {"text": "下さらず", "is_correct": false, "explanation": "否定の中止形で、書かなかったことになり、入学できた理由と合わない。"}, {"text": "下さらないで", "is_correct": false, "explanation": "否定の依頼形で、入学できた理由として成り立たない。"}, {"text": "下さいましょう", "is_correct": false, "explanation": "意向・勧誘の形で、既に書いた事実を述べる文と合わない。"}], "explanations": {"下さった": "過去形で、推薦状を書いてくれた事実を表し、後の「ので」と因果がつながる。", "下さらず": "否定の中止形で、書かなかったことになり、入学できた理由と合わない。", "下さらないで": "否定の依頼形で、入学できた理由として成り立たない。", "下さいましょう": "意向・勧誘の形で、既に書いた事実を述べる文と合わない。"}, "sentence_index": 6, "correct_answer": "下さった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私が後輩に教えて下さった。", "explanation": "ここは〈あげる〉（私が目下にしてやる）の意味。下さるは目上が主語になる語なので、私が行為者の文には合わない。"}, {"text": "弟に宿題を手伝って下さった。", "explanation": "ここは〈やる〉（目下に手を貸す）の意味。下さるは目上への敬語なので、弟には合わない。"}, {"text": "私は先生に本を下さった。", "explanation": "ここは〈差し上げる〉（私が目上に与える）の意味。下さるは目上が与える側の語なので、主語と方向が逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39787, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部長が駅まで送って下さりました。", "corrected_sentence": "部長が駅まで送って下さいました。", "error_description": "「下さる」の丁寧形は「下さいます」。「下さりました」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下さった", "is_correct": true, "explanation": "過去の「た形」で、送ってくれた事実を表し、文にそのまま入る。"}, {"text": "下さらない", "is_correct": false, "explanation": "否定形になるため、してくれなかったという逆の意味になる。"}, {"text": "下さい", "is_correct": false, "explanation": "命令・依頼の形で、過去の出来事を述べる文に合わない。"}, {"text": "下さろう", "is_correct": false, "explanation": "意志・推量の形で、既に送られた事実と合わない。"}], "correct_form": "下さった", "base_form": "下さる", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"下さった": "過去の「た形」で、送ってくれた事実を表し、文にそのまま入る。", "下さらない": "否定形になるため、してくれなかったという逆の意味になる。", "下さい": "命令・依頼の形で、過去の出来事を述べる文に合わない。", "下さろう": "意志・推量の形で、既に送られた事実と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39787, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生が手紙を書いと下さった。", "corrected_sentence": "先生が手紙を書いて下さった。", "error_description": "動詞に続けるのは接続の「て」。「書いと」の「と」は誤りで、「書いて下さった」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下さって", "is_correct": true, "explanation": "て形で、後の「助かりました」へ続く。"}, {"text": "下さる", "is_correct": false, "explanation": "終止形は読点の後で文が切れ、「助かりました」とつながらない。"}, {"text": "下さらず", "is_correct": false, "explanation": "否定の中止形で、運ばなかったことになり、助かった理由と逆になる。"}, {"text": "下さらないで", "is_correct": false, "explanation": "否定の依頼形で、この文脈では成り立たない。"}], "correct_form": "下さって", "base_form": "下さる", "form_label": "て形", "sentence_index": 7, "explanations": {"下さって": "て形で、後の「助かりました」へ続く。", "下さる": "終止形は読点の後で文が切れ、「助かりました」とつながらない。", "下さらず": "否定の中止形で、運ばなかったことになり、助かった理由と逆になる。", "下さらないで": "否定の依頼形で、この文脈では成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
