INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41220, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "かぜが ふく ときの おと。", "primary_collocate": null, "pronunciation": "ぴゅう", "ipa": "pʲɯː", "syllable_count": 2, "sentences": [{"text": "冬の夜、まどの外で風がぴゅうと鳴っている。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "冬(ふゆ)の夜(よる)、まどの外(そと)で風(かぜ)がぴゅうと鳴(な)っている。", "sentence_source": "generated"}, {"text": "山の上では、冷たい風がぴゅうと吹いて、体が冷えた。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)では、冷(つめ)たい風(かぜ)がぴゅうと吹(ふ)いて、体(からだ)が冷(ひ)えた。", "sentence_source": "generated"}, {"text": "ぴゅうという風の音が聞こえて、私は目をさました。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "ぴゅうという風(かぜ)の音(おと)が聞(き)こえて、私(わたし)は目(め)をさました。", "sentence_source": "generated"}, {"text": "強い風がぴゅうと吹いたので、ぼうしが飛んでしまった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "強(つよ)い風(かぜ)がぴゅうと吹(ふ)いたので、ぼうしが飛(と)んでしまった。", "sentence_source": "generated"}, {"text": "戸のすき間から、風がぴゅうと入ってくる。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "戸(と)のすき間(ま)から、風(かぜ)がぴゅうと入(はい)ってくる。", "sentence_source": "generated"}, {"text": "海辺に立つと、ぴゅうと風が耳元を通りすぎた。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "海辺(うみべ)に立(た)つと、ぴゅうと風(かぜ)が耳元(みみもと)を通(とお)りすぎた。", "sentence_source": "generated"}, {"text": "北風がぴゅうと吹くと、木の葉が一度にゆれた。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "北風(きたかぜ)がぴゅうと吹(ふ)くと、木(き)の葉(は)が一度(いちど)にゆれた。", "sentence_source": "generated"}, {"text": "ぴゅうと風が吹いて、洗濯物が空へ舞い上がった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "ぴゅうと風(かぜ)が吹(ふ)いて、洗濯物(せんたくもの)が空(そら)へ舞(ま)い上(あ)がった。", "sentence_source": "generated"}, {"text": "外に出たとたん、ぴゅうと冷たい風が顔に当たった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "外(そと)に出(で)たとたん、ぴゅうと冷(つめ)たい風(かぜ)が顔(かお)に当(あ)たった。", "sentence_source": "generated"}, {"text": "夜道を歩いていると、ぴゅうと風が鳴って少しこわかった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "夜道(よみち)を歩(ある)いていると、ぴゅうと風(かぜ)が鳴(な)って少(すこ)しこわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ぴゅう", "label": "基本形"}], "register": "casual", "sense_fingerprint": "風が吹くときの音を表す擬音語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41220, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ぴゅう", "is_correct": true, "explanation": "風が吹く音を表す「ぴゅう」が入り、「風がぴゅうと鳴っている」と自然に続く。"}, {"text": "ぽーん", "is_correct": false, "explanation": "ぽーんは物がはずむ音なので、風が鳴る様子には合わない。"}, {"text": "ぴょん", "is_correct": false, "explanation": "ぴょんは跳ねる動きの音なので、風の音としては成り立たない。"}, {"text": "ぺたん", "is_correct": false, "explanation": "ぺたんは平たいものが当たる音なので、風が鳴る文脈には合わない。"}], "explanations": {"ぴゅう": "風が吹く音を表す「ぴゅう」が入り、「風がぴゅうと鳴っている」と自然に続く。", "ぽーん": "ぽーんは物がはずむ音なので、風が鳴る様子には合わない。", "ぴょん": "ぴょんは跳ねる動きの音なので、風の音としては成り立たない。", "ぺたん": "ぺたんは平たいものが当たる音なので、風が鳴る文脈には合わない。"}, "sentence_index": 0, "correct_answer": "ぴゅう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんがぴゅうといびきをかいた。", "explanation": "ここは〈ぐうぐう〉の意味。寝ているときのいびきを表す語で、風の音のぴゅうは合わない。"}, {"text": "スイッチがぴゅうと入った。", "explanation": "ここは〈カチッ〉の意味。小さく硬い音を表す語で、風の音のぴゅうは合わない。"}, {"text": "猫がぴゅうと鳴いた。", "explanation": "ここは〈にゃあ〉の意味。猫の鳴き声を表す語で、風の音のぴゅうとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41220, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ぴゅう", "is_correct": true, "explanation": "北風が吹く音を表す「ぴゅう」が入り、「北風がぴゅうと吹く」と自然に続く。"}, {"text": "ぷんぷん", "is_correct": false, "explanation": "ぷんぷんは怒った様子を表すので、風が吹く文脈には合わない。"}, {"text": "ぱらぱら", "is_correct": false, "explanation": "ぱらぱらは軽く降り注ぐ様子を表すので、「北風が吹く」とは合わない。"}, {"text": "ごろごろ", "is_correct": false, "explanation": "ごろごろは転がる様子を表すので、風が吹く音の表現としては合わない。"}], "explanations": {"ぴゅう": "北風が吹く音を表す「ぴゅう」が入り、「北風がぴゅうと吹く」と自然に続く。", "ぷんぷん": "ぷんぷんは怒った様子を表すので、風が吹く文脈には合わない。", "ぱらぱら": "ぱらぱらは軽く降り注ぐ様子を表すので、「北風が吹く」とは合わない。", "ごろごろ": "ごろごろは転がる様子を表すので、風が吹く音の表現としては合わない。"}, "sentence_index": 6, "correct_answer": "ぴゅう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "たき火がぴゅうとはぜた。", "explanation": "ここは〈ぱちぱち〉の意味。火がはぜる音を表すので、風が吹く音のぴゅうは合わない。"}, {"text": "雷がぴゅうと鳴った。", "explanation": "ここは〈ドーン〉の意味。大きく低い音を表す語で、風が吹く音のぴゅうとは違う。"}, {"text": "肩をぴゅうとたたいた。", "explanation": "ここは〈ぽんぽん〉の意味。軽く叩く様子を表すので、風の音のぴゅうは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41220, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の港で、冷たい風がぴゅうに吹きつけた。", "corrected_sentence": "夜の港で、冷たい風がぴゅうと吹きつけた。", "error_description": "「ぴゅう」は副詞なので、「と」を付けて動詞に続ける。「に」は誤りで、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41220, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の窓辺で、風がぴゅうと鳴いた。", "corrected_sentence": "夜の窓辺で、風がぴゅうと鳴った。", "error_description": "「鳴く」は動物や虫の声に使う語で、風には「鳴る」が正しい。「鳴いた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
