INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41221, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "物が速く動いたり、風が強く吹いたりする音を表す語。", "primary_collocate": null, "pronunciation": "ぴゅう", "ipa": "pʲɯː", "syllable_count": 1, "sentences": [{"text": "矢がぴゅうと飛んで、的の真ん中に当たった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "矢(や)がぴゅうと飛(と)んで、的(まと)の真(ま)ん中(なか)に当(あ)たった。", "sentence_source": "generated"}, {"text": "子どもが投げたボールが、ぴゅうと頭の上を通った。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "子(こ)どもが投(な)げたボールが、ぴゅうと頭(あたま)の上(うえ)を通(とお)った。", "sentence_source": "generated"}, {"text": "新幹線がぴゅうと走りぬけて、ホームの風がゆれた。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "新幹線(しんかんせん)がぴゅうと走(はし)りぬけて、ホームの風(かぜ)がゆれた。", "sentence_source": "generated"}, {"text": "犬はぴゅうと走って、ボールを取りに行った。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "犬(いぬ)はぴゅうと走(はし)って、ボールを取(と)りに行(い)った。", "sentence_source": "generated"}, {"text": "屋根の上を、強い風がぴゅうと吹きぬけていった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "屋根(やね)の上(うえ)を、強(つよ)い風(かぜ)がぴゅうと吹(ふ)きぬけていった。", "sentence_source": "generated"}, {"text": "ロケットがぴゅうと空へ上がって、すぐ見えなくなった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "ロケットがぴゅうと空(そら)へ上(あ)がって、すぐ見(み)えなくなった。", "sentence_source": "generated"}, {"text": "自転車の横を、ぴゅうと車が走っていった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "自転車(じてんしゃ)の横(よこ)を、ぴゅうと車(くるま)が走(はし)っていった。", "sentence_source": "generated"}, {"text": "台風の日は、ぴゅうと強い風が吹いて、傘がこわれた。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "台風(たいふう)の日は、ぴゅうと強(つよ)い風(かぜ)が吹(ふ)いて、傘(かさ)がこわれた。", "sentence_source": "generated"}, {"text": "弟はぴゅうと部屋から出て、庭へ走っていった。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "弟(おとうと)はぴゅうと部屋(へや)から出(で)て、庭(にわ)へ走(はし)っていった。", "sentence_source": "generated"}, {"text": "小さな鳥がぴゅうと飛んで、木のかげにかくれた。", "target_word": "ぴゅう", "complexity_tier": "T3", "furigana": "小(ちい)さな鳥(とり)がぴゅうと飛(と)んで、木(き)のかげにかくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ぴゅう", "label": "基本形"}], "register": "casual", "sense_fingerprint": "物が速く動く音や強い風の音を表す擬音語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41221, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ぴゅう", "is_correct": true, "explanation": "速く飛ぶ音を表す「ぴゅう」が入り、「矢がぴゅうと飛ぶ」と自然に続く。"}, {"text": "もぞもぞ", "is_correct": false, "explanation": "もぞもぞは身をよじる小さな動きを表すので、矢が速く飛ぶ様子には合わない。"}, {"text": "ぺらぺら", "is_correct": false, "explanation": "ぺらぺらは薄いものが揺れる様子や流暢な話し方を表すので、矢の飛ぶ様子には合わない。"}, {"text": "ぺたぺた", "is_correct": false, "explanation": "ぺたぺたは軽く触れる音や様子を表すので、矢が飛ぶ文脈には合わない。"}], "explanations": {"ぴゅう": "速く飛ぶ音を表す「ぴゅう」が入り、「矢がぴゅうと飛ぶ」と自然に続く。", "もぞもぞ": "もぞもぞは身をよじる小さな動きを表すので、矢が速く飛ぶ様子には合わない。", "ぺらぺら": "ぺらぺらは薄いものが揺れる様子や流暢な話し方を表すので、矢の飛ぶ様子には合わない。", "ぺたぺた": "ぺたぺたは軽く触れる音や様子を表すので、矢が飛ぶ文脈には合わない。"}, "sentence_index": 0, "correct_answer": "ぴゅう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "亀がぴゅうと歩いた。", "explanation": "ここは〈のそのそ〉の意味。ゆっくり歩く様子を表すので、速く動く様子のぴゅうとは逆になる。"}, {"text": "父がぴゅうと寝言を言った。", "explanation": "ここは〈むにゃむにゃ〉の意味。寝ながら小さくつぶやく声を表すので、速く動く様子や風の音を表すぴゅうは合わない。"}, {"text": "その話を聞いて、彼はぴゅうと感心した。", "explanation": "ここは感動の様子を表す語の意味。ぴゅうは速い動きや風の音を表すので、心の動きには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41221, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ぴゅう", "is_correct": true, "explanation": "速く走る車を表す「ぴゅう」が入り、「車がぴゅうと走っていった」と自然に続く。"}, {"text": "ふさふさ", "is_correct": false, "explanation": "ふさふさは毛が豊かな様子を表すので、車の走る様子には合わない。"}, {"text": "ぱちぱち", "is_correct": false, "explanation": "ぱちぱちは軽くはぜる音や拍手の様子を表すので、車が走る文脈には合わない。"}, {"text": "きらきら", "is_correct": false, "explanation": "きらきらは光る様子を表すので、車が走る動きの表現としては合わない。"}], "explanations": {"ぴゅう": "速く走る車を表す「ぴゅう」が入り、「車がぴゅうと走っていった」と自然に続く。", "ふさふさ": "ふさふさは毛が豊かな様子を表すので、車の走る様子には合わない。", "ぱちぱち": "ぱちぱちは軽くはぜる音や拍手の様子を表すので、車が走る文脈には合わない。", "きらきら": "きらきらは光る様子を表すので、車が走る動きの表現としては合わない。"}, "sentence_index": 6, "correct_answer": "ぴゅう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋がぴゅうと煮えている。", "explanation": "ここは〈ことこと〉の意味。ふたを鳴らしながら静かに煮える様子を表すので、速く動くぴゅうは合わない。"}, {"text": "赤ちゃんがぴゅうと眠っている。", "explanation": "ここは〈すやすや〉の意味。穏やかに眠る様子を表すので、速い動きのぴゅうは合わない。"}, {"text": "二人がぴゅうと話している。", "explanation": "ここは〈ひそひそ〉の意味。小声で話す様子を表すので、速く動くぴゅうとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41221, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "野球の球がぴゅうで飛んでいった。", "corrected_sentence": "野球の球がぴゅうと飛んでいった。", "error_description": "副詞「ぴゅう」には「と」を付けて動詞に続ける。「で」は手段や場所を表す助詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41221, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "スケート選手がぴゅうで氷上をすべった。", "corrected_sentence": "スケート選手がぴゅうと氷上をすべった。", "error_description": "副詞「ぴゅう」には「と」を付けて動詞に続ける。「で」は手段や場所を表す助詞なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41222, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「鐘の音」で、鐘が出す音を表す正しい格。"}, {"text": "に", "is_correct": false, "explanation": "「鐘に音で」では音を鐘に向ける形になり、音の内容と合わない。"}, {"text": "が", "is_correct": false, "explanation": "「鐘が音で」では鐘が主語になり、「目がさめた」とつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「鐘で音で」では手段の意味が重なり、鐘の音を表せない。"}], "correct_answer": "の", "explanations": {"の": "「鐘の音」で、鐘が出す音を表す正しい格。", "に": "「鐘に音で」では音を鐘に向ける形になり、音の内容と合わない。", "が": "「鐘が音で」では鐘が主語になり、「目がさめた」とつながらない。", "で": "「鐘で音で」では手段の意味が重なり、鐘の音を表せない。"}, "error_tags": {"に": "対象の格。鐘と音の関係に合わない", "が": "主語の格。鐘を主語にできない", "で": "手段の格。鐘の音を表せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41222, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「鐘を手に持つ」の目的語を表す正しい格。"}, {"text": "と", "is_correct": false, "explanation": "「鐘と手に持つ」では並列になり、持つ対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「鐘へ手に持つ」は方向の意味になり、持つ動作と合わない。"}, {"text": "から", "is_correct": false, "explanation": "「鐘から手に持つ」は起点の意味になり、持つ対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「鐘を手に持つ」の目的語を表す正しい格。", "と": "「鐘と手に持つ」では並列になり、持つ対象として成り立たない。", "へ": "「鐘へ手に持つ」は方向の意味になり、持つ動作と合わない。", "から": "「鐘から手に持つ」は起点の意味になり、持つ対象を示せない。"}, "error_tags": {"と": "並列の格。持つ対象にならない", "へ": "方向の格。持つ動作と合わない", "から": "起点の格。持つ対象を示せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41222, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かねを ならして おとを だす どうぐです。", "primary_collocate": null, "pronunciation": "かね", "ipa": "kane", "syllable_count": 2, "sentences": [{"text": "お寺の鐘が鳴って、町じゅうに音が広がった。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "お寺(てら)の鐘(かね)が鳴(な)って、町(まち)じゅうに音(おと)が広(ひろ)がった。", "sentence_source": "generated"}, {"text": "朝六時に、教会の鐘の音で目がさめた。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "朝(あさ)六時(ろくじ)に、教会(きょうかい)の鐘(かね)の音(おと)で目(め)がさめた。", "sentence_source": "generated"}, {"text": "大みそかの夜、除夜の鐘をつきに行った。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "大(おお)みそかの夜(よる)、除夜(じょや)の鐘(かね)をつきに行(い)った。", "sentence_source": "generated"}, {"text": "学校の鐘が鳴ったので、みんな教室にもどった。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "学校(がっこう)の鐘(かね)が鳴(な)ったので、みんな教室(きょうしつ)にもどった。", "sentence_source": "generated"}, {"text": "結婚式で、大きな鐘がやさしい音を出した。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "結婚式(けっこんしき)で、大(おお)きな鐘(かね)がやさしい音(おと)を出(だ)した。", "sentence_source": "generated"}, {"text": "鐘をたたくと、高い音が遠くまで聞こえた。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "鐘(かね)をたたくと、高(たか)い音(おと)が遠(とお)くまで聞(き)こえた。", "sentence_source": "generated"}, {"text": "山の上にある古い鐘は、毎日夕方に鳴る。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)にある古(ふる)い鐘(かね)は、毎日(まいにち)夕方(ゆうがた)に鳴(な)る。", "sentence_source": "generated"}, {"text": "小さな鐘を手に持って、ふると音が出る。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "小(ちい)さな鐘(かね)を手(て)に持(も)って、ふると音(おと)が出(で)る。", "sentence_source": "generated"}, {"text": "鐘の音がやんだあと、あたりは静かになった。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "鐘(かね)の音(おと)がやんだあと、あたりは静(しず)かになった。", "sentence_source": "generated"}, {"text": "船の上で鐘を鳴らして、ほかの船に知らせた。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "船(ふね)の上(うえ)で鐘(かね)を鳴(な)らして、ほかの船(ふね)に知(し)らせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鐘", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "鳴らして音を出す道具としての鐘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41222, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鐘", "is_correct": true, "explanation": "鳴らすと音が広がる道具で、「鳴って音が広がった」の主語として合う。"}, {"text": "塔", "is_correct": false, "explanation": "塔は高くそびえる建物で、鳴って音を出すものではないので、ここでは合わない。"}, {"text": "庭", "is_correct": false, "explanation": "庭は植物や地面のある場所で、音を出して鳴る物ではないので合わない。"}, {"text": "墓", "is_correct": false, "explanation": "墓は音を出す物ではなく、「鳴って」と結びつかないので合わない。"}], "explanations": {"鐘": "鳴らすと音が広がる道具で、「鳴って音が広がった」の主語として合う。", "塔": "塔は高くそびえる建物で、鳴って音を出すものではないので、ここでは合わない。", "庭": "庭は植物や地面のある場所で、音を出して鳴る物ではないので合わない。", "墓": "墓は音を出す物ではなく、「鳴って」と結びつかないので合わない。"}, "sentence_index": 0, "correct_answer": "鐘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昼ごはんに、鐘を三つに切って、みんなで食べた。", "explanation": "ここは〈ケーキ〉の意味。切り分けて食べるのは食べ物で、鐘は食べられないので合わない。"}, {"text": "台所で、大きな鐘に水をためて、野菜を洗った。", "explanation": "ここは〈ボウル〉の意味。水をためて野菜を洗う器はボウルで、鐘は器として使わないので合わない。"}, {"text": "壁にかかった鐘の針を見て、時間を確かめた。", "explanation": "ここは〈時計〉の意味。針を見て時刻を読むのは時計で、鐘には針がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41222, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鐘", "is_correct": true, "explanation": "夕方に鳴って時を知らせる道具で、「鳴る」の主語として合う。"}, {"text": "井戸", "is_correct": false, "explanation": "井戸は水をくむ設備で、夕方に鳴る物ではないので合わない。"}, {"text": "石碑", "is_correct": false, "explanation": "石碑は文字を刻んだ石で、音を出して鳴ることはないので合わない。"}, {"text": "旗", "is_correct": false, "explanation": "旗は風になびくもので、「鳴る」とは結びつかないので合わない。"}], "explanations": {"鐘": "夕方に鳴って時を知らせる道具で、「鳴る」の主語として合う。", "井戸": "井戸は水をくむ設備で、夕方に鳴る物ではないので合わない。", "石碑": "石碑は文字を刻んだ石で、音を出して鳴ることはないので合わない。", "旗": "旗は風になびくもので、「鳴る」とは結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "鐘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の始まりに、審判が鐘を吹いて合図した。", "explanation": "ここは〈笛〉を吹く合図の場面。鐘は吹くものではなく鳴らすものなので、ここでは合わない。"}, {"text": "祭りの夜、大きな鐘を両手でどんどんと打って、踊りの拍子を取った。", "explanation": "ここは〈太鼓〉の打ち方。どんどんと打って拍子を取るのは太鼓で、鐘の使い方としては合わない。"}, {"text": "運転手が鐘を回して、車を右にまがった。", "explanation": "ここは〈ハンドル〉の意味。回して車の向きを変えるのはハンドルで、鐘では車は曲がらないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41222, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方の山寺で、鐘が鳴いて、鳥が飛び立った。", "corrected_sentence": "夕方の山寺で、鐘が鳴って、鳥が飛び立った。", "error_description": "誤りは「鳴いて」。「鳴く」は動物の声に使う動詞で、鐘には「鳴る」を使う。正しくは「鳴って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41222, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裏山の古い寺の鐘を、毎日夕方に鳴る。", "corrected_sentence": "裏山の古い寺の鐘は、毎日夕方に鳴る。", "error_description": "誤りは「鐘を」。「鳴る」は自動詞なので目的語の「を」は使えない。主題の「は」にして「鐘は鳴る」とする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41223, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41223, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「鐘を鳴らした」の目的語を表す正しい格。"}, {"text": "と", "is_correct": false, "explanation": "「鐘と鳴らした」では並列になり、鳴らす対象にならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「鐘から鳴らした」は起点の意味になり、鳴らす対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「鐘より鳴らした」は比較の意味になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「鐘を鳴らした」の目的語を表す正しい格。", "と": "「鐘と鳴らした」では並列になり、鳴らす対象にならないので合わない。", "から": "「鐘から鳴らした」は起点の意味になり、鳴らす対象を示せない。", "より": "「鐘より鳴らした」は比較の意味になり、文が成り立たない。"}, "error_tags": {"と": "並列の格。鳴らす対象にならない", "から": "起点の格。鳴らす対象を示せない", "より": "比較の格。文が成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41223, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "金属を打って音を出す道具。寺や学校などで時を知らせるのに使う。", "primary_collocate": null, "pronunciation": "かね", "ipa": "kane", "syllable_count": 2, "sentences": [{"text": "夕方五時になると、寺の鐘が時を知らせる。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "夕方(ゆうがた)五時(ごじ)になると、寺(てら)の鐘(かね)が時(とき)を知(し)らせる。", "sentence_source": "generated"}, {"text": "昔の人は、鐘の音で時間を知った。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)は、鐘(かね)の音(おと)で時間(じかん)を知(し)った。", "sentence_source": "generated"}, {"text": "授業の終わりを告げる鐘が、校舎にひびいた。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)の終(お)わりを告(つ)げる鐘(かね)が、校舎(こうしゃ)にひびいた。", "sentence_source": "generated"}, {"text": "住職が鐘をつくと、ゴーンという重い音がした。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "住職(じゅうしょく)が鐘(かね)をつくと、ゴーンという重(おも)い音(おと)がした。", "sentence_source": "generated"}, {"text": "金属でできた鐘は、たたくといい音がする。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "金属(きんぞく)でできた鐘(かね)は、たたくといい音(おと)がする。", "sentence_source": "generated"}, {"text": "正午の鐘が鳴るまで、あと十分だ。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "正午(しょうご)の鐘(かね)が鳴(な)るまで、あと十分(じゅっぷん)だ。", "sentence_source": "generated"}, {"text": "この町では、毎朝七時に鐘が鳴って朝を知らせる。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "この町(まち)では、毎朝(まいあさ)七時(しちじ)に鐘(かね)が鳴(な)って朝(あさ)を知(し)らせる。", "sentence_source": "generated"}, {"text": "火事のとき、村の人に知らせるために鐘を鳴らした。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "火事(かじ)のとき、村(むら)の人(ひと)に知(し)らせるために鐘(かね)を鳴(な)らした。", "sentence_source": "generated"}, {"text": "古い寺の鐘は、何百年も同じ音を出している。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "古(ふる)い寺(てら)の鐘(かね)は、何百年(なんびゃくねん)も同(おな)じ音(おと)を出(だ)している。", "sentence_source": "generated"}, {"text": "試合の開始を知らせる鐘が鳴り、会場が静まった。", "target_word": "鐘", "complexity_tier": "T3", "furigana": "試合(しあい)の開始(かいし)を知(し)らせる鐘(かね)が鳴(な)り、会場(かいじょう)が静(しず)まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鐘", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "寺や学校などで時を知らせる金属製の鐘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: ひびい (Zipf 1.65)']::text[], 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41223, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鐘", "is_correct": true, "explanation": "寺で時を知らせる金属製の道具で、「時を知らせる」の主語として合う。"}, {"text": "門", "is_correct": false, "explanation": "門は出入りのための入口で、時を知らせる働きはないので合わない。"}, {"text": "庭", "is_correct": false, "explanation": "庭は植物のある場所で、時を知らせるものではないので合わない。"}, {"text": "本堂", "is_correct": false, "explanation": "本堂は寺の建物で、時を知らせる主体にはならないので合わない。"}], "explanations": {"鐘": "寺で時を知らせる金属製の道具で、「時を知らせる」の主語として合う。", "門": "門は出入りのための入口で、時を知らせる働きはないので合わない。", "庭": "庭は植物のある場所で、時を知らせるものではないので合わない。", "本堂": "本堂は寺の建物で、時を知らせる主体にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "鐘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "腕にはめた鐘の針を見て、今の時間を確かめた。", "explanation": "ここは〈腕時計〉の意味。針を見て時間を読むのは腕時計で、鐘は腕にはめないので合わない。"}, {"text": "試合の開始は、審判が鐘を吹いて知らせた。", "explanation": "ここは〈笛〉を吹いて開始を知らせる場面。鐘は吹くものではないので合わない。"}, {"text": "玄関で鐘を押すと、家の中で音が鳴った。", "explanation": "ここは〈チャイム〉のボタン。押して来客を知らせる装置で、鐘は押すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41223, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鐘", "is_correct": true, "explanation": "鳴って朝を知らせる道具で、「鳴って朝を知らせる」の主語として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は光や風を入れる部分で、鳴って朝を知らせるものではないので合わない。"}, {"text": "扉", "is_correct": false, "explanation": "扉は開け閉めするもので、音を出して朝を知らせることはないので合わない。"}, {"text": "煙突", "is_correct": false, "explanation": "煙突は煙を出す筒で、鳴る物ではないので合わない。"}], "explanations": {"鐘": "鳴って朝を知らせる道具で、「鳴って朝を知らせる」の主語として合う。", "窓": "窓は光や風を入れる部分で、鳴って朝を知らせるものではないので合わない。", "扉": "扉は開け閉めするもので、音を出して朝を知らせることはないので合わない。", "煙突": "煙突は煙を出す筒で、鳴る物ではないので合わない。"}, "sentence_index": 6, "correct_answer": "鐘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "運動会の開会式で、大きな鐘を両手で打って、行進の拍子を取った。", "explanation": "ここは〈太鼓〉を打って拍子を取る場面。鐘を打って拍子を取るとは言わないので、ここでは合わない。"}, {"text": "駅では出発の合図に、鐘を長く吹いて知らせた。", "explanation": "ここは〈汽笛〉を吹いて出発を知らせる場面。鐘は吹くものではないので合わない。"}, {"text": "運動会では、先生が鐘を高く吹いてスタートを知らせた。", "explanation": "ここは〈ラッパ〉を吹いて合図する場面。鐘は吹けないので、スタートの合図としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41223, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝六時に、寺の鐘に時を知らせる。", "corrected_sentence": "毎朝六時に、寺の鐘が時を知らせる。", "error_description": "誤りは「鐘に」。知らせる主体である鐘は主語になるので、「鐘が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41223, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "午後三時に、寺の鐘が鳴らして時を知らせた。", "corrected_sentence": "午後三時に、寺の鐘が鳴って時を知らせた。", "error_description": "誤りは「鳴らして」。鐘は自分で鳴るので自動詞の「鳴って」が正しい。「鳴らして」は他動詞の形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41224, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愚か", "is_correct": true, "explanation": "頭の働きが鈍いさまを表し、「賢い」の対義語として辞書に並ぶ。"}, {"text": "穏やか", "is_correct": false, "explanation": "性格や天候が落ち着いたさまで、知能の反対語ではない。"}, {"text": "素直", "is_correct": false, "explanation": "人の言葉を受け入れる性格を表し、賢さの反対語ではない。"}, {"text": "気楽", "is_correct": false, "explanation": "心配がないさまで、頭の働きとは関係しない。"}], "correct_answer": "愚か", "explanations": {"愚か": "頭の働きが鈍いさまを表し、「賢い」の対義語として辞書に並ぶ。", "穏やか": "性格や天候が落ち着いたさまで、知能の反対語ではない。", "素直": "人の言葉を受け入れる性格を表し、賢さの反対語ではない。", "気楽": "心配がないさまで、頭の働きとは関係しない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41224, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "愚か", "is_correct": true, "explanation": "頭の働きが鈍いさまを表し、「賢い」の対義語として辞書に並ぶ。"}, {"text": "誠実", "is_correct": false, "explanation": "真心があるさまを表し、知能の反対語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "動きが盛んなさまを表し、賢さの反対語ではない。"}, {"text": "勤勉", "is_correct": false, "explanation": "よく努めるさまを表し、頭の働きの反対語ではない。"}], "correct_answer": "愚か", "explanations": {"愚か": "頭の働きが鈍いさまを表し、「賢い」の対義語として辞書に並ぶ。", "誠実": "真心があるさまを表し、知能の反対語ではない。", "活発": "動きが盛んなさまを表し、賢さの反対語ではない。", "勤勉": "よく努めるさまを表し、頭の働きの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41224, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "かしこい は、あたまが よく はたらく こと です。", "primary_collocate": null, "pronunciation": "かしこい", "ipa": "kaɕikoi", "syllable_count": 4, "sentences": [{"text": "うちの犬はとても賢いので、すぐに芸を覚える。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "うちの犬[いぬ]はとても賢[かしこ]いので、すぐに芸[げい]を覚[おぼ]える。", "sentence_source": "generated"}, {"text": "あの子は小さいのに、賢い答えを言った。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "あの子[こ]は小[ちい]さいのに、賢[かしこ]い答[こた]えを言[い]った。", "sentence_source": "generated"}, {"text": "カラスは賢い鳥で、道具を使うこともある。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "カラスは賢[かしこ]い鳥[とり]で、道具[どうぐ]を使[つか]うこともある。", "sentence_source": "generated"}, {"text": "兄は賢くて、難しい問題もすぐに解いてしまう。", "target_word": "賢くて", "complexity_tier": "T3", "furigana": "兄[あに]は賢[かしこ]くて、難[むずか]しい問題[もんだい]もすぐに解[と]いてしまう。", "sentence_source": "generated"}, {"text": "賢い子どもほど、よく質問をする。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "賢[かしこ]い子[こ]どもほど、よく質問[しつもん]をする。", "sentence_source": "generated"}, {"text": "彼女は子どものころから賢かったそうだ。", "target_word": "賢かった", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は子[こ]どものころから賢[かしこ]かったそうだ。", "sentence_source": "generated"}, {"text": "この猫は賢くないが、とてもかわいい。", "target_word": "賢くない", "complexity_tier": "T3", "furigana": "この猫[ねこ]は賢[かしこ]くないが、とてもかわいい。", "sentence_source": "generated"}, {"text": "イルカは賢い動物として知られている。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "イルカは賢[かしこ]い動物[どうぶつ]として知[し]られている。", "sentence_source": "generated"}, {"text": "弟は賢いので、先生によくほめられる。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "弟[おとうと]は賢[かしこ]いので、先生[せんせい]によくほめられる。", "sentence_source": "generated"}, {"text": "賢い人は、同じ失敗を二度としないものだ。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "賢[かしこ]い人[ひと]は、同[おな]じ失敗[しっぱい]を二度[にど]としないものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "賢い", "label": "dictionary"}, {"form": "賢く", "label": "adverbial"}, {"form": "賢かった", "label": "past"}, {"form": "賢くない", "label": "negative"}, {"form": "賢ければ", "label": "conditional"}], "register": "neutral", "sense_fingerprint": "頭がよく働くさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41224, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "賢い", "is_correct": true, "explanation": "連体形で「とても賢いので」と続き、理由を示す文として自然。"}, {"text": "賢く", "is_correct": false, "explanation": "連用形は「ので」の前に直接置けず、「とても賢くので」は成り立たない。"}, {"text": "賢くて", "is_correct": false, "explanation": "て形は理由を表す「ので」の前には入らず、文が続かない。"}, {"text": "賢ければ", "is_correct": false, "explanation": "仮定形は「ので」と組み合わせず、文の形が崩れる。"}], "explanations": {"賢い": "連体形で「とても賢いので」と続き、理由を示す文として自然。", "賢く": "連用形は「ので」の前に直接置けず、「とても賢くので」は成り立たない。", "賢くて": "て形は理由を表す「ので」の前には入らず、文が続かない。", "賢ければ": "仮定形は「ので」と組み合わせず、文の形が崩れる。"}, "sentence_index": 0, "correct_answer": "賢い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は手先が賢くて、細かい刺繍もすぐにできる。", "explanation": "ここは〈器用〉の意味。手先の器用さは〈器用〉で表し、賢いは頭の働きを指すので手先には合わない。"}, {"text": "彼はピアノが賢くて、コンクールで一位になった。", "explanation": "ここは〈上手〉の意味。演奏の腕前は〈上手〉で言い、賢いは頭の働きを指すのでピアノには合わない。"}, {"text": "彼は体が賢くて、マラソンを最後まで走り抜いた。", "explanation": "ここは〈強い〉の意味。体力の強さは〈強い〉で言い、賢いは頭の働きを指すので体には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41224, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "賢くない", "is_correct": true, "explanation": "否定形で「が」に続き、「賢くないが、かわいい」と逆接の文として自然。"}, {"text": "賢そう", "is_correct": false, "explanation": "様態の形で、「猫は賢そうが」と「が」に続かない。"}, {"text": "大らか", "is_correct": false, "explanation": "形容動詞の語幹で、「が」の前に「な」「だ」が必要なので入らない。"}, {"text": "静か", "is_correct": false, "explanation": "形容動詞の語幹で、「猫は静かが」と「が」に続かず不自然。"}], "explanations": {"賢くない": "否定形で「が」に続き、「賢くないが、かわいい」と逆接の文として自然。", "賢そう": "様態の形で、「猫は賢そうが」と「が」に続かない。", "大らか": "形容動詞の語幹で、「が」の前に「な」「だ」が必要なので入らない。", "静か": "形容動詞の語幹で、「猫は静かが」と「が」に続かず不自然。"}, "sentence_index": 6, "correct_answer": "賢くない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は足が賢くて、どの選手よりも速く走る。", "explanation": "ここは〈俊足〉の意味。足の速さは〈俊足〉で言い、賢いは頭の働きを指すので足には合わない。"}, {"text": "彼女は字が賢くて、読みやすい。", "explanation": "ここは〈きれい〉の意味。字の見た目の美しさは〈きれい〉で言い、賢いは頭の働きを指すので字には使わない。"}, {"text": "この傘は賢くて、持ち運びに便利だ。", "explanation": "ここは〈軽い〉の意味。重さの少なさは〈軽い〉で表し、賢いは頭の働きを指すので傘には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41224, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その鳥は賢く動物で、人の言葉をまねできる。", "corrected_sentence": "その鳥は賢い動物で、人の言葉をまねできる。", "error_description": "誤りは「賢く」。名詞「動物」を修飾するには連体形「賢い」が必要で、連用形「賢く」は後ろの名詞に直接続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "賢い", "is_correct": true, "explanation": "連体形で「賢い答え」と名詞を修飾する形。"}, {"text": "賢さ", "is_correct": false, "explanation": "名詞なので後ろの「答え」を直接修飾できず、「賢さ答え」は成り立たない。"}, {"text": "賢そう", "is_correct": false, "explanation": "様態の形は名詞の前に「な」が要るため、「賢そう答え」は成り立たない。"}, {"text": "賢ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾せず、「賢ければ答え」は成り立たない。"}], "correct_form": "賢い", "base_form": "賢い", "form_label": "連体形", "sentence_index": 1, "explanations": {"賢い": "連体形で「賢い答え」と名詞を修飾する形。", "賢さ": "名詞なので後ろの「答え」を直接修飾できず、「賢さ答え」は成り立たない。", "賢そう": "様態の形は名詞の前に「な」が要るため、「賢そう答え」は成り立たない。", "賢ければ": "仮定形は名詞を修飾せず、「賢ければ答え」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41224, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は賢ないが、努力家だ。", "corrected_sentence": "彼女は賢くないが、努力家だ。", "error_description": "誤りは「賢ない」。形容詞の否定は語幹に「く」を入れて「賢くない」と言い、「賢ない」とは言わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "賢い", "is_correct": true, "explanation": "連体形で、後ろの名詞「動物」を修飾する形。"}, {"text": "賢げ", "is_correct": false, "explanation": "様態の形は名詞の前に「な」が要るため、「賢げ動物」は成り立たない。"}, {"text": "賢かろう", "is_correct": false, "explanation": "推量の形は名詞を直接修飾できず、「賢かろう動物」は成り立たない。"}, {"text": "賢く", "is_correct": false, "explanation": "副詞なので名詞「動物」を修飾できず、「賢く動物」は成り立たない。"}], "correct_form": "賢い", "base_form": "賢い", "form_label": "連体形", "sentence_index": 7, "explanations": {"賢い": "連体形で、後ろの名詞「動物」を修飾する形。", "賢げ": "様態の形は名詞の前に「な」が要るため、「賢げ動物」は成り立たない。", "賢かろう": "推量の形は名詞を直接修飾できず、「賢かろう動物」は成り立たない。", "賢く": "副詞なので名詞「動物」を修飾できず、「賢く動物」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
