INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41225, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "賢いとは、知識や経験を活かして、適切に判断したり行動したりできること。頭の良いこと。", "primary_collocate": null, "pronunciation": "かしこい", "ipa": "kaɕikoi", "syllable_count": 4, "sentences": [{"text": "お金を賢く使う人は、将来困らない。", "target_word": "賢く", "complexity_tier": "T4", "furigana": "お金[かね]を賢[かしこ]く使[つか]う人[ひと]は、将来[しょうらい]困[こま]らない。", "sentence_source": "generated"}, {"text": "賢い選択をしたおかげで、損をしなかった。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "賢[かしこ]い選択[せんたく]をしたおかげで、損[そん]をしなかった。", "sentence_source": "generated"}, {"text": "彼は経験を活かして、賢く判断した。", "target_word": "賢く", "complexity_tier": "T4", "furigana": "彼[かれ]は経験[けいけん]を活[い]かして、賢[かしこ]く判断[はんだん]した。", "sentence_source": "generated"}, {"text": "安い時期に買うのは、賢い買い物のしかただ。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "安[やす]い時期[じき]に買[か]うのは、賢[かしこ]い買[か]い物[もの]のしかただ。", "sentence_source": "generated"}, {"text": "賢い人は、危ない場所には近づかない。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "賢[かしこ]い人[ひと]は、危[あぶ]ない場所[ばしょ]には近[ちか]づかない。", "sentence_source": "generated"}, {"text": "もっと賢く行動していれば、あんな失敗はしなかった。", "target_word": "賢く", "complexity_tier": "T4", "furigana": "もっと賢[かしこ]く行動[こうどう]していれば、あんな失敗[しっぱい]はしなかった。", "sentence_source": "generated"}, {"text": "忙しい日は、時間を賢く使うことが大切だ。", "target_word": "賢く", "complexity_tier": "T3", "furigana": "忙[いそが]しい日[ひ]は、時間[じかん]を賢[かしこ]く使[つか]うことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "賢いやり方で、問題は早く解決した。", "target_word": "賢い", "complexity_tier": "T3", "furigana": "賢[かしこ]いやり方[かた]で、問題[もんだい]は早[はや]く解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "社長は賢い人で、状況を見て正しく決断する。", "target_word": "賢い", "complexity_tier": "T4", "furigana": "社長[しゃちょう]は賢[かしこ]い人[ひと]で、状況[じょうきょう]を見[み]て正[ただ]しく決断[けつだん]する。", "sentence_source": "generated"}, {"text": "ここで争わずに引くのが、賢い判断だと思う。", "target_word": "賢い", "complexity_tier": "T4", "furigana": "ここで争[あらそ]わずに引[ひ]くのが、賢[かしこ]い判断[はんだん]だと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "賢い", "label": "dictionary"}, {"form": "賢く", "label": "adverbial"}, {"form": "賢かった", "label": "past"}, {"form": "賢くない", "label": "negative"}, {"form": "賢ければ", "label": "conditional"}], "register": "neutral", "sense_fingerprint": "知識や経験を活かして適切に判断・行動できるさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41225, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "賢く", "is_correct": true, "explanation": "連用形で、動詞「使う」を修飾して「賢く使う」となる。"}, {"text": "賢い", "is_correct": false, "explanation": "形容詞の終止形は動詞を直接修飾できず、「お金を賢い使う」は成り立たない。"}, {"text": "賢ければ", "is_correct": false, "explanation": "仮定形は動詞の前に置けず、「お金を賢ければ使う」は不自然。"}, {"text": "賢かった", "is_correct": false, "explanation": "過去形は動詞の前に置けず、「お金を賢かった使う」は文が崩れる。"}], "explanations": {"賢く": "連用形で、動詞「使う」を修飾して「賢く使う」となる。", "賢い": "形容詞の終止形は動詞を直接修飾できず、「お金を賢い使う」は成り立たない。", "賢ければ": "仮定形は動詞の前に置けず、「お金を賢ければ使う」は不自然。", "賢かった": "過去形は動詞の前に置けず、「お金を賢かった使う」は文が崩れる。"}, "sentence_index": 0, "correct_answer": "賢く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は料理が賢くて、友達によくふるまう。", "explanation": "ここは〈上手〉の意味。料理の腕前は〈上手〉で言い、賢いは判断や行動の適切さを指すので料理には合わない。"}, {"text": "この靴は賢くて、三年も長く履ける。", "explanation": "ここは〈丈夫〉の意味。物の頑丈さは〈丈夫〉で言い、賢いは人の判断を指すので靴には合わない。"}, {"text": "このかばんは賢くて、たくさん入る。", "explanation": "ここは〈大きい〉の意味。容量の大きさは〈大きい〉で表し、賢いは判断の適切さを指すのでかばんには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41225, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "賢く", "is_correct": true, "explanation": "連用形で、動詞「使う」を修飾して「賢く使う」となる。"}, {"text": "賢そう", "is_correct": false, "explanation": "様態の形は動詞を修飾できず、「時間を賢そう使う」は成り立たない。"}, {"text": "賢さ", "is_correct": false, "explanation": "名詞なので動詞を修飾できず、「時間を賢さ使う」は不自然。"}, {"text": "賢くない", "is_correct": false, "explanation": "否定形は動詞の前に置けず、「時間を賢くない使う」は文が崩れる。"}], "explanations": {"賢く": "連用形で、動詞「使う」を修飾して「賢く使う」となる。", "賢そう": "様態の形は動詞を修飾できず、「時間を賢そう使う」は成り立たない。", "賢さ": "名詞なので動詞を修飾できず、「時間を賢さ使う」は不自然。", "賢くない": "否定形は動詞の前に置けず、「時間を賢くない使う」は文が崩れる。"}, "sentence_index": 6, "correct_answer": "賢く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このパンは賢くて、噛みにくい。", "explanation": "ここは〈硬い〉の意味。食べ物の硬さは〈硬い〉で表し、賢いは判断や頭の働きを指すのでパンには合わない。"}, {"text": "今朝は賢くて、窓の水が凍っていた。", "explanation": "ここは〈寒い〉の意味。気温の低さは〈寒い〉で表し、賢いは判断の適切さを指すので天気には使わない。"}, {"text": "そのドレスは賢くて、とても目立つ。", "explanation": "ここは〈派手〉の意味。目立つ装いは〈派手〉で言い、賢いは判断の適切さを指すのでドレスには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41225, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は危険を予測して、賢い身を引いた。", "corrected_sentence": "彼は危険を予測して、賢く身を引いた。", "error_description": "誤りは「賢い」。動詞「引いた」を修飾するので連用形「賢く」が必要で、「賢い身」は不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "賢い", "is_correct": true, "explanation": "連体形で「賢い選択」と名詞を修飾する形。"}, {"text": "賢さ", "is_correct": false, "explanation": "名詞なので「選択をした」を修飾できず、「賢さ選択」は成り立たない。"}, {"text": "賢そう", "is_correct": false, "explanation": "様態の形は名詞の前に「な」が要るため、「賢そう選択」は成り立たない。"}, {"text": "賢げ", "is_correct": false, "explanation": "様態の形は名詞の前に「な」が要るため、「賢げ選択」は成り立たない。"}], "correct_form": "賢い", "base_form": "賢い", "form_label": "連体形", "sentence_index": 1, "explanations": {"賢い": "連体形で「賢い選択」と名詞を修飾する形。", "賢さ": "名詞なので「選択をした」を修飾できず、「賢さ選択」は成り立たない。", "賢そう": "様態の形は名詞の前に「な」が要るため、「賢そう選択」は成り立たない。", "賢げ": "様態の形は名詞の前に「な」が要るため、「賢げ選択」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41225, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は時間を賢さ使って、資格を取った。", "corrected_sentence": "彼女は時間を賢く使って、資格を取った。", "error_description": "誤りは「賢さ」。「賢さ」は名詞で動詞「使って」を修飾できない。連用形「賢く」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "賢い", "is_correct": true, "explanation": "連体形で、後ろの名詞「やり方」を修飾する形。"}, {"text": "賢く", "is_correct": false, "explanation": "副詞なので名詞「やり方」を修飾できず、「賢くやり方で」は成り立たない。"}, {"text": "賢かろう", "is_correct": false, "explanation": "推量の形は名詞を直接修飾できず、「賢かろうやり方で」は成り立たない。"}, {"text": "賢ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「賢ければやり方で」は成り立たない。"}], "correct_form": "賢い", "base_form": "賢い", "form_label": "連体形", "sentence_index": 7, "explanations": {"賢い": "連体形で、後ろの名詞「やり方」を修飾する形。", "賢く": "副詞なので名詞「やり方」を修飾できず、「賢くやり方で」は成り立たない。", "賢かろう": "推量の形は名詞を直接修飾できず、「賢かろうやり方で」は成り立たない。", "賢ければ": "仮定形は名詞を修飾できず、「賢ければやり方で」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41226, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「絵がかけてある」の主語を示す「が」で、文が自然に成り立つ。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「絵からかけてある」と続かず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「絵へかけてある」と続かず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「絵よりかけてある」と続かず、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「絵がかけてある」の主語を示す「が」で、文が自然に成り立つ。", "から": "起点の「から」は「絵からかけてある」と続かず、文が成り立たない。", "へ": "方向の「へ」は「絵へかけてある」と続かず不自然。", "より": "比較の「より」は「絵よりかけてある」と続かず、意味が通らない。"}, "error_tags": {"から": "起点", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41226, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「絵が飾ってある」の主語を示す「が」で、文が自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "場所や手段の「に」は「絵に飾ってある」と続かず不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用の「と」は「絵と飾ってある」と続かず、文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "所属の「の」は「絵の飾ってある」と続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「絵が飾ってある」の主語を示す「が」で、文が自然に成り立つ。", "に": "場所や手段の「に」は「絵に飾ってある」と続かず不自然。", "と": "共同や引用の「と」は「絵と飾ってある」と続かず、文が崩れる。", "の": "所属の「の」は「絵の飾ってある」と続かず、文が成り立たない。"}, "error_tags": {"に": "位置", "と": "共同", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41226, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かいたもの。え。", "primary_collocate": null, "pronunciation": "え", "ipa": "e", "syllable_count": 1, "sentences": [{"text": "妹は毎日、公園で絵をかいている。", "target_word": "絵", "complexity_tier": "T3", "furigana": "妹[いもうと]は毎日[まいにち]、公園[こうえん]で絵[え]をかいている。", "sentence_source": "generated"}, {"text": "壁に大きな絵がかけてあります。", "target_word": "絵", "complexity_tier": "T3", "furigana": "壁[かべ]に大[おお]きな絵[え]がかけてあります。", "sentence_source": "generated"}, {"text": "美術館で、有名な画家の絵を見た。", "target_word": "絵", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で、有名[ゆうめい]な画家[がか]の絵[え]を見[み]た。", "sentence_source": "generated"}, {"text": "この絵は、海と空の色がとてもきれいだ。", "target_word": "絵", "complexity_tier": "T3", "furigana": "この絵[え]は、海[うみ]と空[そら]の色[いろ]がとてもきれいだ。", "sentence_source": "generated"}, {"text": "子どもたちは、先生の顔の絵を上手にかいた。", "target_word": "絵", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、先生[せんせい]の顔[かお]の絵[え]を上手[じょうず]にかいた。", "sentence_source": "generated"}, {"text": "私は絵が好きなので、休みの日によく描く。", "target_word": "絵", "complexity_tier": "T3", "furigana": "私[わたし]は絵[え]が好[す]きなので、休[やす]みの日[ひ]によく描[えが]く。", "sentence_source": "generated"}, {"text": "この絵本には、かわいい動物の絵がたくさんある。", "target_word": "絵", "complexity_tier": "T3", "furigana": "この絵本[えほん]には、かわいい動物[どうぶつ]の絵[え]がたくさんある。", "sentence_source": "generated"}, {"text": "祖父の部屋には、古い山の絵が飾ってある。", "target_word": "絵", "complexity_tier": "T3", "furigana": "祖父[そふ]の部屋[へや]には、古[ふる]い山[やま]の絵[え]が飾[かざ]ってある。", "sentence_source": "generated"}, {"text": "友達に誕生日の絵をもらって、うれしかった。", "target_word": "絵", "complexity_tier": "T3", "furigana": "友達[ともだち]に誕生日[たんじょうび]の絵[え]をもらって、うれしかった。", "sentence_source": "generated"}, {"text": "この絵の作者は、まだ十歳の男の子だそうだ。", "target_word": "絵", "complexity_tier": "T3", "furigana": "この絵[え]の作者[さくしゃ]は、まだ十歳[じっさい]の男[おとこ]の子[こ]だそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵", "label": "dictionary"}, {"form": "絵を", "label": "object"}, {"form": "絵が", "label": "subject"}, {"form": "絵の", "label": "genitive"}], "register": "neutral", "sense_fingerprint": "描かれたもの（絵画・イラスト）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41226, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絵", "is_correct": true, "explanation": "「絵をかく」の目的語として、描かれるものを指すのに合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は作るもので、「料理をかく」とは言わない。"}, {"text": "電話", "is_correct": false, "explanation": "電話はかけるもので、「電話をかく」とは言わない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題はするもので、「宿題をかく」とは言わない。"}], "explanations": {"絵": "「絵をかく」の目的語として、描かれるものを指すのに合う。", "料理": "料理は作るもので、「料理をかく」とは言わない。", "電話": "電話はかけるもので、「電話をかく」とは言わない。", "宿題": "宿題はするもので、「宿題をかく」とは言わない。"}, "sentence_index": 0, "correct_answer": "絵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹は公園で、絵を撮った。", "explanation": "ここは〈写真〉の意味。カメラで写すことは〈写真〉で表し、絵は描くものなので『撮る』とは合わない。"}, {"text": "先生は黒板に絵をひいた。", "explanation": "ここは〈線〉の意味。黒板に線をひくことは〈線〉で言い、絵は『描く』ものなので『ひく』とは言わない。"}, {"text": "妹は毎日、公園で絵を口ずさんでいる。", "explanation": "ここは〈歌〉の意味。声に出して歌うことは〈歌〉で表し、絵は見たりかいたりするものなので、声に出す行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41226, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絵", "is_correct": true, "explanation": "「かわいい動物の絵がたくさんある」の名詞として、描かれたものを指すのに合う。"}, {"text": "空気", "is_correct": false, "explanation": "「かわいい動物の空気」は意味が通らない。"}, {"text": "水道", "is_correct": false, "explanation": "「かわいい動物の水道」は絵本の文脈に合わない。"}, {"text": "湿気", "is_correct": false, "explanation": "「かわいい動物の湿気」は絵本の文脈に合わない。"}], "explanations": {"絵": "「かわいい動物の絵がたくさんある」の名詞として、描かれたものを指すのに合う。", "空気": "「かわいい動物の空気」は意味が通らない。", "水道": "「かわいい動物の水道」は絵本の文脈に合わない。", "湿気": "「かわいい動物の湿気」は絵本の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "絵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹は寝る前に、母に絵を聞かせてもらう。", "explanation": "ここは〈話〉の意味。話は聞くもので、絵は見るものなので『聞く』とは合わない。"}, {"text": "彼は休みの日、部屋で絵を聴いて過ごす。", "explanation": "ここは〈音楽〉の意味。音楽は聴くもので、絵は見るものなので『聴く』とは合わない。"}, {"text": "祖母は庭に出て、花の絵をかいでいた。", "explanation": "ここは〈匂い〉の意味。花の香りは『かぐ』もので、絵は見るものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41226, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は祖父の絵に大切に保管している。", "corrected_sentence": "父は祖父の絵を大切に保管している。", "error_description": "誤りは「絵に」。「保管する」の目的語は「を」で示すので、「に」ではなく「絵を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
