INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41228, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「気がする」の「が」。ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「気をする」は言わない。"}, {"text": "で", "is_correct": false, "explanation": "「気でする」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「気とする」は言わない。"}], "correct_answer": "が", "explanations": {"が": "「気がする」の「が」。ここに合う。", "を": "「気をする」は言わない。", "で": "「気でする」は成り立たない。", "と": "「気とする」は言わない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41228, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の心の動きや、感じ方のこと。", "primary_collocate": null, "pronunciation": "き", "ipa": "kʲi", "syllable_count": 1, "sentences": [{"text": "明日の面接を考えると、気が重いです。", "target_word": "気", "complexity_tier": "T3", "furigana": "明日[あした]の面接[めんせつ]を考[かんが]えると、気[き]が重[おも]いです。", "sentence_source": "generated"}, {"text": "行くつもりでしたが、雨が降ってきたので気が変わりました。", "target_word": "気", "complexity_tier": "T3", "furigana": "行[い]くつもりでしたが、雨[あめ]が降[ふ]ってきたので気[き]が変[か]わりました。", "sentence_source": "generated"}, {"text": "友だちに話したら、気が楽になりました。", "target_word": "気", "complexity_tier": "T3", "furigana": "友[とも]だちに話[はな]したら、気[き]が楽[らく]になりました。", "sentence_source": "generated"}, {"text": "今日は疲れていて、パーティーに行く気が進みません。", "target_word": "気", "complexity_tier": "T3", "furigana": "今日[きょう]は疲[つか]れていて、パーティーに行[い]く気[き]が進[すす]みません。", "sentence_source": "generated"}, {"text": "海をながめると、気が晴れます。", "target_word": "気", "complexity_tier": "T3", "furigana": "海[うみ]をながめると、気[き]が晴[は]れます。", "sentence_source": "generated"}, {"text": "兄は気が短いので、待たされるとすぐおこります。", "target_word": "気", "complexity_tier": "T3", "furigana": "兄[あに]は気[き]が短[みじか]いので、待[ま]たされるとすぐおこります。", "sentence_source": "generated"}, {"text": "彼とは気が合うので、何時間でも話せます。", "target_word": "気", "complexity_tier": "T3", "furigana": "彼[かれ]とは気[き]が合[あ]うので、何時間[なんじかん]でも話[はな]せます。", "sentence_source": "generated"}, {"text": "失敗したあとで、なんだか落ち着かない気がします。", "target_word": "気", "complexity_tier": "T3", "furigana": "失敗[しっぱい]したあとで、なんだか落[お]ち着[つ]かない気[き]がします。", "sentence_source": "generated"}, {"text": "試合の前は気が張って、よく眠れませんでした。", "target_word": "気", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]は気[き]が張[は]って、よく眠[ねむ]れませんでした。", "sentence_source": "generated"}, {"text": "祖母は気が弱くて、人にいやと言えません。", "target_word": "気", "complexity_tier": "T3", "furigana": "祖母[そぼ]は気[き]が弱[よわ]くて、人[ひと]にいやと言[い]えません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "気分や性格など、人の心の動きと感じ方を表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: contains vocabulary far above tier T1: ながめる (Zipf 1.71)']::text[], 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41228, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気", "is_correct": true, "explanation": "「気が重い」（気分が晴れない）の「気」。ここに合う。"}, {"text": "月", "is_correct": false, "explanation": "「月が重い」は気分の意味にならず、文に合わない。"}, {"text": "光", "is_correct": false, "explanation": "「光が重い」は成り立たない。"}, {"text": "力", "is_correct": false, "explanation": "「力が重い」は気分を表さず、文に合わない。"}], "explanations": {"気": "「気が重い」（気分が晴れない）の「気」。ここに合う。", "月": "「月が重い」は気分の意味にならず、文に合わない。", "光": "「光が重い」は成り立たない。", "力": "「力が重い」は気分を表さず、文に合わない。"}, "sentence_index": 0, "correct_answer": "気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この紅茶は気が豊かで、香りをかぐと落ち着く。", "explanation": "「香り」の語を入れ替えた文。「香りが豊か」は自然だが、「気が豊か」とは言わない。"}, {"text": "この店は気が明るくて、家族連れに人気がある。", "explanation": "「雰囲気」の語を入れ替えた文。「雰囲気が明るい」は自然だが、「気が明るい」とは言わない。"}, {"text": "彼は気が冷たくて、いつも話しかけにくい。", "explanation": "「態度」の語を入れ替えた文。「態度が冷たい」は自然だが、「気が冷たい」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41228, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気", "is_correct": true, "explanation": "「気が合う」の「気」。ここに合う。"}, {"text": "腰", "is_correct": false, "explanation": "「腰が合う」は言わない。相性の意味にならない。"}, {"text": "波", "is_correct": false, "explanation": "「波が合う」は不自然で、相性の意味にならない。"}, {"text": "足", "is_correct": false, "explanation": "「足が合う」は相性を表さず、文に合わない。"}], "explanations": {"気": "「気が合う」の「気」。ここに合う。", "腰": "「腰が合う」は言わない。相性の意味にならない。", "波": "「波が合う」は不自然で、相性の意味にならない。", "足": "「足が合う」は相性を表さず、文に合わない。"}, "sentence_index": 6, "correct_answer": "気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は気が実って、ついに試験に合格した。", "explanation": "「努力」の語を入れ替えた文。「努力が実る」は自然だが、「気が実る」とは言わない。"}, {"text": "この先生は気が正確で、聞き取りやすい。", "explanation": "「発音」の語を入れ替えた文。「発音が正確」は自然だが、「気が正確」とは言わない。"}, {"text": "彼の報告は気が詳しくて、資料に欠かせない。", "explanation": "「記述」の語を入れ替えた文。「記述が詳しい」は自然だが、「気が詳しい」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41228, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けると、気を晴れます。", "corrected_sentence": "窓を開けると、気が晴れます。", "error_description": "「晴れる」は自動詞なので「気が」で受ける。「気を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
