INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41229, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「気になる」の「に」。「気に＋なる」で、ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「気をなる」は不自然。「なる」は「に」で受ける。"}, {"text": "で", "is_correct": false, "explanation": "「気でなる」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「気となる」は「気になる」の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「気になる」の「に」。「気に＋なる」で、ここに合う。", "を": "「気をなる」は不自然。「なる」は「に」で受ける。", "で": "「気でなる」は成り立たない。", "と": "「気となる」は「気になる」の意味にならない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
