INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41229, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "注意や意識を向けること。「気をつける」「気になる」「気がつく」などで使う。", "primary_collocate": null, "pronunciation": "き", "ipa": "kʲi", "syllable_count": 1, "sentences": [{"text": "道がこんでいるので、車に気をつけてください。", "target_word": "気", "complexity_tier": "T3", "furigana": "道[みち]がこんでいるので、車[くるま]に気[き]をつけてください。", "sentence_source": "generated"}, {"text": "隣の部屋の音が気になって、勉強できません。", "target_word": "気", "complexity_tier": "T3", "furigana": "隣[となり]の部屋[へや]の音[おと]が気[き]になって、勉強[べんきょう]できません。", "sentence_source": "generated"}, {"text": "話しながら歩いていたので、信号が変わったことに気がつきませんでした。", "target_word": "気", "complexity_tier": "T3", "furigana": "話[はな]しながら歩[ある]いていたので、信号[しんごう]が変[か]わったことに気[き]がつきませんでした。", "sentence_source": "generated"}, {"text": "スマホを見ていると気が散って、宿題が進みません。", "target_word": "気", "complexity_tier": "T3", "furigana": "スマホを見[み]ていると気[き]が散[ち]って、宿題[しゅくだい]が進[すす]みません。", "sentence_source": "generated"}, {"text": "店員さんはお客さんの様子に気を配っています。", "target_word": "気", "complexity_tier": "T3", "furigana": "店員[てんいん]さんはお客[きゃく]さんの様子[ようす]に気[き]を配[くば]っています。", "sentence_source": "generated"}, {"text": "彼は本に気を取られて、駅を乗りすごしてしまいました。", "target_word": "気", "complexity_tier": "T3", "furigana": "彼[かれ]は本[ほん]に気[き]を取[と]られて、駅[えき]を乗[の]りすごしてしまいました。", "sentence_source": "generated"}, {"text": "試験の前は、風邪をひかないように気をつけています。", "target_word": "気", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は、風邪[かぜ]をひかないように気[き]をつけています。", "sentence_source": "generated"}, {"text": "忘れ物をしたことに気がついて、家へもどりました。", "target_word": "気", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]をしたことに気[き]がついて、家[いえ]へもどりました。", "sentence_source": "generated"}, {"text": "彼女は細かいところまで気がつくので、秘書に向いています。", "target_word": "気", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は細[こま]かいところまで気[き]がつくので、秘書[ひしょ]に向[む]いています。", "sentence_source": "generated"}, {"text": "急いでいたので、かぎをかけたかどうかが気になりました。", "target_word": "気", "complexity_tier": "T3", "furigana": "急[いそ]いでいたので、かぎをかけたかどうかが気[き]になりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "注意や意識の向け方としての心の働きを表す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5d009b0-9a2b-46b1-b29d-64697f5f3725') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41229, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気", "is_correct": true, "explanation": "「気をつける」の目的語。「注意する」の意味で、ここに合う。"}, {"text": "口", "is_correct": false, "explanation": "「口をつける」は飲む意味で、注意の意味にならない。"}, {"text": "声", "is_correct": false, "explanation": "「声をつける」は成り立たず、注意の意味にならない。"}, {"text": "足", "is_correct": false, "explanation": "「足をつける」は「車に足をつける」と続かず、注意の意味にならない。"}], "explanations": {"気": "「気をつける」の目的語。「注意する」の意味で、ここに合う。", "口": "「口をつける」は飲む意味で、注意の意味にならない。", "声": "「声をつける」は成り立たず、注意の意味にならない。", "足": "「足をつける」は「車に足をつける」と続かず、注意の意味にならない。"}, "sentence_index": 0, "correct_answer": "気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋の蓋を開けると、白い気が勢いよく立ちのぼった。", "explanation": "ここは〈湯気〉の意味。「気」が心の働きや注意を指すので、湯気の意味では使えない。"}, {"text": "このエンジンは気が故障して、動かなくなった。", "explanation": "ここは〈機械〉の意味の別の語「機」。「気」は心の働きを指すので、機械には使わない。"}, {"text": "彼は気が豊富で、どんな歴史の質問にも答えられる。", "explanation": "ここは〈知識〉の意味。「知識が豊富」とは言えても、「気が豊富」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41229, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気", "is_correct": true, "explanation": "「気をつける」の目的語。「注意する」の意味で、ここに合う。"}, {"text": "腹", "is_correct": false, "explanation": "「腹をつける」は言わない。注意の意味にならない。"}, {"text": "頭", "is_correct": false, "explanation": "「頭をつける」は注意の意味にならず、文に合わない。"}, {"text": "鼻", "is_correct": false, "explanation": "「鼻をつける」は不自然で、注意を表さない。"}], "explanations": {"気": "「気をつける」の目的語。「注意する」の意味で、ここに合う。", "腹": "「腹をつける」は言わない。注意の意味にならない。", "頭": "「頭をつける」は注意の意味にならず、文に合わない。", "鼻": "「鼻をつける」は不自然で、注意を表さない。"}, "sentence_index": 6, "correct_answer": "気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は気が鋭く、色のわずかな違いもすぐ見分ける。", "explanation": "「感性」の語を入れ替えた文。「感性が鋭い」とは言えても、「気が鋭い」とは言わない。"}, {"text": "この作家は気が豊かで、毎回斬新な企画を出す。", "explanation": "「発想」の語を入れ替えた文。「発想が豊か」は自然だが、「気が豊か」とは言わない。"}, {"text": "祖父は気が鮮明で、昔の出来事を細かく話してくれる。", "explanation": "「記憶」の語を入れ替えた文。「記憶が鮮明」は自然だが、「気が鮮明」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41229, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "スマホに気が取られて、駅を乗りすごしました。", "corrected_sentence": "スマホに気を取られて、駅を乗りすごしました。", "error_description": "「気を取られる」の目的語は「を」で示す。「が」に変えたのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41229, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、気をつけに運転してください。", "corrected_sentence": "雨の日は、気をつけて運転してください。", "error_description": "「気をつける」の連用形は「気をつけて」。「に」に変えると後ろの動詞に続かず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bad5028-fea7-4a05-b046-8c14601ff2f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41232, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「医療が進んで」の主語を示す「が」。正解。"}, {"text": "と", "is_correct": false, "explanation": "「医療と進んで」は並列の意味になり、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「医療の進んで」は文の形が崩れ、成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「医療より進んで」と続かず、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「医療が進んで」の主語を示す「が」。正解。", "と": "「医療と進んで」は並列の意味になり、文として成り立たない。", "の": "「医療の進んで」は文の形が崩れ、成り立たない。", "より": "比較の「より」は「医療より進んで」と続かず、意味が通らない。"}, "error_tags": {"と": "並列の誤り", "の": "連体修飾の誤り", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41232, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「必要とする」の目的語を示す「を」。正解。"}, {"text": "に", "is_correct": false, "explanation": "「医療に必要とする」は不自然で、目的語を示すには「を」が必要。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「医療で必要とする」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「必要とする」とつながらず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「必要とする」の目的語を示す「を」。正解。", "に": "「医療に必要とする」は不自然で、目的語を示すには「を」が必要。", "で": "手段の「で」では「医療で必要とする」は成り立たない。", "へ": "方向の「へ」は「必要とする」とつながらず、意味が通らない。"}, "error_tags": {"に": "格の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41232, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "けがや病気をなおすために、お医者さんがすることです。", "primary_collocate": null, "pronunciation": "いりょう", "ipa": "iɾʲoː", "syllable_count": 3, "sentences": [{"text": "医療を受けるために、おばあさんは毎週病院へ行きます。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]を受[う]けるために、おばあさんは毎週[まいしゅう]病院[びょういん]へ行[い]きます。", "sentence_source": "generated"}, {"text": "医療が進んで、治る病気は増えました。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]が進[すす]んで、治[なお]る病気[びょうき]は増[ふ]えました。", "sentence_source": "generated"}, {"text": "この島には医療をする人が少なくて、みんな困っています。", "target_word": "医療", "complexity_tier": "T3", "furigana": "この島[しま]には医療[いりょう]をする人[ひと]が少[すく]なくて、みんな困[こま]っています。", "sentence_source": "generated"}, {"text": "医療の仕事は、人の命を守る大切な仕事です。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]の仕事[しごと]は、人[ひと]の命[いのち]を守[まも]る大切[たいせつ]な仕事[しごと]です。", "sentence_source": "generated"}, {"text": "戦争が起きた地域では、医療が足りなくて苦しむ人が多い。", "target_word": "医療", "complexity_tier": "T3", "furigana": "戦争[せんそう]が起[お]きた地域[ちいき]では、医療[いりょう]が足[た]りなくて苦[くる]しむ人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "兄は医療の勉強をして、看護師になりました。", "target_word": "医療", "complexity_tier": "T3", "furigana": "兄[あに]は医療[いりょう]の勉強[べんきょう]をして、看護師[かんごし]になりました。", "sentence_source": "generated"}, {"text": "新しい医療の機械が、病院に届きました。", "target_word": "医療", "complexity_tier": "T3", "furigana": "新[あたら]しい医療[いりょう]の機械[きかい]が、病院[びょういん]に届[とど]きました。", "sentence_source": "generated"}, {"text": "医療を必要とする子どもたちのために、募金した。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]を必要[ひつよう]とする子[こ]どもたちのために、募金[ぼきん]した。", "sentence_source": "generated"}, {"text": "外国に住むときは、その国の医療について調べておくと安心だ。", "target_word": "医療", "complexity_tier": "T3", "furigana": "外国[がいこく]に住[す]むときは、その国[くに]の医療[いりょう]について調[しら]べておくと安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "山の上の村にも、医療のチームが来てくれました。", "target_word": "医療", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]の村[むら]にも、医療[いりょう]のチームが来[き]てくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "医療", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "けがや病気を治すために医者が行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41232, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医療", "is_correct": true, "explanation": "治療の意味で「医療を受ける」と言え、病院へ通う文脈に合う。正解。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を受ける」は成り立たず、文脈にも合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖を受ける」は成り立たず、文脈にも合わない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓を受ける」は成り立たず、文脈にも合わない。"}], "explanations": {"医療": "治療の意味で「医療を受ける」と言え、病院へ通う文脈に合う。正解。", "天気": "「天気を受ける」は成り立たず、文脈にも合わない。", "砂糖": "「砂糖を受ける」は成り立たず、文脈にも合わない。", "窓": "「窓を受ける」は成り立たず、文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "医療"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ダイエットを続けたら、医療が三キロ減った。", "explanation": "ここは〈体重〉の意味。医療は治療のことで、重さが減るものではないので合わない。"}, {"text": "あの医療は、患者の話をよく聞いてくれる。", "explanation": "ここは〈医者〉（人）の意味。医療は人ではないので、『話を聞いてくれる』とは合わない。"}, {"text": "明日は、朝から医療が晴れるでしょう。", "explanation": "ここは〈天気〉の意味。医療は治療のことで、空のように晴れたり曇ったりするものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41232, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医療", "is_correct": true, "explanation": "治療の意味で、新しい医療の機械という名詞句として自然。正解。"}, {"text": "給料", "is_correct": false, "explanation": "お金の意味で、機械を修飾する語として成り立たない。"}, {"text": "靴", "is_correct": false, "explanation": "履物で、医療の機械を修飾する語として成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "植物で、病院に届く医療の機械という文脈に合わない。"}], "explanations": {"医療": "治療の意味で、新しい医療の機械という名詞句として自然。正解。", "給料": "お金の意味で、機械を修飾する語として成り立たない。", "靴": "履物で、医療の機械を修飾する語として成り立たない。", "花": "植物で、病院に届く医療の機械という文脈に合わない。"}, "sentence_index": 6, "correct_answer": "医療"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喉がはれて、熱とともに医療が出た。", "explanation": "ここは〈症状〉の意味。医療は治療のことで、喉のはれや熱のように体に出てくる変化を指さないので合わない。"}, {"text": "医療の机の上に、資料が積んであった。", "explanation": "ここは〈医局〉（医者の部屋）の意味。医療は部屋や家具ではないので、机の置かれる場所にはならない。"}, {"text": "熱を計ると、医療が三十八度と表示された。", "explanation": "ここは〈体温〉の意味。医療は治療のことで、温度を表示するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41232, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族が医療に必要としたとき、すぐに連絡しました。", "corrected_sentence": "家族が医療を必要としたとき、すぐに連絡しました。", "error_description": "「必要とする」の目的語は「を」で示す。「医療に必要とした」は誤りで、正しくは「医療を必要とした」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41232, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域では、医療を必要にする高齢者が増えている。", "corrected_sentence": "この地域では、医療を必要とする高齢者が増えている。", "error_description": "「医療」と結びつく動詞は「必要とする」。「必要にする」は誤った組み合わせで、正しくは「必要とする」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41233, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「医療にかかる（費用がかかる）」の結びつきで「に」が付く。正解。"}, {"text": "が", "is_correct": false, "explanation": "「医療がかかる」は費用がかかる意味の文型にならず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「医療とかかる」は文として成り立たず、並列の意味にもならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「かかる」とつながらず、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「医療にかかる（費用がかかる）」の結びつきで「に」が付く。正解。", "が": "「医療がかかる」は費用がかかる意味の文型にならず、不自然。", "と": "「医療とかかる」は文として成り立たず、並列の意味にもならない。", "へ": "方向を表す「へ」は「かかる」とつながらず、意味が通らない。"}, "error_tags": {"が": "主語・格の誤り", "と": "並列・引用の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41233, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「受ける」の目的語を示す「を」。正解。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」だと「医療で受ける」は不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「医療の受ける」は文の形が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「医療より受ける」と続かず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「受ける」の目的語を示す「を」。正解。", "で": "手段の「で」だと「医療で受ける」は不自然になる。", "の": "「医療の受ける」は文の形が成り立たない。", "より": "比較の「より」は「医療より受ける」と続かず、意味が通らない。"}, "error_tags": {"で": "手段の誤り", "の": "連体修飾の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41233, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "病気やけがを治療すること。また、そのための技術や活動。", "primary_collocate": null, "pronunciation": "いりょう", "ipa": "iɾʲoː", "syllable_count": 3, "sentences": [{"text": "お医者さんが、病気の人の体に、他の人の体の一部を入れる医療の手順があります。", "target_word": "医療", "complexity_tier": "T3", "furigana": "お医者[いしゃ]さんが、病気[びょうき]の人[ひと]の体[からだ]に、他[ほか]の人[ひと]の体[からだ]の一部[いちぶ]を入[い]れる医療[いりょう]の手順[てじゅん]があります。", "sentence_source": "mined"}, {"text": "この国では、医療にかかるお金が高くなっています。", "target_word": "医療", "complexity_tier": "T3", "furigana": "この国[くに]では、医療[いりょう]にかかるお金[かね]が高[たか]くなっています。", "sentence_source": "generated"}, {"text": "山の小さな村には、医療を受けられる病院が少ない。", "target_word": "医療", "complexity_tier": "T3", "furigana": "山[やま]の小[ちい]さな村[むら]には、医療[いりょう]を受[う]けられる病院[びょういん]が少[すく]ない。", "sentence_source": "generated"}, {"text": "医療の技術が進んだので、昔は治せなかった病気も治せるようになった。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]の技術[ぎじゅつ]が進[すす]んだので、昔[むかし]は治[なお]せなかった病気[びょうき]も治[なお]せるようになった。", "sentence_source": "generated"}, {"text": "彼女は医療の仕事をするために、大学で勉強しています。", "target_word": "医療", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は医療[いりょう]の仕事[しごと]をするために、大学[だいがく]で勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "地震のあと、医療を必要とする人がたくさんいた。", "target_word": "医療", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、医療[いりょう]を必要[ひつよう]とする人[ひと]がたくさんいた。", "sentence_source": "generated"}, {"text": "医療が発達したおかげで、人々は長生きできるようになった。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]が発達[はったつ]したおかげで、人々[ひとびと]は長生[ながい]きできるようになった。", "sentence_source": "generated"}, {"text": "外国で医療を受けると、費用が日本よりずっと高いことがある。", "target_word": "医療", "complexity_tier": "T3", "furigana": "外国[がいこく]で医療[いりょう]を受[う]けると、費用[ひよう]が日本[にほん]よりずっと高[たか]いことがある。", "sentence_source": "generated"}, {"text": "医療の現場では、毎日たくさんの人が働いています。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]の現場[げんば]では、毎日[まいにち]たくさんの人[ひと]が働[はたら]いています。", "sentence_source": "generated"}, {"text": "医療のニュースを見て、将来は医者になりたいと思った。", "target_word": "医療", "complexity_tier": "T3", "furigana": "医療[いりょう]のニュースを見[み]て、将来[しょうらい]は医者[いしゃ]になりたいと思[おも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "医療", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "病気やけがを治すための技術・活動としての医療", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41233, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医療", "is_correct": true, "explanation": "病気やけがの治療の意味で、体に他人の組織を入れる医療行為の手順として自然に合う。"}, {"text": "交通", "is_correct": false, "explanation": "移動や交通機関の意味で、体の中に入れる手順の対象にならない。"}, {"text": "給料", "is_correct": false, "explanation": "お金の意味で、体に入れる手順の名詞としては成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の意味で、体に入れる手順とは結びつかない。"}], "explanations": {"医療": "病気やけがの治療の意味で、体に他人の組織を入れる医療行為の手順として自然に合う。", "交通": "移動や交通機関の意味で、体の中に入れる手順の対象にならない。", "給料": "お金の意味で、体に入れる手順の名詞としては成り立たない。", "天気": "気象の意味で、体に入れる手順とは結びつかない。"}, "sentence_index": 0, "correct_answer": "医療"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は医療が混むので、午前中に行くことにした。", "explanation": "ここは〈病院〉の意味。医療は治療の行為を指すので、場所のように『混む』とは言わないため合わない。"}, {"text": "あの医療は話が丁寧で、患者に人気がある。", "explanation": "ここは〈医者〉（人）の意味。医療は行為であって人ではないので、『話が丁寧』とは合わない。"}, {"text": "風邪をひいたので、医療を買いに薬局へ行った。", "explanation": "ここは〈薬〉の意味。医療は治療の行為で商品ではないので、薬局で買えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41233, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医療", "is_correct": true, "explanation": "治療の技術や活動の意味で、発達するものとして自然に合う。正解。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品で、発達して人々の寿命を延ばすものとしては成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "建具で、発達して人々が長生きできるようになる、という文脈に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "履物で、長寿との結びつきが成り立たない。"}], "explanations": {"医療": "治療の技術や活動の意味で、発達するものとして自然に合う。正解。", "砂糖": "食品で、発達して人々の寿命を延ばすものとしては成り立たない。", "窓": "建具で、発達して人々が長生きできるようになる、という文脈に合わない。", "靴": "履物で、長寿との結びつきが成り立たない。"}, "sentence_index": 6, "correct_answer": "医療"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱とせきという医療が三日間続いた。", "explanation": "ここは〈症状〉の意味。医療は治療のことで、熱やせきのような体の状態を指さないので、『続く』とは言わない。"}, {"text": "昼休みに医療に寄って、先輩と話した。", "explanation": "ここは〈医局〉（医者の部屋）の意味。医療は場所ではないので、『寄る』とは言わない。"}, {"text": "朝に熱を測ったら、医療が三十八度あった。", "explanation": "ここは〈体温〉の意味。医療は治療のことで、体の温度を表す語としては使わないので、『三十八度ある』とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41233, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は医療に受けるため、毎週病院へ通っています。", "corrected_sentence": "祖母は医療を受けるため、毎週病院へ通っています。", "error_description": "「受ける」の目的語は「を」で示す。「医療に受ける」は誤りで、正しくは「医療を受ける」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41233, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町の病院では、医療を受けれる日が決まっている。", "corrected_sentence": "この町の病院では、医療を受けられる日が決まっている。", "error_description": "「受けれる」はら抜き言葉で、標準的な形は「受けられる」。活用の形が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41234, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「病気のとき」と続く連体修飾の「の」。正解。"}, {"text": "が", "is_correct": false, "explanation": "「病気がとき」は成り立たず、文の形が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「病気へとき」は不自然で、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「病気とき」は助詞として不適当で、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「病気のとき」と続く連体修飾の「の」。正解。", "が": "「病気がとき」は成り立たず、文の形が崩れる。", "へ": "方向の「へ」では「病気へとき」は不自然で、意味が通らない。", "と": "「病気とき」は助詞として不適当で、文が成り立たない。"}, "error_tags": {"が": "主語の誤り", "へ": "方向の誤り", "と": "並列の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "類語辞典でも「病気」の対義語とされ、からだの具合が悪い状態の反対。正解。"}, {"text": "会議", "is_correct": false, "explanation": "仕事の集まりの意味で、病気の対義語ではない。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かす行為の意味で、病気の対義語ではない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う品物の意味で、病気と対義の関係にはない。"}], "correct_answer": "健康", "explanations": {"健康": "類語辞典でも「病気」の対義語とされ、からだの具合が悪い状態の反対。正解。", "会議": "仕事の集まりの意味で、病気の対義語ではない。", "運動": "体を動かす行為の意味で、病気の対義語ではない。", "切手": "郵便に使う品物の意味で、病気と対義の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41234, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「病気をする」の目的語を示す「を」。正解。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「病気へしたことがない」は成り立たず、文が崩れる。"}, {"text": "が", "is_correct": false, "explanation": "「病気がしたことがない」は主語と動詞が合わず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「病気からしたこと」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「病気をする」の目的語を示す「を」。正解。", "へ": "方向の「へ」では「病気へしたことがない」は成り立たず、文が崩れる。", "が": "「病気がしたことがない」は主語と動詞が合わず、不自然。", "から": "起点の「から」では「病気からしたこと」は成り立たない。"}, "error_tags": {"へ": "方向の誤り", "が": "主語の誤り", "から": "起点の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "類語辞典でも「病気」の対義語とされ、からだの具合が悪い状態の反対。正解。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を知る道具の意味で、病気の対義語ではない。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具の意味で、病気と対義の関係にはない。"}, {"text": "机", "is_correct": false, "explanation": "家具の意味で、病気の対義語ではない。"}], "correct_answer": "健康", "explanations": {"健康": "類語辞典でも「病気」の対義語とされ、からだの具合が悪い状態の反対。正解。", "時計": "時刻を知る道具の意味で、病気の対義語ではない。", "鍋": "調理器具の意味で、病気と対義の関係にはない。", "机": "家具の意味で、病気の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41234, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "からだのぐあいがわるいことです。", "primary_collocate": null, "pronunciation": "びょうき", "ipa": "bʲoːki", "syllable_count": 3, "sentences": [{"text": "弟は病気で、今日は学校を休みました。", "target_word": "病気", "complexity_tier": "T3", "furigana": "弟[おとうと]は病気[びょうき]で、今日[きょう]は学校[がっこう]を休[やす]みました。", "sentence_source": "generated"}, {"text": "病気のとき、母がおかゆを作ってくれました。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]のとき、母[はは]がおかゆを作[つく]ってくれました。", "sentence_source": "generated"}, {"text": "病気になったら、早く病院へ行ったほうがいいです。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]になったら、早[はや]く病院[びょういん]へ行[い]ったほうがいいです。", "sentence_source": "generated"}, {"text": "病気が治って、やっと外で遊べるようになりました。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]が治[なお]って、やっと外[そと]で遊[あそ]べるようになりました。", "sentence_source": "generated"}, {"text": "友だちが病気だと聞いて、お見舞いに行きました。", "target_word": "病気", "complexity_tier": "T3", "furigana": "友[とも]だちが病気[びょうき]だと聞[き]いて、お見舞[みま]いに行[い]きました。", "sentence_source": "generated"}, {"text": "犬が病気になって、とても心配しました。", "target_word": "病気", "complexity_tier": "T3", "furigana": "犬[いぬ]が病気[びょうき]になって、とても心配[しんぱい]しました。", "sentence_source": "generated"}, {"text": "病気の人は、ゆっくり休むことが大切です。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]の人[ひと]は、ゆっくり休[やす]むことが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "私は病気をしたことがないので、入院の経験はありません。", "target_word": "病気", "complexity_tier": "T3", "furigana": "私[わたし]は病気[びょうき]をしたことがないので、入院[にゅういん]の経験[けいけん]はありません。", "sentence_source": "generated"}, {"text": "病気で寝ている間、ずっと本を読んでいた。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]で寝[ね]ている間[あいだ]、ずっと本[ほん]を読[よ]んでいた。", "sentence_source": "generated"}, {"text": "病気にならないように、毎日手を洗います。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]にならないように、毎日[まいにち]手[て]を洗[あら]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "病気", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "からだの具合が悪いこと、身近な病気の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41234, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病気", "is_correct": true, "explanation": "からだの具合が悪いことの意味で、弟が学校を休む理由として自然。正解。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品の意味で、「砂糖で休む」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "建具の意味で、学校を休む理由として成り立たない。"}, {"text": "靴", "is_correct": false, "explanation": "履物の意味で、学校を休む理由として成り立たない。"}], "explanations": {"病気": "からだの具合が悪いことの意味で、弟が学校を休む理由として自然。正解。", "砂糖": "食品の意味で、「砂糖で休む」は成り立たない。", "窓": "建具の意味で、学校を休む理由として成り立たない。", "靴": "履物の意味で、学校を休む理由として成り立たない。"}, "sentence_index": 0, "correct_answer": "病気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ダイエットを続けたら、病気が三キロ増えた。", "explanation": "ここは〈体重〉の意味。病気は体の調子を表す語で、重さとして増えることはないので合わない。"}, {"text": "春になって、庭の病気がいっせいに咲いた。", "explanation": "ここは〈花〉の意味。病気は状態を表す語で、庭で咲くものではないので合わない。"}, {"text": "授業のあと、病気を開いて、テストの範囲を確認した。", "explanation": "ここは〈教科書〉の意味。病気は本ではないので、開いて中身を読むものではなく合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41234, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病気", "is_correct": true, "explanation": "からだの具合が悪いことの意味で、病気の人は休むべきという文脈に合う。正解。"}, {"text": "給料", "is_correct": false, "explanation": "お金の意味で、「給料の人」という表現は成り立たない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物の意味で、「電車の人」という表現は成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "植物の意味で、「花の人」という表現は成り立たない。"}], "explanations": {"病気": "からだの具合が悪いことの意味で、病気の人は休むべきという文脈に合う。正解。", "給料": "お金の意味で、「給料の人」という表現は成り立たない。", "電車": "乗り物の意味で、「電車の人」という表現は成り立たない。", "花": "植物の意味で、「花の人」という表現は成り立たない。"}, "sentence_index": 6, "correct_answer": "病気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "看護師は、病気を待合室に呼んで、名前を確認した。", "explanation": "ここは〈患者〉（病人）の意味。病気は状態を表す語で、人として呼んだり名前を確認したりするものではないので合わない。"}, {"text": "脇に挟んだ計器を見ると、病気が三十八度を指していた。", "explanation": "ここは〈体温〉の意味。病気は状態を表す語で、温度を指すものではないので合わない。"}, {"text": "病気の廊下は、静かで涼しかった。", "explanation": "ここは〈病棟〉（入院病室のある区域）の意味。病気は建物の一部ではないので、廊下を持つものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41234, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱が下がって、病気がすっかり治れました。", "corrected_sentence": "熱が下がって、病気がすっかり治りました。", "error_description": "「治る」の活用が誤っている。過去の丁寧形は「治りました」で、「治れました」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41234, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体が弱いと、病気をかかりやすくなります。", "corrected_sentence": "体が弱いと、病気にかかりやすくなります。", "error_description": "「病気にかかる」の助詞は「に」で示す。「病気をかかる」は誤りで、正しくは「病気にかかる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41235, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「治す」の目的語を示す「を」。正解。"}, {"text": "が", "is_correct": false, "explanation": "「病気が治すために」は主語と動詞が合わず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「病気と治すために」は並列の意味にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「病気で治すために」は不自然で、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「治す」の目的語を示す「を」。正解。", "が": "「病気が治すために」は主語と動詞が合わず、成り立たない。", "と": "「病気と治すために」は並列の意味にならず、文が成り立たない。", "で": "手段の「で」では「病気で治すために」は不自然で、意味が通らない。"}, "error_tags": {"が": "主語の誤り", "と": "並列の誤り", "で": "手段の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "類語辞典でも「病気」の対義語とされ、体の調子が悪い状態の反対。正解。"}, {"text": "会議", "is_correct": false, "explanation": "仕事の集まりの意味で、病気の対義語ではない。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かす行為の意味で、病気の対義語ではない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物の意味で、病気と対義の関係にはない。"}], "correct_answer": "健康", "explanations": {"健康": "類語辞典でも「病気」の対義語とされ、体の調子が悪い状態の反対。正解。", "会議": "仕事の集まりの意味で、病気の対義語ではない。", "運動": "体を動かす行為の意味で、病気の対義語ではない。", "電車": "乗り物の意味で、病気と対義の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41235, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「心配する」の目的語を示す「を」。正解。"}, {"text": "に", "is_correct": false, "explanation": "「病気に心配して」は目的語を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「心配して」とつながらず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では「病気から心配して」は不自然で、成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「心配する」の目的語を示す「を」。正解。", "に": "「病気に心配して」は目的語を示せず、不自然。", "へ": "方向の「へ」は「心配して」とつながらず、意味が通らない。", "から": "起点の「から」では「病気から心配して」は不自然で、成り立たない。"}, "error_tags": {"に": "格の誤り", "へ": "方向の誤り", "から": "起点の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "類語辞典でも「病気」の対義語とされ、体の具合が悪い状態の反対。正解。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う品物の意味で、病気の対義語ではない。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を知る道具の意味で、病気と対義の関係にはない。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具の意味で、病気の対義語ではない。"}], "correct_answer": "健康", "explanations": {"健康": "類語辞典でも「病気」の対義語とされ、体の具合が悪い状態の反対。正解。", "切手": "郵便に使う品物の意味で、病気の対義語ではない。", "時計": "時刻を知る道具の意味で、病気と対義の関係にはない。", "鍋": "調理器具の意味で、病気の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41235, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体の調子が悪くなり、健康でなくなること。疾患。", "primary_collocate": null, "pronunciation": "びょうき", "ipa": "bʲoːki", "syllable_count": 3, "sentences": [{"text": "お医者さんが、病気の人の体に、他の人の体の一部を入れる医療の手順があります。", "target_word": "病気", "complexity_tier": "T3", "furigana": "お医者[いしゃ]さんが、病気[びょうき]の人[ひと]の体[からだ]に、他[ほか]の人[ひと]の体[からだ]の一部[いちぶ]を入[い]れる医療[いりょう]の手順[てじゅん]があります。", "sentence_source": "mined"}, {"text": "病気を治すために、他の人が臓器を提供します。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]を治[なお]すために、他[ほか]の人[ひと]が臓器[ぞうき]を提供[ていきょう]します。", "sentence_source": "generated"}, {"text": "彼は重い病気にかかって、半年間入院した。", "target_word": "病気", "complexity_tier": "T3", "furigana": "彼[かれ]は重[おも]い病気[びょうき]にかかって、半年間[はんとしかん]入院[にゅういん]した。", "sentence_source": "generated"}, {"text": "病気が治るまで、無理に仕事をしてはいけません。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]が治[なお]るまで、無理[むり]に仕事[しごと]をしてはいけません。", "sentence_source": "generated"}, {"text": "この病気は、早く見つければ薬で治すことができる。", "target_word": "病気", "complexity_tier": "T3", "furigana": "この病気[びょうき]は、早[はや]く見[み]つければ薬[くすり]で治[なお]すことができる。", "sentence_source": "generated"}, {"text": "病気のため、今日の会議は休ませていただきます。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]のため、今日[きょう]の会議[かいぎ]は休[やす]ませていただきます。", "sentence_source": "generated"}, {"text": "祖父は長い病気のあと、静かに亡くなった。", "target_word": "病気", "complexity_tier": "T3", "furigana": "祖父[そふ]は長[なが]い病気[びょうき]のあと、静[しず]かに亡[な]くなった。", "sentence_source": "generated"}, {"text": "子どもの病気を心配して、母は一晩中眠れなかった。", "target_word": "病気", "complexity_tier": "T3", "furigana": "子[こ]どもの病気[びょうき]を心配[しんぱい]して、母[はは]は一晩中[ひとばんじゅう]眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "運動と食事に気をつければ、多くの病気は防げると言われている。", "target_word": "病気", "complexity_tier": "T3", "furigana": "運動[うんどう]と食事[しょくじ]に気[き]をつければ、多[おお]くの病気[びょうき]は防[ふせ]げると言[い]われている。", "sentence_source": "generated"}, {"text": "病気の原因がわからなくて、医者は検査を続けた。", "target_word": "病気", "complexity_tier": "T3", "furigana": "病気[びょうき]の原因[げんいん]がわからなくて、医者[いしゃ]は検査[けんさ]を続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "病気", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "体の健康が損なわれた状態、疾患としての病気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41235, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病気", "is_correct": true, "explanation": "体の調子が悪くなる疾患の意味で、病気の人という文脈に合う。正解。"}, {"text": "天気", "is_correct": false, "explanation": "気象の意味で、体に他人の組織を入れる人の文脈には合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品で、「砂糖の人」という表現は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "建具で、「窓の人」という表現は成り立たず、文脈にも合わない。"}], "explanations": {"病気": "体の調子が悪くなる疾患の意味で、病気の人という文脈に合う。正解。", "天気": "気象の意味で、体に他人の組織を入れる人の文脈には合わない。", "砂糖": "食品で、「砂糖の人」という表現は成り立たない。", "窓": "建具で、「窓の人」という表現は成り立たず、文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "病気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ダイエットを続けたら、病気が三キロ減った。", "explanation": "ここは〈体重〉の意味。病気は体の調子を表す語で、重さとして減ることはないので合わない。"}, {"text": "あの病気は、患者の話を最後まで聞く。", "explanation": "ここは〈医者〉（人）の意味。病気は人ではないので、話を聞くという行為の主語にならない。"}, {"text": "明日は、朝から病気が晴れるでしょう。", "explanation": "ここは〈天気〉の意味。病気は状態を表す語で、空のように晴れることはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41235, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病気", "is_correct": true, "explanation": "長く患った病の意味で、祖父の闘病を示す文脈に合う。正解。"}, {"text": "給料", "is_correct": false, "explanation": "お金の意味で、「長い給料のあと」は成り立たない。"}, {"text": "靴", "is_correct": false, "explanation": "履物で、「長い靴のあと」は成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "植物で、「長い花のあと」は文脈に合わない。"}], "explanations": {"病気": "長く患った病の意味で、祖父の闘病を示す文脈に合う。正解。", "給料": "お金の意味で、「長い給料のあと」は成り立たない。", "靴": "履物で、「長い靴のあと」は成り立たない。", "花": "植物で、「長い花のあと」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "病気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、病気を診察室に呼んで、毎朝熱を測った。", "explanation": "ここは〈患者〉（病人）の意味。病気は状態を表す語で、人として呼んだり熱を測ったりするものではないので合わない。"}, {"text": "朝に熱を測ったら、病気が三十八度あった。", "explanation": "ここは〈体温〉の意味。病気は状態を表す語で、度数を持つものではないので合わない。"}, {"text": "病気は、味がうすいけれど体にいい。", "explanation": "ここは〈病院食〉の意味。病気は食事ではないので、味の評価の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41235, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "かぜの病気に防ぐために、毎朝うがいをしています。", "corrected_sentence": "かぜの病気を防ぐために、毎朝うがいをしています。", "error_description": "「防ぐ」の目的語は「を」で示す。「病気に防ぐ」は誤りで、正しくは「病気を防ぐ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41235, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "規則正しい生活を送れば、病気を守れます。", "corrected_sentence": "規則正しい生活を送れば、病気を防げます。", "error_description": "「病気」と結びつく動詞は「防ぐ」。「守る」は健康や体を目的語にするため、「病気を守る」は誤りで、正しくは「病気を防ぐ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
