INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41236, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、決まったやり方の順番です。", "primary_collocate": null, "pronunciation": "てじゅん", "ipa": "teʑɯɴ", "syllable_count": 3, "sentences": [{"text": "手順を見ながら、ゆっくりおりがみを折りました。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]を見[み]ながら、ゆっくりおりがみを折[お]りました。", "sentence_source": "generated"}, {"text": "料理の手順は、まず野菜を洗うことから始まります。", "target_word": "手順", "complexity_tier": "T3", "furigana": "料理[りょうり]の手順[てじゅん]は、まず野菜[やさい]を洗[あら]うことから始[はじ]まります。", "sentence_source": "generated"}, {"text": "手順が分からないときは、先生に聞いてください。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]が分[わ]からないときは、先生[せんせい]に聞[き]いてください。", "sentence_source": "generated"}, {"text": "このゲームの手順は、とても簡単です。", "target_word": "手順", "complexity_tier": "T3", "furigana": "このゲームの手順[てじゅん]は、とても簡単[かんたん]です。", "sentence_source": "generated"}, {"text": "手順を守らないと、うまくできません。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]を守[まも]らないと、うまくできません。", "sentence_source": "generated"}, {"text": "母は手順を考えてから、夕ごはんを作った。", "target_word": "手順", "complexity_tier": "T3", "furigana": "母[はは]は手順[てじゅん]を考[かんが]えてから、夕[ゆう]ごはんを作[つく]った。", "sentence_source": "generated"}, {"text": "手順を書いた紙を、壁にはっておきます。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]を書[か]いた紙[かみ]を、壁[かべ]にはっておきます。", "sentence_source": "generated"}, {"text": "手順どおりにやったのに、失敗してしまった。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]どおりにやったのに、失敗[しっぱい]してしまった。", "sentence_source": "generated"}, {"text": "薬を飲む手順を、お医者さんが教えてくれた。", "target_word": "手順", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]む手順[てじゅん]を、お医者[いしゃ]さんが教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "手順を一つ忘れて、最初からやり直した。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]を一[ひと]つ忘[わす]れて、最初[さいしょ]からやり直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手順", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かをするときの決まったやり方の順番", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 夕ごはん (Zipf 1.84)']::text[], '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41236, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手順", "is_correct": true, "explanation": "正解。「手順を見る」は作り方の順番を見る意味で、折り紙の文脈に合う。"}, {"text": "利息", "is_correct": false, "explanation": "利息は借りた金額への対価で、折り紙の作業を見る対象にならない。"}, {"text": "時差", "is_correct": false, "explanation": "時差は地域の時刻のずれで、作業を見ながら折る文脈では成り立たない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は髪の乱れで、折り紙を見ながら折る文脈では意味が通らない。"}], "explanations": {"手順": "正解。「手順を見る」は作り方の順番を見る意味で、折り紙の文脈に合う。", "利息": "利息は借りた金額への対価で、折り紙の作業を見る対象にならない。", "時差": "時差は地域の時刻のずれで、作業を見ながら折る文脈では成り立たない。", "寝癖": "寝癖は髪の乱れで、折り紙を見ながら折る文脈では意味が通らない。"}, "sentence_index": 0, "correct_answer": "手順"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓口で手順を待った。", "explanation": "ここは〈順番〉の意味。窓口で待つ列の番を指すので、作業の進め方の手順とは言わない。"}, {"text": "チームで自分の手順を果たした。", "explanation": "ここは〈役割〉の意味。担う任務を果たす言い方で、手順は果たす対象にならない。"}, {"text": "チームは手順を達成した。", "explanation": "ここは〈目標〉の意味。達成するのは目的で、やり方の順序である手順は達成の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41236, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手順", "is_correct": true, "explanation": "正解。「手順を書いた紙」は作業の順番を書いた紙で、文脈に合う。"}, {"text": "腹痛", "is_correct": false, "explanation": "腹痛は体の痛みで、紙に書いて壁にはる内容としては成り立たない。"}, {"text": "鼻水", "is_correct": false, "explanation": "鼻水は体から出る液体で、紙に書く対象として意味が通らない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は寝過ごすことで、紙に書いて壁にはる対象にならない。"}], "explanations": {"手順": "正解。「手順を書いた紙」は作業の順番を書いた紙で、文脈に合う。", "腹痛": "腹痛は体の痛みで、紙に書いて壁にはる内容としては成り立たない。", "鼻水": "鼻水は体から出る液体で、紙に書く対象として意味が通らない。", "寝坊": "寝坊は寝過ごすことで、紙に書いて壁にはる対象にならない。"}, "sentence_index": 6, "correct_answer": "手順"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "オーブンの手順を上げた。", "explanation": "ここは〈温度〉の意味。上げられるのは温度や数値で、手順は上げる対象にならない。"}, {"text": "味の手順が鋭い。", "explanation": "ここは〈感覚〉の意味。鋭いと言えるのは感覚で、やり方の順序である手順には合わない。"}, {"text": "明日の手順を予報する。", "explanation": "ここは〈天気〉の意味。予報するのは天候で、手順は予測の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41236, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手順へ確認しながら、ゆっくり組み立てましょう。", "corrected_sentence": "手順を確認しながら、ゆっくり組み立てましょう。", "error_description": "「確認する」の対象は「を」。「手順へ」の「へ」は誤りで、「手順を確認する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
