INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41237, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事をするための段階的な方法や順序。", "primary_collocate": null, "pronunciation": "てじゅん", "ipa": "teʑɯɴ", "syllable_count": 3, "sentences": [{"text": "お医者さんが、病気の人の体に、他の人の体の一部を入れる医療の手順があります。", "target_word": "手順", "complexity_tier": "T3", "furigana": "お医者[いしゃ]さんが、病気[びょうき]の人[ひと]の体[からだ]に、他[ほか]の人[ひと]の体[からだ]の一部[いちぶ]を入[い]れる医療[いりょう]の手順[てじゅん]があります。", "sentence_source": "mined"}, {"text": "機械を使う前に、手順を説明書でよく確認してください。", "target_word": "手順", "complexity_tier": "T3", "furigana": "機械[きかい]を使[つか]う前[まえ]に、手順[てじゅん]を説明書[せつめいしょ]でよく確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "手順どおりに作れば、初心者でも失敗しません。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]どおりに作[つく]れば、初心者[しょしんしゃ]でも失敗[しっぱい]しません。", "sentence_source": "generated"}, {"text": "料理の手順を間違えたので、ケーキがふくらまなかった。", "target_word": "手順", "complexity_tier": "T3", "furigana": "料理[りょうり]の手順[てじゅん]を間違[まちが]えたので、ケーキがふくらまなかった。", "sentence_source": "generated"}, {"text": "新しい社員に、書類を出す手順を教えた。", "target_word": "手順", "complexity_tier": "T3", "furigana": "新[あたら]しい社員[しゃいん]に、書類[しょるい]を出[だ]す手順[てじゅん]を教[おし]えた。", "sentence_source": "generated"}, {"text": "手順が多すぎて、全部覚えるのに時間がかかった。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]が多[おお]すぎて、全部[ぜんぶ]覚[おぼ]えるのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "手順を省くと、事故が起きる危険がある。", "target_word": "手順", "complexity_tier": "T3", "furigana": "手順[てじゅん]を省[はぶ]くと、事故[じこ]が起[お]きる危険[きけん]がある。", "sentence_source": "generated"}, {"text": "実験の手順は、先生がホワイトボードに書いてくれた。", "target_word": "手順", "complexity_tier": "T3", "furigana": "実験[じっけん]の手順[てじゅん]は、先生[せんせい]がホワイトボードに書[か]いてくれた。", "sentence_source": "generated"}, {"text": "パスワードを変える手順は、画面に順番に出てきます。", "target_word": "手順", "complexity_tier": "T3", "furigana": "パスワードを変[か]える手順[てじゅん]は、画面[がめん]に順番[じゅんばん]に出[で]てきます。", "sentence_source": "generated"}, {"text": "彼は手順を無視して作業を進めたため、上司に注意された。", "target_word": "手順", "complexity_tier": "T3", "furigana": "彼[かれ]は手順[てじゅん]を無視[むし]して作業[さぎょう]を進[すす]めたため、上司[じょうし]に注意[ちゅうい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手順", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "作業や手続きを進める段階的な順序・方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: ふくらま (Zipf 1.97)']::text[], '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41237, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手順", "is_correct": true, "explanation": "正解。「医療の手順」は、臓器を移す処置の進め方の順序を指し、文脈に合う。"}, {"text": "時差", "is_correct": false, "explanation": "時差は地域間の時刻のずれで、医療の進め方を表さないので合わない。"}, {"text": "残高", "is_correct": false, "explanation": "残高は口座や在庫の残りを表し、医療の行為には当てはまらない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさで、医療の段取りを表す語ではない。"}], "explanations": {"手順": "正解。「医療の手順」は、臓器を移す処置の進め方の順序を指し、文脈に合う。", "時差": "時差は地域間の時刻のずれで、医療の進め方を表さないので合わない。", "残高": "残高は口座や在庫の残りを表し、医療の行為には当てはまらない。", "音量": "音量は音の大きさで、医療の段取りを表す語ではない。"}, "sentence_index": 0, "correct_answer": "手順"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "受付で、先に来た人から手順に呼ばれた。", "explanation": "ここは〈順番〉の意味。人を呼ぶ場面では順番を使い、手順は作業の進め方なので合わない。"}, {"text": "子どもの手順が伸びて、背が高くなった。", "explanation": "ここは〈身長〉の意味。背が伸びるのは身長で、作業の進め方を指す手順は伸びない。"}, {"text": "店の前に、手順ができていた。", "explanation": "ここは〈行列〉の意味。人が並んでできる列は行列で、手順は列を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41237, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手順", "is_correct": true, "explanation": "正解。「手順を省く」は作業の段取りを飛ばす意味で、文に合う。"}, {"text": "期限", "is_correct": false, "explanation": "期限は決められた日時で、省くという行為の対象にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分量で、省くことで事故が起きる流れにならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、省くという行為の対象にならない。"}], "explanations": {"手順": "正解。「手順を省く」は作業の段取りを飛ばす意味で、文に合う。", "期限": "期限は決められた日時で、省くという行為の対象にならない。", "湿度": "湿度は空気中の水分量で、省くことで事故が起きる流れにならない。", "天気": "天気は空模様で、省くという行為の対象にならない。"}, "sentence_index": 6, "correct_answer": "手順"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "野菜の手順が上がり、家計が苦しくなった。", "explanation": "ここは〈物価〉の意味。値段が上がるのは物価で、作業の進め方を指す手順は上がらない。"}, {"text": "つらい時も、心に手順がある人は強い。", "explanation": "ここは〈余裕〉の意味。心の状態に使う語で、手順は作業の進め方なので合わない。"}, {"text": "熱があったので、手順を測った。", "explanation": "ここは〈体温〉の意味。測れるのは温度や数値で、手順は測定の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41237, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手順に守らないと、事故が起きる。", "corrected_sentence": "手順を守らないと、事故が起きる。", "error_description": "「守る」の目的語は「を」。「手順に」の「に」は誤りで、「手順を守る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41237, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新人は手順を覚えたまで、先輩が教えた。", "corrected_sentence": "新人は手順を覚えるまで、先輩が教えた。", "error_description": "「覚える」の辞書形を「まで」の前に置く。「覚えたまで」は誤りで、「覚えるまで」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
