INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41238, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「移植を待つ間」の「を」で、移植が待つ対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "「移植と待つ間」は並列の形にならず、待つ対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「移植へ待つ間」は方向を示す形で、待つ対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「移植より待つ間」は比較の形で、待つ対象として意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「移植を待つ間」の「を」で、移植が待つ対象を示す。", "と": "「移植と待つ間」は並列の形にならず、待つ対象として成り立たない。", "へ": "「移植へ待つ間」は方向を示す形で、待つ対象にはならない。", "より": "「移植より待つ間」は比較の形で、待つ対象として意味が通らない。"}, "error_tags": {"と": "並列", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41238, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体の一部を、べつの人からもらってうつしかえること。", "primary_collocate": null, "pronunciation": "いしょく", "ipa": "iɕokɯ", "syllable_count": 3, "sentences": [{"text": "弟は兄から腎臓を一つもらう移植を受け、元気になった。", "target_word": "移植", "complexity_tier": "T3", "furigana": "おとうとはあにからじんぞうをひとつもらういしょくをうけ、げんきになった。", "sentence_source": "generated"}, {"text": "家族の中で適合した人がいれば、その人からの移植も考えられる。", "target_word": "移植", "complexity_tier": "T3", "furigana": "かぞくのなかにてきごうしたひとがいれば、そのひとからのいしょくもかんがえられる。", "sentence_source": "generated"}, {"text": "亡くなった方の善意による移植で、多くの人の命が救われている。", "target_word": "移植", "complexity_tier": "T3", "furigana": "なくなったかたのぜんいによるいしょくで、おおくのひとのいのちがすくわれている。", "sentence_source": "generated"}, {"text": "移植を受けた人は、他人の体の一部を自分の体が拒まないように薬を飲む。", "target_word": "移植", "complexity_tier": "T3", "furigana": "いしょくをうけたひとは、たにんのからだのいちぶをじぶんのからだがこばまないようにくすりをのむ。", "sentence_source": "generated"}, {"text": "母は私に肝臓の一部を分ける移植を決意した。", "target_word": "移植", "complexity_tier": "T3", "furigana": "はははわたしにかんぞうのいちぶをわけるいしょくをけついした。", "sentence_source": "generated"}, {"text": "移植のために、遠くの病院から臓器が空輸された。", "target_word": "移植", "complexity_tier": "T3", "furigana": "いしょくのために、とおくのびょういんからぞうきがくうそうされた。", "sentence_source": "generated"}, {"text": "友人は角膜の移植で、十年ぶりに桜の色を見ることができた。", "target_word": "移植", "complexity_tier": "T3", "furigana": "ゆうじんはかくまくのいしょくで、じゅうねんぶりにさくらのいろをみることができた。", "sentence_source": "generated"}, {"text": "移植を待つ間、彼は提供者が現れるのを毎日祈っていた。", "target_word": "移植", "complexity_tier": "T3", "furigana": "いしょくをまつあいだ、かれはていきょうしゃがあらわれるのをまいにちいのっていた。", "sentence_source": "generated"}, {"text": "骨髄の移植では、提供者と患者の型が合うかどうかが重要だ。", "target_word": "移植", "complexity_tier": "T3", "furigana": "こつずいのいしょくでは、ていきょうしゃとかんじゃのかたがあうかどうかがじゅうようだ。", "sentence_source": "generated"}, {"text": "姉は夫から腎臓をもらう移植に、感謝の気持ちでいっぱいだ。", "target_word": "移植", "complexity_tier": "T3", "furigana": "あねはおっとからじんぞうをもらういしょくに、かんしゃのきもちでいっぱいだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移植する", "label": "終止形"}, {"form": "移植した", "label": "過去形"}, {"form": "移植して", "label": "て形"}, {"form": "移植される", "label": "受身形"}], "register": "中立（普通体の書き言葉）", "sense_fingerprint": "ほかの人から体の一部をもらって自分の体にうつしかえること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41238, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正解。「もらう移植を受ける」は他人の体の一部を移す医療を指し、文脈に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊を受けるは意味が通らず、腎臓をもらう文脈に合わない。"}, {"text": "閉店", "is_correct": false, "explanation": "閉店を受けるは成り立たず、臓器をもらう行為とは関係がない。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞を受けるは意味が通らず、体の一部をもらう流れに合わない。"}], "explanations": {"移植": "正解。「もらう移植を受ける」は他人の体の一部を移す医療を指し、文脈に合う。", "寝坊": "寝坊を受けるは意味が通らず、腎臓をもらう文脈に合わない。", "閉店": "閉店を受けるは成り立たず、臓器をもらう行為とは関係がない。", "渋滞": "渋滞を受けるは意味が通らず、体の一部をもらう流れに合わない。"}, "sentence_index": 0, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟に風邪を移植された。", "explanation": "ここは〈感染〉の意味。病気を人にうつすのは感染で、体の一部を別の人から移す移植は病気には使わない。"}, {"text": "電池が切れたので、電池を移植した。", "explanation": "ここは〈交換〉の意味。物を新しいものに入れかえる行為で、体の一部を移す移植とは言わない。"}, {"text": "会社がお金を移植した。", "explanation": "ここは〈寄付〉の意味。お金を譲る行為で、体の一部を移す移植とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41238, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正解。「角膜の移植」は角膜を移す医療を指し、文脈に合う。"}, {"text": "残高", "is_correct": false, "explanation": "残高は口座の残りで、角膜の処置の意味にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分量で、角膜の処置を表さない。"}, {"text": "時差", "is_correct": false, "explanation": "時差は時刻のずれで、医療の処置の意味にならない。"}], "explanations": {"移植": "正解。「角膜の移植」は角膜を移す医療を指し、文脈に合う。", "残高": "残高は口座の残りで、角膜の処置の意味にならない。", "湿度": "湿度は空気中の水分量で、角膜の処置を表さない。", "時差": "時差は時刻のずれで、医療の処置の意味にならない。"}, "sentence_index": 6, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "血液をきれいにするため、週三回、移植を受けている。", "explanation": "ここは〈透析〉の意味。血液を機械で浄化する治療は透析で、一度の移植とは合わない。"}, {"text": "健康診断の後、腕にワクチンを移植した。", "explanation": "ここは〈接種〉の意味。ワクチンを体に入れることは接種で、体の一部を移す移植は使わない。"}, {"text": "熱があるので、移植を受けた。", "explanation": "ここは〈点滴〉の意味。熱の治療で薬液を入れるのは点滴で、移植は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41238, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は兄から腎臓の移植へ受けた。", "corrected_sentence": "弟は兄から腎臓の移植を受けた。", "error_description": "「受ける」の対象は「を」。「移植へ」の「へ」は誤りで、「移植を受けた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41238, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人は角膜を移植すて、十年ぶりに桜の色を見られた。", "corrected_sentence": "友人は角膜を移植して、十年ぶりに桜の色を見られた。", "error_description": "「移植する」のて形は「移植して」。「すて」は誤りで、「して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41239, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「移植を受けてから」の「を」で、移植が受ける対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「移植が受けてから」は主語になり、「受ける」の目的語として合わない。"}, {"text": "に", "is_correct": false, "explanation": "「移植に受けて」は位置や相手の形で、受ける対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「移植へ受けて」は方向を示すが、受ける対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「移植を受けてから」の「を」で、移植が受ける対象を示す。", "が": "「移植が受けてから」は主語になり、「受ける」の目的語として合わない。", "に": "「移植に受けて」は位置や相手の形で、受ける対象として成り立たない。", "へ": "「移植へ受けて」は方向を示すが、受ける対象にはならない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41239, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41239, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "病気やけがで悪くなった臓器や組織を、健康なものと入れかえる医療行為。", "primary_collocate": null, "pronunciation": "いしょく", "ipa": "iɕokɯ", "syllable_count": 3, "sentences": [{"text": "祖父は腎臓の病気が重く、医師から移植を勧められた。", "target_word": "移植", "complexity_tier": "T3", "furigana": "そふはじんぞうのびょうきがおもく、いしからいしょくをすすめられた。", "sentence_source": "generated"}, {"text": "角膜の移植を受けてから、彼女はまた本が読めるようになった。", "target_word": "移植", "complexity_tier": "T3", "furigana": "かくまくのいしょくをうけてから、かのじょはまたほんがよめるようになった。", "sentence_source": "generated"}, {"text": "移植には、体に合う臓器を提供してくれる人が必要だ。", "target_word": "移植", "complexity_tier": "T3", "furigana": "いしょくには、からだにあうぞうきをていきょうしてくれるひとがひつようだ。", "sentence_source": "generated"}, {"text": "手術のあと、移植した臓器が働くまで、薬を毎日飲み続けた。", "target_word": "移植", "complexity_tier": "T3", "furigana": "しゅじゅつのあと、いしょくしたぞうきがはたらくまで、くすりをまいにちのみつづけた。", "sentence_source": "generated"}, {"text": "皮膚の移植は、やけどで広く傷ついた患者にとって大切な治療だ。", "target_word": "移植", "complexity_tier": "T3", "furigana": "ひふのいしょくは、やけどでひろくきずついたかんじゃにとってたいせつなちりょうだ。", "sentence_source": "generated"}, {"text": "肝臓の移植が成功したので、兄は来月退院できる。", "target_word": "移植", "complexity_tier": "T3", "furigana": "かんぞうのいしょくがせいこうしたので、あにはらいげつたいいんできる。", "sentence_source": "generated"}, {"text": "移植を待つ患者は多いが、提供される臓器は少ない。", "target_word": "移植", "complexity_tier": "T3", "furigana": "いしょくをまつかんじゃはおおいが、ていきょうされるぞうきはすくない。", "sentence_source": "generated"}, {"text": "心臓の移植は、とても難しい手術なので、経験豊かな医師が担当する。", "target_word": "移植", "complexity_tier": "T3", "furigana": "しんぞうのいしょくは、とてもむずかしいしゅじゅつなので、けいけんゆたかないしがたんとうする。", "sentence_source": "generated"}, {"text": "医師は「移植が必要かどうか、検査の結果を見て決めます」と説明した。", "target_word": "移植", "complexity_tier": "T3", "furigana": "いしは「いしょくがひつようかどうか、けんさのけっかをみてきめます」とせつめいした。", "sentence_source": "generated"}, {"text": "骨髄の移植を受けた妹は、半年間、人の多い場所を避けて暮らした。", "target_word": "移植", "complexity_tier": "T3", "furigana": "こつずいのいしょくをうけたいもうとは、はんとしかん、ひとのおおいばしょをさけてくらした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移植する", "label": "終止形"}, {"form": "移植した", "label": "過去形"}, {"form": "移植して", "label": "て形"}, {"form": "移植される", "label": "受身形"}], "register": "中立（普通体の書き言葉）", "sense_fingerprint": "悪くなった臓器や組織を健康なものと入れかえる医療行為としての移植", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41239, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正解。「移植を勧める」は臓器の移し替え治療を指し、文脈に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊を勧めるのは意味が通らず、医師の勧めとして成り立たない。"}, {"text": "閉店", "is_correct": false, "explanation": "閉店は店の営業終了で、医師が勧める対象にはならない。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は道路の混雑で、医師から勧められる治療とは合わない。"}], "explanations": {"移植": "正解。「移植を勧める」は臓器の移し替え治療を指し、文脈に合う。", "寝坊": "寝坊を勧めるのは意味が通らず、医師の勧めとして成り立たない。", "閉店": "閉店は店の営業終了で、医師が勧める対象にはならない。", "渋滞": "渋滞は道路の混雑で、医師から勧められる治療とは合わない。"}, "sentence_index": 0, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壊れた時計を移植した。", "explanation": "ここは〈修理〉の意味。壊れた機械を直すのは修理で、体の臓器を入れかえる移植は機械には使わない。"}, {"text": "事故で大量に血を失い、移植を受けた。", "explanation": "ここは〈輸血〉の意味。血液を入れる処置は輸血で、臓器を入れかえる移植は使わない。"}, {"text": "インフルエンザの予防で、移植を打った。", "explanation": "ここは〈注射〉の意味。薬液を体に入れる処置は注射で、移植とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41239, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移植", "is_correct": true, "explanation": "正解。「移植を待つ患者」は臓器の提供を待つ人を指し、文脈に合う。"}, {"text": "時差", "is_correct": false, "explanation": "時差は時刻のずれで、患者が待つ対象にはならない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分量で、患者が待つ対象にはならない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさで、患者が待つ対象として意味が通らない。"}], "explanations": {"移植": "正解。「移植を待つ患者」は臓器の提供を待つ人を指し、文脈に合う。", "時差": "時差は時刻のずれで、患者が待つ対象にはならない。", "湿度": "湿度は空気中の水分量で、患者が待つ対象にはならない。", "音量": "音量は音の大きさで、患者が待つ対象として意味が通らない。"}, "sentence_index": 6, "correct_answer": "移植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "腎臓が弱ったので、毎週、移植を受けている。", "explanation": "ここは〈透析〉の意味。血液を機械で浄化する治療は透析で、一度の移植とは合わない。"}, {"text": "予防のため、ワクチンの移植を受けた。", "explanation": "ここは〈接種〉の意味。ワクチンを体に入れる行為は接種で、臓器を移す移植ではない。"}, {"text": "腕に移植の針を刺した。", "explanation": "ここは〈点滴〉の意味。針で薬液を入れる処置は点滴で、移植の針とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41239, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "腎臓の移植を行けた祖父は、元気になった。", "corrected_sentence": "腎臓の移植を受けた祖父は、元気になった。", "error_description": "移植は「受ける」と結びつく。「行けた」は「行く」の誤りで、「受けた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41239, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "移植へ待つ家族は多いが、心配も多い。", "corrected_sentence": "移植を待つ家族は多いが、心配も多い。", "error_description": "「待つ」の目的語は「を」。「移植へ」の「へ」は誤りで、「移植を待つ」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41240, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「最近は忙しい」と、話題の時期を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「最近を忙しくて」は文が成り立たず、目的語にもならない。"}, {"text": "に", "is_correct": false, "explanation": "時点を示す「に」では「最近に忙しくて」の形にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、ここでは文の形に合わない。"}], "correct_answer": "は", "explanations": {"は": "「最近は忙しい」と、話題の時期を示す「は」。", "を": "「最近を忙しくて」は文が成り立たず、目的語にもならない。", "に": "時点を示す「に」では「最近に忙しくて」の形にならず、不自然。", "へ": "方向を示す「へ」は、ここでは文の形に合わない。"}, "error_tags": {"を": "目的語", "に": "位置・時点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41240, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41240, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「さいきん」は、今より少し前の時間のことです。", "primary_collocate": null, "pronunciation": "さいきん", "ipa": "saikʲiɴ", "syllable_count": 4, "sentences": [{"text": "最近、駅の前に新しいパン屋ができました。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]、駅[えき]の前[まえ]に新[あたら]しいパン屋[や]ができました。", "sentence_source": "generated"}, {"text": "最近は忙しくて、友だちとゆっくり話す時間がありません。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]は忙[いそが]しくて、友[とも]だちとゆっくり話[はな]す時間[じかん]がありません。", "sentence_source": "generated"}, {"text": "田中さんは最近、毎朝走っているそうです。", "target_word": "最近", "complexity_tier": "T3", "furigana": "田中[たなか]さんは最近[さいきん]、毎朝[まいあさ]走[はし]っているそうです。", "sentence_source": "generated"}, {"text": "昔は手紙をよく書いたが、最近はメールばかりだ。", "target_word": "最近", "complexity_tier": "T3", "furigana": "昔[むかし]は手紙[てがみ]をよく書[か]いたが、最近[さいきん]はメールばかりだ。", "sentence_source": "generated"}, {"text": "最近、母から電話が来ないので、少し心配です。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]、母[はは]から電話[でんわ]が来[こ]ないので、少[すこ]し心配[しんぱい]です。", "sentence_source": "generated"}, {"text": "最近よく眠れないので、夜はお茶を飲まないようにしています。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]よく眠[ねむ]れないので、夜[よる]はお茶[ちゃ]を飲[の]まないようにしています。", "sentence_source": "generated"}, {"text": "最近買った靴は、とても歩きやすいです。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]買[か]った靴[くつ]は、とても歩[ある]きやすいです。", "sentence_source": "generated"}, {"text": "この店は最近人気が出て、いつも行列ができている。", "target_word": "最近", "complexity_tier": "T3", "furigana": "この店[みせ]は最近[さいきん]人気[にんき]が出[で]て、いつも行列[ぎょうれつ]ができている。", "sentence_source": "generated"}, {"text": "最近、弟は漫画より小説を読むようになりました。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]、弟[おとうと]は漫画[まんが]より小説[しょうせつ]を読[よ]むようになりました。", "sentence_source": "generated"}, {"text": "最近になって、やっと日本語のニュースが分かってきた。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]になって、やっと日本語[にほんご]のニュースが分[わ]かってきた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "今より少し前から今までの時間。副詞的に「最近、〜」と使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41240, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最近", "is_correct": true, "explanation": "今に近い期間を表し、「最近、パン屋ができた」と自然に合う。"}, {"text": "来年", "is_correct": false, "explanation": "来年は未来のことで、すでにできたという完了の文と矛盾する。"}, {"text": "未来", "is_correct": false, "explanation": "未来は先のことで、完了した出来事の時間を表すには合わない。"}, {"text": "江戸時代", "is_correct": false, "explanation": "江戸時代に駅前の店ができたという文脈になり、現代の話と噛み合わない。"}], "explanations": {"最近": "今に近い期間を表し、「最近、パン屋ができた」と自然に合う。", "来年": "来年は未来のことで、すでにできたという完了の文と矛盾する。", "未来": "未来は先のことで、完了した出来事の時間を表すには合わない。", "江戸時代": "江戸時代に駅前の店ができたという文脈になり、現代の話と噛み合わない。"}, "sentence_index": 0, "correct_answer": "最近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来年の最近に、新しい校舎が建つ。", "explanation": "ここは〈来年ごろ〉の意味。「最近」は現在から遡る期間で、未来の時期は指さない。"}, {"text": "映画の最近に、彼女は泣いた。", "explanation": "ここは〈最中〉の意味。「最近」は今に近い期間で、映画の途中の場面は指さない。"}, {"text": "試合の最近に、選手たちは準備運動をした。", "explanation": "ここは「直前」の意味。「最近」は今に近い期間を表し、出来事の直前は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41240, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最近", "is_correct": true, "explanation": "今に近い期間を指し、「最近買った靴」と自然に合う。"}, {"text": "来週", "is_correct": false, "explanation": "来週はこれから先のことで、もう買った靴の話と矛盾する。"}, {"text": "将来", "is_correct": false, "explanation": "将来は先のことで、すでに買った靴と合わない。"}, {"text": "縄文時代", "is_correct": false, "explanation": "縄文時代に買った靴という文脈になり、現代の話と噛み合わない。"}], "explanations": {"最近": "今に近い期間を指し、「最近買った靴」と自然に合う。", "来週": "来週はこれから先のことで、もう買った靴の話と矛盾する。", "将来": "将来は先のことで、すでに買った靴と合わない。", "縄文時代": "縄文時代に買った靴という文脈になり、現代の話と噛み合わない。"}, "sentence_index": 6, "correct_answer": "最近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卒業式の最近に、先生が全員に挨拶した。", "explanation": "ここは「直後」の意味。「最近」は今に近い期間で、出来事の直後の時点は表さない。"}, {"text": "数年前の最近に引っ越して、やっと日本語のニュースが分かってきた。", "explanation": "ここは〈数年前〉の意味。「最近」は今に近い期間を表し、過去の一時点は指さない。"}, {"text": "小学校の最近に、やっと日本語のニュースが分かってきた。", "explanation": "ここは〈小学校の頃〉の意味。「最近」は今に近い時期を表し、昔の一時期は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41240, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近を忙しくて、会えていない。", "corrected_sentence": "最近は忙しくて、会えていない。", "error_description": "主題の「は」を目的格の「を」にした。「最近」は時を表す語で、「を」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41240, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近を、この町は人が増えてきた。", "corrected_sentence": "最近、この町は人が増えてきた。", "error_description": "「最近」は副詞として使うので、直後に「を」は付かない。「最近、〜」の形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
