INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41241, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「最近」は、現在からさかのぼって少し前の時期を指します。", "primary_collocate": null, "pronunciation": "さいきん", "ipa": "saikʲiɴ", "syllable_count": 4, "sentences": [{"text": "最近の天気は変わりやすくて、傘が手放せません。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]の天気[てんき]は変[か]わりやすくて、傘[かさ]が手放[てばな]せません。", "sentence_source": "generated"}, {"text": "最近では、スマートフォンで切符を買う人も多い。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]では、スマートフォンで切符[きっぷ]を買[か]う人[ひと]も多[おお]い。", "sentence_source": "generated"}, {"text": "彼が引っ越したことを、私は最近まで知りませんでした。", "target_word": "最近", "complexity_tier": "T3", "furigana": "彼[かれ]が引[ひ]っ越[こ]したことを、私[わたし]は最近[さいきん]まで知[し]りませんでした。", "sentence_source": "generated"}, {"text": "最近の子どもたちは、小さいころからタブレットを使いこなす。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]の子[こ]どもたちは、小[ちい]さいころからタブレットを使[つか]いこなす。", "sentence_source": "generated"}, {"text": "これは最近撮った写真ではなく、十年前のものです。", "target_word": "最近", "complexity_tier": "T3", "furigana": "これは最近[さいきん]撮[と]った写真[しゃしん]ではなく、十年前[じゅうねんまえ]のものです。", "sentence_source": "generated"}, {"text": "最近のニュースによると、来月から電車の料金が上がるそうです。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]のニュースによると、来月[らいげつ]から電車[でんしゃ]の料金[りょうきん]が上[あ]がるそうです。", "sentence_source": "generated"}, {"text": "祖父は最近の若者の言葉が分からないと言っている。", "target_word": "最近", "complexity_tier": "T3", "furigana": "祖父[そふ]は最近[さいきん]の若者[わかもの]の言葉[ことば]が分[わ]からないと言[い]っている。", "sentence_source": "generated"}, {"text": "最近まで空き地だった場所に、大きなビルが建った。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]まで空[あ]き地[ち]だった場所[ばしょ]に、大[おお]きなビルが建[た]った。", "sentence_source": "generated"}, {"text": "最近では、家で働く会社員も珍しくありません。", "target_word": "最近", "complexity_tier": "T3", "furigana": "最近[さいきん]では、家[いえ]で働[はたら]く会社員[かいしゃいん]も珍[めずら]しくありません。", "sentence_source": "generated"}, {"text": "先生は最近の研究について、授業で詳しく説明した。", "target_word": "最近", "complexity_tier": "T3", "furigana": "先生[せんせい]は最近[さいきん]の研究[けんきゅう]について、授業[じゅぎょう]で詳[くわ]しく説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [], "register": "neutral", "sense_fingerprint": "現在からさかのぼった少し前の時期。「最近の+名詞」「最近では」「最近まで」の形で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41241, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数学", "is_correct": false, "explanation": "「数学の天気」は意味が通らず、空欄には入らない。"}, {"text": "最近", "is_correct": true, "explanation": "「最近の天気」は現在に近い時期の天気を表し、文の意味に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙の天気」は成り立たず、空欄には入らない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布の天気」は意味が通らず、時期を表す語でもないので入らない。"}], "explanations": {"数学": "「数学の天気」は意味が通らず、空欄には入らない。", "最近": "「最近の天気」は現在に近い時期の天気を表し、文の意味に合う。", "手紙": "「手紙の天気」は成り立たず、空欄には入らない。", "財布": "「財布の天気」は意味が通らず、時期を表す語でもないので入らない。"}, "sentence_index": 0, "correct_answer": "最近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最近、来週の月曜日に雨が降る。", "explanation": "ここは〈今後〉の意味。〈最近〉は過去から現在に近い時期を指すので、来週のような先の出来事には使えない。"}, {"text": "最近、三百年前の城が建った。", "explanation": "ここは〈昔〉の意味。〈最近〉は現在に近い時期なので、三百年前の出来事には合わない。"}, {"text": "最近連絡を取ったのは十年前です。", "explanation": "ここは〈最後〉の意味。〈最近〉は現在に近い時期なので、十年前を指す「最後」の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41241, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教科書", "is_correct": false, "explanation": "「教科書の若者」は意味が通らず、空欄には入らない。"}, {"text": "最近", "is_correct": true, "explanation": "「最近の若者」は近年の若い世代を表し、文の意味に合う。"}, {"text": "段ボール", "is_correct": false, "explanation": "「段ボールの若者」は成り立たず、空欄には入らない。"}, {"text": "駐車場", "is_correct": false, "explanation": "「駐車場の若者」は意味が通らず、空欄には入らない。"}], "explanations": {"教科書": "「教科書の若者」は意味が通らず、空欄には入らない。", "最近": "「最近の若者」は近年の若い世代を表し、文の意味に合う。", "段ボール": "「段ボールの若者」は成り立たず、空欄には入らない。", "駐車場": "「駐車場の若者」は意味が通らず、空欄には入らない。"}, "sentence_index": 6, "correct_answer": "最近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年末の最近に、家族で温泉へ行った。", "explanation": "ここは〈年末近く〉の意味。「最近」は現在から遡る期間で、年末の一時期は指さない。"}, {"text": "最近、この瞬間の彼は笑っている。", "explanation": "ここは〈今〉の意味。〈最近〉は時期の幅を表すので、「この瞬間」のような一点とは合わない。"}, {"text": "最近、この景色は一万年前から変わらない。", "explanation": "ここは〈昔から〉の意味。〈最近〉は現在に近い時期なので、一万年前から続くことには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41241, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近に話題は、ダイエットの方法が中心だ。", "corrected_sentence": "最近の話題は、ダイエットの方法が中心だ。", "error_description": "「最近」が名詞を修飾するときは「の」を使う（最近の話題）。誤りは「最近」に続く助詞「に」の部分で、「の」にすべき。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41241, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近から海外に住んでいました。", "corrected_sentence": "最近まで海外に住んでいました。", "error_description": "「最近から」は不自然で、誤りは「最近」に続く助詞「から」の部分。「最近まで」が正しい（最近の時期まで続き、今は終わったことを表す）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
