INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41242, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「助けて」の対象は「おばあさんを」で示すので、文が成り立つ。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すため、助ける対象を示すことができない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すため、「おばあさんで助けて」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表すため、「おばあさんの助けて」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「助けて」の対象は「おばあさんを」で示すので、文が成り立つ。", "より": "比較を表すため、助ける対象を示すことができない。", "で": "手段や場所を表すため、「おばあさんで助けて」は成り立たない。", "の": "連体修飾を表すため、「おばあさんの助けて」は文が成り立たない。"}, "error_tags": {"より": "比較（対象を示せない）", "で": "手段・場所（対象を示せない）", "の": "連体修飾（文が成り立たない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41242, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "だれかをてつだうこと。", "primary_collocate": null, "pronunciation": "たすける", "ipa": "ta̠sɨke̞ɾɯᵝ", "syllable_count": 4, "sentences": [{"text": "毎日、母が夕食を作るのを助けている。", "target_word": "助けている", "complexity_tier": "T3", "furigana": "毎日[まいにち]、母[はは]が夕食[ゆうしょく]を作[つく]るのを助[たす]けている。", "sentence_source": "generated"}, {"text": "弟が重い荷物を運ぶのを助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "弟[おとうと]が重[おも]い荷物[にもつ]を運[はこ]ぶのを助[たす]けた。", "sentence_source": "generated"}, {"text": "兄は私が宿題をするのを助けてくれた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "兄[あに]は私[わたし]が宿題[しゅくだい]をするのを助[たす]けてくれた。", "sentence_source": "generated"}, {"text": "忙しい先輩の仕事を助けるのは、後輩として当然のことだ。", "target_word": "助ける", "complexity_tier": "T3", "furigana": "忙[いそが]しい先輩[せんぱい]の仕事[しごと]を助[たす]けるのは、後輩[こうはい]として当然[とうぜん]のことだ。", "sentence_source": "generated"}, {"text": "先生は、新しい生徒が学校に慣れるのを助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "先生[せんせい]は、新[あたら]しい生徒[せいと]が学校[がっこう]に慣[な]れるのを助[たす]けた。", "sentence_source": "generated"}, {"text": "隣の人が、道に迷った私を助けてくれた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]が、道[みち]に迷[まよ]った私[わたし]を助[たす]けてくれた。", "sentence_source": "generated"}, {"text": "父の店を助けるために、週末に働いている。", "target_word": "助ける", "complexity_tier": "T3", "furigana": "父[ちち]の店[みせ]を助[たす]けるために、週末[しゅうまつ]に働[はたら]いている。", "sentence_source": "generated"}, {"text": "彼女は病気のおばあさんを助けて、毎日世話をしている。", "target_word": "助け", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は病気[びょうき]のおばあさんを助[たす]けて、毎日[まいにち]世話[せわ]をしている。", "sentence_source": "generated"}, {"text": "友だちが引っ越しを助けてくれたので、早く終わった。", "target_word": "助け", "complexity_tier": "T3", "furigana": "友[とも]だちが引[ひ]っ越[こ]しを助[たす]けてくれたので、早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "妹が、母の料理の準備を助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "妹[いもうと]が、母[はは]の料理[りょうり]の準備[じゅんび]を助[たす]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "助ける", "label": "辞書形"}, {"form": "助けます", "label": "丁寧形"}, {"form": "助けない", "label": "否定形"}, {"form": "助けて", "label": "て形"}, {"form": "助けた", "label": "過去形"}, {"form": "助ければ", "label": "仮定形"}, {"form": "助けよう", "label": "意向形"}, {"form": "助けられる", "label": "可能・受身形"}], "register": "中立", "sense_fingerprint": "人の仕事や作業をそばで手伝って楽にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41242, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "助けている", "is_correct": true, "explanation": "母が夕食作りを手伝っている状態を表し、「〜のを___」に入る。"}, {"text": "眠っている", "is_correct": false, "explanation": "眠るは目的語を取らないため、「作るのを眠っている」は成り立たない。"}, {"text": "転んでいる", "is_correct": false, "explanation": "転ぶは自動詞で「〜のを」を取れないため、文が成り立たない。"}, {"text": "光っている", "is_correct": false, "explanation": "光るは自動詞で、料理を手伝う意味にならず、「作るのを」に続かない。"}], "explanations": {"助けている": "母が夕食作りを手伝っている状態を表し、「〜のを___」に入る。", "眠っている": "眠るは目的語を取らないため、「作るのを眠っている」は成り立たない。", "転んでいる": "転ぶは自動詞で「〜のを」を取れないため、文が成り立たない。", "光っている": "光るは自動詞で、料理を手伝う意味にならず、「作るのを」に続かない。"}, "sentence_index": 0, "correct_answer": "助けている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末に、散らかった部屋を助けた。", "explanation": "ここは〈片づける〉の意味。散らかったものを整えることは片づけると言い、助けるとは言わないので合わない。"}, {"text": "後輩に、仕事の手順を助けた。", "explanation": "ここは〈教える〉の意味。知識や手順を伝えることは教えると言い、助けるとは言わないので合わない。"}, {"text": "母は朝、ケーキを助けた。", "explanation": "ここは〈焼く〉の意味。ケーキを熱で作ることは焼くと言い、助けるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41242, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "助ける", "is_correct": true, "explanation": "父の店を手伝って楽にする意味で、「父の店を___ために」に入る。"}, {"text": "咲く", "is_correct": false, "explanation": "花が開く意味の自動詞で、店を対象に取れないため文が成り立たない。"}, {"text": "凍る", "is_correct": false, "explanation": "液体が固まる意味の自動詞で、店を対象に取れないため文が成り立たない。"}, {"text": "泣く", "is_correct": false, "explanation": "涙を流す意味の自動詞で、「父の店を」に続かないので文が成り立たない。"}], "explanations": {"助ける": "父の店を手伝って楽にする意味で、「父の店を___ために」に入る。", "咲く": "花が開く意味の自動詞で、店を対象に取れないため文が成り立たない。", "凍る": "液体が固まる意味の自動詞で、店を対象に取れないため文が成り立たない。", "泣く": "涙を流す意味の自動詞で、「父の店を」に続かないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "助ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちの合格を助けて、みんなで喜んだ。", "explanation": "ここは〈祝う〉の意味。人の成功をよろこび言葉や行事で示すことは祝うと言い、助けるとは言わないので合わない。"}, {"text": "店員は、お金を助けて、おつりを渡した。", "explanation": "ここは〈数える〉の意味。硬貨や紙幣の枚数を確かめることは数えると言い、助けるとは言わないので合わない。"}, {"text": "彼は毎朝、車を助けて会社へ行く。", "explanation": "ここは〈運転する〉の意味。車を操作して走らせることは運転すると言い、助けるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41242, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、私が庭の草むしりをするのが助けてくれた。", "corrected_sentence": "祖父は、私が庭の草むしりをするのを助けてくれた。", "error_description": "「助けてくれた」の対象は「〜のを」で示す。「〜のが」は主語の形で、助ける対象としてはつながらない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "助け", "is_correct": true, "explanation": "た形の前に置く連用形で、「弟が運ぶのを助けた」に合う。"}, {"text": "助けない", "is_correct": false, "explanation": "否定形で、「〜た」の前には続かない。"}, {"text": "助けよう", "is_correct": false, "explanation": "意向形で、「〜た」の前には続かない。"}, {"text": "助ける", "is_correct": false, "explanation": "辞書形で、「〜た」の前には直接続かない。"}], "correct_form": "助け", "base_form": "助ける", "form_label": "連用形（た形・て形の前）", "sentence_index": 1, "explanations": {"助け": "た形の前に置く連用形で、「弟が運ぶのを助けた」に合う。", "助けない": "否定形で、「〜た」の前には続かない。", "助けよう": "意向形で、「〜た」の前には続かない。", "助ける": "辞書形で、「〜た」の前には直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41242, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その子は、転んだ友だちを助けよとした。", "corrected_sentence": "その子は、転んだ友だちを助けようとした。", "error_description": "「助けよ」は命令の形で、「〜とした」には続かない。意向形の「助けよう」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "助け", "is_correct": true, "explanation": "て形の前に置く連用形で、「病気のおばあさんを助けて」に合う。"}, {"text": "助けます", "is_correct": false, "explanation": "丁寧形で、「助けます＋て」の形は成り立たない。"}, {"text": "助ければ", "is_correct": false, "explanation": "仮定形で、「〜て」の前には続かない。"}, {"text": "助けられる", "is_correct": false, "explanation": "可能・受身形で、「助けられるて」とは続かず、文が成り立たない。"}], "correct_form": "助け", "base_form": "助ける", "form_label": "連用形（た形・て形の前）", "sentence_index": 7, "explanations": {"助け": "て形の前に置く連用形で、「病気のおばあさんを助けて」に合う。", "助けます": "丁寧形で、「助けます＋て」の形は成り立たない。", "助ければ": "仮定形で、「〜て」の前には続かない。", "助けられる": "可能・受身形で、「助けられるて」とは続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41243, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「男の人が」で、助ける動作の主語を示すので文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "与格を表すため、「男の人に助けた」は主語を示せず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すため、主語を示すことができない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、主語にならず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「男の人が」で、助ける動作の主語を示すので文が成り立つ。", "に": "与格を表すため、「男の人に助けた」は主語を示せず文が成り立たない。", "で": "手段や場所を表すため、主語を示すことができない。", "へ": "方向を表すため、主語にならず文が成り立たない。"}, "error_tags": {"に": "与格（主語にならない）", "で": "手段・場所（主語にならない）", "へ": "方向（主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41243, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「助けた」の対象は「私を」で示すので、文が成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を表すため、「私と助けた」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すため、助ける対象を示せず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すため、助ける対象を示すことができない。"}], "correct_answer": "を", "explanations": {"を": "「助けた」の対象は「私を」で示すので、文が成り立つ。", "と": "並列や共同を表すため、「私と助けた」は文として成り立たない。", "から": "起点を表すため、助ける対象を示せず文が成り立たない。", "より": "比較を表すため、助ける対象を示すことができない。"}, "error_tags": {"と": "並列・共同（文が成り立たない）", "から": "起点（対象を示せない）", "より": "比較（対象を示せない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41243, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "相手のためになるように、行動や力を貸すこと。", "primary_collocate": null, "pronunciation": "たすける", "ipa": "ta̠sɨke̞ɾɯᵝ", "syllable_count": 4, "sentences": [{"text": "火事のとき、消防士が子どもを助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "火事[かじ]のとき、消防士[しょうぼうし]が子[こ]どもを助[たす]けた。", "sentence_source": "generated"}, {"text": "川に落ちた犬を、男の人が助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "川[かわ]に落[お]ちた犬[いぬ]を、男[おとこ]の人[ひと]が助[たす]けた。", "sentence_source": "generated"}, {"text": "この薬は、体が病気から回復するのを助ける。", "target_word": "助ける", "complexity_tier": "T3", "furigana": "この薬[くすり]は、体[からだ]が病気[びょうき]から回復[かいふく]するのを助[たす]ける。", "sentence_source": "generated"}, {"text": "集まったお金は、災害にあった人々を助ける。", "target_word": "助ける", "complexity_tier": "T3", "furigana": "集[あつ]まったお金[かね]は、災害[さいがい]にあった人々[ひとびと]を助[たす]ける。", "sentence_source": "generated"}, {"text": "国は貧しい家庭を助けるために、お金を出している。", "target_word": "助ける", "complexity_tier": "T3", "furigana": "国[くに]は貧[まず]しい家庭[かてい]を助[たす]けるために、お金[かね]を出[だ]している。", "sentence_source": "generated"}, {"text": "先輩がくれたアドバイスが、私を大いに助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "先輩[せんぱい]がくれたアドバイスが、私[わたし]を大[おお]いに助[たす]けた。", "sentence_source": "generated"}, {"text": "この辞書は、言葉の勉強を助けてくれる。", "target_word": "助け", "complexity_tier": "T3", "furigana": "この辞書[じしょ]は、言葉[ことば]の勉強[べんきょう]を助[たす]けてくれる。", "sentence_source": "generated"}, {"text": "友だちの一言が、落ちこんでいた私を助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "友[とも]だちの一言[ひとこと]が、落[お]ちこんでいた私[わたし]を助[たす]けた。", "sentence_source": "generated"}, {"text": "大雨で困っていた人を、近所の人たちが助けた。", "target_word": "助けた", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で困[こま]っていた人[ひと]を、近所[きんじょ]の人[ひと]たちが助[たす]けた。", "sentence_source": "generated"}, {"text": "海で泳げなくなった人を、ライフセーバーが助けた。", "target_word": "助け", "complexity_tier": "T3", "furigana": "海[うみ]で泳[およ]げなくなった人[ひと]を、ライフセーバーが助[たす]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "助ける", "label": "辞書形"}, {"form": "助けます", "label": "丁寧形"}, {"form": "助けない", "label": "否定形"}, {"form": "助けて", "label": "て形"}, {"form": "助けた", "label": "過去形"}, {"form": "助ければ", "label": "仮定形"}, {"form": "助けよう", "label": "意向形"}, {"form": "助けられる", "label": "可能・受身形"}], "register": "中立", "sense_fingerprint": "相手のために行動や力を貸して手伝い、支える（危険の救助から日常的な手助けまで）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 落ちこん (Zipf 1.69)']::text[], '90fa4bdf-c71d-489f-bb70-e9e1151b79b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41243, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "助け", "is_correct": true, "explanation": "救う意味の他動詞の連用形で、「子どもを助けた」に入る。"}, {"text": "寝", "is_correct": false, "explanation": "寝るは自動詞で「子どもを」を対象に取れないため、「子どもを寝た」は成り立たない。"}, {"text": "転び", "is_correct": false, "explanation": "転ぶは自動詞で対象を取れないため、「子どもを転んだ」は成り立たない。"}, {"text": "帰り", "is_correct": false, "explanation": "帰るは自動詞で、子どもを対象にできないため文が成り立たない。"}], "explanations": {"助け": "救う意味の他動詞の連用形で、「子どもを助けた」に入る。", "寝": "寝るは自動詞で「子どもを」を対象に取れないため、「子どもを寝た」は成り立たない。", "転び": "転ぶは自動詞で対象を取れないため、「子どもを転んだ」は成り立たない。", "帰り": "帰るは自動詞で、子どもを対象にできないため文が成り立たない。"}, "sentence_index": 0, "correct_answer": "助け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月末に、電気代を助けるため、エアコンを止めた。", "explanation": "ここは〈節約する〉の意味。お金や時間を減らして無駄を省くことは節約すると言い、助けるとは言わないので合わない。"}, {"text": "朝、髪を助けてから出かけた。", "explanation": "ここは〈整える〉の意味。乱れたものを直して形をととのえることは整えると言い、助けるとは言わないので合わない。"}, {"text": "放課後、チラシを助けた。", "explanation": "ここは〈配る〉の意味。多くの人に物を渡して回ることは配ると言い、助けるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41243, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "助け", "is_correct": true, "explanation": "手伝って力を貸す意味で、「言葉の勉強を___てくれる」に入る。"}, {"text": "咲き", "is_correct": false, "explanation": "咲くは自動詞で「言葉の勉強を」を対象に取れないため、文が成り立たない。"}, {"text": "凍り", "is_correct": false, "explanation": "凍るは自動詞で対象を取れないため、「言葉の勉強を凍る」は成り立たない。"}, {"text": "泣き", "is_correct": false, "explanation": "泣くは自動詞で、勉強を対象にできないため文が成り立たない。"}], "explanations": {"助け": "手伝って力を貸す意味で、「言葉の勉強を___てくれる」に入る。", "咲き": "咲くは自動詞で「言葉の勉強を」を対象に取れないため、文が成り立たない。", "凍り": "凍るは自動詞で対象を取れないため、「言葉の勉強を凍る」は成り立たない。", "泣き": "泣くは自動詞で、勉強を対象にできないため文が成り立たない。"}, "sentence_index": 6, "correct_answer": "助け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は毎晩、ピアノを助けてくれた。", "explanation": "ここは〈演奏する〉の意味。楽器で曲を奏でることは演奏すると言い、助けるとは言わないので合わない。"}, {"text": "彼は毎朝、バイクを助けて会社へ行く。", "explanation": "ここは〈運転する〉の意味。乗り物を操って走らせることは運転すると言い、助けるとは言わないので合わない。"}, {"text": "先生は夏休みに、答案を助けた。", "explanation": "ここは〈採点する〉の意味。答案に点数をつけることは採点すると言い、助けるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41243, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "がけ崩れの現場で、ボランティアが埋まった人に助けた。", "corrected_sentence": "がけ崩れの現場で、ボランティアが埋まった人を助けた。", "error_description": "「助けた」の対象は「〜を」で示す。「〜に」では対象を正しく表せず、不自然な文になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "助け", "is_correct": true, "explanation": "た形の前に置く連用形で、「犬を男の人が助けた」に合う。"}, {"text": "助けない", "is_correct": false, "explanation": "否定形で、「〜た」の前には続かない。"}, {"text": "助けよう", "is_correct": false, "explanation": "意向形で、「〜た」の前には続かない。"}, {"text": "助ける", "is_correct": false, "explanation": "辞書形で、「〜た」の前には直接続かない。"}], "correct_form": "助け", "base_form": "助ける", "form_label": "連用形（た形・て形の前）", "sentence_index": 1, "explanations": {"助け": "た形の前に置く連用形で、「犬を男の人が助けた」に合う。", "助けない": "否定形で、「〜た」の前には続かない。", "助けよう": "意向形で、「〜た」の前には続かない。", "助ける": "辞書形で、「〜た」の前には直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41243, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪山で遭難した登山者を、救助隊が助けかった。", "corrected_sentence": "雪山で遭難した登山者を、救助隊が助けた。", "error_description": "「助けた」は動詞の過去形。「助けかった」は形容詞の過去形（〜かった）を動詞に付けた誤りで、動詞には使わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "助け", "is_correct": true, "explanation": "た形の前に置く連用形で、「私を助けた」に合う。"}, {"text": "助けます", "is_correct": false, "explanation": "丁寧形で、「〜た」の前には続かない。"}, {"text": "助ければ", "is_correct": false, "explanation": "仮定形で、「〜た」の前には続かない。"}, {"text": "助けられる", "is_correct": false, "explanation": "可能・受身形で、「助けられるた」とは続かず、文が成り立たない。"}], "correct_form": "助け", "base_form": "助ける", "form_label": "連用形（た形・て形の前）", "sentence_index": 7, "explanations": {"助け": "た形の前に置く連用形で、「私を助けた」に合う。", "助けます": "丁寧形で、「〜た」の前には続かない。", "助ければ": "仮定形で、「〜た」の前には続かない。", "助けられる": "可能・受身形で、「助けられるた」とは続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c2144-4eec-4e23-a8bc-dde1dd29150b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41244, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「事故が起こる」の「が」。起こる主体の事故を示す。"}, {"text": "に", "is_correct": false, "explanation": "「事故に起こりやすい」は位置や相手を示さず、文が不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「事故へ起こりやすい」は方向を示せず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「事故と起こりやすい」は共同の形にならず、文が不自然。"}], "correct_answer": "が", "explanations": {"が": "「事故が起こる」の「が」。起こる主体の事故を示す。", "に": "「事故に起こりやすい」は位置や相手を示さず、文が不自然。", "へ": "「事故へ起こりやすい」は方向を示せず、文が成り立たない。", "と": "「事故と起こりやすい」は共同の形にならず、文が不自然。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41244, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「事故を防ぐ」の「を」。防ぐ対象の事故を示す。"}, {"text": "で", "is_correct": false, "explanation": "「事故で防ぐ」は手段の形になり、防ぐ対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「事故より防ぐ」は比較の形になり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「事故が防ぐ」では事故が防ぐことになり、文の意味が変わる。"}], "correct_answer": "を", "explanations": {"を": "「事故を防ぐ」の「を」。防ぐ対象の事故を示す。", "で": "「事故で防ぐ」は手段の形になり、防ぐ対象を示せない。", "より": "「事故より防ぐ」は比較の形になり、文が成り立たない。", "が": "「事故が防ぐ」では事故が防ぐことになり、文の意味が変わる。"}, "error_tags": {"で": "手段", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41244, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "じこは、わるいことがおこることです。", "primary_collocate": null, "pronunciation": "じこ", "ipa": "dʑiko", "syllable_count": 2, "sentences": [{"text": "昨日、駅の近くで事故があった。", "target_word": "事故", "complexity_tier": "T3", "furigana": "昨日[きのう]、駅[えき]の近[ちか]くで事故[じこ]があった。", "sentence_source": "generated"}, {"text": "雨の日は、事故が起こりやすい。", "target_word": "事故", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、事故[じこ]が起[お]こりやすい。", "sentence_source": "generated"}, {"text": "事故にあわないように、道を渡る前に右と左を見る。", "target_word": "事故", "complexity_tier": "T3", "furigana": "事故[じこ]にあわないように、道[みち]を渡[わた]る前[まえ]に右[みぎ]と左[ひだり]を見[み]る。", "sentence_source": "generated"}, {"text": "事故のせいで、電車が三十分も遅れた。", "target_word": "事故", "complexity_tier": "T3", "furigana": "事故[じこ]のせいで、電車[でんしゃ]が三十分[さんじゅっぷん]も遅[おく]れた。", "sentence_source": "generated"}, {"text": "先生は事故のことを、みんなに静かに話した。", "target_word": "事故", "complexity_tier": "T3", "furigana": "先生[せんせい]は事故[じこ]のことを、みんなに静[しず]かに話[はな]した。", "sentence_source": "generated"}, {"text": "大きな事故にならなくて、本当によかった。", "target_word": "事故", "complexity_tier": "T3", "furigana": "大[おお]きな事故[じこ]にならなくて、本当[ほんとう]によかった。", "sentence_source": "generated"}, {"text": "工場で事故が起きて、けが人が出た。", "target_word": "事故", "complexity_tier": "T3", "furigana": "工場[こうじょう]で事故[じこ]が起[お]きて、けが人[にん]が出[で]た。", "sentence_source": "generated"}, {"text": "事故を防ぐために、毎朝機械を点検する。", "target_word": "事故", "complexity_tier": "T3", "furigana": "事故[じこ]を防[ふせ]ぐために、毎朝[まいあさ]機械[きかい]を点検[てんけん]する。", "sentence_source": "generated"}, {"text": "目の前で事故を見て、とても驚いた。", "target_word": "事故", "complexity_tier": "T3", "furigana": "目[め]の前[まえ]で事故[じこ]を見[み]て、とても驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "事故の知らせを聞いて、母はすぐ病院へ向かった。", "target_word": "事故", "complexity_tier": "T3", "furigana": "事故[じこ]の知[し]らせを聞[き]いて、母[はは]はすぐ病院[びょういん]へ向[む]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事故", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "悪いことが起こること。やさしい言葉で説明した、日常の「事故」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41244, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事故", "is_correct": true, "explanation": "悪いことが起こる意味で、駅の近くの出来事として自然。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚で、駅の近くの出来事としては合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "課題の意味で、駅の近くで起きた出来事としては合わない。"}, {"text": "静けさ", "is_correct": false, "explanation": "静かな様子で、悪いことが起きた文脈とは合わない。"}], "explanations": {"事故": "悪いことが起こる意味で、駅の近くの出来事として自然。", "眠気": "眠くなる感覚で、駅の近くの出来事としては合わない。", "宿題": "課題の意味で、駅の近くで起きた出来事としては合わない。", "静けさ": "静かな様子で、悪いことが起きた文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "事故"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で、新しい事故を提案した。", "explanation": "事故は提案の対象にならないので、この文は不自然。"}, {"text": "窓の外に広がる事故が、とてもきれいだった。", "explanation": "事故は悪い出来事なので、美しい景色を表す語としては使えない。"}, {"text": "実験の事故を祝った。", "explanation": "事故は悪い出来事なので、祝う対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41244, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事故", "is_correct": true, "explanation": "悪い出来事が起き、けが人が出た文脈に合う。"}, {"text": "注文", "is_correct": false, "explanation": "頼んだ品の意味で、けが人が出た出来事とは合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様の意味で、出来事の原因として文が成立しない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の感覚で、工場の出来事とは合わない。"}], "explanations": {"事故": "悪い出来事が起き、けが人が出た文脈に合う。", "注文": "頼んだ品の意味で、けが人が出た出来事とは合わない。", "天気": "空模様の意味で、出来事の原因として文が成立しない。", "味": "食べ物の感覚で、工場の出来事とは合わない。"}, "sentence_index": 6, "correct_answer": "事故"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の事故の予定を立てた。", "explanation": "事故は計画して立てるものではないので、予定には合わない。"}, {"text": "会議で事故を交換した。", "explanation": "事故は交換するものではないので、この文は不自然。"}, {"text": "友人の事故が決まって、みんなで祝った。", "explanation": "事故は決めたり祝ったりするものではないので、この文は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
