INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41245, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「事故で」は原因を表し、旅行の予定が変わった理由にあたるので自然。"}, {"text": "に", "is_correct": false, "explanation": "「事故に」は対象や相手を表す形で、ここでは変化の原因を示せず合わない。"}, {"text": "を", "is_correct": false, "explanation": "「事故を」は動作の対象を表すが、後ろに対応する他動詞がなく、原因の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「事故へ」は行き先の方向を表し、予定が変わった理由としては成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「事故で」は原因を表し、旅行の予定が変わった理由にあたるので自然。", "に": "「事故に」は対象や相手を表す形で、ここでは変化の原因を示せず合わない。", "を": "「事故を」は動作の対象を表すが、後ろに対応する他動詞がなく、原因の文として成り立たない。", "へ": "「事故へ」は行き先の方向を表し、予定が変わった理由としては成り立たない。"}, "error_tags": {"に": "対象・相手", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
