INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41245, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "予期しない悪い出来事や災難のこと。", "primary_collocate": null, "pronunciation": "じこ", "ipa": "dʑiko", "syllable_count": 2, "sentences": [{"text": "高速道路で事故が起き、道路が通れなくなった。", "target_word": "事故", "complexity_tier": "T3", "furigana": "高速道路[こうそくどうろ]で事故[じこ]が起[お]き、道路[どうろ]が通[とお]れなくなった。", "sentence_source": "generated"}, {"text": "予期しない事故で、旅行の予定が変わってしまった。", "target_word": "事故", "complexity_tier": "T3", "furigana": "予期[よき]しない事故[じこ]で、旅行[りょこう]の予定[よてい]が変[か]わってしまった。", "sentence_source": "generated"}, {"text": "事故の原因を調べるため、警察が来た。", "target_word": "事故", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を調[しら]べるため、警察[けいさつ]が来[き]た。", "sentence_source": "generated"}, {"text": "事故に巻き込まれた人たちは、幸い軽いけがですんだ。", "target_word": "事故", "complexity_tier": "T4", "furigana": "事故[じこ]に巻[ま]き込[こ]まれた人[ひと]たちは、幸[さいわ]い軽[かる]いけがですんだ。", "sentence_source": "generated"}, {"text": "彼は事故で足を痛め、しばらく仕事を休んだ。", "target_word": "事故", "complexity_tier": "T3", "furigana": "彼[かれ]は事故[じこ]で足[あし]を痛[いた]め、しばらく仕事[しごと]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "事故が起きた時の連絡先を、全員が知っておくべきだ。", "target_word": "事故", "complexity_tier": "T4", "furigana": "事故[じこ]が起[お]きた時[とき]の連絡先[れんらくさき]を、全員[ぜんいん]が知[し]っておくべきだ。", "sentence_source": "generated"}, {"text": "小さな事故でも、会社には必ず報告する。", "target_word": "事故", "complexity_tier": "T3", "furigana": "小[ちい]さな事故[じこ]でも、会社[かいしゃ]には必[かなら]ず報告[ほうこく]する。", "sentence_source": "generated"}, {"text": "雪の日の事故は、スピードの出しすぎが原因になることが多い。", "target_word": "事故", "complexity_tier": "T4", "furigana": "雪[ゆき]の日[ひ]の事故[じこ]は、スピードの出[だ]しすぎが原因[げんいん]になることが多[おお]い。", "sentence_source": "generated"}, {"text": "事故の現場には、花が置かれていた。", "target_word": "事故", "complexity_tier": "T3", "furigana": "事故[じこ]の現場[げんば]には、花[はな]が置[お]かれていた。", "sentence_source": "generated"}, {"text": "事故から一年が過ぎても、彼女はあの日のことを忘れられない。", "target_word": "事故", "complexity_tier": "T4", "furigana": "事故[じこ]から一年[いちねん]が過[す]ぎても、彼女[かのじょ]はあの日[ひ]のことを忘[わす]れられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事故", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "予期せず起こる悪い出来事や災難としての「事故」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41245, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事故", "is_correct": true, "explanation": "「事故が起き」は予期しない悪い出来事が起きたという意味で、道路が通れなくなった原因として自然。"}, {"text": "買い物", "is_correct": false, "explanation": "「買い物が起き」は不自然で、道路が通れなくなる原因にもならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は起きる出来事ではないので、「が起き」と続かない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は起きるものではなく、道路が通れなくなる理由にならない。"}], "explanations": {"事故": "「事故が起き」は予期しない悪い出来事が起きたという意味で、道路が通れなくなった原因として自然。", "買い物": "「買い物が起き」は不自然で、道路が通れなくなる原因にもならない。", "教科書": "教科書は起きる出来事ではないので、「が起き」と続かない。", "手紙": "手紙は起きるものではなく、道路が通れなくなる理由にならない。"}, "sentence_index": 0, "correct_answer": "事故"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社で横領の事故が起きて、社長が辞任した。", "explanation": "ここは〈事件〉の意味。事故は予期しない災難を指し、横領のような故意の犯罪には使わない。"}, {"text": "古いラジオの事故を、業者に直してもらった。", "explanation": "ここは〈故障〉の意味。機械の不具合は「故障」と言い、事故とは言わないので、修理を頼む文に合わない。"}, {"text": "彼が始めた新しい事故は、大成功した。", "explanation": "ここは〈事業〉の意味。事故は悪い出来事なので、新しく始めた事業が大成功したという文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41245, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事故", "is_correct": true, "explanation": "「小さな事故でも、会社には必ず報告する」は、事故の大小を問わず会社へ伝える文として自然。"}, {"text": "足音", "is_correct": false, "explanation": "足音は会社への報告の対象にならず、「小さな足音でも報告する」という文脈は合わない。"}, {"text": "朝食", "is_correct": false, "explanation": "朝食は報告すべき出来事ではなく、「会社には必ず報告する」と合わない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は報告の対象として文脈に合わず、「小さな切符」も不自然。"}], "explanations": {"事故": "「小さな事故でも、会社には必ず報告する」は、事故の大小を問わず会社へ伝える文として自然。", "足音": "足音は会社への報告の対象にならず、「小さな足音でも報告する」という文脈は合わない。", "朝食": "朝食は報告すべき出来事ではなく、「会社には必ず報告する」と合わない。", "切符": "切符は報告の対象として文脈に合わず、「小さな切符」も不自然。"}, "sentence_index": 6, "correct_answer": "事故"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷蔵庫の事故を修理業者に頼んだ。", "explanation": "ここは〈故障〉の意味。家電や機械の不具合は「故障」と言い、事故とは言わないので、修理を頼む文に合わない。"}, {"text": "彼女の事故は無事に成功した。", "explanation": "ここは〈手術〉の意味。事故は予期しない災難で、手術のように「成功した」と評価される出来事ではない。"}, {"text": "あのピアノの事故は大成功だった。", "explanation": "ここは〈演奏会〉の意味。事故は悪い出来事なので、演奏会の出来を「大成功」と評価する文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41245, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨夜、交差点で事故を起きて、救急車が来た。", "corrected_sentence": "昨夜、交差点で事故が起きて、救急車が来た。", "error_description": "「起きる」は自動詞なので、出来事が主語になり「事故が起きる」と言う。「事故を起きて」は誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41245, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事故を遭った車は、すぐに修理へ運ばれた。", "corrected_sentence": "事故に遭った車は、すぐに修理へ運ばれた。", "error_description": "「遭う」は「に」を取る。「事故を遭った」は誤りで、「事故に遭った」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41246, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」で、麺について述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "「麺を細くて」は麺を目的語にする形になり、形容詞の文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「麺に細くて」は成り立たず、位置を示す形にもならない。"}, {"text": "の", "is_correct": false, "explanation": "「麺の細くて」は修飾になり、文が続かない。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」で、麺について述べる文になる。", "を": "「麺を細くて」は麺を目的語にする形になり、形容詞の文が崩れる。", "に": "「麺に細くて」は成り立たず、位置を示す形にもならない。", "の": "「麺の細くて」は修飾になり、文が続かない。"}, "error_tags": {"を": "目的語", "に": "位置", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41246, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「麺と卵を」の「と」は、買った物を並べる並列の働きをする。"}, {"text": "へ", "is_correct": false, "explanation": "「麺へ」は方向を示すが、買い物の対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「麺から卵を買って」は起点の意味になり、文が不自然になる。"}, {"text": "が", "is_correct": false, "explanation": "「麺が」は主語になり、麺が買い物をするという不自然な意味になる。"}], "correct_answer": "と", "explanations": {"と": "「麺と卵を」の「と」は、買った物を並べる並列の働きをする。", "へ": "「麺へ」は方向を示すが、買い物の対象にはならない。", "から": "「麺から卵を買って」は起点の意味になり、文が不自然になる。", "が": "「麺が」は主語になり、麺が買い物をするという不自然な意味になる。"}, "error_tags": {"へ": "方向", "から": "起点", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41246, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゆでたり冷ましたりして食べる、細く長い食べ物。", "primary_collocate": null, "pronunciation": "めん", "ipa": "meɴ", "syllable_count": 2, "sentences": [{"text": "麺を茹でて、冷たい水で洗います。", "target_word": "麺", "complexity_tier": "T3", "furigana": "麺[めん]を茹[ゆ]でて、冷[つめ]たい水[みず]で洗[あら]います。", "sentence_source": "generated"}, {"text": "この店の麺は細くて、スープによく合う。", "target_word": "麺", "complexity_tier": "T3", "furigana": "この店[みせ]の麺[めん]は細[ほそ]くて、スープによく合[あ]う。", "sentence_source": "generated"}, {"text": "麺がのびる前に、早く食べてください。", "target_word": "麺", "complexity_tier": "T3", "furigana": "麺[めん]がのびる前[まえ]に、早[はや]く食[た]べてください。", "sentence_source": "generated"}, {"text": "弟は麺をすする音が大きくて、いつも注意される。", "target_word": "麺", "complexity_tier": "T3", "furigana": "弟[おとうと]は麺[めん]をすする音[おと]が大[おお]きくて、いつも注意[ちゅうい]される。", "sentence_source": "generated"}, {"text": "麺が少し硬いので、もう一分茹でましょう。", "target_word": "麺", "complexity_tier": "T3", "furigana": "麺[めん]が少[すこ]し硬[かた]いので、もう一分[いっぷん]茹[ゆ]でましょう。", "sentence_source": "generated"}, {"text": "昼ごはんは、麺に野菜をのせて食べた。", "target_word": "麺", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんは、麺[めん]に野菜[やさい]をのせて食[た]べた。", "sentence_source": "generated"}, {"text": "熱いので、麺をよく冷ましてから食べなさい。", "target_word": "麺", "complexity_tier": "T3", "furigana": "熱[あつ]いので、麺[めん]をよく冷[さ]ましてから食[た]べなさい。", "sentence_source": "generated"}, {"text": "スーパーで麺と卵を買って帰った。", "target_word": "麺", "complexity_tier": "T3", "furigana": "スーパーで麺[めん]と卵[たまご]を買[か]って帰[かえ]った。", "sentence_source": "generated"}, {"text": "この麺は長いので、切らずに食べるのがいいです。", "target_word": "麺", "complexity_tier": "T3", "furigana": "この麺[めん]は長[なが]いので、切[き]らずに食[た]べるのがいいです。", "sentence_source": "generated"}, {"text": "おなかがすいたので、麺を二人分作った。", "target_word": "麺", "complexity_tier": "T3", "furigana": "おなかがすいたので、麺[めん]を二人分[ふたりぶん]作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "麺", "label": "base"}], "register": "neutral", "sense_fingerprint": "めん: thin, long noodles as a food, handled while cooking and eating", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41246, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "麺", "is_correct": true, "explanation": "茹でて冷水で洗う食べ物で、空所にそのまま入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は茹でて冷水で洗う食材ではないので、文が成り立たない。"}, {"text": "醤油", "is_correct": false, "explanation": "醤油は茹でない調味料で、茹でて洗う文に合わない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳は茹でて冷水で洗う料理の材料ではないので合わない。"}], "explanations": {"麺": "茹でて冷水で洗う食べ物で、空所にそのまま入る。", "砂糖": "砂糖は茹でて冷水で洗う食材ではないので、文が成り立たない。", "醤油": "醤油は茹でない調味料で、茹でて洗う文に合わない。", "牛乳": "牛乳は茹でて冷水で洗う料理の材料ではないので合わない。"}, "sentence_index": 0, "correct_answer": "麺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この問題には、いろいろな麺がある。", "explanation": "ここは同じ読みの「面」（側面・点）の意味。食べ物の麺では、問題の側面という意味にならない。"}, {"text": "このシャツは麺でできていて、夏でも涼しい。", "explanation": "ここは同じ読みの「綿」（植物の繊維）の意味。麺は布の材料にならないので合わない。"}, {"text": "朝は麺を炊いて、味噌汁を作った。", "explanation": "ここは〈ご飯〉の意味。米を炊く料理で、麺は炊かずに茹でるので、炊く対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41246, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "麺", "is_correct": true, "explanation": "冷まして食べる食べ物で、空所にそのまま入る。"}, {"text": "氷", "is_correct": false, "explanation": "氷は冷まして食べる食品ではなく、文の意味が成り立たない。"}, {"text": "酢", "is_correct": false, "explanation": "酢は冷まして食べる料理の材料ではないので合わない。"}, {"text": "小麦粉", "is_correct": false, "explanation": "小麦粉は冷まして食べるものではないので、文が成り立たない。"}], "explanations": {"麺": "冷まして食べる食べ物で、空所にそのまま入る。", "氷": "氷は冷まして食べる食品ではなく、文の意味が成り立たない。", "酢": "酢は冷まして食べる料理の材料ではないので合わない。", "小麦粉": "小麦粉は冷まして食べるものではないので、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "麺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この畑では毎年、麺を育てている。", "explanation": "ここは〈小麦〉の意味。麦は育てるが、麺は育てる作物ではなく、小麦から作るものなので合わない。"}, {"text": "寒い日は麺を飲むと体が温まる。", "explanation": "ここは〈スープ〉の意味。飲むのは汁物で、麺は飲まずにすするので合わない。"}, {"text": "母は朝、家族のために麺を握った。", "explanation": "ここは〈おにぎり〉の意味。握るのは米で、麺は握らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41246, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "麺に茹でて、ざるにあげる。", "corrected_sentence": "麺を茹でて、ざるにあげる。", "error_description": "「茹でる」の対象は「を」で示す。「麺に」は誤りで、「麺を茹でて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41246, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熱い麺をなめて食べた。", "corrected_sentence": "熱い麺をすすって食べた。", "error_description": "麺を食べるときの動作は「すする」。「なめる」は麺には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
