INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41247, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小麦粉などをこねて細く切った食べ物。", "primary_collocate": null, "pronunciation": "めん", "ipa": "meɴ", "syllable_count": 2, "sentences": [{"text": "小麦粉をこねて、手で麺を作った。", "target_word": "麺", "complexity_tier": "T3", "furigana": "小麦粉[こむぎこ]をこねて、手[て]で麺[めん]を作[つく]った。", "sentence_source": "generated"}, {"text": "母は生地を薄くのばして、麺を細く切った。", "target_word": "麺", "complexity_tier": "T3", "furigana": "母[はは]は生地[きじ]を薄[うす]くのばして、麺[めん]を細[ほそ]く切[き]った。", "sentence_source": "generated"}, {"text": "この麺は小麦粉と水だけでできています。", "target_word": "麺", "complexity_tier": "T3", "furigana": "この麺[めん]は小麦粉[こむぎこ]と水[みず]だけでできています。", "sentence_source": "generated"}, {"text": "太い麺より、細い麺のほうが好きだ。", "target_word": "麺", "complexity_tier": "T3", "furigana": "太[ふと]い麺[めん]より、細[ほそ]い麺[めん]のほうが好[す]きだ。", "sentence_source": "generated"}, {"text": "祖父の店では、毎朝自分で麺を打っている。", "target_word": "麺", "complexity_tier": "T3", "furigana": "祖父[そふ]の店[みせ]では、毎朝[まいあさ]自分[じぶん]で麺[めん]を打[う]っている。", "sentence_source": "generated"}, {"text": "麺にスープをかけて、ねぎをのせた。", "target_word": "麺", "complexity_tier": "T3", "furigana": "麺[めん]にスープをかけて、ねぎをのせた。", "sentence_source": "generated"}, {"text": "この麺は味がしっかりしているので、スープなしでもおいしい。", "target_word": "麺", "complexity_tier": "T3", "furigana": "この麺[めん]は味[あじ]がしっかりしているので、スープなしでもおいしい。", "sentence_source": "generated"}, {"text": "冷たい麺は、夏にぴったりの食べ物です。", "target_word": "麺", "complexity_tier": "T3", "furigana": "冷[つめ]たい麺[めん]は、夏[なつ]にぴったりの食[た]べ物[もの]です。", "sentence_source": "generated"}, {"text": "麺を切るとき、包丁の幅をそろえるのが大切です。", "target_word": "麺", "complexity_tier": "T3", "furigana": "麺[めん]を切[き]るとき、包丁[ほうちょう]の幅[はば]をそろえるのが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "うどんもそばも、細長い麺の仲間です。", "target_word": "麺", "complexity_tier": "T3", "furigana": "うどんもそばも、細長[ほそなが]い麺[めん]の仲間[なかま]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "麺", "label": "base"}], "register": "neutral", "sense_fingerprint": "めん: food made by kneading wheat flour and cutting it into thin strips", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d4d027-9182-4543-9cde-8599e49e17ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41247, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "麺", "is_correct": true, "explanation": "小麦粉をこねて手で作る食べ物で、空所にそのまま入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は小麦粉をこねて手で作る食品ではないので、文が成り立たない。"}, {"text": "醤油", "is_correct": false, "explanation": "醤油は手で作る食品ではないので、文に合わない。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳は小麦粉をこねて作るものではないので合わない。"}], "explanations": {"麺": "小麦粉をこねて手で作る食べ物で、空所にそのまま入る。", "砂糖": "砂糖は小麦粉をこねて手で作る食品ではないので、文が成り立たない。", "醤油": "醤油は手で作る食品ではないので、文に合わない。", "牛乳": "牛乳は小麦粉をこねて作るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "麺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "問題を三つの麺から考えてみよう。", "explanation": "ここは同じ読みの「面」（角度・側面）の意味。食べ物の麺では、考える角度という意味にならない。"}, {"text": "この布団は麺でできている。", "explanation": "ここは同じ読みの「綿」（植物の繊維）の意味。麺は布団の材料にならないので合わない。"}, {"text": "朝は釜で麺を炊いた。", "explanation": "ここは〈ご飯〉の意味。米を釜で炊く料理で、麺は炊かずに茹でるので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41247, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "麺", "is_correct": true, "explanation": "味がしっかりしている食品で、空所にそのまま入る。"}, {"text": "氷", "is_correct": false, "explanation": "氷は味がないので、味がしっかりしているという文に合わない。"}, {"text": "水", "is_correct": false, "explanation": "水は味がしっかりした食品ではないので合わない。"}, {"text": "雪", "is_correct": false, "explanation": "雪は味がないので、味がしっかりしているという文に合わない。"}], "explanations": {"麺": "味がしっかりしている食品で、空所にそのまま入る。", "氷": "氷は味がないので、味がしっかりしているという文に合わない。", "水": "水は味がしっかりした食品ではないので合わない。", "雪": "雪は味がないので、味がしっかりしているという文に合わない。"}, "sentence_index": 6, "correct_answer": "麺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この畑では毎年、麺を育てている。", "explanation": "ここは〈小麦〉の意味。麦は育てる作物だが、麺は育てて得るものではないので合わない。"}, {"text": "寒い夜は麺を飲んで体を温めた。", "explanation": "ここは〈スープ〉の意味。麺は飲むものではなく、すするものなので、この文の使い方には合わない。"}, {"text": "コップに麺を注いだ。", "explanation": "ここは〈ジュース〉の意味。注ぐのは液体で、麺は注げないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41247, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は毎朝、自分で麺が打つ。", "corrected_sentence": "父は毎朝、自分で麺を打つ。", "error_description": "「打つ」の目的語は「を」で示す。「麺が打つ」では麺が動作主になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41247, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゆでた麺を剥いて食べた。", "corrected_sentence": "ゆでた麺をすすって食べた。", "error_description": "麺を食べるときの動作は「すする」。「剥く」は皮をむく動作で、麺には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da667aa5-779a-4238-964c-25841c968713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41248, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「茶色になるまで」の〈まで〉。変化の終点を示す。"}, {"text": "に", "is_correct": false, "explanation": "「茶色になるに」は続かず、変化の終点を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、状態変化の終わりを表す位置には入らない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。ここは変化の終点を示す位置なので合わない。"}], "correct_answer": "まで", "explanations": {"まで": "「茶色になるまで」の〈まで〉。変化の終点を示す。", "に": "「茶色になるに」は続かず、変化の終点を示せない。", "へ": "〈へ〉は方向を示すので、状態変化の終わりを表す位置には入らない。", "が": "〈が〉は主語を示す。ここは変化の終点を示す位置なので合わない。"}, "error_tags": {"に": "状態変化の終点を示さない", "へ": "方向を示す", "が": "主語を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41248, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「肉を炒めて」の〈を〉。炒める対象（目的語）を示す。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示す。「肉で炒めて」は材料を道具扱いする不自然な文になる。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞を連ねる助詞で、動詞の目的語には使えない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示す。ここで比べる対象はないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「肉を炒めて」の〈を〉。炒める対象（目的語）を示す。", "で": "〈で〉は手段や場所を示す。「肉で炒めて」は材料を道具扱いする不自然な文になる。", "の": "〈の〉は名詞を連ねる助詞で、動詞の目的語には使えない。", "より": "〈より〉は比較を示す。ここで比べる対象はないので合わない。"}, "error_tags": {"で": "手段・場所", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41248, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "食べ物を、油や熱で、よくかき混ぜながら焼くこと。", "primary_collocate": null, "pronunciation": "いためる", "ipa": "itameɾɯ", "syllable_count": 4, "sentences": [{"text": "野菜をフライパンで炒めます。", "target_word": "炒めます", "complexity_tier": "T3", "furigana": "野菜[やさい]をフライパンで炒[いた]めます。", "sentence_source": "generated"}, {"text": "玉ねぎを茶色になるまで炒めた。", "target_word": "炒めた", "complexity_tier": "T3", "furigana": "玉[たま]ねぎを茶色[ちゃいろ]になるまで炒[いた]めた。", "sentence_source": "generated"}, {"text": "強い火で、肉をさっと炒めるとおいしい。", "target_word": "炒める", "complexity_tier": "T3", "furigana": "強[つよ]い火[ひ]で、肉[にく]をさっと炒[いた]めるとおいしい。", "sentence_source": "generated"}, {"text": "母はにんじんとピーマンを炒めている。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "母[はは]はにんじんとピーマンを炒[いた]めている。", "sentence_source": "generated"}, {"text": "ごはんを炒めて、チャーハンを作った。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "ごはんを炒[いた]めて、チャーハンを作[つく]った。", "sentence_source": "generated"}, {"text": "油が熱くなってから、卵を炒めてください。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "油[あぶら]が熱[あつ]くなってから、卵[たまご]を炒[いた]めてください。", "sentence_source": "generated"}, {"text": "野菜は長く炒めると、柔らかくなります。", "target_word": "炒める", "complexity_tier": "T3", "furigana": "野菜[やさい]は長[なが]く炒[いた]めると、柔[やわ]らかくなります。", "sentence_source": "generated"}, {"text": "先に肉を炒めて、そのあとに野菜を入れる。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "先[さき]に肉[にく]を炒[いた]めて、そのあとに野菜[やさい]を入[い]れる。", "sentence_source": "generated"}, {"text": "にんにくを炒めると、いい香りがしてきた。", "target_word": "炒める", "complexity_tier": "T3", "furigana": "にんにくを炒[いた]めると、いい香[かお]りがしてきた。", "sentence_source": "generated"}, {"text": "休みの日は、自分で麺を炒めて昼ごはんにする。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、自分[じぶん]で麺[めん]を炒[いた]めて昼[ひる]ごはんにする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "炒めます", "label": "丁寧形"}, {"form": "炒めた", "label": "過去形"}, {"form": "炒めない", "label": "否定形"}, {"form": "炒めて", "label": "て形"}, {"form": "炒めれば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "油と熱で混ぜながら焼いて調理する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41248, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "炒めます", "is_correct": true, "explanation": "〈炒める〉の丁寧形。油と熱でかき混ぜて調理する意味で、フライパンの野菜に合う。"}, {"text": "剥きます", "is_correct": false, "explanation": "〈剥く〉は皮をむくこと。野菜を『フライパンで』皮をむくのは文として成り立たない。"}, {"text": "凍らせます", "is_correct": false, "explanation": "〈凍らせる〉は冷やして固めること。フライパンで加熱する文脈と矛盾する。"}, {"text": "沸かします", "is_correct": false, "explanation": "〈沸かす〉は水などを煮立たせること。野菜をフライパンで沸かすという組み合わせは不自然。"}], "explanations": {"炒めます": "〈炒める〉の丁寧形。油と熱でかき混ぜて調理する意味で、フライパンの野菜に合う。", "剥きます": "〈剥く〉は皮をむくこと。野菜を『フライパンで』皮をむくのは文として成り立たない。", "凍らせます": "〈凍らせる〉は冷やして固めること。フライパンで加熱する文脈と矛盾する。", "沸かします": "〈沸かす〉は水などを煮立たせること。野菜をフライパンで沸かすという組み合わせは不自然。"}, "sentence_index": 0, "correct_answer": "炒めます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食パンを炒めてトーストにした。", "explanation": "ここは〈トーストする〉の意味。炒めるは油で具材をかき混ぜながら火を通す調理なので、食パンに焼き色をつけてトーストにする用途には合わない。"}, {"text": "天ぷらを炒めて、油から取り出した。", "explanation": "ここは〈揚げる〉の意味。炒めるは鍋で具材をかき混ぜながら火を通すことで、たっぷりの油で揚げる天ぷらには使わない。"}, {"text": "大根をだし汁で炒めて、味をしみ込ませた。", "explanation": "ここは〈煮る〉の意味。炒めるは油で混ぜながら加熱することで、だし汁で味を含ませる煮物の調理には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41248, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炒める", "is_correct": true, "explanation": "〈炒める〉は油と熱でかき混ぜて調理すること。長く加熱すると柔らかくなる文脈に合う。"}, {"text": "結ぶ", "is_correct": false, "explanation": "〈結ぶ〉は紐などをくくること。野菜を長く結んで柔らかくなるという文にはならない。"}, {"text": "眺める", "is_correct": false, "explanation": "〈眺める〉は見つめること。野菜を長く眺めても柔らかくはならない。"}, {"text": "磨く", "is_correct": false, "explanation": "〈磨く〉は表面をこすって光らせること。野菜を磨いて柔らかくなるという文には合わない。"}], "explanations": {"炒める": "〈炒める〉は油と熱でかき混ぜて調理すること。長く加熱すると柔らかくなる文脈に合う。", "結ぶ": "〈結ぶ〉は紐などをくくること。野菜を長く結んで柔らかくなるという文にはならない。", "眺める": "〈眺める〉は見つめること。野菜を長く眺めても柔らかくはならない。", "磨く": "〈磨く〉は表面をこすって光らせること。野菜を磨いて柔らかくなるという文には合わない。"}, "sentence_index": 6, "correct_answer": "炒める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "せいろで魚を炒めていた。", "explanation": "ここは〈蒸す〉の意味。炒めるは油でかき混ぜて調理することで、せいろで蒸す料理には使わない。"}, {"text": "卵を炒めて、殻をむいた。", "explanation": "ここは〈茹でる〉の意味。殻をむく工程は茹でた卵の話で、油で混ぜながら調理する炒めるとは合わない。"}, {"text": "鶏肉をオーブンで炒めた。", "explanation": "ここは〈ローストする〉の意味。炒めるは鍋やフライパンでかき混ぜて調理するので、オーブンで焼く料理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41248, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "野菜を炒めに、器に盛った。", "corrected_sentence": "野菜を炒めて、器に盛った。", "error_description": "〈炒めに〉は〈行く・来る〉などの前の目的用法に限られる。ここは次の動作〈器に盛る〉へつなぐ〈て形〉が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "炒めた", "is_correct": true, "explanation": "過去形。玉ねぎを茶色にした完了の文の述語として正しい。"}, {"text": "炒めない", "is_correct": false, "explanation": "否定形。完了した動作を否定することになり、文の内容と合わない。"}, {"text": "炒めて", "is_correct": false, "explanation": "て形。文末の述語にはならず、「〜た」で終わる文に入らない。"}, {"text": "炒めれば", "is_correct": false, "explanation": "仮定形。条件節になるため、完結した述語としては使えない。"}], "correct_form": "炒めた", "base_form": "炒める", "form_label": "過去形", "sentence_index": 1, "explanations": {"炒めた": "過去形。玉ねぎを茶色にした完了の文の述語として正しい。", "炒めない": "否定形。完了した動作を否定することになり、文の内容と合わない。", "炒めて": "て形。文末の述語にはならず、「〜た」で終わる文に入らない。", "炒めれば": "仮定形。条件節になるため、完結した述語としては使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41248, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中華鍋で肉に炒めて、野菜と合わせる。", "corrected_sentence": "中華鍋で肉を炒めて、野菜と合わせる。", "error_description": "〈炒める〉の目的語は〈を〉で示す。〈肉に炒めて〉ではなく〈肉を炒めて〉が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "炒めて", "is_correct": true, "explanation": "て形。「先に肉を炒めて、そのあとに入れる」と動作を連続させる形で正しい。"}, {"text": "炒める", "is_correct": false, "explanation": "辞書形。「炒める、そのあとに」とは続かず、て形の代わりにはならない。"}, {"text": "炒めます", "is_correct": false, "explanation": "丁寧形。文の途中で「、」の前に置く形ではなく、普通体の文中の動作のつなぎには使えない。"}, {"text": "炒めよう", "is_correct": false, "explanation": "意志形。「先に肉を炒めよう」と誘う意味になり、手順を述べる文と合わない。"}], "correct_form": "炒めて", "base_form": "炒める", "form_label": "て形", "sentence_index": 7, "explanations": {"炒めて": "て形。「先に肉を炒めて、そのあとに入れる」と動作を連続させる形で正しい。", "炒める": "辞書形。「炒める、そのあとに」とは続かず、て形の代わりにはならない。", "炒めます": "丁寧形。文の途中で「、」の前に置く形ではなく、普通体の文中の動作のつなぎには使えない。", "炒めよう": "意志形。「先に肉を炒めよう」と誘う意味になり、手順を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41249, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "正解。「炒めてから」と順序を示して、「キャベツを入れます」につながる。"}, {"text": "に", "is_correct": false, "explanation": "「炒めてに」は成り立たず、位置や時点を示す形としても文が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「炒めてを」は対象を示す形として成り立たず、文の流れが崩れる。"}, {"text": "が", "is_correct": false, "explanation": "「炒めてが」は主語を示す形として成り立たず、後の文とつながらない。"}], "correct_answer": "から", "explanations": {"から": "正解。「炒めてから」と順序を示して、「キャベツを入れます」につながる。", "に": "「炒めてに」は成り立たず、位置や時点を示す形としても文が通らない。", "を": "「炒めてを」は対象を示す形として成り立たず、文の流れが崩れる。", "が": "「炒めてが」は主語を示す形として成り立たず、後の文とつながらない。"}, "error_tags": {"に": "位置・時点", "を": "対象", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41249, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41249, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "食材を油をひいた鍋やフライパンに入れ、熱を加えながらかき混ぜて調理すること。", "primary_collocate": null, "pronunciation": "いためる", "ipa": "itameɾɯ", "syllable_count": 4, "sentences": [{"text": "フライパンに油をひいて、野菜を炒めます。", "target_word": "炒めます", "complexity_tier": "T3", "furigana": "フライパンに油[あぶら]をひいて、野菜[やさい]を炒[いた]めます。", "sentence_source": "generated"}, {"text": "豚肉を先に炒めてから、キャベツを入れます。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "豚肉[ぶたにく]を先[さき]に炒[いた]めてから、キャベツを入[い]れます。", "sentence_source": "generated"}, {"text": "玉ねぎが茶色になるまで、弱い火でゆっくり炒めました。", "target_word": "炒めました", "complexity_tier": "T3", "furigana": "玉[たま]ねぎが茶色[ちゃいろ]になるまで、弱[よわ]い火[ひ]でゆっくり炒[いた]めました。", "sentence_source": "generated"}, {"text": "強い火で短く炒めると、野菜がやわらかくなりすぎません。", "target_word": "炒める", "complexity_tier": "T3", "furigana": "強[つよ]い火[ひ]で短[みじか]く炒[いた]めると、野菜[やさい]がやわらかくなりすぎません。", "sentence_source": "generated"}, {"text": "卵を炒めて、あとでご飯と混ぜました。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "卵[たまご]を炒[いた]めて、あとでご飯[はん]と混[ま]ぜました。", "sentence_source": "generated"}, {"text": "母はにんにくを油で炒めて、いい香りを出します。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "母[はは]はにんにくを油[あぶら]で炒[いた]めて、いい香[かお]りを出[だ]します。", "sentence_source": "generated"}, {"text": "野菜は炒めるより、蒸すほうが体にいいと言われます。", "target_word": "炒める", "complexity_tier": "T3", "furigana": "野菜[やさい]は炒[いた]めるより、蒸[む]すほうが体[からだ]にいいと言[い]われます。", "sentence_source": "generated"}, {"text": "焦げないように、木のへらで混ぜながら炒めてください。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "焦[こ]げないように、木[き]のへらで混[ま]ぜながら炒[いた]めてください。", "sentence_source": "generated"}, {"text": "今日は時間がないので、冷蔵庫の野菜を炒めて食べました。", "target_word": "炒めて", "complexity_tier": "T3", "furigana": "今日[きょう]は時間[じかん]がないので、冷蔵庫[れいぞうこ]の野菜[やさい]を炒[いた]めて食[た]べました。", "sentence_source": "generated"}, {"text": "肉を長く炒めたので、かたくなってしまいました。", "target_word": "炒めた", "complexity_tier": "T3", "furigana": "肉[にく]を長[なが]く炒[いた]めたので、かたくなってしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "炒める", "label": "終止形"}, {"form": "炒めます", "label": "丁寧形"}, {"form": "炒めた", "label": "過去形"}, {"form": "炒めて", "label": "て形"}, {"form": "炒めない", "label": "否定形"}, {"form": "炒めれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "炒める: 油を使い、鍋やフライパンで混ぜながら加熱する調理の動詞(いためる。傷める・痛めるとは別語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41249, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "炒めます", "is_correct": true, "explanation": "正解。油をひいたフライパンで野菜を熱しながら混ぜる動作を表し、文の中で自然に続く。"}, {"text": "注ぎます", "is_correct": false, "explanation": "注ぐは液体を入れる動詞で、野菜には使わないので文が成り立たない。"}, {"text": "溶かします", "is_correct": false, "explanation": "溶かすは固形物を液体にする動詞で、野菜を溶かすとは言わない。"}, {"text": "沸かします", "is_correct": false, "explanation": "沸かすは水などを熱して沸騰させる動詞で、野菜を沸かすとは言わないので合わない。"}], "explanations": {"炒めます": "正解。油をひいたフライパンで野菜を熱しながら混ぜる動作を表し、文の中で自然に続く。", "注ぎます": "注ぐは液体を入れる動詞で、野菜には使わないので文が成り立たない。", "溶かします": "溶かすは固形物を液体にする動詞で、野菜を溶かすとは言わない。", "沸かします": "沸かすは水などを熱して沸騰させる動詞で、野菜を沸かすとは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "炒めます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大切な家具を炒めないように、布で包みます。", "explanation": "ここは〈傷める〉の意味。炒めるは調理の動詞で、家具を損なう意味では使わないので合わない。"}, {"text": "オーブンで野菜を炒めて、ごはんにしました。", "explanation": "ここは〈焼く〉の意味。炒めるは鍋やフライパンで具材を混ぜながら加熱する調理なので、オーブンでじっくり焼く場合には合わない。"}, {"text": "腰を炒めて、しばらく重い荷物を持てません。", "explanation": "ここは〈痛める〉の意味。炒めるは調理の動詞で、体の部位を傷める意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41249, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炒める", "is_correct": true, "explanation": "正解。「〜より、蒸す」と比べる調理法として自然に入る。"}, {"text": "塗る", "is_correct": false, "explanation": "塗るは表面に液体を広げる動作で、野菜の調理法としては比べる文に入らない。"}, {"text": "編む", "is_correct": false, "explanation": "編むは糸や布を組む動詞で、「野菜は編むより」とは言えない。"}, {"text": "結ぶ", "is_correct": false, "explanation": "結ぶはひもや糸をつなぐ動詞で、野菜の調理法として比べる文には入らない。"}], "explanations": {"炒める": "正解。「〜より、蒸す」と比べる調理法として自然に入る。", "塗る": "塗るは表面に液体を広げる動作で、野菜の調理法としては比べる文に入らない。", "編む": "編むは糸や布を組む動詞で、「野菜は編むより」とは言えない。", "結ぶ": "結ぶはひもや糸をつなぐ動詞で、野菜の調理法として比べる文には入らない。"}, "sentence_index": 6, "correct_answer": "炒める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷めたスープを炒めて、もう一度飲みました。", "explanation": "ここは〈温める〉の意味。炒めるは具材を鍋で混ぜながら加熱する調理で、液体を温め直す意味では使わないので合わない。"}, {"text": "やかんで水を炒めて、お茶を入れました。", "explanation": "ここは〈沸かす〉の意味。炒めるは鍋やフライパンで具材を混ぜる調理で、やかんで水を沸騰させる意味では使わないので合わない。"}, {"text": "トーストを炒めてしまい、苦い味になりました。", "explanation": "ここは〈焦がす〉の意味。炒めるは材料に火を通す調理で、焦がして苦くする意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41249, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ひき肉をフライパンで炒めに、味をつけます。", "corrected_sentence": "ひき肉をフライパンで炒めて、味をつけます。", "error_description": "正しくは「炒めて」（て形）。「炒めに」は「炒める」の連用形に「に」を付けた誤った形で、「味をつけます」と続けられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "炒めて", "is_correct": true, "explanation": "正解。「先に炒めてから」と順序をつなぐて形で、文の流れに合う。"}, {"text": "炒めよう", "is_correct": false, "explanation": "意志形で、「炒めようから」とは続かず、順序をつなぐ文に入らない。"}, {"text": "炒めれば", "is_correct": false, "explanation": "仮定形で、「炒めればから」とは続かず、この文の順序の流れに合わない。"}, {"text": "炒めろ", "is_correct": false, "explanation": "命令形で、「炒めろから」とは続かず、順序をつなぐ文に入らない。"}], "correct_form": "炒めて", "base_form": "炒める", "form_label": "て形", "sentence_index": 1, "explanations": {"炒めて": "正解。「先に炒めてから」と順序をつなぐて形で、文の流れに合う。", "炒めよう": "意志形で、「炒めようから」とは続かず、順序をつなぐ文に入らない。", "炒めれば": "仮定形で、「炒めればから」とは続かず、この文の順序の流れに合わない。", "炒めろ": "命令形で、「炒めろから」とは続かず、順序をつなぐ文に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41249, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ピーマンを炒めるて、塩を少し入れます。", "corrected_sentence": "ピーマンを炒めて、塩を少し入れます。", "error_description": "正しくは「炒めて」（て形）。「炒めるて」は辞書形に「て」を付けた誤った形で、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "炒めて", "is_correct": true, "explanation": "正解。「炒めてください」と依頼をつなぐて形で、文の流れに合う。"}, {"text": "炒めます", "is_correct": false, "explanation": "丁寧形で、「炒めますください」とはならず、依頼の形に合わない。"}, {"text": "炒めた", "is_correct": false, "explanation": "過去形で、「たてください」とは続かず依頼の形に合わない。"}, {"text": "炒めず", "is_correct": false, "explanation": "否定の連用形で、「ずてください」は成り立たない。"}], "correct_form": "炒めて", "base_form": "炒める", "form_label": "て形", "sentence_index": 7, "explanations": {"炒めて": "正解。「炒めてください」と依頼をつなぐて形で、文の流れに合う。", "炒めます": "丁寧形で、「炒めますください」とはならず、依頼の形に合わない。", "炒めた": "過去形で、「たてください」とは続かず依頼の形に合わない。", "炒めず": "否定の連用形で、「ずてください」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
