INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41251, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「腸の壁」として、壁の所在を示す「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「腸を壁から」は目的語になり、壁から吸収される文の場所の関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「腸に壁から」は帰着を表すが、「壁から吸収される」と続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「腸へ壁から」は壁の所在と合わず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「腸の壁」として、壁の所在を示す「の」が正しい。", "を": "「腸を壁から」は目的語になり、壁から吸収される文の場所の関係が成り立たない。", "に": "「腸に壁から」は帰着を表すが、「壁から吸収される」と続かず不自然。", "へ": "「へ」は方向を表す。「腸へ壁から」は壁の所在と合わず、不自然。"}, "error_tags": {"を": "目的語の格", "に": "位置・帰着", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41251, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "消化管の一部で、栄養の吸収や便の形成に関わる器官。食物の消化と吸収、免疫機能にも重要な役割を果たす。", "primary_collocate": null, "pronunciation": "ちょう", "ipa": "tɕoː", "syllable_count": 2, "sentences": [{"text": "腸は、栄養の吸収と便の形成にかかわる器官だ。", "target_word": "腸", "complexity_tier": "T3", "furigana": "腸[ちょう]は、栄養[えいよう]の吸収[きゅうしゅう]と便[べん]の形成[けいせい]にかかわる器官[きかん]だ。", "sentence_source": "generated"}, {"text": "腸には、体の免疫細胞の多くが集まっている。", "target_word": "腸", "complexity_tier": "T3", "furigana": "腸[ちょう]には、体[からだ]の免疫細胞[めんえきさいぼう]の多[おお]くが集[あつ]まっている。", "sentence_source": "generated"}, {"text": "食物繊維は、腸の働きを助けて便通を整える。", "target_word": "腸", "complexity_tier": "T3", "furigana": "食物繊維[しょくもつせんい]は、腸[ちょう]の働[はたら]きを助[たす]けて便通[べんつう]を整[ととの]える。", "sentence_source": "generated"}, {"text": "手術のあと、腸の動きが戻るまで食事を控えた。", "target_word": "腸", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]のあと、腸[ちょう]の動[うご]きが戻[もど]るまで食事[しょくじ]を控[ひか]えた。", "sentence_source": "generated"}, {"text": "腸にすむ細菌が、消化を手伝っている。", "target_word": "腸", "complexity_tier": "T3", "furigana": "腸[ちょう]にすむ細菌[さいきん]が、消化[しょうか]を手伝[てつだ]っている。", "sentence_source": "generated"}, {"text": "検査で、腸に小さなポリープが見つかった。", "target_word": "腸", "complexity_tier": "T3", "furigana": "検査[けんさ]で、腸[ちょう]に小[ちい]さなポリープが見[み]つかった。", "sentence_source": "generated"}, {"text": "ストレスが強いと、腸の働きが乱れることがある。", "target_word": "腸", "complexity_tier": "T3", "furigana": "ストレスが強[つよ]いと、腸[ちょう]の働[はたら]きが乱[みだ]れることがある。", "sentence_source": "generated"}, {"text": "腸の壁から、水分と栄養分が吸収される。", "target_word": "腸", "complexity_tier": "T3", "furigana": "腸[ちょう]の壁[かべ]から、水分[すいぶん]と栄養分[えいようぶん]が吸収[きゅうしゅう]される。", "sentence_source": "generated"}, {"text": "医師は、腸の炎症を抑える薬を出した。", "target_word": "腸", "complexity_tier": "T3", "furigana": "医師[いし]は、腸[ちょう]の炎症[えんしょう]を抑[おさ]える薬[くすり]を出[だ]した。", "sentence_source": "generated"}, {"text": "胃で消化された食べ物は、腸でさらに分解される。", "target_word": "腸", "complexity_tier": "T3", "furigana": "胃[い]で消化[しょうか]された食[た]べ物[もの]は、腸[ちょう]でさらに分解[ぶんかい]される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "腸", "label": "基本形"}], "register": "formal", "sense_fingerprint": "消化管の一部で、栄養の吸収・便の形成・免疫に関わる器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8104bb-358f-42db-9a79-a76080280153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41251, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肺", "is_correct": false, "explanation": "肺は呼吸の器官で、栄養の吸収や便の形成にはかかわらないので合わない。"}, {"text": "腸", "is_correct": true, "explanation": "栄養の吸収と便の形成にかかわる消化管の器官なので、「腸は」で文が成り立つ。"}, {"text": "骨", "is_correct": false, "explanation": "骨は体を支える器官で、栄養の吸収や便の形成とは関係がないので合わない。"}, {"text": "耳", "is_correct": false, "explanation": "耳は音を聞く器官で、栄養の吸収や便の形成にはかかわらないので合わない。"}], "explanations": {"肺": "肺は呼吸の器官で、栄養の吸収や便の形成にはかかわらないので合わない。", "腸": "栄養の吸収と便の形成にかかわる消化管の器官なので、「腸は」で文が成り立つ。", "骨": "骨は体を支える器官で、栄養の吸収や便の形成とは関係がないので合わない。", "耳": "耳は音を聞く器官で、栄養の吸収や便の形成にはかかわらないので合わない。"}, "sentence_index": 0, "correct_answer": "腸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になると、庭に腸が飛んでいる。", "explanation": "ここは〈蝶〉（同じ「ちょう」）の意味。腸は消化器官で、庭を飛ぶ虫には使わない。"}, {"text": "腸は、思考と記憶をつかさどる器官だ。", "explanation": "思考や記憶をつかさどるのは脳で、腸にはその働きがないので合わない。"}, {"text": "腸は、血液を全身に送り出すポンプの役割を果たす。", "explanation": "血液を全身に送り出すポンプの役割は心臓が担うもので、腸にはその役割がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41251, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爪", "is_correct": false, "explanation": "爪は体の働きを担う器官ではないので、「働きが乱れる」の主語には合わない。"}, {"text": "髪", "is_correct": false, "explanation": "髪は体の働きを担う器官ではなく、「働きが乱れる」とは言わないので合わない。"}, {"text": "腸", "is_correct": true, "explanation": "ストレスで働きが乱れる消化器官なので、「腸の働きが乱れる」として自然に入る。"}, {"text": "まつげ", "is_correct": false, "explanation": "まつげは目を守る部位で、「働きが乱れる」と言う主語としては合わない。"}], "explanations": {"爪": "爪は体の働きを担う器官ではないので、「働きが乱れる」の主語には合わない。", "髪": "髪は体の働きを担う器官ではなく、「働きが乱れる」とは言わないので合わない。", "腸": "ストレスで働きが乱れる消化器官なので、「腸の働きが乱れる」として自然に入る。", "まつげ": "まつげは目を守る部位で、「働きが乱れる」と言う主語としては合わない。"}, "sentence_index": 6, "correct_answer": "腸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "腸は、血糖値を下げるインスリンを出す。", "explanation": "インスリンを分泌する器官は膵臓で、腸の働きではないので合わない。"}, {"text": "腸は、汗をかいて体温を下げる。", "explanation": "汗をかいて体温を調節するのは皮膚で、腸には使わない。"}, {"text": "彼はチームの腸として、選手を励ました。", "explanation": "ここは〈長〉（リーダー）の意味。同じ「ちょう」でも腸は消化器官なので、チームの指導者を指す文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41251, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "腸を、免疫細胞が多く集まっている。", "corrected_sentence": "腸には、免疫細胞が多く集まっている。", "error_description": "「集まっている」は自動詞で、集まる場所は「に」で示す。「腸を」は目的語の格で、場所を表す文には合わず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41251, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食べ物の水分は、腸を壁から吸収される。", "corrected_sentence": "食べ物の水分は、腸の壁から吸収される。", "error_description": "「腸の壁から」は、壁がある場所を示す「の」が正しい。「腸を」は目的語の格で、場所を表す文には合わず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41252, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「学ぶ」の対象を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」では主語になってしまい、「学ぶ」の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」では所有や修飾を示すため、「学ぶ」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「学ぶ」の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「学ぶ」の対象を示す「を」が入る。", "が": "「が」では主語になってしまい、「学ぶ」の対象にならない。", "の": "「の」では所有や修飾を示すため、「学ぶ」の対象にはならない。", "へ": "「へ」は方向を示すため、「学ぶ」の対象を表せない。"}, "error_tags": {"が": "subject", "の": "modifier", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41252, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ファーマコゲノミクスのおかげで」の「の」で、「おかげ」を修飾する。"}, {"text": "に", "is_correct": false, "explanation": "「にお陰で」とは言わず、「のおかげで」が自然な形。"}, {"text": "と", "is_correct": false, "explanation": "「と」では並列や相手を示すため、「おかげ」とは結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」では、「おかげで」とは結びつかない。"}], "correct_answer": "の", "explanations": {"の": "「ファーマコゲノミクスのおかげで」の「の」で、「おかげ」を修飾する。", "に": "「にお陰で」とは言わず、「のおかげで」が自然な形。", "と": "「と」では並列や相手を示すため、「おかげ」とは結びつかない。", "より": "比較を示す「より」では、「おかげで」とは結びつかない。"}, "error_tags": {"に": "target", "と": "with", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41252, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の体のちがいが、くすりのききかたにどうかかわるかをしらべるがくもんです。", "primary_collocate": null, "pronunciation": "ふぁーまこげのみくす", "ipa": "ɸaːmakoɡenomikɯsɯ", "syllable_count": 9, "sentences": [{"text": "ファーマコゲノミクスは、薬のききかたを調べる学問です。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスは、薬[くすり]のききかたを調[しら]べる学問[がくもん]です。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスを学ぶために、大学に入りました。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスを学[まな]ぶために、大学[だいがく]に入[はい]りました。", "sentence_source": "generated"}, {"text": "人によって薬の効果が違う理由を、ファーマコゲノミクスで調べます。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "人[ひと]によって薬[くすり]の効果[こうか]が違[ちが]う理由[りゆう]を、ファーマコゲノミクスで調[しら]べます。", "sentence_source": "generated"}, {"text": "兄はファーマコゲノミクスの研究をしています。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "兄[あに]はファーマコゲノミクスの研究[けんきゅう]をしています。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスの授業は、むずかしいですが面白いです。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスの授業[じゅぎょう]は、むずかしいですが面白[おもしろ]いです。", "sentence_source": "generated"}, {"text": "体のちがいを調べるファーマコゲノミクスが、今注目されています。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "体[からだ]のちがいを調[しら]べるファーマコゲノミクスが、今[いま]注目[ちゅうもく]されています。", "sentence_source": "generated"}, {"text": "医者は、ファーマコゲノミクスの本を読んで勉強しました。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、ファーマコゲノミクスの本[ほん]を読[よ]んで勉強[べんきょう]しました。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスのおかげで、薬の選び方が変わってきました。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスのおかげで、薬[くすり]の選[えら]び方[かた]が変[か]わってきました。", "sentence_source": "generated"}, {"text": "先生は、ファーマコゲノミクスについてやさしく話してくれました。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ファーマコゲノミクスについてやさしく話[はな]してくれました。", "sentence_source": "generated"}, {"text": "この大学には、ファーマコゲノミクスを研究する研究室があります。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "この大学[だいがく]には、ファーマコゲノミクスを研究[けんきゅう]する研究室[けんきゅうしつ]があります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファーマコゲノミクス", "label": "基本形"}], "register": "専門用語（丁寧体）", "sense_fingerprint": "体質の違いと薬のききかたの関係を調べる学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41252, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ファーマコゲノミクス", "is_correct": true, "explanation": "薬のききかたを調べる学問を指し、「学問です」と説明する文に合う。"}, {"text": "天文学", "is_correct": false, "explanation": "星や宇宙を調べる学問で、薬のききかたは対象にしない。"}, {"text": "心理学", "is_correct": false, "explanation": "人の心や行動を調べる学問で、薬のききかたは対象にしない。"}, {"text": "地質学", "is_correct": false, "explanation": "大地の成り立ちを調べる学問で、薬のききかたは対象にしない。"}], "explanations": {"ファーマコゲノミクス": "薬のききかたを調べる学問を指し、「学問です」と説明する文に合う。", "天文学": "星や宇宙を調べる学問で、薬のききかたは対象にしない。", "心理学": "人の心や行動を調べる学問で、薬のききかたは対象にしない。", "地質学": "大地の成り立ちを調べる学問で、薬のききかたは対象にしない。"}, "sentence_index": 0, "correct_answer": "ファーマコゲノミクス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ファーマコゲノミクスでは、家族の病気がどう遺伝するかを調べます。", "explanation": "ここは「遺伝学」の意味。この語は薬の効果を個人ごとに予測する学問分野で、遺伝の仕組みを調べる分野ではない。"}, {"text": "薬をもらいに、ファーマコゲノミクスへ行きました。", "explanation": "ここは「薬局」の意味。この語は学問分野で、行く場所ではない。"}, {"text": "兄はファーマコゲノミクスを一箱買いました。", "explanation": "ここは〈商品〉の意味。学問分野は箱で買える物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41252, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ファーマコゲノミクス", "is_correct": true, "explanation": "本の内容として学問名が入ると、医者が勉強した内容として自然に成り立つ。"}, {"text": "給料", "is_correct": false, "explanation": "お金に関する語で、学問の本の内容としては合わない。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の入り口を表す語で、本の内容としては合わない。"}, {"text": "交差点", "is_correct": false, "explanation": "道路の場所を表す語で、本の内容としては合わない。"}], "explanations": {"ファーマコゲノミクス": "本の内容として学問名が入ると、医者が勉強した内容として自然に成り立つ。", "給料": "お金に関する語で、学問の本の内容としては合わない。", "玄関": "建物の入り口を表す語で、本の内容としては合わない。", "交差点": "道路の場所を表す語で、本の内容としては合わない。"}, "sentence_index": 6, "correct_answer": "ファーマコゲノミクス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ファーマコゲノミクスに新しい機械が入りました。", "explanation": "ここは〈研究所〉の意味。この語は学問分野で、機械が入る施設ではない。"}, {"text": "ファーマコゲノミクスに乗りました。", "explanation": "ここは〈体重計〉の意味。この語は学問分野で、人が乗れる道具ではない。"}, {"text": "ファーマコゲノミクスを沸かしました。", "explanation": "ここは〈湯〉の意味。学問分野は沸かせる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41252, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はファーマコゲノミクスに研究しています。", "corrected_sentence": "私はファーマコゲノミクスを研究しています。", "error_description": "「研究する」の対象は「を」で示す。「に」を使ったため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41252, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ファーマコゲノミクスが学ぶ学生が増えています。", "corrected_sentence": "ファーマコゲノミクスを学ぶ学生が増えています。", "error_description": "「学ぶ」の対象は「を」で示す。「が」では学問が主語になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41253, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の対象を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」では主語になり、「使う」の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」では修飾や所有を示し、「使う」の対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「使う」の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「使う」の対象を示す「を」が入る。", "が": "「が」では主語になり、「使う」の対象にならない。", "の": "「の」では修飾や所有を示し、「使う」の対象にならない。", "へ": "「へ」は方向を示すため、「使う」の対象を表せない。"}, "error_tags": {"が": "subject", "の": "modifier", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
