INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41253, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "遺伝子の情報をもとに、個人に合った薬の効果や副作用を予測する学問分野です。", "primary_collocate": null, "pronunciation": "ふぁーまこげのみくす", "ipa": "ɸaːmakoɡenomikɯsɯ", "syllable_count": 9, "sentences": [{"text": "ファーマコゲノミクスでは、遺伝子の情報から薬の効果を予測します。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスでは、遺伝子[いでんし]の情報[じょうほう]から薬[くすり]の効果[こうか]を予測[よそく]します。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスを使うと、副作用が出やすい人が事前に分かります。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスを使[つか]うと、副作用[ふくさよう]が出[で]やすい人[ひと]が事前[じぜん]に分[わ]かります。", "sentence_source": "generated"}, {"text": "病院は、ファーマコゲノミクスの検査を取り入れ始めました。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "病院[びょういん]は、ファーマコゲノミクスの検査[けんさ]を取[と]り入[い]れ始[はじ]めました。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスの研究により、個人に合った治療ができるようになりました。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスの研究[けんきゅう]により、個人[こじん]に合[あ]った治療[ちりょう]ができるようになりました。", "sentence_source": "generated"}, {"text": "同じ薬でも人によって違うことを、ファーマコゲノミクスは説明します。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "同[おな]じ薬[くすり]でも人[ひと]によって違[ちが]うことを、ファーマコゲノミクスは説明[せつめい]します。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスの発展で、薬の無駄が減ると期待されています。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスの発展[はってん]で、薬[くすり]の無駄[むだ]が減[へ]ると期待[きたい]されています。", "sentence_source": "generated"}, {"text": "医学部の学生は、ファーマコゲノミクスの基礎を学びます。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "医学部[いがくぶ]の学生[がくせい]は、ファーマコゲノミクスの基礎[きそ]を学[まな]びます。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスの結果を見て、医者は薬の量を決めました。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスの結果[けっか]を見[み]て、医者[いしゃ]は薬[くすり]の量[りょう]を決[き]めました。", "sentence_source": "generated"}, {"text": "新しい薬を作る会社も、ファーマコゲノミクスに関心を持っています。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]を作[つく]る会社[かいしゃ]も、ファーマコゲノミクスに関心[かんしん]を持[も]っています。", "sentence_source": "generated"}, {"text": "ファーマコゲノミクスが進めば、薬選びで悩む人が少なくなるでしょう。", "target_word": "ファーマコゲノミクス", "complexity_tier": "T3", "furigana": "ファーマコゲノミクスが進[すす]めば、薬選[くすりえら]びで悩[なや]む人[ひと]が少[すく]なくなるでしょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファーマコゲノミクス", "label": "基本形"}], "register": "専門用語（丁寧体）", "sense_fingerprint": "遺伝子情報から個人ごとの薬の効果と副作用を予測する分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41253, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ファーマコゲノミクス", "is_correct": true, "explanation": "遺伝子の情報から薬の効果を予測する分野を指し、「では」で始まる文に合う。"}, {"text": "書道", "is_correct": false, "explanation": "文字を書く技術の名前で、遺伝子情報から薬の効果を予測する分野ではない。"}, {"text": "交通", "is_correct": false, "explanation": "人や物の移動に関する語で、薬の効果の予測には関係しない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、薬の効果の予測には関係しない。"}], "explanations": {"ファーマコゲノミクス": "遺伝子の情報から薬の効果を予測する分野を指し、「では」で始まる文に合う。", "書道": "文字を書く技術の名前で、遺伝子情報から薬の効果を予測する分野ではない。", "交通": "人や物の移動に関する語で、薬の効果の予測には関係しない。", "天気": "空模様を表す語で、薬の効果の予測には関係しない。"}, "sentence_index": 0, "correct_answer": "ファーマコゲノミクス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前の店で、ファーマコゲノミクスを一つ買いました。", "explanation": "ここは〈製品〉の意味。この語は学問分野で、店で買える品物ではない。"}, {"text": "駅までの道を、ファーマコゲノミクスで聞きました。", "explanation": "ここは〈案内〉の意味。この語は学問分野で、道を教えてくれる相手や場所ではない。"}, {"text": "製薬会社がファーマコゲノミクスを発売しました。", "explanation": "ここは〈新薬〉の意味。この語は学問分野で、販売される製品ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41253, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ファーマコゲノミクス", "is_correct": true, "explanation": "医学部の学生が学ぶ分野の名前で、「の基礎」と結びつく。"}, {"text": "給料", "is_correct": false, "explanation": "お金に関する語で、学ぶ分野の基礎とは結びつかない。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の入り口を表す語で、学ぶ分野の基礎とは結びつかない。"}, {"text": "交差点", "is_correct": false, "explanation": "道路の場所を表す語で、学ぶ分野の基礎とは結びつかない。"}], "explanations": {"ファーマコゲノミクス": "医学部の学生が学ぶ分野の名前で、「の基礎」と結びつく。", "給料": "お金に関する語で、学ぶ分野の基礎とは結びつかない。", "玄関": "建物の入り口を表す語で、学ぶ分野の基礎とは結びつかない。", "交差点": "道路の場所を表す語で、学ぶ分野の基礎とは結びつかない。"}, "sentence_index": 6, "correct_answer": "ファーマコゲノミクス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ファーマコゲノミクスで薬をもらいました。", "explanation": "ここは〈薬局〉の意味。この語は学問分野で、薬をもらう場所ではない。"}, {"text": "ファーマコゲノミクスで熱を測りました。", "explanation": "ここは〈体温計〉の意味。この語は学問分野で、熱を測る道具ではない。"}, {"text": "ファーマコゲノミクスで、家の鍵を開けました。", "explanation": "ここは〈道具〉の意味。鍵を開ける道具を指す語ではなく、この語は学問分野なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41253, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ファーマコゲノミクスに考え方を、先生が説明した。", "corrected_sentence": "ファーマコゲノミクスの考え方を、先生が説明した。", "error_description": "「考え方」を修飾する「の」を「に」に変えたため誤り。「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41253, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ファーマコゲノミクスを使わって、新しい薬が作られた。", "corrected_sentence": "ファーマコゲノミクスを使って、新しい薬が作られた。", "error_description": "「使う」のて形は「使って」。「使わって」は誤った活用形なので、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41254, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「療法もある」の「も」は、ほかにも方法があるという意味を表す。"}, {"text": "の", "is_correct": false, "explanation": "「療法の」は名詞をつなぐ形で、「ある」には続かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「療法よりある」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「療法からある」は文にならない。"}], "correct_answer": "も", "explanations": {"も": "「療法もある」の「も」は、ほかにも方法があるという意味を表す。", "の": "「療法の」は名詞をつなぐ形で、「ある」には続かない。", "より": "「より」は比較を表すので、「療法よりある」は成り立たない。", "から": "「から」は起点を表すので、「療法からある」は文にならない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41254, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「療法で」の「で」は、療法の内容（音楽を聴くこと）による、という意味を表す。"}, {"text": "を", "is_correct": false, "explanation": "「療法を」は後ろに動詞がなく、「気持ちが落ち着く人もいる」につながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「療法へ」は方向を表すが、文の流れに合わない。"}, {"text": "と", "is_correct": false, "explanation": "「療法と」は並列の形で、ここでは文の意味がつながらない。"}], "correct_answer": "で", "explanations": {"で": "「療法で」の「で」は、療法の内容（音楽を聴くこと）による、という意味を表す。", "を": "「療法を」は後ろに動詞がなく、「気持ちが落ち着く人もいる」につながらない。", "へ": "「療法へ」は方向を表すが、文の流れに合わない。", "と": "「療法と」は並列の形で、ここでは文の意味がつながらない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41254, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "病気を治すための方法です。", "primary_collocate": null, "pronunciation": "りょうほう", "ipa": "ɾʲoːhoː", "syllable_count": 4, "sentences": [{"text": "祖母は新しい療法を試して、腰の痛みが軽くなった。", "target_word": "療法", "complexity_tier": "T3", "furigana": "そぼはあたらしいりょうほうをためして、こしのいたみがかるくなった。", "sentence_source": "generated"}, {"text": "この病気には、薬を使わない療法もある。", "target_word": "療法", "complexity_tier": "T3", "furigana": "このびょうきには、くすりをつかわないりょうほうもある。", "sentence_source": "generated"}, {"text": "医者は患者に合った療法を選んだ。", "target_word": "療法", "complexity_tier": "T3", "furigana": "いしゃはかんじゃにあったりょうほうをえらんだ。", "sentence_source": "generated"}, {"text": "温泉に入る療法は、昔から日本で行われてきた。", "target_word": "療法", "complexity_tier": "T3", "furigana": "おんせんにはいるりょうほうは、むかしからにほんでおこなわれてきた。", "sentence_source": "generated"}, {"text": "療法を変えたら、熱が下がった。", "target_word": "療法", "complexity_tier": "T3", "furigana": "りょうほうをかえたら、ねつがさがった。", "sentence_source": "generated"}, {"text": "病院で、食事を工夫する療法を教えてもらった。", "target_word": "療法", "complexity_tier": "T3", "furigana": "びょういんで、しょくじをくふうするりょうほうをおしえてもらった。", "sentence_source": "generated"}, {"text": "兄は自分に合う療法が見つかるまで、何度も病院を変えた。", "target_word": "療法", "complexity_tier": "T3", "furigana": "あにはじぶんにあうりょうほうがみつかるまで、なんどもびょういんをかえた。", "sentence_source": "generated"}, {"text": "音楽を聴く療法で、気持ちが落ち着く人もいる。", "target_word": "療法", "complexity_tier": "T3", "furigana": "おんがくをきくりょうほうで、きもちがおちつくひともいる。", "sentence_source": "generated"}, {"text": "その療法は時間がかかるが、体への負担は小さい。", "target_word": "療法", "complexity_tier": "T3", "furigana": "そのりょうほうはじかんがかかるが、からだへのふたんはちいさい。", "sentence_source": "generated"}, {"text": "新しい療法の研究が進み、治る人が増えた。", "target_word": "療法", "complexity_tier": "T3", "furigana": "あたらしいりょうほうのけんきゅうがすすみ、なおるひとがふえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "療法", "label": "基本形"}], "register": "標準", "sense_fingerprint": "病気を治すための方法ややり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41254, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "療法", "is_correct": true, "explanation": "「新しい療法を試す」の目的語として、病気を治す方法を表す「療法」が合う。"}, {"text": "病名", "is_correct": false, "explanation": "病名は病気の名前で、試してみる対象にはならない。"}, {"text": "症状", "is_correct": false, "explanation": "症状は病気の現れ方で、試して効果を確かめるものではない。"}, {"text": "患者", "is_correct": false, "explanation": "患者は病気の人を指すので、「試す」の対象にはならない。"}], "explanations": {"療法": "「新しい療法を試す」の目的語として、病気を治す方法を表す「療法」が合う。", "病名": "病名は病気の名前で、試してみる対象にはならない。", "症状": "症状は病気の現れ方で、試して効果を確かめるものではない。", "患者": "患者は病気の人を指すので、「試す」の対象にはならない。"}, "sentence_index": 0, "correct_answer": "療法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この療法で料理を作ると、味がよくなる。", "explanation": "ここは〈方法〉の意味。療法は病気を治す方法のことなので、料理の手順には使わない。"}, {"text": "目的を果たす療法を考えた。", "explanation": "ここは〈手段〉の意味。療法は病気の治し方を指すので、目的全般には使わない。"}, {"text": "この研究では、新しい療法でデータを分析した。", "explanation": "ここは〈手法〉の意味。療法は病気を治す方法のことなので、データを分析する手順には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41254, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "療法", "is_correct": true, "explanation": "「自分に合う療法が見つかるまで」の「療法」は、病気を治す方法を表す。"}, {"text": "体温", "is_correct": false, "explanation": "「自分に合う体温」は意味が通らず、病院を変える理由にもならない。"}, {"text": "体重", "is_correct": false, "explanation": "「自分に合う体重」は意味が通らず、病院を変える理由にもならない。"}, {"text": "痛み", "is_correct": false, "explanation": "「自分に合う痛み」は意味が通らない。痛みは探すものではない。"}], "explanations": {"療法": "「自分に合う療法が見つかるまで」の「療法」は、病気を治す方法を表す。", "体温": "「自分に合う体温」は意味が通らず、病院を変える理由にもならない。", "体重": "「自分に合う体重」は意味が通らず、病院を変える理由にもならない。", "痛み": "「自分に合う痛み」は意味が通らない。痛みは探すものではない。"}, "sentence_index": 6, "correct_answer": "療法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は大きな療法に入院した。", "explanation": "ここは〈病院〉の意味。療法は治し方のことで、入院する場所ではない。"}, {"text": "彼は歴史の療法が豊富で、質問に何でも答える。", "explanation": "ここは〈知識〉の意味。療法は病気の治し方なので、知っていることの量には使わない。"}, {"text": "役所で引っ越しの療法をした。", "explanation": "ここは〈手続き〉の意味。療法は病気を治す方法なので、役所での届け出には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41254, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手術が難しい患者には、薬を使う療法に勧めることが多い。", "corrected_sentence": "手術が難しい患者には、薬を使う療法を勧めることが多い。", "error_description": "「勧める」の対象は「療法」なので、目的語を示す「を」が必要。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41254, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい療法を試えば、効果がわかるかもしれない。", "corrected_sentence": "新しい療法を試せば、効果がわかるかもしれない。", "error_description": "「試す」の仮定形は「試せば」。「試えば」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41255, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「療法は」の「は」は、話題として「がんの療法」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「療法を、分かれる」は、「分かれる」が目的語を取らないので成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「療法へ分かれる」は不自然で、方向の意味にもならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞句を作るだけで、「療法の、」の後に述語がなく文が完結しない。"}], "correct_answer": "は", "explanations": {"は": "「療法は」の「は」は、話題として「がんの療法」を示す。", "を": "「療法を、分かれる」は、「分かれる」が目的語を取らないので成り立たない。", "へ": "「療法へ分かれる」は不自然で、方向の意味にもならない。", "の": "「の」は名詞句を作るだけで、「療法の、」の後に述語がなく文が完結しない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41255, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「切り傷の療法で」の「で」は、療法の方法に限った範囲を示す。"}, {"text": "が", "is_correct": false, "explanation": "「療法が」の後に「は」が続くと不自然で、文の流れに合わない。"}, {"text": "の", "is_correct": false, "explanation": "「療法の」の後に「は」が続くと、名詞をつなぐ形が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「療法を」の後に「は」が続くと助詞が重なり、「を」は文の中で成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「切り傷の療法で」の「で」は、療法の方法に限った範囲を示す。", "が": "「療法が」の後に「は」が続くと不自然で、文の流れに合わない。", "の": "「療法の」の後に「は」が続くと、名詞をつなぐ形が崩れる。", "を": "「療法を」の後に「は」が続くと助詞が重なり、「を」は文の中で成り立たない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41255, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "病気やけがを治療するための方法や手段。薬を使ったり、手術をしたりすることなど。", "primary_collocate": null, "pronunciation": "りょうほう", "ipa": "ɾʲoːhoː", "syllable_count": 4, "sentences": [{"text": "医師は、薬による療法と手術のどちらがよいか説明した。", "target_word": "療法", "complexity_tier": "T3", "furigana": "いしは、くすりによるりょうほうとしゅじゅつのどちらがよいかせつめいした。", "sentence_source": "generated"}, {"text": "がんの療法は、薬や手術などいくつもの方法に分かれる。", "target_word": "療法", "complexity_tier": "T3", "furigana": "がんのりょうほうは、くすりやしゅじゅつなどいくつものほうほうにわかれる。", "sentence_source": "generated"}, {"text": "手術をしない療法を望む患者が増えている。", "target_word": "療法", "complexity_tier": "T3", "furigana": "しゅじゅつをしないりょうほうをのぞむかんじゃがふえている。", "sentence_source": "generated"}, {"text": "骨折の療法として、ギプスで固定する方法が選ばれた。", "target_word": "療法", "complexity_tier": "T3", "furigana": "こっせつのりょうほうとして、ぎぷすでこていするほうほうがえらばれた。", "sentence_source": "generated"}, {"text": "この療法は副作用が少ないので、高齢の患者にも使われる。", "target_word": "療法", "complexity_tier": "T3", "furigana": "このりょうほうはふくさようがすくないので、こうれいのかんじゃにもつかわれる。", "sentence_source": "generated"}, {"text": "症状が重いため、薬だけの療法では足りなかった。", "target_word": "療法", "complexity_tier": "T3", "furigana": "しょうじょうがおもいため、くすりだけのりょうほうではたりなかった。", "sentence_source": "generated"}, {"text": "病院は、患者の年齢に合わせて療法を決めている。", "target_word": "療法", "complexity_tier": "T3", "furigana": "びょういんは、かんじゃのねんれいにあわせてりょうほうをきめている。", "sentence_source": "generated"}, {"text": "切り傷の療法では、傷口を清潔に保つことが基本になる。", "target_word": "療法", "complexity_tier": "T3", "furigana": "きりきずのりょうほうでは、きずぐちをせいけつにたもつことがきほんになる。", "sentence_source": "generated"}, {"text": "新しい療法の効果は、数年かけて確かめられた。", "target_word": "療法", "complexity_tier": "T3", "furigana": "あたらしいりょうほうのこうかは、すうねんかけてたしかめられた。", "sentence_source": "generated"}, {"text": "手術と薬を組み合わせた療法で、彼は元気になった。", "target_word": "療法", "complexity_tier": "T3", "furigana": "しゅじゅつとくすりをくみあわせたりょうほうで、かれはげんきになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "療法", "label": "基本形"}], "register": "標準", "sense_fingerprint": "薬や手術など、病気やけがを治療する具体的な手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6de5a0b9-a021-442b-bdb1-a53a82200e7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41255, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "療法", "is_correct": true, "explanation": "「薬による療法と手術」の「療法」は、病気を治す方法を表す。"}, {"text": "病室", "is_correct": false, "explanation": "病室は部屋で、薬と手術の比較には入らない。"}, {"text": "診察券", "is_correct": false, "explanation": "診察券は病院の札で、治療方法と並べることはできない。"}, {"text": "聴診器", "is_correct": false, "explanation": "聴診器は医療器具で、薬と手術と並べて比べる対象ではない。"}], "explanations": {"療法": "「薬による療法と手術」の「療法」は、病気を治す方法を表す。", "病室": "病室は部屋で、薬と手術の比較には入らない。", "診察券": "診察券は病院の札で、治療方法と並べることはできない。", "聴診器": "聴診器は医療器具で、薬と手術と並べて比べる対象ではない。"}, "sentence_index": 0, "correct_answer": "療法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最終的な療法として、彼は車を売った。", "explanation": "ここは〈医療以外の手段〉の意味。療法は病気やけがの治療に限るので、車を売ってお金を作る場面には使わない。"}, {"text": "この問題は、新しい療法で解いた。", "explanation": "ここは〈解法〉の意味。療法は病気やけがの治療なので、数学の問題を解く方法には使わない。"}, {"text": "会社は新しい療法で売り上げを伸ばした。", "explanation": "ここは〈戦略〉の意味。療法は病気やけがの治療に限るので、会社の売り上げを伸ばす手だてには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41255, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "療法", "is_correct": true, "explanation": "「患者の年齢に合わせて療法を決める」の「療法」が、治療方法を表す。"}, {"text": "体温", "is_correct": false, "explanation": "「年齢に合わせて体温を決める」は意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "「年齢に合わせて体重を決める」は意味が通らない。"}, {"text": "痛み", "is_correct": false, "explanation": "「年齢に合わせて痛みを決める」は意味が通らない。"}], "explanations": {"療法": "「患者の年齢に合わせて療法を決める」の「療法」が、治療方法を表す。", "体温": "「年齢に合わせて体温を決める」は意味が通らない。", "体重": "「年齢に合わせて体重を決める」は意味が通らない。", "痛み": "「年齢に合わせて痛みを決める」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "療法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "療法が晴れて、洗濯日和になった。", "explanation": "ここは〈天気〉の意味。療法は治療の方法なので、空が晴れる様子には使わない。"}, {"text": "彼女の療法は明るい。", "explanation": "ここは〈性格〉の意味。療法は治療方法なので、人の性格には使わない。"}, {"text": "療法が赤に変わった。", "explanation": "ここは〈信号〉の意味。療法は治療方法なので、色の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41255, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "がんの療法を選び方は、医師とよく相談して決める。", "corrected_sentence": "がんの療法の選び方は、医師とよく相談して決める。", "error_description": "「療法」と「選び方」をつなぐのは「の」。「を」は目的語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41255, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この療法に受ける患者は、事前に医師と相談する。", "corrected_sentence": "この療法を受ける患者は、事前に医師と相談する。", "error_description": "「受ける」の目的語は「療法」なので「を」が必要。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a40b381-057f-4ed8-b833-703e7894d0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41257, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一括", "is_correct": true, "explanation": "「個別」（一つずつ分けて扱う）の対義語。「一括」はまとめて扱う意味で、対になる。"}, {"text": "海岸", "is_correct": false, "explanation": "「海岸」は場所を表す名詞で、「個別」の対義語ではない。"}, {"text": "夢想", "is_correct": false, "explanation": "「夢想」は想像の意味で、「個別」と対義関係にない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温」は身体の温度で、「個別」の対義語にならない。"}], "correct_answer": "一括", "explanations": {"一括": "「個別」（一つずつ分けて扱う）の対義語。「一括」はまとめて扱う意味で、対になる。", "海岸": "「海岸」は場所を表す名詞で、「個別」の対義語ではない。", "夢想": "「夢想」は想像の意味で、「個別」と対義関係にない。", "体温": "「体温」は身体の温度で、「個別」の対義語にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
