INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41257, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ひとつひとつを他と区別して扱うこと。個々に分けること。", "primary_collocate": null, "pronunciation": "こべつ", "ipa": "kobetsɯ", "syllable_count": 3, "sentences": [{"text": "すなわち、教育の公平性を保つには、学習者を個別に扱う新たな枠組みが必要だと言えよう。", "target_word": "個別", "complexity_tier": "T6", "furigana": "すなわち、教育[きょういく]の公平性[こうへいせい]を保[たも]つには、学習者[がくしゅうしゃ]を個別[こべつ]に扱[あつか]う新[あら]たな枠組[わくぐ]みが必要[ひつよう]だと言[い]えよう。", "sentence_source": "generated"}, {"text": "個別に話を聞きます。", "target_word": "個別", "complexity_tier": "T2", "furigana": "個別[こべつ]に話[はなし]を聞[き]きます。", "sentence_source": "generated"}, {"text": "先生は生徒を個別に指導した。", "target_word": "個別", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]を個別[こべつ]に指導[しどう]した。", "sentence_source": "generated"}, {"text": "個別の相談もできます。", "target_word": "個別", "complexity_tier": "T2", "furigana": "個別[こべつ]の相談[そうだん]もできます。", "sentence_source": "generated"}, {"text": "各商品は個別に包装され、出荷された。", "target_word": "個別", "complexity_tier": "T3", "furigana": "各[かく]商品[しょうひん]は個[こ]別[べつ]に包装[ほうそう]され、出荷[しゅっか]された。", "sentence_source": "generated"}, {"text": "個別に締結されていた契約を一つにまとめる。", "target_word": "個別", "complexity_tier": "T3", "furigana": "個[こ]別[べつ]に締結[ていけつ]されていた契約[けいやく]を一[ひと]つにまとめる。", "sentence_source": "generated"}, {"text": "一人ひとりの事情を個別に検討する。", "target_word": "個別", "complexity_tier": "T3", "furigana": "一人[ひとり]ひとりの事情[じじょう]を個[こ]別[べつ]に検討[けんとう]する。", "sentence_source": "generated"}, {"text": "料金は個別に計算される。", "target_word": "個別", "complexity_tier": "T3", "furigana": "料金[りょうきん]は個別[こべつ]に計算[けいさん]される。", "sentence_source": "generated"}, {"text": "客室は個別に管理されている。", "target_word": "個別", "complexity_tier": "T3", "furigana": "客室[きゃくしつ]は個[こ]別[べつ]に管理[かんり]されている。", "sentence_source": "generated"}, {"text": "個別の問題として扱うべきだ。", "target_word": "個別", "complexity_tier": "T3", "furigana": "個別[こべつ]の問題[もんだい]として扱[あつか]うべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "個別的", "label": "派生"}, {"form": "個別化", "label": "派生"}, {"form": "個別性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ひとつひとつを区別して個々に扱うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41257, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "個別", "is_correct": true, "explanation": "「学習者を個別に扱う」の「個別」。空欄に入るのはこの語。"}, {"text": "放置", "is_correct": false, "explanation": "「学習者を放置に扱う」は文として成立しない。"}, {"text": "天候", "is_correct": false, "explanation": "「学習者を天候に扱う」は文として通らない。"}, {"text": "季節", "is_correct": false, "explanation": "「学習者を季節に扱う」は文として通らない。"}], "explanations": {"個別": "「学習者を個別に扱う」の「個別」。空欄に入るのはこの語。", "放置": "「学習者を放置に扱う」は文として成立しない。", "天候": "「学習者を天候に扱う」は文として通らない。", "季節": "「学習者を季節に扱う」は文として通らない。"}, "sentence_index": 0, "correct_answer": "個別"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "顧客の個別情報を厳重に管理する。", "explanation": "ここは〈個人〉の意味。人に関する情報は「個人情報」と言うもので、個別は一つずつ区別して扱う語なので合わない。"}, {"text": "彼女の個別が際立っている。", "explanation": "ここは〈個性〉（その人らしさ）の意味。個別は一つずつ区別して扱うことで、人柄や特徴を表す語ではない。"}, {"text": "レストランの個別を予約した。", "explanation": "ここは〈個室〉（一人専用の部屋）の意味。個別は一つずつ区別して扱うことで、部屋を指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41257, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "個別", "is_correct": true, "explanation": "「個別に検討する」で、一人ひとりの事情を別々に検討する意味。"}, {"text": "世界", "is_correct": false, "explanation": "「世界に検討する」は意味をなさず、事情を一人ずつ扱う文脈に合わない。"}, {"text": "時代", "is_correct": false, "explanation": "「時代に検討する」は文として通らず、一人ひとりを扱う意味にならない。"}, {"text": "人情", "is_correct": false, "explanation": "「人情に検討する」は不自然で、事情を個別に扱うという意味に合わない。"}], "explanations": {"個別": "「個別に検討する」で、一人ひとりの事情を別々に検討する意味。", "世界": "「世界に検討する」は意味をなさず、事情を一人ずつ扱う文脈に合わない。", "時代": "「時代に検討する」は文として通らず、一人ひとりを扱う意味にならない。", "人情": "「人情に検討する」は不自然で、事情を個別に扱うという意味に合わない。"}, "sentence_index": 6, "correct_answer": "個別"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は個別な才能の持ち主で、みんなに一目置かれている。", "explanation": "ここは〈特別〉（並外れて優れた）の意味。個別は一つずつ分けて扱う意味で、才能の優れ方は表せない。"}, {"text": "在庫の個別を数えた。", "explanation": "ここは〈個数〉（物の数）の意味。個別は一つずつ区別して扱う語で、数量を表すものではないので合わない。"}, {"text": "チームの個別が試合に出た。", "explanation": "ここは〈代表〉（全体を代表する人）の意味。個別は一つずつ区別して扱うことで、全体を代表する人を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41257, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校長は新入生を個別へ呼び出した。", "corrected_sentence": "校長は新入生を個別に呼び出した。", "error_description": "「個別」に付く助詞は「に」。「へ」は方向を表すため「個別へ」は誤り。正しくは「個別に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41257, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会費は個別へ徴収される。", "corrected_sentence": "会費は個別に徴収される。", "error_description": "「個別」に付く助詞は「に」。「へ」は方向を表すため「個別へ」は誤り。正しくは「個別に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41260, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「石を拾う」の対象を表す「を」で、文が通る。"}, {"text": "が", "is_correct": false, "explanation": "「石が拾いました」では石が主語になり、人が拾った文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「石に拾いました」は「に」が拾う動作の対象にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、拾う対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「石を拾う」の対象を表す「を」で、文が通る。", "が": "「石が拾いました」では石が主語になり、人が拾った文脈に合わない。", "に": "「石に拾いました」は「に」が拾う動作の対象にならず、不自然。", "へ": "「へ」は方向を表すので、拾う対象には合わない。"}, "error_tags": {"が": "主語", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41260, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を表す「は」。「石は〜です」で文が成立する。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すので、主題の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、ここでは文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すので、主題の位置には合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を表す「は」。「石は〜です」で文が成立する。", "を": "「を」は目的語を表すので、主題の位置には合わない。", "で": "「で」は手段や場所を表すので、ここでは文が成立しない。", "と": "「と」は並列を表すので、主題の位置には合わない。"}, "error_tags": {"を": "対象", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41260, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "道や川にある、かたくて重い小さな石ころです。", "primary_collocate": null, "pronunciation": "いし", "ipa": "iɕi", "syllable_count": 2, "sentences": [{"text": "石はとてもかたいので、手で割れません。", "target_word": "石", "complexity_tier": "T3", "furigana": "石(いし)はとてもかたいので、手(て)で割(わ)れません。", "sentence_source": "generated"}, {"text": "公園で小さな石を拾いました。", "target_word": "石", "complexity_tier": "T3", "furigana": "公園(こうえん)で小(ちい)さな石(いし)を拾(ひろ)いました。", "sentence_source": "generated"}, {"text": "石は水に入れると、すぐ沈みます。", "target_word": "石", "complexity_tier": "T3", "furigana": "石(いし)は水(みず)に入(い)れると、すぐ沈(しず)みます。", "sentence_source": "generated"}, {"text": "道に大きな石があって、歩きにくかったです。", "target_word": "石", "complexity_tier": "T3", "furigana": "道(みち)に大(おお)きな石(いし)があって、歩(ある)きにくかったです。", "sentence_source": "generated"}, {"text": "弟は川に石を投げて遊んでいます。", "target_word": "石", "complexity_tier": "T3", "furigana": "弟(おとうと)は川(かわ)に石(いし)を投(な)げて遊(あそ)んでいます。", "sentence_source": "generated"}, {"text": "この石は重いから、一人では持てません。", "target_word": "石", "complexity_tier": "T3", "furigana": "この石(いし)は重(おも)いから、一人(ひとり)では持(も)てません。", "sentence_source": "generated"}, {"text": "靴の中に石が入って、足が痛くなりました。", "target_word": "石", "complexity_tier": "T3", "furigana": "靴(くつ)の中(なか)に石(いし)が入(はい)って、足(あし)が痛(いた)くなりました。", "sentence_source": "generated"}, {"text": "石は冷たくて、かたいです。", "target_word": "石", "complexity_tier": "T3", "furigana": "石(いし)は冷(つめ)たくて、かたいです。", "sentence_source": "generated"}, {"text": "海できれいな丸い石を見つけました。", "target_word": "石", "complexity_tier": "T3", "furigana": "海(うみ)できれいな丸(まる)い石(いし)を見(み)つけました。", "sentence_source": "generated"}, {"text": "石を積んで、小さな山を作りました。", "target_word": "石", "complexity_tier": "T3", "furigana": "石(いし)を積(つ)んで、小(ちい)さな山(やま)を作(つく)りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "石", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "道や川にある、かたくて重い小さな石ころ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41260, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石", "is_correct": true, "explanation": "「石はとてもかたい」で、手で割れないという文脈に合う。"}, {"text": "紙", "is_correct": false, "explanation": "紙はかたくないので、「とてもかたい」という文脈に合わない。"}, {"text": "水", "is_correct": false, "explanation": "水はかたさを持たず、「手で割れない」と結びつかない。"}, {"text": "綿", "is_correct": false, "explanation": "綿はやわらかいので、「とてもかたい」という文脈に合わない。"}], "explanations": {"石": "「石はとてもかたい」で、手で割れないという文脈に合う。", "紙": "紙はかたくないので、「とてもかたい」という文脈に合わない。", "水": "水はかたさを持たず、「手で割れない」と結びつかない。", "綿": "綿はやわらかいので、「とてもかたい」という文脈に合わない。"}, "sentence_index": 0, "correct_answer": "石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石をこねて、パンを焼いた。", "explanation": "〈小麦粉〉の意味。小麦粉はこねてパンにするが、石はこねられないので合わない。"}, {"text": "夏の暑い日、石を削って、ふわふわの食べ物を作った。", "explanation": "〈氷〉の意味。氷は削ってかき氷にするが、石は削っても食べ物にはならないので合わない。"}, {"text": "かまどに石をくべて、火を起こした。", "explanation": "〈石炭〉の意味。石は燃えないので、燃料としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41260, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石", "is_correct": true, "explanation": "靴の中に入って足が痛くなるものとして文脈に合う。"}, {"text": "切手", "is_correct": false, "explanation": "切手が靴に入っても足が痛くなる文脈にはならない。"}, {"text": "花びら", "is_correct": false, "explanation": "花びらでは足が痛くならず、文脈に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙が靴に入っても足が痛くなる文脈にはならない。"}], "explanations": {"石": "靴の中に入って足が痛くなるものとして文脈に合う。", "切手": "切手が靴に入っても足が痛くなる文脈にはならない。", "花びら": "花びらでは足が痛くならず、文脈に合わない。", "紙": "紙が靴に入っても足が痛くなる文脈にはならない。"}, "sentence_index": 6, "correct_answer": "石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石を絞って、ジュースを作った。", "explanation": "〈果物〉の意味。果物は絞ってジュースにするが、石は絞れないので合わない。"}, {"text": "石を泡立てて、手を洗った。", "explanation": "〈石鹸〉の意味。泡立てて手を洗うのは石鹸で、石ころには使えない。"}, {"text": "石を折って、小さな船を作った。", "explanation": "〈紙〉の意味。折って船を作るのは紙で、石は折れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41260, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "男の子が小さな石に池に投げた。", "corrected_sentence": "男の子が小さな石を池に投げた。", "error_description": "誤: 「に」／正: 「を」。「投げる」の対象は「を」で示す。「石に」では対象の表し方が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41260, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川原に転がる、かたい石で集めた。", "corrected_sentence": "川原に転がる、かたい石を集めた。", "error_description": "誤: 「で」／正: 「を」。「集める」の対象は「を」で示す。「で」は手段や場所を表し、対象の表し方が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41261, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "材料・手段を表す「で」。「石で橋を作る」の形で文が通る。"}, {"text": "へ", "is_correct": false, "explanation": "「石へ橋を作る」は「へ」が方向を表し、材料の意味にならない。"}, {"text": "に", "is_correct": false, "explanation": "「石に橋を作る」は「に」が材料の意味を表せず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「石を橋を作る」は目的語が二つになり、意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "材料・手段を表す「で」。「石で橋を作る」の形で文が通る。", "へ": "「石へ橋を作る」は「へ」が方向を表し、材料の意味にならない。", "に": "「石に橋を作る」は「に」が材料の意味を表せず、不自然。", "を": "「石を橋を作る」は目的語が二つになり、意味が通らない。"}, "error_tags": {"に": "相手・帰着点", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41261, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "材料を表す「で」。「石でできている」で自然に文が通る。"}, {"text": "の", "is_correct": false, "explanation": "「石のできています」は「の」の働きが成立せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、材料の意味に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を表すので、材料の意味に合わない。"}], "correct_answer": "で", "explanations": {"で": "材料を表す「で」。「石でできている」で自然に文が通る。", "の": "「石のできています」は「の」の働きが成立せず、不自然。", "へ": "「へ」は方向を表すので、材料の意味に合わない。", "と": "「と」は並列や共同を表すので、材料の意味に合わない。"}, "error_tags": {"の": "連体", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41261, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "石は、地面にある硬い物質で、建物や道などを作るのに使われます。", "primary_collocate": null, "pronunciation": "いし", "ipa": "iɕi", "syllable_count": 2, "sentences": [{"text": "石を積んで、家を作ります。", "target_word": "石", "complexity_tier": "T3", "furigana": "石(いし)を積(つ)んで、家(いえ)を作(つく)ります。", "sentence_source": "generated"}, {"text": "昔の人は、山から運んだ石で橋を作りました。", "target_word": "石", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)は、山(やま)から運(はこ)んだ石(いし)で橋(はし)を作(つく)りました。", "sentence_source": "generated"}, {"text": "この家の壁は、大きな石を積んで作ってあります。", "target_word": "石", "complexity_tier": "T3", "furigana": "この家(いえ)の壁(かべ)は、大(おお)きな石(いし)を積(つ)んで作(つく)ってあります。", "sentence_source": "generated"}, {"text": "道に石を敷いたので、雨の日も歩きやすいです。", "target_word": "石", "complexity_tier": "T3", "furigana": "道(みち)に石(いし)を敷(し)いたので、雨(あめ)の日(ひ)も歩(ある)きやすいです。", "sentence_source": "generated"}, {"text": "石は硬いので、建物の土台に使われます。", "target_word": "石", "complexity_tier": "T3", "furigana": "石(いし)は硬(かた)いので、建物(たてもの)の土台(どだい)に使(つか)われます。", "sentence_source": "generated"}, {"text": "職人は、石を一つずつ丁寧に並べています。", "target_word": "石", "complexity_tier": "T3", "furigana": "職人(しょくにん)は、石(いし)を一(ひと)つずつ丁寧(ていねい)に並(なら)べています。", "sentence_source": "generated"}, {"text": "川の近くで、家を建てるための石を集めました。", "target_word": "石", "complexity_tier": "T3", "furigana": "川(かわ)の近(ちか)くで、家(いえ)を建(た)てるための石(いし)を集(あつ)めました。", "sentence_source": "generated"}, {"text": "この古い道は、四角い石でできています。", "target_word": "石", "complexity_tier": "T3", "furigana": "この古(ふる)い道(みち)は、四角(しかく)い石(いし)でできています。", "sentence_source": "generated"}, {"text": "木の家より石の家のほうが、火事に強いです。", "target_word": "石", "complexity_tier": "T3", "furigana": "木(き)の家(いえ)より石(いし)の家(いえ)のほうが、火事(かじ)に強(つよ)いです。", "sentence_source": "generated"}, {"text": "重い石を運ぶので、みんなで力を合わせました。", "target_word": "石", "complexity_tier": "T3", "furigana": "重(おも)い石(いし)を運(はこ)ぶので、みんなで力(ちから)を合(あ)わせました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "石", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "石材としての石。建物や道を作る硬い材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b3b14ba-f350-4b70-835c-74054ef8b390') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41261, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石", "is_correct": true, "explanation": "「石を積んで作る」は建物や道の材料として文脈に合う。"}, {"text": "花", "is_correct": false, "explanation": "花は積んで建物などを作る材料ではないので、文が成立しない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖を積んで何かを作る文脈はなく、意味が通らない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は積み上げて作るものではないので、「つんでつくる」と合わない。"}], "explanations": {"石": "「石を積んで作る」は建物や道の材料として文脈に合う。", "花": "花は積んで建物などを作る材料ではないので、文が成立しない。", "砂糖": "砂糖を積んで何かを作る文脈はなく、意味が通らない。", "鍵": "鍵は積み上げて作るものではないので、「つんでつくる」と合わない。"}, "sentence_index": 0, "correct_answer": "石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は、石を編んで、マフラーを作った。", "explanation": "〈毛糸〉の意味。毛糸は編んで布にするが、石は硬くて編めないので合わない。"}, {"text": "昔は石を燃やして、汽車を走らせていた。", "explanation": "〈石炭〉の意味。石は燃えないので、燃料の文脈には合わない。"}, {"text": "石を縫って、ワンピースを作った。", "explanation": "〈布〉の意味。布は縫って服にするが、石は縫えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41261, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石", "is_correct": true, "explanation": "「家を建てるための石」として集める文脈に合う。"}, {"text": "切手", "is_correct": false, "explanation": "切手は家を建てる材料ではないので、文脈に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は家を建てるための材料ではなく、文が成立しない。"}, {"text": "人形", "is_correct": false, "explanation": "人形は家を建てる材料ではないので、「建てるための」と合わない。"}], "explanations": {"石": "「家を建てるための石」として集める文脈に合う。", "切手": "切手は家を建てる材料ではないので、文脈に合わない。", "鉛筆": "鉛筆は家を建てるための材料ではなく、文が成立しない。", "人形": "人形は家を建てる材料ではないので、「建てるための」と合わない。"}, "sentence_index": 6, "correct_answer": "石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石を溶かして、包丁を作った。", "explanation": "〈鉄〉の意味。鉄は溶かして加工する金属だが、石は溶かして包丁にはできないので合わない。"}, {"text": "石を折って、鶴を作った。", "explanation": "〈紙〉の意味。折って形を作るのは紙の使い方で、石は折れないので合わない。"}, {"text": "石を炊いて、ご飯を作った。", "explanation": "〈米〉の意味。米は炊いてご飯にするが、石は炊けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41261, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "川原で拾った石が、小さな祠を作りました。", "corrected_sentence": "川原で拾った石で、小さな祠を作りました。", "error_description": "誤: 「が」／正: 「で」。「石が」では石が主語になり、人が作る文脈に合わない。「で」は材料・手段を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41261, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川で拾った石が、ひとつずつ積み上げた。", "corrected_sentence": "川で拾った石を、ひとつずつ積み上げた。", "error_description": "誤: 「が」／正: 「を」。「積み上げる」の対象は「を」で示す。「石が」では石が主語になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dec09fbc-fcba-454a-b6ed-e640766ca95d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41262, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この部屋の壁は白い」と主題を示す。文の骨格として自然。"}, {"text": "を", "is_correct": false, "explanation": "「壁を白いです」では目的語になり、形容詞の文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「壁に白いです」では場所になり、白いという説明にならない。"}, {"text": "で", "is_correct": false, "explanation": "「壁で白いです」は手段の意味になり、不自然。"}], "correct_answer": "は", "explanations": {"は": "「この部屋の壁は白い」と主題を示す。文の骨格として自然。", "を": "「壁を白いです」では目的語になり、形容詞の文が成り立たない。", "に": "「壁に白いです」では場所になり、白いという説明にならない。", "で": "「壁で白いです」は手段の意味になり、不自然。"}, "error_tags": {"を": "目的語", "に": "場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41262, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「壁の近く」と名詞を結ぶ連体修飾。ここでは正しい。"}, {"text": "が", "is_correct": false, "explanation": "「壁が近くにいすを置く」では、近くに置く主体が壁になり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「壁と近く」は並列の相手を表し、場所の関係が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「壁へ近く」は名詞とつながらず不自然。"}], "correct_answer": "の", "explanations": {"の": "「壁の近く」と名詞を結ぶ連体修飾。ここでは正しい。", "が": "「壁が近くにいすを置く」では、近くに置く主体が壁になり、意味が通らない。", "と": "「壁と近く」は並列の相手を表し、場所の関係が通らない。", "へ": "「へ」は方向を表すが、「壁へ近く」は名詞とつながらず不自然。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41262, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かべは、へややたてものをわける、たてにたったもののことです。", "primary_collocate": null, "pronunciation": "かべ", "ipa": "kabe", "syllable_count": 2, "sentences": [{"text": "壁にカレンダーをかけました。", "target_word": "壁", "complexity_tier": "T2", "furigana": "壁[かべ]にカレンダーをかけました。", "sentence_source": "generated"}, {"text": "この部屋の壁は白いです。", "target_word": "壁", "complexity_tier": "T2", "furigana": "この部屋[へや]の壁[かべ]は白[しろ]いです。", "sentence_source": "generated"}, {"text": "壁に絵をはったので、部屋が明るくなった。", "target_word": "壁", "complexity_tier": "T3", "furigana": "壁[かべ]に絵[え]をはったので、部屋[へや]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "犬が壁の前で、じっと座っている。", "target_word": "壁", "complexity_tier": "T3", "furigana": "犬[いぬ]が壁[かべ]の前[まえ]で、じっと座[すわ]っている。", "sentence_source": "generated"}, {"text": "となりの家との間に、高い壁がある。", "target_word": "壁", "complexity_tier": "T2", "furigana": "となりの家[いえ]との間[あいだ]に、高[たか]い壁[かべ]がある。", "sentence_source": "generated"}, {"text": "壁にボールをぶつけて、ひとりで遊んだ。", "target_word": "壁", "complexity_tier": "T2", "furigana": "壁[かべ]にボールをぶつけて、ひとりで遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "古い壁がこわれたので、新しく作り直した。", "target_word": "壁", "complexity_tier": "T3", "furigana": "古[ふる]い壁[かべ]がこわれたので、新[あたら]しく作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "壁の近くにいすを置くと、部屋が広く使える。", "target_word": "壁", "complexity_tier": "T3", "furigana": "壁[かべ]の近[ちか]くにいすを置[お]くと、部屋[へや]が広[ひろ]く使[つか]える。", "sentence_source": "generated"}, {"text": "雨がふって、家の外の壁がぬれた。", "target_word": "壁", "complexity_tier": "T2", "furigana": "雨[あめ]がふって、家[いえ]の外[そと]の壁[かべ]がぬれた。", "sentence_source": "generated"}, {"text": "弟は壁に落書きをして、母におこられた。", "target_word": "壁", "complexity_tier": "T3", "furigana": "弟[おとうと]は壁[かべ]に落書[らくが]きをして、母[はは]におこられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "壁", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "部屋や建物を分ける、縦に立った身近な壁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41262, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "壁", "is_correct": true, "explanation": "カレンダーは壁に掛けるものなので、「壁」が正しい。"}, {"text": "床", "is_correct": false, "explanation": "床にカレンダーを掛けるとは言わないので合わない。"}, {"text": "机", "is_correct": false, "explanation": "机の上に置くことはあっても、掛けることはないので合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子にカレンダーを掛けるのは不自然で、文脈に合わない。"}], "explanations": {"壁": "カレンダーは壁に掛けるものなので、「壁」が正しい。", "床": "床にカレンダーを掛けるとは言わないので合わない。", "机": "机の上に置くことはあっても、掛けることはないので合わない。", "椅子": "椅子にカレンダーを掛けるのは不自然で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、壁を着て外に出た。", "explanation": "ここは〈服〉の意味。壁は身につけられないので「着る」の対象にはならない。"}, {"text": "ケーキを壁で切って、みんなで食べた。", "explanation": "ここは〈ナイフ・包丁〉の意味。壁は切るための道具にはならないので合わない。"}, {"text": "壁のページをめくって、本を読んだ。", "explanation": "ここは〈本のページ・紙〉の意味。壁はめくれないので、ページの代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41262, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壁", "is_correct": true, "explanation": "古くなって壊れて作り直す対象は家の壁なので、「壁」が正しい。"}, {"text": "波", "is_correct": false, "explanation": "波は海や水面の動きで、壊れて作り直すものではないので合わない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は作り直すものではないので、「作り直した」と結びつかない。"}, {"text": "虹", "is_correct": false, "explanation": "虹は壊れて作り直す対象にならないので合わない。"}], "explanations": {"壁": "古くなって壊れて作り直す対象は家の壁なので、「壁」が正しい。", "波": "波は海や水面の動きで、壊れて作り直すものではないので合わない。", "雷": "雷は作り直すものではないので、「作り直した」と結びつかない。", "虹": "虹は壊れて作り直す対象にならないので合わない。"}, "sentence_index": 6, "correct_answer": "壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁は頭がよくて、宿題を手伝ってくれる。", "explanation": "ここは〈人や動物〉の意味。壁は考えたり手伝ったりできないので、主語にはならない。"}, {"text": "祖母は壁の服を縫ってくれた。", "explanation": "ここは〈布〉の意味。壁は布ではないので、服の材料にはならない。"}, {"text": "昨日は、壁の中で寝転がって、テレビを見た。", "explanation": "ここは〈部屋・空間〉の意味。壁の中は人が入って寝転がれる空間ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41262, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの部屋の壁から、星の絵をはった。", "corrected_sentence": "子どもの部屋の壁に、星の絵をはった。", "error_description": "貼る場所は「に」で示す。「から」は起点を表すので、壁から絵を貼るという意味にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41262, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝室の壁を、薄い緑色です。", "corrected_sentence": "寝室の壁は、薄い緑色です。", "error_description": "「薄い緑色です」の主題は「壁は」で示す。「壁を」は目的語になり、「です」の文の主語として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41263, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「壁を薄くして」と目的語になり、壁を薄くするという意味が通る。"}, {"text": "に", "is_correct": false, "explanation": "「壁に薄くして」では、薄くする対象として文がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「薄くする」の対象には使えないので不自然。"}, {"text": "で", "is_correct": false, "explanation": "「壁で薄くして」は手段の意味になり、壁を薄くするという意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「壁を薄くして」と目的語になり、壁を薄くするという意味が通る。", "に": "「壁に薄くして」では、薄くする対象として文がつながらない。", "へ": "方向を表す「へ」は「薄くする」の対象には使えないので不自然。", "で": "「壁で薄くして」は手段の意味になり、壁を薄くするという意味が通らない。"}, "error_tags": {"に": "場所", "へ": "方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41263, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「壁が崩れて」と主語を示す。自動詞「くずれる」の主語として正しい。"}, {"text": "と", "is_correct": false, "explanation": "「壁と崩れて」では主語にならず、崩れる主体を示せないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「壁の崩れて」は名詞修飾にならず、文がつながらない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表すので、「壁より崩れて」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「壁が崩れて」と主語を示す。自動詞「くずれる」の主語として正しい。", "と": "「壁と崩れて」では主語にならず、崩れる主体を示せないので不自然。", "の": "「壁の崩れて」は名詞修飾にならず、文がつながらない。", "より": "「より」は比較の基準を表すので、「壁より崩れて」は意味が通らない。"}, "error_tags": {"と": "並列", "の": "修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41263, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "壁は、建物の内部や外部を区切る、垂直に立つ構造物です。", "primary_collocate": null, "pronunciation": "かべ", "ipa": "kabe", "syllable_count": 2, "sentences": [{"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "壁", "complexity_tier": "T4", "furigana": "特[とく]に注目[ちゅうもく]すべきは、天井[てんじょう]の重量[じゅうりょう]を分散[ぶんさん]させる「リブ・ヴォールト」と、壁[かべ]の外側[そとがわ]から支[ささ]える「フライング・バットレス」と呼[よ]ばれる技術[ぎじゅつ]です。", "sentence_source": "mined"}, {"text": "これらにより、壁を薄くして大きな窓を設けることが可能となり、内部は光に満ちあふれました。", "target_word": "壁", "complexity_tier": "T4", "furigana": "これらにより、壁[かべ]を薄[うす]くして大[おお]きな窓[まど]を設[もう]けることが可能[かのう]となり、内部[ないぶ]は光[ひかり]に満[み]ちあふれました。", "sentence_source": "mined"}, {"text": "この家は、壁が厚いので、冬でも暖かい。", "target_word": "壁", "complexity_tier": "T3", "furigana": "この家[いえ]は、壁[かべ]が厚[あつ]いので、冬[ふゆ]でも暖[あたた]かい。", "sentence_source": "generated"}, {"text": "隣の部屋との間の壁が薄くて、話し声が聞こえる。", "target_word": "壁", "complexity_tier": "T3", "furigana": "隣[となり]の部屋[へや]との間[あいだ]の壁[かべ]が薄[うす]くて、話[はな]し声[ごえ]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "白い壁に、子どもの絵をかざった。", "target_word": "壁", "complexity_tier": "T2", "furigana": "白[しろ]い壁[かべ]に、子[こ]どもの絵[え]をかざった。", "sentence_source": "generated"}, {"text": "古い壁にひびが入ったので、工事をたのんだ。", "target_word": "壁", "complexity_tier": "T3", "furigana": "古[ふる]い壁[かべ]にひびが入[はい]ったので、工事[こうじ]をたのんだ。", "sentence_source": "generated"}, {"text": "壁の色を青にかえたら、部屋が明るく見えた。", "target_word": "壁", "complexity_tier": "T3", "furigana": "壁[かべ]の色[いろ]を青[あお]にかえたら、部屋[へや]が明[あか]るく見[み]えた。", "sentence_source": "generated"}, {"text": "地震のとき、壁がくずれて道にたおれた。", "target_word": "壁", "complexity_tier": "T3", "furigana": "地震[じしん]のとき、壁[かべ]がくずれて道[みち]にたおれた。", "sentence_source": "generated"}, {"text": "城の壁は石でできていて、とても丈夫です。", "target_word": "壁", "complexity_tier": "T3", "furigana": "城[しろ]の壁[かべ]は石[いし]でできていて、とても丈夫[じょうぶ]です。", "sentence_source": "generated"}, {"text": "壁にはしごを立てかけて、屋根にのぼった。", "target_word": "壁", "complexity_tier": "T3", "furigana": "壁[かべ]にはしごを立[た]てかけて、屋根[やね]にのぼった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "壁", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "建物の内外や部屋を区切る、垂直に立つ構造物としての壁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: かざっ (Zipf 2.02)','sentence 7 above tier T2: contains vocabulary far above tier T2: たおれ (Zipf 1.74)','sentence 9 above tier T2: contains vocabulary far above tier T2: 立てかけ (Zipf 2.34)']::text[], '7e7e25ea-baf0-40aa-854e-f91aed929b10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41263, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "壁", "is_correct": true, "explanation": "フライング・バットレスが外から支えるのは建物の壁なので、ここは「壁」が正しい。"}, {"text": "扉", "is_correct": false, "explanation": "扉は開閉する建具で、大聖堂の外側から支える構造物ではないので合わない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は上り下りに使う設備で、外側から何かを支える役目はないので合わない。"}, {"text": "煙突", "is_correct": false, "explanation": "煙突は煙を出す筒で、ここでいう外側から支える構造物には当たらないので合わない。"}], "explanations": {"壁": "フライング・バットレスが外から支えるのは建物の壁なので、ここは「壁」が正しい。", "扉": "扉は開閉する建具で、大聖堂の外側から支える構造物ではないので合わない。", "階段": "階段は上り下りに使う設備で、外側から何かを支える役目はないので合わない。", "煙突": "煙突は煙を出す筒で、ここでいう外側から支える構造物には当たらないので合わない。"}, "sentence_index": 0, "correct_answer": "壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い夜は、壁を閉めて冷たい風を防いだ。", "explanation": "ここは〈窓や戸〉の意味。壁は開け閉めするものではないので「閉める」とは言わない。"}, {"text": "壁が冷たくて、裸足では歩けない。", "explanation": "ここは〈床〉の意味。歩く場所になるのは床で、壁の上を歩いて進むことはないので合わない。"}, {"text": "寒いので、服を壁にしまった。", "explanation": "ここは〈押し入れ・たんす〉の意味。壁は中に物を入れる場所ではないので「しまう」先にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41263, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壁", "is_correct": true, "explanation": "壁の色を青にかえるのは部屋の壁なので、「壁」が正しい。"}, {"text": "風", "is_correct": false, "explanation": "風には色を青にかえるという操作ができないので合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は色を塗り替える対象にならないので、ここでは合わない。"}, {"text": "霧", "is_correct": false, "explanation": "霧は色を塗り替える対象にならないので、ここでは合わない。"}], "explanations": {"壁": "壁の色を青にかえるのは部屋の壁なので、「壁」が正しい。", "風": "風には色を青にかえるという操作ができないので合わない。", "雨": "雨は色を塗り替える対象にならないので、ここでは合わない。", "霧": "霧は色を塗り替える対象にならないので、ここでは合わない。"}, "sentence_index": 6, "correct_answer": "壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟が壁に相談して、宿題の答えを決めた。", "explanation": "ここは〈人や相手〉の意味。壁は話を聞いて応じられないので、相談の相手にはならない。"}, {"text": "母は壁の料理を作ってくれた。", "explanation": "ここは〈食べ物〉の意味。壁は料理の材料にならないので、「壁の料理」という言い方は成り立たない。"}, {"text": "兄は壁の医者で、毎日患者を診ている。", "explanation": "ここは〈人〉の意味。壁は人ではないので、職業の「医者」を修飾する言い方にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41263, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この家は壁を厚くて、夏でも涼しい。", "corrected_sentence": "この家は壁が厚くて、夏でも涼しい。", "error_description": "「厚い」の主語は「壁」なので「壁が」が正しい。「壁を」にすると目的語になり、形容詞の文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41263, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "壁が塗って、部屋が明るくなった。", "corrected_sentence": "壁を塗って、部屋が明るくなった。", "error_description": "「塗る」の対象は「壁を」で示す。「壁が」にすると主語になり、「塗って」の目的語が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b1723d-0a83-488f-8cc3-0b5ba554d013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
