INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41264, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「積み上げる」の目的語「お皿」に付く格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、お皿を対象とする文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、お皿を起点にして積むという意味にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、ここでは比べる対象がなく文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「積み上げる」の目的語「お皿」に付く格助詞。", "へ": "「へ」は方向を表すため、お皿を対象とする文には合わない。", "から": "「から」は起点を表し、お皿を起点にして積むという意味にはならない。", "より": "「より」は比較を表し、ここでは比べる対象がなく文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41264, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを うえに のせて たかく する こと。", "primary_collocate": null, "pronunciation": "つみあげる", "ipa": "tsɯmiaɡeɾɯ", "syllable_count": 5, "sentences": [{"text": "子どもたちは積み木を高く積み上げて、塔を作った。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "子[こ]どもたちは積[つ]み木[き]を高[たか]く積[つ]み上[あ]げて、塔[とう]を作[つく]った。", "sentence_source": "generated"}, {"text": "倉庫の人は荷物を壁まで積み上げた。", "target_word": "積み上げた", "complexity_tier": "T3", "furigana": "倉庫[そうこ]の人[ひと]は荷物[にもつ]を壁[かべ]まで積[つ]み上[あ]げた。", "sentence_source": "generated"}, {"text": "本を机の上に積み上げると、くずれやすい。", "target_word": "積み上げる", "complexity_tier": "T3", "furigana": "本[ほん]を机[つくえ]の上[うえ]に積[つ]み上[あ]げると、くずれやすい。", "sentence_source": "generated"}, {"text": "雪が降る前に、薪を小屋に積み上げておいた。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]る前[まえ]に、薪[まき]を小屋[こや]に積[つ]み上[あ]げておいた。", "sentence_source": "generated"}, {"text": "彼は箱を一つずつ積み上げていった。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "彼[かれ]は箱[はこ]を一[ひと]つずつ積[つ]み上[あ]げていった。", "sentence_source": "generated"}, {"text": "石を積み上げて、小さな壁を作る。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "石[いし]を積[つ]み上[あ]げて、小[ちい]さな壁[かべ]を作[つく]る。", "sentence_source": "generated"}, {"text": "田中さんは古い雑誌を部屋のすみに積み上げている。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "田中[たなか]さんは古[ふる]い雑誌[ざっし]を部屋[へや]のすみに積[つ]み上[あ]げている。", "sentence_source": "generated"}, {"text": "お皿をそんなに高く積み上げたら、落ちますよ。", "target_word": "積み上げたら", "complexity_tier": "T3", "furigana": "お皿[さら]をそんなに高[たか]く積[つ]み上[あ]げたら、落[お]ちますよ。", "sentence_source": "generated"}, {"text": "農家の人が収穫した米の袋をトラックに積み上げた。", "target_word": "積み上げた", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]が収穫[しゅうかく]した米[こめ]の袋[ふくろ]をトラックに積[つ]み上[あ]げた。", "sentence_source": "generated"}, {"text": "レンガを積み上げる仕事は、思ったより大変だ。", "target_word": "積み上げる", "complexity_tier": "T3", "furigana": "レンガを積[つ]み上[あ]げる仕事[しごと]は、思[おも]ったより大変[たいへん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "積み上げる", "label": "辞書形"}, {"form": "積み上げて", "label": "て形"}, {"form": "積み上げた", "label": "た形"}, {"form": "積み上げない", "label": "ない形"}, {"form": "積み上げられる", "label": "受身形"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "物を上に重ねて高くする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41264, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "積み上げて", "is_correct": true, "explanation": "て形で、後ろの「塔を作った」に続く。ここでは正しい形。"}, {"text": "積み上げよう", "is_correct": false, "explanation": "意向形では文が切れず、「塔を作った」とつながらない。"}, {"text": "積み上げられて", "is_correct": false, "explanation": "受身にすると「積み木を」が成り立たず、主語の子どもたちとも合わない。"}, {"text": "積み上げます", "is_correct": false, "explanation": "丁寧体の語幹では「、」の後の過去の文につながらない。"}], "explanations": {"積み上げて": "て形で、後ろの「塔を作った」に続く。ここでは正しい形。", "積み上げよう": "意向形では文が切れず、「塔を作った」とつながらない。", "積み上げられて": "受身にすると「積み木を」が成り立たず、主語の子どもたちとも合わない。", "積み上げます": "丁寧体の語幹では「、」の後の過去の文につながらない。"}, "sentence_index": 0, "correct_answer": "積み上げて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "タオルを積み上げて、ぎゅっとねじって水を切った。", "explanation": "ここは〈ねじる〉の意味。積み上げるは物を上へ重ねることで、布に力を加えて水を絞り出す動作には合わない。"}, {"text": "ばらばらの部品を積み上げて、机を作った。", "explanation": "ここは〈組み立てる〉の意味。積み上げるは物を上へ重ねることで、部品を組んで作る意味では使わない。"}, {"text": "本を横一列に積み上げて、棚に置いた。", "explanation": "ここは〈並べる〉の意味。積み上げるは上へ重ねることなので、横一列には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41264, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "積み上げて", "is_correct": true, "explanation": "て形で、後ろの「いる」と続いて「積み上げている」になる。"}, {"text": "積み上げ", "is_correct": false, "explanation": "語幹だけでは「いる」とつながらず、「積み上げいる」になってしまう。"}, {"text": "積み上げなかった", "is_correct": false, "explanation": "否定過去は「いる」と続かず、現在進行の意味が崩れる。"}, {"text": "積み上げた", "is_correct": false, "explanation": "た形は「いる」と続かず、「積み上げている」の形にならない。"}], "explanations": {"積み上げて": "て形で、後ろの「いる」と続いて「積み上げている」になる。", "積み上げ": "語幹だけでは「いる」とつながらず、「積み上げいる」になってしまう。", "積み上げなかった": "否定過去は「いる」と続かず、現在進行の意味が崩れる。", "積み上げた": "た形は「いる」と続かず、「積み上げている」の形にならない。"}, "sentence_index": 6, "correct_answer": "積み上げて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ひまわりの種を畑全体に積み上げた。", "explanation": "ここは〈まく〉の意味。積み上げるは物を上に重ねることで、種を地面に広くばらまく動作には合わない。"}, {"text": "野球のボールを空高く積み上げた。", "explanation": "ここは〈投げる〉の意味。積み上げるは物を重ねることで、物を空中へ放る動作には合わない。"}, {"text": "井戸を地面の下へ深く積み上げた。", "explanation": "ここは〈掘る〉の意味。積み上げるは重ねる動作で、地面を掘って穴をあける意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41264, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薪を小屋に積み上げでおくと、雨に濡れにくい。", "corrected_sentence": "薪を小屋に積み上げておくと、雨に濡れにくい。", "error_description": "「積み上げておく」のて形は「て」。「で」にすると誤った形になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "積み上げた", "is_correct": true, "explanation": "た形で、過去の動作として文末と合う。"}, {"text": "積み上げて", "is_correct": false, "explanation": "て形のままでは文が完結せず、過去の出来事として終わらない。"}, {"text": "積み上げたり", "is_correct": false, "explanation": "たり形は並列の途中の形で、文を終えることができない。"}, {"text": "積み上げられた", "is_correct": false, "explanation": "受身形になり、倉庫の人が積んだのではなく荷物が積まれた意味になる。"}], "correct_form": "積み上げた", "base_form": "積み上げる", "form_label": "た形", "sentence_index": 1, "explanations": {"積み上げた": "た形で、過去の動作として文末と合う。", "積み上げて": "て形のままでは文が完結せず、過去の出来事として終わらない。", "積み上げたり": "たり形は並列の途中の形で、文を終えることができない。", "積み上げられた": "受身形になり、倉庫の人が積んだのではなく荷物が積まれた意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41264, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い雑誌を部屋のすみを積み上げておいた。", "corrected_sentence": "古い雑誌を部屋のすみに積み上げておいた。", "error_description": "場所を示す助詞は「に」。「積み上げる」の直前は「に」で、「を」にすると不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "積み上げたら", "is_correct": true, "explanation": "たら形で、「たら」の仮定の条件を表す。ここでは正しい形。"}, {"text": "積み上げる", "is_correct": false, "explanation": "辞書形では条件の「たら」の意味にならず、文が続かない。"}, {"text": "積み上げよう", "is_correct": false, "explanation": "意向形では「落ちますよ」と条件の文がつながらず、文が成り立たない。"}, {"text": "積み上げなかった", "is_correct": false, "explanation": "否定過去は、条件を述べる文の形と合わない。"}], "correct_form": "積み上げたら", "base_form": "積み上げる", "form_label": "たら形", "sentence_index": 7, "explanations": {"積み上げたら": "たら形で、「たら」の仮定の条件を表す。ここでは正しい形。", "積み上げる": "辞書形では条件の「たら」の意味にならず、文が続かない。", "積み上げよう": "意向形では「落ちますよ」と条件の文がつながらず、文が成り立たない。", "積み上げなかった": "否定過去は、条件を述べる文の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41265, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41265, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「積み上げる」の目的語「丸太」に付く格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、丸太を対象とする積む動作には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、ここでは比べる対象がなく文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、積み上げる動作の対象は丸太なので成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「積み上げる」の目的語「丸太」に付く格助詞。", "へ": "「へ」は方向を表し、丸太を対象とする積む動作には合わない。", "より": "「より」は比較を表し、ここでは比べる対象がなく文が成り立たない。", "が": "「が」は主語を示すが、積み上げる動作の対象は丸太なので成り立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41265, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を順番に上に重ねて、高くしたり、山のようにしたりすること。", "primary_collocate": null, "pronunciation": "つみあげる", "ipa": "tsɯmiaɡeɾɯ", "syllable_count": 5, "sentences": [{"text": "店員は缶詰を順番に積み上げて、山のように見せた。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "店員[てんいん]は缶詰[かんづめ]を順番[じゅんばん]に積[つ]み上[あ]げて、山[やま]のように見[み]せた。", "sentence_source": "generated"}, {"text": "港では、コンテナが何段にも積み上げられている。", "target_word": "積み上げられて", "complexity_tier": "T3", "furigana": "港[みなと]では、コンテナが何段[なんだん]にも積[つ]み上[あ]げられている。", "sentence_source": "generated"}, {"text": "母は洗濯したタオルをきちんと積み上げた。", "target_word": "積み上げた", "complexity_tier": "T3", "furigana": "母[はは]は洗濯[せんたく]したタオルをきちんと積[つ]み上[あ]げた。", "sentence_source": "generated"}, {"text": "子どもがブロックを積み上げては、すぐにくずしている。", "target_word": "積み上げては", "complexity_tier": "T3", "furigana": "子[こ]どもがブロックを積[つ]み上[あ]げては、すぐにくずしている。", "sentence_source": "generated"}, {"text": "工事の前に、砂の袋を順番に積み上げておく。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "工事[こうじ]の前[まえ]に、砂[すな]の袋[ふくろ]を順番[じゅんばん]に積[つ]み上[あ]げておく。", "sentence_source": "generated"}, {"text": "畑のわきに、刈った草が山のように積み上げてある。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "畑[はたけ]のわきに、刈[か]った草[くさ]が山[やま]のように積[つ]み上[あ]げてある。", "sentence_source": "generated"}, {"text": "彼は大きさの順に、棚の横へ箱を積み上げた。", "target_word": "積み上げた", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きさの順[じゅん]に、棚[たな]の横[よこ]へ箱[はこ]を積[つ]み上[あ]げた。", "sentence_source": "generated"}, {"text": "祭りの前に、みんなで丸太を積み上げて、やぐらを作った。", "target_word": "積み上げて", "complexity_tier": "T3", "furigana": "祭[まつ]りの前[まえ]に、みんなで丸太[まるた]を積[つ]み上[あ]げて、やぐらを作[つく]った。", "sentence_source": "generated"}, {"text": "テーブルいっぱいに、果物が積み上げられていた。", "target_word": "積み上げられて", "complexity_tier": "T3", "furigana": "テーブルいっぱいに、果物[くだもの]が積[つ]み上[あ]げられていた。", "sentence_source": "generated"}, {"text": "雪かきでどけた雪を、道の両側に積み上げた。", "target_word": "積み上げた", "complexity_tier": "T3", "furigana": "雪[ゆき]かきでどけた雪[ゆき]を、道[みち]の両側[りょうがわ]に積[つ]み上[あ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "積み上げる", "label": "辞書形"}, {"form": "積み上げて", "label": "て形"}, {"form": "積み上げた", "label": "た形"}, {"form": "積み上げられて", "label": "受身て形"}, {"form": "積み上げては", "label": "ては形"}], "register": "標準（丁寧体・普通体）", "sense_fingerprint": "物を順に重ねて高く・山のようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41265, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "積み上げて", "is_correct": true, "explanation": "て形で、「山のように見せた」に続き、積んでから見せたという流れになる。"}, {"text": "積み上げよう", "is_correct": false, "explanation": "意向形では「山のように見せた」とつながらず、文が成り立たない。"}, {"text": "積み上げない", "is_correct": false, "explanation": "「で」なしでは否定の形が続かず、「見せた」との関係が崩れる。"}, {"text": "積み上げます", "is_correct": false, "explanation": "丁寧体は「、」の後の過去の文につながらない。"}], "explanations": {"積み上げて": "て形で、「山のように見せた」に続き、積んでから見せたという流れになる。", "積み上げよう": "意向形では「山のように見せた」とつながらず、文が成り立たない。", "積み上げない": "「で」なしでは否定の形が続かず、「見せた」との関係が崩れる。", "積み上げます": "丁寧体は「、」の後の過去の文につながらない。"}, "sentence_index": 0, "correct_answer": "積み上げて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "荷物をひもで積み上げた。", "explanation": "ここは〈結ぶ〉の意味。積み上げるは物を重ねる動作で、ひもで縛る意味には合わない。"}, {"text": "テーブルを積み上げて、きれいにふき取った。", "explanation": "ここは〈ふく〉の意味。積み上げるは物を上へ重ねることで、布で表面の汚れを拭き取る動作には合わない。"}, {"text": "ボールを坂の上から積み上げた。", "explanation": "ここは〈転がす〉の意味。積み上げるは物を上に重ねることで、坂を転がす動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41265, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "積み上げた", "is_correct": true, "explanation": "た形で、「箱を積み上げた」と文が完結する。"}, {"text": "積み上げ", "is_correct": false, "explanation": "語幹だけでは文が終わらず、「箱を積み上げ」で切れてしまう。"}, {"text": "積み上げたら", "is_correct": false, "explanation": "たら形は条件を表し、ここで文を終えることができない。"}, {"text": "積み上げれば", "is_correct": false, "explanation": "仮定形は条件を表し、文を完結させる形ではない。"}], "explanations": {"積み上げた": "た形で、「箱を積み上げた」と文が完結する。", "積み上げ": "語幹だけでは文が終わらず、「箱を積み上げ」で切れてしまう。", "積み上げたら": "たら形は条件を表し、ここで文を終えることができない。", "積み上げれば": "仮定形は条件を表し、文を完結させる形ではない。"}, "sentence_index": 6, "correct_answer": "積み上げた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "おにぎりをラップで積み上げて、弁当箱に入れた。", "explanation": "ここは〈包む〉の意味。積み上げるは物を重ねる動作で、ラップで覆う意味には合わない。"}, {"text": "鉛筆を小刀で積み上げて、先をとがらせた。", "explanation": "ここは〈削る〉の意味。積み上げるは重ねる動作で、刃物で表面を削る意味には合わない。"}, {"text": "ドアを強く積み上げて、大きな音を立てた。", "explanation": "ここは〈叩く〉の意味。積み上げるは重ねる動作で、打ちつける意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41265, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "缶詰を順番と積み上げた。", "corrected_sentence": "缶詰を順番に積み上げた。", "error_description": "「順番に」の「に」は様子を表す。「と」にすると誤った文になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "積み上げられて", "is_correct": true, "explanation": "受身て形で、「何段にも積み上げられている」の形として正しい。"}, {"text": "積み上げよう", "is_correct": false, "explanation": "意向形は「いる」と続かず、受身の状態を述べる文と合わない。"}, {"text": "積み上げる", "is_correct": false, "explanation": "辞書形では「いる」と続かず、受身の状態を表せない。"}, {"text": "積み上げられた", "is_correct": false, "explanation": "た形では「いる」と続かず、現在の状態を表す文と合わない。"}], "correct_form": "積み上げられて", "base_form": "積み上げる", "form_label": "受身て形", "sentence_index": 1, "explanations": {"積み上げられて": "受身て形で、「何段にも積み上げられている」の形として正しい。", "積み上げよう": "意向形は「いる」と続かず、受身の状態を述べる文と合わない。", "積み上げる": "辞書形では「いる」と続かず、受身の状態を表せない。", "積み上げられた": "た形では「いる」と続かず、現在の状態を表す文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41265, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "丸太を広場に積み上げでおいた。", "corrected_sentence": "丸太を広場に積み上げておいた。", "error_description": "「積み上げておく」のて形は「て」。「で」にすると誤った形になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "積み上げて", "is_correct": true, "explanation": "て形で、後ろの「やぐらを作った」に続く。ここでは正しい形。"}, {"text": "積み上げない", "is_correct": false, "explanation": "否定形では「やぐらを作った」とつながらず、積んだ事実と合わない。"}, {"text": "積み上げなかった", "is_correct": false, "explanation": "否定過去では積んだ事実と矛盾する。"}, {"text": "積み上げられる", "is_correct": false, "explanation": "受身の辞書形では、みんなで積む動作を表せない。"}], "correct_form": "積み上げて", "base_form": "積み上げる", "form_label": "て形", "sentence_index": 7, "explanations": {"積み上げて": "て形で、後ろの「やぐらを作った」に続く。ここでは正しい形。", "積み上げない": "否定形では「やぐらを作った」とつながらず、積んだ事実と合わない。", "積み上げなかった": "否定過去では積んだ事実と矛盾する。", "積み上げられる": "受身の辞書形では、みんなで積む動作を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41268, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「土木の仕事」のように、名詞の「土木」を後ろの「仕事」とつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「仕事」を修飾するには使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、名詞同士をつなぐ働きがない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表すが、「土木と仕事で」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「土木の仕事」のように、名詞の「土木」を後ろの「仕事」とつなぐ。", "を": "「を」は目的語を示すが、「仕事」を修飾するには使えない。", "へ": "「へ」は方向を表し、名詞同士をつなぐ働きがない。", "と": "「と」は並列を表すが、「土木と仕事で」では意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
