INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41268, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "建物や道路、橋などを作るための勉強や仕事のことです。", "primary_collocate": null, "pronunciation": "どぼく", "ipa": "dobokɯ", "syllable_count": 3, "sentences": [{"text": "兄は大学で土木を勉強している。", "target_word": "土木", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]で土木[どぼく]を勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "父は土木の仕事で、毎日道路を作っている。", "target_word": "土木", "complexity_tier": "T3", "furigana": "父[ちち]は土木[どぼく]の仕事[しごと]で、毎日[まいにち]道路[どうろ]を作[つく]っている。", "sentence_source": "generated"}, {"text": "土木の会社で働く人は、夏も外で作業する。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]の会社[かいしゃ]で働[はたら]く人[ひと]は、夏[なつ]も外[そと]で作業[さぎょう]する。", "sentence_source": "generated"}, {"text": "橋を作りたいから、土木を学ぶことにした。", "target_word": "土木", "complexity_tier": "T3", "furigana": "橋[はし]を作[つく]りたいから、土木[どぼく]を学[まな]ぶことにした。", "sentence_source": "generated"}, {"text": "土木の現場では、ヘルメットを必ずかぶる。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]の現場[げんば]では、ヘルメットを必[かなら]ずかぶる。", "sentence_source": "generated"}, {"text": "彼女は土木を専門にして、町の道を直している。", "target_word": "土木", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は土木[どぼく]を専門[せんもん]にして、町[まち]の道[みち]を直[なお]している。", "sentence_source": "generated"}, {"text": "土木の仕事は大変だが、町の人の役に立つ。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]の仕事[しごと]は大変[たいへん]だが、町[まち]の人[ひと]の役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "雨の日は、土木の工事が止まることが多い。", "target_word": "土木", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、土木[どぼく]の工事[こうじ]が止[と]まることが多[おお]い。", "sentence_source": "generated"}, {"text": "祖父は若いころ土木の仕事をしていたそうだ。", "target_word": "土木", "complexity_tier": "T3", "furigana": "祖父[そふ]は若[わか]いころ土木[どぼく]の仕事[しごと]をしていたそうだ。", "sentence_source": "generated"}, {"text": "土木を学ぶ学生は、川や山の調査にも行く。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]を学[まな]ぶ学生[がくせい]は、川[かわ]や山[やま]の調査[ちょうさ]にも行[い]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "土木", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "道路や橋を作る勉強・仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41268, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土木", "is_correct": true, "explanation": "勉強の対象として「土木を勉強している」と自然につながる。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は勉強の対象にならず、「渋滞を勉強している」と言えない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、勉強の対象にならない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は行為で、「勉強する」の対象にはならない。"}], "explanations": {"土木": "勉強の対象として「土木を勉強している」と自然につながる。", "渋滞": "渋滞は勉強の対象にならず、「渋滞を勉強している」と言えない。", "冷蔵庫": "冷蔵庫は家電で、勉強の対象にならない。", "散歩": "散歩は行為で、「勉強する」の対象にはならない。"}, "sentence_index": 0, "correct_answer": "土木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家を建てたいから、土木を学ぶことにした。", "explanation": "ここは〈建築〉の意味。土木は道路や橋などの社会基盤を扱い、家を建てる分野ではない。"}, {"text": "山の木を切るため、土木を学ぶことにした。", "explanation": "ここは〈林業〉の意味。土木は建設の分野で、木を切る仕事には合わない。"}, {"text": "絵を描く腕を磨くため、土木を学ぶことにした。", "explanation": "ここは〈美術〉の意味。土木は道路や橋の建設で、絵を描く技術とは関係がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41268, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土木", "is_correct": true, "explanation": "「土木の仕事は大変だが、町の人の役に立つ」と文脈に合う分野名。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、「仕事」を表せない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は物で、町の人の役に立つ仕事の分野にはならない。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は気体で、仕事の分野を表さない。"}], "explanations": {"土木": "「土木の仕事は大変だが、町の人の役に立つ」と文脈に合う分野名。", "夕焼け": "夕焼けは空の現象で、「仕事」を表せない。", "鉛筆": "鉛筆は物で、町の人の役に立つ仕事の分野にはならない。", "湯気": "湯気は気体で、仕事の分野を表さない。"}, "sentence_index": 6, "correct_answer": "土木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病気を治すため、土木を学ぶ学生は病院で実習する。", "explanation": "ここは〈医学〉の意味。土木は道路や橋などの建設が対象で、病気の治療には合わない。"}, {"text": "機械を設計するため、土木を学ぶ学生は工場を見学する。", "explanation": "ここは〈工学〉の機械設計の意味。土木は社会基盤の建設が対象で、機械設計には合わない。"}, {"text": "料理の腕を上げるため、土木を学ぶ学生は調理場で実習する。", "explanation": "ここは〈調理〉の意味。土木は建設の分野で、料理の技術とは関係がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41268, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は専門学校で土木が学んでいる。", "corrected_sentence": "姉は専門学校で土木を学んでいる。", "error_description": "「学ぶ」の目的語には「を」を使う。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41268, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土木を仕事は夜勤が多い。", "corrected_sentence": "土木の仕事は夜勤が多い。", "error_description": "「仕事」を修飾するには「の」が必要。「を」にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41269, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「土木の技術」のように、名詞の「土木」を後ろの「技術」とつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「技術」を修飾するには使えない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示し、名詞を修飾する働きがない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を表し、「技術」を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「土木の技術」のように、名詞の「土木」を後ろの「技術」とつなぐ。", "が": "「が」は主語を示すが、「技術」を修飾するには使えない。", "を": "「を」は目的語を示し、名詞を修飾する働きがない。", "に": "「に」は場所や対象を表し、「技術」を修飾できない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41269, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「専攻する」の目的語「土木」に付く格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表し、専攻する対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、専攻の対象には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を表し、「土木と専攻し」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「専攻する」の目的語「土木」に付く格助詞。", "で": "「で」は手段や場所を表し、専攻する対象を示せない。", "へ": "「へ」は方向を表し、専攻の対象には使えない。", "と": "「と」は並列を表し、「土木と専攻し」では文が成り立たない。"}, "error_tags": {"で": "手段", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41269, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "建物、道路、橋、ダムなど、社会の基盤となる構造物を計画・設計・建設・維持するための技術や学問。", "primary_collocate": null, "pronunciation": "どぼく", "ipa": "dobokɯ", "syllable_count": 3, "sentences": [{"text": "土木は、社会の基盤となる構造物をつくる技術である。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]は、社会[しゃかい]の基盤[きばん]となる構造物[こうぞうぶつ]をつくる技術[ぎじゅつ]である。", "sentence_source": "generated"}, {"text": "日本は地震が多いため、土木の技術が特に発達してきた。", "target_word": "土木", "complexity_tier": "T3", "furigana": "日本[にほん]は地震[じしん]が多[おお]いため、土木[どぼく]の技術[ぎじゅつ]が特[とく]に発達[はったつ]してきた。", "sentence_source": "generated"}, {"text": "ダムの維持管理は、土木の重要な役割の一つだ。", "target_word": "土木", "complexity_tier": "T3", "furigana": "ダムの維持[いじ]管理[かんり]は、土木[どぼく]の重要[じゅうよう]な役割[やくわり]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "この大学の土木の研究室では、橋の耐震設計を扱っている。", "target_word": "土木", "complexity_tier": "T3", "furigana": "この大学[だいがく]の土木[どぼく]の研究室[けんきゅうしつ]では、橋[はし]の耐震[たいしん]設計[せっけい]を扱[あつか]っている。", "sentence_source": "generated"}, {"text": "土木は、計画から維持まで、まちの安全を支える学問だ。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]は、計画[けいかく]から維持[いじ]まで、まちの安全[あんぜん]を支[ささ]える学問[がくもん]だ。", "sentence_source": "generated"}, {"text": "土木の専門家が、堤防の強度を調べている。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]の専門家[せんもんか]が、堤防[ていぼう]の強度[きょうど]を調[しら]べている。", "sentence_source": "generated"}, {"text": "災害に強い町づくりには、土木の知識が欠かせない。", "target_word": "土木", "complexity_tier": "T3", "furigana": "災害[さいがい]に強[つよ]い町[まち]づくりには、土木[どぼく]の知識[ちしき]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "彼は土木を専攻し、トンネルの設計に携わっている。", "target_word": "土木", "complexity_tier": "T3", "furigana": "彼[かれ]は土木[どぼく]を専攻[せんこう]し、トンネルの設計[せっけい]に携[たずさ]わっている。", "sentence_source": "generated"}, {"text": "古代ローマの土木は、水道橋などに今も姿を残している。", "target_word": "土木", "complexity_tier": "T3", "furigana": "古代[こだい]ローマの土木[どぼく]は、水道橋[すいどうきょう]などに今[いま]も姿[すがた]を残[のこ]している。", "sentence_source": "generated"}, {"text": "土木の分野でも、ドローンを使った測量が広がっている。", "target_word": "土木", "complexity_tier": "T3", "furigana": "土木[どぼく]の分野[ぶんや]でも、ドローンを使[つか]った測量[そくりょう]が広[ひろ]がっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "土木", "label": "基本形"}], "register": "文章語（硬めの説明文）", "sense_fingerprint": "社会基盤を計画・建設・維持する技術と学問", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a97fd89-32a8-419f-a096-ef0c799e5c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41269, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土木", "is_correct": true, "explanation": "「構造物をつくる技術」を指す語で、文の主語として自然に入る。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文書で、構造物をつくる技術ではない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は自然現象で、技術の分野にはならない。"}, {"text": "踊り", "is_correct": false, "explanation": "踊りは芸能で、構造物をつくる技術とは関係がない。"}], "explanations": {"土木": "「構造物をつくる技術」を指す語で、文の主語として自然に入る。", "手紙": "手紙は文書で、構造物をつくる技術ではない。", "天気": "天気は自然現象で、技術の分野にはならない。", "踊り": "踊りは芸能で、構造物をつくる技術とは関係がない。"}, "sentence_index": 0, "correct_answer": "土木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この大学の土木の研究室では、家の間取りを扱っている。", "explanation": "ここは〈建築〉の意味。土木は道路や橋などの社会基盤が対象で、家の間取りを扱う分野ではない。"}, {"text": "この大学の土木の研究室では、ロボットの制御を扱っている。", "explanation": "ここは〈機械工学〉の意味。土木は道路や橋などの構造物が対象で、ロボットの制御を扱う分野ではない。"}, {"text": "この大学の土木の研究室では、新薬の効果を調べている。", "explanation": "ここは〈医学〉の意味。土木は社会基盤の建設が対象で、薬の効果を調べる分野ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41269, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土木", "is_correct": true, "explanation": "「災害に強い町づくり」の分野として、「土木の知識」と文脈に合う。"}, {"text": "手芸", "is_correct": false, "explanation": "手芸は趣味の分野で、災害に強い町づくりの知識とは関係がない。"}, {"text": "美容", "is_correct": false, "explanation": "美容は身だしなみの分野で、町づくりには関係がない。"}, {"text": "占い", "is_correct": false, "explanation": "占いは町づくりの知識にならず、文脈に合わない。"}], "explanations": {"土木": "「災害に強い町づくり」の分野として、「土木の知識」と文脈に合う。", "手芸": "手芸は趣味の分野で、災害に強い町づくりの知識とは関係がない。", "美容": "美容は身だしなみの分野で、町づくりには関係がない。", "占い": "占いは町づくりの知識にならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "土木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農薬を散布するため、ドローンを使った農業の分野でも土木が広がっている。", "explanation": "ここは〈農業〉の意味。土木は道路や橋などの建設の分野で、農薬散布とは合わない。"}, {"text": "映像を撮影するため、芸術の分野でも土木を使ったドローンが広がっている。", "explanation": "ここは〈芸術〉の意味。土木は社会基盤の建設の分野で、映像撮影を表す語ではない。"}, {"text": "舞台の照明を調整するため、演劇の分野でも土木にドローンが広がっている。", "explanation": "ここは〈演劇〉の意味。土木は建設の分野で、照明の調整とは関係がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41269, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は土木を研究を続けている。", "corrected_sentence": "彼女は土木の研究を続けている。", "error_description": "「土木の研究」の「の」を「を」に変えると誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41269, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は土木を詳しい。", "corrected_sentence": "彼は土木に詳しい。", "error_description": "「詳しい」には「に」を使う。「を」にすると誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8f27e85-70a1-42e9-8e5b-8fbd0521c983') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
