INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41272, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "友だちと、けんかをしないで、たのしくすること。", "primary_collocate": null, "pronunciation": "なかよく", "ipa": "nakajokɯ", "syllable_count": 4, "sentences": [{"text": "兄と妹は、けんかをしないで仲良く遊んでいます。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "兄[あに]と妹[いもうと]は、けんかをしないで仲良[なかよ]く遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "公園で友だちと仲良く砂遊びをした。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "公園[こうえん]で友[とも]だちと仲良[なかよ]く砂遊[すなあそ]びをした。", "sentence_source": "generated"}, {"text": "先生は「みんな仲良くしましょう」と言いました。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "先生[せんせい]は「みんな仲良[なかよ]くしましょう」と言[い]いました。", "sentence_source": "generated"}, {"text": "二人の子どもは、おもちゃを仲良く分けて使っている。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "二人[ふたり]の子[こ]どもは、おもちゃを仲良[なかよ]く分[わ]けて使[つか]っている。", "sentence_source": "generated"}, {"text": "弟とは仲良く暮らしたいので、けんかをしないようにしている。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "弟[おとうと]とは仲良[なかよ]く暮[く]らしたいので、けんかをしないようにしている。", "sentence_source": "generated"}, {"text": "隣の席の子と仲良くなって、毎日いっしょに帰る。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "隣[となり]の席[せき]の子[こ]と仲良[なかよ]くなって、毎日[まいにち]いっしょに帰[かえ]る。", "sentence_source": "generated"}, {"text": "犬と猫が仲良く並んで寝ているのを見て、みんな笑った。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "犬[いぬ]と猫[ねこ]が仲良[なかよ]く並[なら]んで寝[ね]ているのを見[み]て、みんな笑[わら]った。", "sentence_source": "generated"}, {"text": "遠足では、グループの友だちと仲良くお弁当を食べました。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "遠足[えんそく]では、グループの友[とも]だちと仲良[なかよ]くお弁当[べんとう]を食[た]べました。", "sentence_source": "generated"}, {"text": "けんかをしても、すぐ仲直りして、また仲良く遊べばいい。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "けんかをしても、すぐ仲直[なかなお]りして、また仲良[なかよ]く遊[あそ]べばいい。", "sentence_source": "generated"}, {"text": "母は「姉妹なんだから、仲良くしなさい」と言った。", "target_word": "仲良く", "complexity_tier": "T3", "furigana": "母[はは]は「姉妹[しまい]なんだから、仲良[なかよ]くしなさい」と言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仲良く", "label": "副詞形"}, {"form": "仲良くなる", "label": "変化の形"}], "register": "標準", "sense_fingerprint": "子ども同士がけんかをせず楽しく過ごすさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 砂遊び (Zipf 2.22)']::text[], '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41272, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仲良く", "is_correct": true, "explanation": "「けんかをしないで」と合い、友だちどうしが楽しく遊ぶ様子を表す副詞。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す語。遊ぶ様子には合わない。"}, {"text": "ぺこぺこ", "is_correct": false, "explanation": "空腹の状態を表す語で、遊ぶ動作を修飾できない。"}, {"text": "ぐったり", "is_correct": false, "explanation": "疲れて力が抜けた様子。元気に遊んでいる状況と矛盾する。"}], "explanations": {"仲良く": "「けんかをしないで」と合い、友だちどうしが楽しく遊ぶ様子を表す副詞。", "ぐっすり": "眠りの深さを表す語。遊ぶ様子には合わない。", "ぺこぺこ": "空腹の状態を表す語で、遊ぶ動作を修飾できない。", "ぐったり": "疲れて力が抜けた様子。元気に遊んでいる状況と矛盾する。"}, "sentence_index": 0, "correct_answer": "仲良く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "親友は仲良く約束を裏切った。", "explanation": "〈仲良く〉は親しく和やかに振る舞う意味。約束を裏切る行為とは噛み合わず、〈無断で〉の意味と混同した使い方になる。"}, {"text": "夕立が仲良く降り出した。", "explanation": "〈仲良く〉を雨の降り方に当てはめた誤用。この語は人どうしの親しい振る舞いの意味で、雨脚の強さを表す〈激しく〉の意味とは別。"}, {"text": "先生は生徒を仲良く叱った。", "explanation": "〈仲良く〉は双方が親しく関わる様子。一方的な叱責には使えず、〈厳しく〉と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41272, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仲良く", "is_correct": true, "explanation": "「並んで寝ている」様子に合い、仲のよい様子を表す副詞。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝く様子を表す語。寝ている犬と猫の様子には当てはまらない。"}, {"text": "ぐるぐる", "is_correct": false, "explanation": "回転する様子を表す語。並んで寝ている様子とは合わない。"}, {"text": "ぷかぷか", "is_correct": false, "explanation": "水などに浮かぶ様子を表す語。寝ている動物には使えない。"}], "explanations": {"仲良く": "「並んで寝ている」様子に合い、仲のよい様子を表す副詞。", "きらきら": "光が輝く様子を表す語。寝ている犬と猫の様子には当てはまらない。", "ぐるぐる": "回転する様子を表す語。並んで寝ている様子とは合わない。", "ぷかぷか": "水などに浮かぶ様子を表す語。寝ている動物には使えない。"}, "sentence_index": 6, "correct_answer": "仲良く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄は妹の宿題を仲良く横取りした。", "explanation": "〈仲良く〉は親しく協力する意味。奪い取る行為とは合わず、〈無理やり〉と混同した使い方になる。"}, {"text": "彼は一人で仲良く買い物をした。", "explanation": "〈仲良く〉を単独の行動に当てはめた誤用。この語は相手どうしが親しく振る舞う意味で、〈気ままに〉の意味とは別。"}, {"text": "会社は社員を仲良くクビにした。", "explanation": "〈仲良く〉は双方が和やかに関わる様子。一方的な解雇には使わず、〈一方的に〉と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41272, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹と仲良くに遊んだ。", "corrected_sentence": "妹と仲良く遊んだ。", "error_description": "副詞の〈仲良く〉には格助詞〈に〉を付けない。〈仲良く〉の直後には動詞が続く形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41272, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子犬と子猫が仲良くで並んで眠っている。", "corrected_sentence": "子犬と子猫が仲良く並んで眠っている。", "error_description": "副詞〈仲良く〉に格助詞〈で〉は付かない。〈仲良く〉は動詞「並んで眠る」を直接修飾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
