INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41273, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "互いに親しく、友好的に行動するさま。", "primary_collocate": null, "pronunciation": "なかよく", "ipa": "nakajokɯ", "syllable_count": 4, "sentences": [{"text": "隣の家の人たちとは、引っ越してきた時から仲良く付き合っている。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "隣[となり]の家[いえ]の人[ひと]たちとは、引[ひ]っ越[こ]してきた時[とき]から仲良[なかよ]く付[つ]き合[あ]っている。", "sentence_source": "generated"}, {"text": "両国が仲良く協力して、川の環境を守っている。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "両国[りょうこく]が仲良[なかよ]く協力[きょうりょく]して、川[かわ]の環境[かんきょう]を守[まも]っている。", "sentence_source": "generated"}, {"text": "職場の同僚と仲良く働けるので、仕事が楽しい。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "職場[しょくば]の同僚[どうりょう]と仲良[なかよ]く働[はたら]けるので、仕事[しごと]が楽[たの]しい。", "sentence_source": "generated"}, {"text": "夫婦は結婚して四十年、いつも仲良く暮らしている。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "夫婦[ふうふ]は結婚[けっこん]して四十年[よんじゅうねん]、いつも仲良[なかよ]く暮[く]らしている。", "sentence_source": "generated"}, {"text": "近所の人と仲良くするために、毎朝あいさつをしている。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "近所[きんじょ]の人[ひと]と仲良[なかよ]くするために、毎朝[まいあさ]あいさつをしている。", "sentence_source": "generated"}, {"text": "新しい部署のメンバーと仲良くなりたくて、昼食に誘った。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "新[あたら]しい部署[ぶしょ]のメンバーと仲良[なかよ]くなりたくて、昼食[ちゅうしょく]に誘[さそ]った。", "sentence_source": "generated"}, {"text": "祖父母は庭の花を見ながら、仲良くお茶を飲んでいた。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "祖父母[そふぼ]は庭[にわ]の花[はな]を見[み]ながら、仲良[なかよ]くお茶[ちゃ]を飲[の]んでいた。", "sentence_source": "generated"}, {"text": "意見は違っても、仲良く話し合えば答えは見つかる。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "意見[いけん]は違[ちが]っても、仲良[なかよ]く話[はな]し合[あ]えば答[こた]えは見[み]つかる。", "sentence_source": "generated"}, {"text": "町の人々は、外国から来た留学生とも仲良く交流している。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "町[まち]の人々[ひとびと]は、外国[がいこく]から来[き]た留学生[りゅうがくせい]とも仲良[なかよ]く交流[こうりゅう]している。", "sentence_source": "generated"}, {"text": "二つの店は競争相手だが、客の前では仲良く挨拶を交わす。", "target_word": "仲良く", "complexity_tier": "T4", "furigana": "二[ふた]つの店[みせ]は競争相手[きょうそうあいて]だが、客[きゃく]の前[まえ]では仲良[なかよ]く挨拶[あいさつ]を交[か]わす。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仲良く", "label": "副詞形"}, {"form": "仲良くする", "label": "動詞を伴う形"}], "register": "標準", "sense_fingerprint": "大人や集団どうしが互いに親しく友好的に付き合うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2603f605-dab9-49f9-b64c-1d4ff3964621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41273, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仲良く", "is_correct": true, "explanation": "付き合う様子を修飾し、親しく交際している意味になる副詞。"}, {"text": "ぺこぺこ", "is_correct": false, "explanation": "空腹を表す語で、付き合う様子とは合わない。"}, {"text": "ぐったり", "is_correct": false, "explanation": "疲れて力が抜けた様子を表す語。友好的な付き合いとは合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す語。付き合うという動作を修飾できない。"}], "explanations": {"仲良く": "付き合う様子を修飾し、親しく交際している意味になる副詞。", "ぺこぺこ": "空腹を表す語で、付き合う様子とは合わない。", "ぐったり": "疲れて力が抜けた様子を表す語。友好的な付き合いとは合わない。", "ぐっすり": "眠りの深さを表す語。付き合うという動作を修飾できない。"}, "sentence_index": 0, "correct_answer": "仲良く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妻は夫の財布から仲良くお金を盗んでいた。", "explanation": "〈仲良く〉は互いに親しく振る舞う意味。盗みとは両立せず、〈こっそり〉と混同している。"}, {"text": "この機械は仲良く壊れた。", "explanation": "〈仲良く〉を機械の壊れ方に当てはめた誤用。この語は人どうしの親しい振る舞いの意味で、〈突然〉の意味とは別。"}, {"text": "彼は部長に仲良く抗議した。", "explanation": "〈仲良く〉は穏やかな関係を表す。抗議は対立の行動なので、〈強く〉と混同した使い方になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41273, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仲良く", "is_correct": true, "explanation": "複数の人が和やかに過ごす様子を表す副詞。お茶を飲む様子に合う。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝く様子を表す語。お茶を飲む様子には合わない。"}, {"text": "ぐるぐる", "is_correct": false, "explanation": "回転する様子を表す語。飲む動作とは合わない。"}, {"text": "ぷかぷか", "is_correct": false, "explanation": "浮かぶ様子を表す語。お茶を飲む様子には使えない。"}], "explanations": {"仲良く": "複数の人が和やかに過ごす様子を表す副詞。お茶を飲む様子に合う。", "きらきら": "光が輝く様子を表す語。お茶を飲む様子には合わない。", "ぐるぐる": "回転する様子を表す語。飲む動作とは合わない。", "ぷかぷか": "浮かぶ様子を表す語。お茶を飲む様子には使えない。"}, "sentence_index": 6, "correct_answer": "仲良く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの店は競争相手なので、客の前で仲良く値下げ競争をした。", "explanation": "〈仲良く〉は争わず親しく振る舞う意味。競争と両立せず、〈激しく〉と混同している。"}, {"text": "取引先は契約を一方的に仲良く打ち切った。", "explanation": "〈仲良く〉は双方が和やかに関わる意味。片方の都合で終わらせる行為とは合わず、〈強引に〉の意味と混同している。"}, {"text": "この企画は仲良くあっけなく失敗に終わった。", "explanation": "〈仲良く〉を企画の結果に当てはめた誤用。この語は人どうしの親しい振る舞いの意味で、〈無事に〉などの結果の様子を表す意味とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41273, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "隣の家の人たちと仲良くを付き合っている。", "corrected_sentence": "隣の家の人たちと仲良く付き合っている。", "error_description": "副詞〈仲良く〉の後に格助詞〈を〉は付けない。「仲良く付き合う」の形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41273, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町内の人と仲良くにするために、毎朝あいさつをしている。", "corrected_sentence": "町内の人と仲良くするために、毎朝あいさつをしている。", "error_description": "〈仲良く〉は〈仲良くする〉の形で使う。間に格助詞〈に〉を挟むと不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1d5d6ad-8d82-48eb-89cd-c36c880bfac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41276, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『ステージがあります』で存在の主語を示す『が』。正解。"}, {"text": "を", "is_correct": false, "explanation": "『ステージをあります』は動作の対象の形になり、存在の文にならない。"}, {"text": "と", "is_correct": false, "explanation": "『ステージとあります』は並列の形で、存在を表す文にならない。"}, {"text": "から", "is_correct": false, "explanation": "『ステージからあります』は起点の形で、存在の文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『ステージがあります』で存在の主語を示す『が』。正解。", "を": "『ステージをあります』は動作の対象の形になり、存在の文にならない。", "と": "『ステージとあります』は並列の形で、存在を表す文にならない。", "から": "『ステージからあります』は起点の形で、存在の文として成り立たない。"}, "error_tags": {"を": "対象", "と": "並列", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
