INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41276, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がえんげいやうたをするためのたかいばしょ。", "primary_collocate": null, "pronunciation": "すてーじ", "ipa": "sɯteːdʑi", "syllable_count": 4, "sentences": [{"text": "ステージの上で、女の子がきれいな声で歌っています。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "ステージの上[うえ]で、女[おんな]の子[こ]がきれいな声[こえ]で歌[うた]っています。", "sentence_source": "generated"}, {"text": "学校の体育館には、大きなステージがあります。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "学校[がっこう]の体育館[たいいくかん]には、大[おお]きなステージがあります。", "sentence_source": "generated"}, {"text": "先生に呼ばれて、私はステージに上がりました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "先生[せんせい]に呼[よ]ばれて、私[わたし]はステージに上[あ]がりました。", "sentence_source": "generated"}, {"text": "ステージが高いので、後ろの席からも見えます。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "ステージが高[たか]いので、後[うし]ろの席[せき]からも見[み]えます。", "sentence_source": "generated"}, {"text": "ステージの上でダンスをするのは、とても楽しいです。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "ステージの上[うえ]でダンスをするのは、とても楽[たの]しいです。", "sentence_source": "generated"}, {"text": "明日の発表会のために、ステージを掃除しました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "明日[あした]の発表会[はっぴょうかい]のために、ステージを掃除[そうじ]しました。", "sentence_source": "generated"}, {"text": "歌手がステージに出てくると、みんなが拍手をしました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "歌手[かしゅ]がステージに出[で]てくると、みんなが拍手[はくしゅ]をしました。", "sentence_source": "generated"}, {"text": "ステージは暗いので、足元に気をつけてください。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "ステージは暗[くら]いので、足元[あしもと]に気[き]をつけてください。", "sentence_source": "generated"}, {"text": "公園の小さなステージで、友だちがギターを弾きました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "公園[こうえん]の小[ちい]さなステージで、友[とも]だちがギターを弾[ひ]きました。", "sentence_source": "generated"}, {"text": "弟はステージで、緊張して声が出ませんでした。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "弟[おとうと]はステージで、緊張[きんちょう]して声[こえ]が出[で]ませんでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ステージ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "歌や演技をするための高い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41276, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ステージ", "is_correct": true, "explanation": "歌や演技をする高い場所。『ステージの上で歌う』は自然に通じる。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本。歌う場所にはならず、『教科書の上で歌う』は成り立たない。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面。人が歌う場所としては不自然で、『天井の上で歌う』は意味が通らない。"}, {"text": "引き出し", "is_correct": false, "explanation": "家具の収納部分。歌う場所にはならず、『引き出しの上で歌う』は不自然。"}], "explanations": {"ステージ": "歌や演技をする高い場所。『ステージの上で歌う』は自然に通じる。", "教科書": "授業で使う本。歌う場所にはならず、『教科書の上で歌う』は成り立たない。", "天井": "部屋の上の面。人が歌う場所としては不自然で、『天井の上で歌う』は意味が通らない。", "引き出し": "家具の収納部分。歌う場所にはならず、『引き出しの上で歌う』は不自然。"}, "sentence_index": 0, "correct_answer": "ステージ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "棚の物を取ろうと、ステージに乗った。", "explanation": "ここは〈踏み台〉の意味と混同している。ステージは歌や演技の場で、棚の物を取るための台ではないので、この使い方はしない。"}, {"text": "寝不足の夜、ステージに横になって眠った。", "explanation": "ここは〈ベッド〉の意味と混同している。ステージは歌や演技の場で、横になって眠る道具ではない。"}, {"text": "試合が始まり、選手がステージでゴールを決めた。", "explanation": "ここは〈競技場〉の意味で、スタジアムと混同している。ステージは歌や演技の場なので、試合の場には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41276, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ステージ", "is_correct": true, "explanation": "歌手が上がって出てくる高い場所。『歌手がステージに出てくる』は自然な文になる。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を保存する家電。歌手が出てくる場所にはならず、文が成り立たない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "襖の奥の収納。歌手が出てくる場としては不自然で、意味が通らない。"}, {"text": "郵便受け", "is_correct": false, "explanation": "郵便物を入れる箱。人が出てくる場所ではなく、『郵便受けに出てくる』は成り立たない。"}], "explanations": {"ステージ": "歌手が上がって出てくる高い場所。『歌手がステージに出てくる』は自然な文になる。", "冷蔵庫": "食品を保存する家電。歌手が出てくる場所にはならず、文が成り立たない。", "押し入れ": "襖の奥の収納。歌手が出てくる場としては不自然で、意味が通らない。", "郵便受け": "郵便物を入れる箱。人が出てくる場所ではなく、『郵便受けに出てくる』は成り立たない。"}, "sentence_index": 6, "correct_answer": "ステージ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前のステージで、切符を買って改札を通った。", "explanation": "ここは〈駅〉の意味と混同している。ステージは公演用の台で、切符を買う場所や改札にはならない。"}, {"text": "寝る前に、ステージでパジャマに着替えた。", "explanation": "ここは〈寝室〉の意味と混同している。ステージは歌や演技の場で、着替える場所としては使わない。"}, {"text": "朝ごはんの後、ステージで皿を洗った。", "explanation": "ここは〈台所〉の意味と混同している。ステージは公演用の台で、皿を洗う場所としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41276, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ステージの低いので、前の席からは見えにくいです。", "corrected_sentence": "ステージが低いので、前の席からは見えにくいです。", "error_description": "『ステージが低い』と述語を立てるので主語には〈が〉。〈の〉は名詞を修飾する形になり、ここでは文が続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41276, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ステージを立つのは、とても緊張する。", "corrected_sentence": "ステージに立つのは、とても緊張する。", "error_description": "『立つ』（立ち位置）は〈に〉を取る。〈を〉は動作の対象につくので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41277, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『ステージの真ん中』で、ステージと真ん中の位置関係をつなぐ『の』。正解。"}, {"text": "に", "is_correct": false, "explanation": "『ステージに真ん中で』では位置の関係がつながらず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は動作の場所につく。ここでは名詞同士をつなぐ位置が必要で、合わない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は動作の対象につく。『ステージを真ん中で』では対象の文にならず不自然。"}], "correct_answer": "の", "explanations": {"の": "『ステージの真ん中』で、ステージと真ん中の位置関係をつなぐ『の』。正解。", "に": "『ステージに真ん中で』では位置の関係がつながらず、文が成り立たない。", "で": "『で』は動作の場所につく。ここでは名詞同士をつなぐ位置が必要で、合わない。", "を": "『を』は動作の対象につく。『ステージを真ん中で』では対象の文にならず不自然。"}, "error_tags": {"に": "到着・相手", "で": "動作の場所", "を": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41277, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『ステージの横』で、ステージの位置を示す『の』。正解。"}, {"text": "が", "is_correct": false, "explanation": "『ステージが横から』では主語として続かず、後ろの文ともつながらない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示す。『ステージと横から』では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。『ステージへ横から』は位置の文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『ステージの横』で、ステージの位置を示す『の』。正解。", "が": "『ステージが横から』では主語として続かず、後ろの文ともつながらない。", "と": "『と』は並列や相手を示す。『ステージと横から』では意味が通らない。", "へ": "『へ』は方向を示す。『ステージへ横から』は位置の文として成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41277, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "演劇や音楽などの公演で、出演者が立ち演技や演奏をするための、観客より高い位置にある台。", "primary_collocate": null, "pronunciation": "すてーじ", "ipa": "sɯteːdʑi", "syllable_count": 4, "sentences": [{"text": "十代の人が初めてステージに立ちます。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "十代[じゅうだい]の人[ひと]が初[はじ]めてステージに立[た]ちます。", "sentence_source": "mined"}, {"text": "歌手がステージの真ん中で、ゆっくりおじぎをしました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "歌手[かしゅ]がステージの真[ま]ん中[なか]で、ゆっくりおじぎをしました。", "sentence_source": "generated"}, {"text": "古いホールのステージは高くて、客席からよく見えます。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "古[ふる]いホールのステージは高[たか]くて、客席[きゃくせき]からよく見[み]えます。", "sentence_source": "generated"}, {"text": "開演の前に、スタッフがステージに椅子を並べました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "開演[かいえん]の前[まえ]に、スタッフがステージに椅子[いす]を並[なら]べました。", "sentence_source": "generated"}, {"text": "子どもたちはステージの上で、緊張しながら歌いました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "子[こ]どもたちはステージの上[うえ]で、緊張[きんちょう]しながら歌[うた]いました。", "sentence_source": "generated"}, {"text": "ステージの照明が消えて、会場は急に暗くなりました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "ステージの照明[しょうめい]が消[き]えて、会場[かいじょう]は急[きゅう]に暗[くら]くなりました。", "sentence_source": "generated"}, {"text": "雨が降ったので、ステージでの演奏は中止になりました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、ステージでの演奏[えんそう]は中止[ちゅうし]になりました。", "sentence_source": "generated"}, {"text": "ステージの横から、友だちが私に手を振ってくれました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "ステージの横[よこ]から、友[とも]だちが私[わたし]に手[て]を振[ふ]ってくれました。", "sentence_source": "generated"}, {"text": "ダンサーたちはステージから降りて、客席の間を歩きました。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "ダンサーたちはステージから降[お]りて、客席[きゃくせき]の間[あいだ]を歩[ある]きました。", "sentence_source": "generated"}, {"text": "大きなステージを作るために、朝から工事をしています。", "target_word": "ステージ", "complexity_tier": "T3", "furigana": "大[おお]きなステージを作[つく]るために、朝[あさ]から工事[こうじ]をしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ステージ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "公演で出演者が立つ、観客より高い台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41277, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ステージ", "is_correct": true, "explanation": "公演で出演者が立つ台。『初めてステージに立つ』は出演する意味で自然に通じる。"}, {"text": "楽屋", "is_correct": false, "explanation": "出演者の控室。『楽屋に立つ』は演技の場所にならず、文として不自然。"}, {"text": "照明", "is_correct": false, "explanation": "光を当てる器具で、人が立つ場所にはならない。『照明に立つ』は成り立たない。"}, {"text": "幕", "is_correct": false, "explanation": "舞台の前に掛ける布。立って演技する場所を表せず、『幕に立つ』は不自然。"}], "explanations": {"ステージ": "公演で出演者が立つ台。『初めてステージに立つ』は出演する意味で自然に通じる。", "楽屋": "出演者の控室。『楽屋に立つ』は演技の場所にならず、文として不自然。", "照明": "光を当てる器具で、人が立つ場所にはならない。『照明に立つ』は成り立たない。", "幕": "舞台の前に掛ける布。立って演技する場所を表せず、『幕に立つ』は不自然。"}, "sentence_index": 0, "correct_answer": "ステージ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、ステージに乗って体重を量った。", "explanation": "ここは〈体重計〉の意味と混同している。ステージは公演用の台で、体重を量る道具にはならない。"}, {"text": "駅のステージで、電車を待った。", "explanation": "ここは〈駅のホーム〉の意味と混同している。ステージは公演用の台で、電車を待つ場所にはならない。"}, {"text": "試合が始まり、選手がステージでゴールを決めた。", "explanation": "ここは〈競技場〉の意味で、スタジアムと混同している。ステージは公演の台なので、試合の場には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41277, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ステージ", "is_correct": true, "explanation": "演奏の場になる舞台。『ステージでの演奏は中止』は自然な文になる。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる入れ物。演奏の場所にはならず、『財布での演奏』は意味を成さない。"}, {"text": "手帳", "is_correct": false, "explanation": "メモ帳。演奏の場所にはならず、『手帳での演奏』は意味を成さない。"}, {"text": "字幕", "is_correct": false, "explanation": "映像に出す文字。演奏の場所にはならず、文が成り立たない。"}], "explanations": {"ステージ": "演奏の場になる舞台。『ステージでの演奏は中止』は自然な文になる。", "財布": "お金を入れる入れ物。演奏の場所にはならず、『財布での演奏』は意味を成さない。", "手帳": "メモ帳。演奏の場所にはならず、『手帳での演奏』は意味を成さない。", "字幕": "映像に出す文字。演奏の場所にはならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ステージ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "銀行のステージで、通帳を出して預金を下ろした。", "explanation": "ここは〈窓口〉の意味と混同している。ステージは公演用の台で、預金を下ろす手続きの場所にはならない。"}, {"text": "寝不足のまま、ステージで朝ごはんを食べた。", "explanation": "ここは〈食堂〉の意味と混同している。ステージは食事をする場所ではないので、この使い方はしない。"}, {"text": "雨が降り始めたので、ステージに洗濯物を干した。", "explanation": "ここは〈物干し場〉の意味と混同している。ステージは公演用の台で、洗濯物を干す場所としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41277, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは、ステージを立つと緊張します。", "corrected_sentence": "子どもたちは、ステージに立つと緊張します。", "error_description": "『立つ』（立ち位置）は〈に〉を取る。〈を〉は動作の対象につくので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41277, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司会者がステージで出てくると、会場が静かになった。", "corrected_sentence": "司会者がステージに出てくると、会場が静かになった。", "error_description": "『出てくる』は到着点を表し〈に〉を取る。〈で〉は動作の場所を表すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41279, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『詩を書いている』の対象を示す『を』。正解。"}, {"text": "に", "is_correct": false, "explanation": "『詩に書いている』では書く対象の形にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『詩へ書いている』は方向の形で、書く対象として不自然。"}, {"text": "より", "is_correct": false, "explanation": "『詩より書いている』は比較の『より』で、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『詩を書いている』の対象を示す『を』。正解。", "に": "『詩に書いている』では書く対象の形にならず、不自然。", "へ": "『詩へ書いている』は方向の形で、書く対象として不自然。", "より": "『詩より書いている』は比較の『より』で、文が成り立たない。"}, "error_tags": {"に": "方向・相手", "で": "場所・手段", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41279, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『詩をノートに写して』の対象を示す『を』。正解。"}, {"text": "が", "is_correct": false, "explanation": "『詩がノートに写して』では主語になり、写す対象の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『詩へノートに写して』は方向の形になり、写す対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "『詩とノートに写して』は並列の形になり、写す対象が二つになって文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "『詩をノートに写して』の対象を示す『を』。正解。", "が": "『詩がノートに写して』では主語になり、写す対象の関係が成り立たない。", "へ": "『詩へノートに写して』は方向の形になり、写す対象として不自然。", "と": "『詩とノートに写して』は並列の形になり、写す対象が二つになって文が崩れる。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41279, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "感情や情景を表現するために、言葉をリズムよく並べた文芸作品", "primary_collocate": null, "pronunciation": "し", "ipa": "ɕi", "syllable_count": 1, "sentences": [{"text": "マイクを持って詩を読みます。", "target_word": "詩", "complexity_tier": "T3", "furigana": "マイクを持[も]って詩[し]を読[よ]みます。", "sentence_source": "mined"}, {"text": "彼女は毎晩、日記のノートに短い詩を書いている。", "target_word": "詩", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は毎晩[まいばん]、日記[にっき]のノートに短[みじか]い詩[し]を書[か]いている。", "sentence_source": "generated"}, {"text": "この詩は春の朝の静けさを美しく描いている。", "target_word": "詩", "complexity_tier": "T3", "furigana": "この詩[し]は春[はる]の朝[あさ]の静[しず]けさを美[うつく]しく描[えが]いている。", "sentence_source": "generated"}, {"text": "国語の授業で、宮沢賢治の詩を暗記した。", "target_word": "詩", "complexity_tier": "T3", "furigana": "国語[こくご]の授業[じゅぎょう]で、宮沢賢治[みやざわけんじ]の詩[し]を暗記[あんき]した。", "sentence_source": "generated"}, {"text": "詩は短いので、小説より早く読み終わった。", "target_word": "詩", "complexity_tier": "T3", "furigana": "詩[し]は短[みじか]いので、小説[しょうせつ]より早[はや]く読[よ]み終[お]わった。", "sentence_source": "generated"}, {"text": "卒業式で、友達が自分で作った詩を朗読した。", "target_word": "詩", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]で、友達[ともだち]が自分[じぶん]で作[つく]った詩[し]を朗読[ろうどく]した。", "sentence_source": "generated"}, {"text": "その詩には、故郷を離れた人の寂しさが込められている。", "target_word": "詩", "complexity_tier": "T3", "furigana": "その詩[し]には、故郷[こきょう]を離[はな]れた人[ひと]の寂[さび]しさが込[こ]められている。", "sentence_source": "generated"}, {"text": "好きな詩をノートに写して、毎朝読み返している。", "target_word": "詩", "complexity_tier": "T3", "furigana": "好[す]きな詩[し]をノートに写[うつ]して、毎朝[まいあさ]読[よ]み返[かえ]している。", "sentence_source": "generated"}, {"text": "兄は詩を作るのが得意で、コンテストで賞をもらった。", "target_word": "詩", "complexity_tier": "T3", "furigana": "兄[あに]は詩[し]を作[つく]るのが得意[とくい]で、コンテストで賞[しょう]をもらった。", "sentence_source": "generated"}, {"text": "この詩を声に出して読むと、言葉のリズムがよく分かる。", "target_word": "詩", "complexity_tier": "T3", "furigana": "この詩[し]を声[こえ]に出[だ]して読[よ]むと、言葉[ことば]のリズムがよく分[わ]かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "詩", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "言葉をリズムよく並べて感情や情景を表す文芸作品(ポエム)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e92d26c-8372-4048-8f6a-0ae56306fb40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41279, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "詩", "is_correct": true, "explanation": "読み上げる文芸作品。『マイクを持って詩を読む』は自然に通じる。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部。読むものではなく、『窓を読みます』は成り立たない。"}, {"text": "鍵", "is_correct": false, "explanation": "錠を開ける道具。読むものではなく、『鍵を読みます』は意味を成さない。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる袋。読む対象にはならず、『財布を読みます』は不自然。"}], "explanations": {"詩": "読み上げる文芸作品。『マイクを持って詩を読む』は自然に通じる。", "窓": "建物の開口部。読むものではなく、『窓を読みます』は成り立たない。", "鍵": "錠を開ける道具。読むものではなく、『鍵を読みます』は意味を成さない。", "財布": "お金を入れる袋。読む対象にはならず、『財布を読みます』は不自然。"}, "sentence_index": 0, "correct_answer": "詩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は詩の役所で働いている。", "explanation": "ここは同音語の〈市〉の意味。詩は作品なので、役所に勤めるという意味にはならない。"}, {"text": "祖父は去年、詩を迎えた。", "explanation": "ここは同音語の〈死〉（死を迎える）の意味。詩は作品で、迎えるものではない。"}, {"text": "詩を切って、絆創膏を貼った。", "explanation": "ここは〈指〉の意味として使っている。詩は作品で体の部分ではないので、切って絆創膏を貼る話にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41279, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "詩", "is_correct": true, "explanation": "感情を込めて表す文芸作品。『その詩には寂しさが込められている』で自然に通じる。"}, {"text": "信号", "is_correct": false, "explanation": "交通の合図。感情を込められるものではなく、不自然。"}, {"text": "電柱", "is_correct": false, "explanation": "電線を支える柱。寂しさを込めるものではなく、文が成り立たない。"}, {"text": "郵便局", "is_correct": false, "explanation": "郵便を扱う施設。感情が込められるものではなく、意味が通らない。"}], "explanations": {"詩": "感情を込めて表す文芸作品。『その詩には寂しさが込められている』で自然に通じる。", "信号": "交通の合図。感情を込められるものではなく、不自然。", "電柱": "電線を支える柱。寂しさを込めるものではなく、文が成り立たない。", "郵便局": "郵便を扱う施設。感情が込められるものではなく、意味が通らない。"}, "sentence_index": 6, "correct_answer": "詩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行先で詩を撮って、友だちに送った。", "explanation": "ここは〈写真〉の意味と混同している。詩は撮るものではなく、撮影の動作とは結びつかない。"}, {"text": "友だちと詩を食べながら話した。", "explanation": "ここは〈お菓子〉の意味と混同している。詩は食べるものではないので、この使い方はしない。"}, {"text": "ドアの鍵を回すかわりに、詩を回して開けた。", "explanation": "ここは〈鍵〉の意味と混同している。詩は回す道具ではないので、ドアを開ける手順には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41279, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は詩で心を込めて、家族に読んで聞かせた。", "corrected_sentence": "彼は詩に心を込めて、家族に読んで聞かせた。", "error_description": "『心を込める』の対象は〈に〉。〈で〉は場所や手段を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41279, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "詩の作るには、まず身近な言葉を選ぶとよい。", "corrected_sentence": "詩を作るには、まず身近な言葉を選ぶとよい。", "error_description": "『作る』の対象は〈を〉。〈の〉は名詞を修飾する形になり、ここでは文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f67e28d-6154-441f-af27-c9c8844196a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41282, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「スポークンで分かりやすく話す」で、話し方の様式を表す。スポークンに直接続く。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すので、話し方の様式を示す文脈には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すので、話し方の様式を表す文脈には合わない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すが、ここでは「スポークンが〜話す」と主語にするには文脈が合わない。"}], "correct_answer": "で", "explanations": {"で": "「スポークンで分かりやすく話す」で、話し方の様式を表す。スポークンに直接続く。", "へ": "〈へ〉は方向を表すので、話し方の様式を示す文脈には合わない。", "に": "「に」は相手や方向を示すので、話し方の様式を表す文脈には合わない。", "が": "〈が〉は主語を示すが、ここでは「スポークンが〜話す」と主語にするには文脈が合わない。"}, "error_tags": {"へ": "方向", "が": "主語", "に": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41282, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「スポークンで伝える」で、伝える手段・様式を表す。スポークンに直接続く。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は対象を表すが、「スポークンを伝える」では話し方が伝えられる対象になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は相手や方向を表すので、話し方の手段を示す文脈には合わない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表すが、「スポークンから伝える」では手段の意味にならず合わない。"}], "correct_answer": "で", "explanations": {"で": "「スポークンで伝える」で、伝える手段・様式を表す。スポークンに直接続く。", "を": "〈を〉は対象を表すが、「スポークンを伝える」では話し方が伝えられる対象になり不自然。", "に": "〈に〉は相手や方向を表すので、話し方の手段を示す文脈には合わない。", "から": "〈から〉は起点を表すが、「スポークンから伝える」では手段の意味にならず合わない。"}, "error_tags": {"を": "対象", "に": "相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41282, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ことばをはなすときに、ふつうの会話のように話すこと。", "primary_collocate": null, "pronunciation": "すぽーくん", "ipa": "supoːkɯɴ", "syllable_count": 3, "sentences": [{"text": "発表のときも、原稿を読まずにスポークンで話すと、聞きやすくなります。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "発表[はっぴょう]のときも、原稿[げんこう]を読[よ]まずにスポークンで話[はな]すと、聞[き]きやすくなります。", "sentence_source": "generated"}, {"text": "先生はむずかしい説明を、スポークンで分かりやすく話してくれました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "先生[せんせい]はむずかしい説明[せつめい]を、スポークンで分[わ]かりやすく話[はな]してくれました。", "sentence_source": "generated"}, {"text": "ニュースでは、アナウンサーが原稿を読まず、スポークンのように話す番組が増えています。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "ニュースでは、アナウンサーが原稿[げんこう]を読[よ]まず、スポークンのように話[はな]す番組[ばんぐみ]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "堅い文章を、スポークンで言い換えてから音読しました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "堅[かた]い文章[ぶんしょう]を、スポークンで言[い]い換[か]えてから音読[おんどく]しました。", "sentence_source": "generated"}, {"text": "スポークンを意識すると、文の終わりが短くなります。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンを意識[いしき]すると、文[ぶん]の終[お]わりが短[みじか]くなります。", "sentence_source": "generated"}, {"text": "社内会議では、堅い言葉より、スポークンのほうが意見を言いやすいです。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "社内会議[しゃないかいぎ]では、堅[かた]い言葉[ことば]より、スポークンのほうが意見[いけん]を言[い]いやすいです。", "sentence_source": "generated"}, {"text": "彼女は店のお客さんに、スポークンで気軽に話しかけます。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は店[みせ]のお客[きゃく]さんに、スポークンで気軽[きがる]に話[はな]しかけます。", "sentence_source": "generated"}, {"text": "緊張していたので、スポークンで気軽に話すことができませんでした。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "緊張[きんちょう]していたので、スポークンで気軽[きがる]に話[はな]すことができませんでした。", "sentence_source": "generated"}, {"text": "講演会の司会者は、スポークンで会場をなごませました。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "講演会[こうえんかい]の司会者[しかいしゃ]は、スポークンで会場[かいじょう]をなごませました。", "sentence_source": "generated"}, {"text": "子どもに話すときは、むずかしい言葉を避けて、スポークンで伝えます。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "子[こ]どもに話[はな]すときは、むずかしい言葉[ことば]を避[さ]けて、スポークンで伝[つた]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スポークン", "label": "基本形"}], "register": "polite", "sense_fingerprint": "原稿を読まず、ふつうの会話のように話すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: なごま (Zipf 1.61)']::text[], 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41282, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "原稿を読まずに「スポークンで話す」と続くので、ふつうの会話のように話す意味でこの語が入る。"}, {"text": "作文", "is_correct": false, "explanation": "文章を書くことを指し、「作文で話す」とは言わないので合わない。"}, {"text": "句読点", "is_correct": false, "explanation": "文字を区切る記号で、話す手段にはならないので合わない。"}, {"text": "数式", "is_correct": false, "explanation": "式や記号を指し、話し方の手段としては合わない。"}], "explanations": {"スポークン": "原稿を読まずに「スポークンで話す」と続くので、ふつうの会話のように話す意味でこの語が入る。", "作文": "文章を書くことを指し、「作文で話す」とは言わないので合わない。", "句読点": "文字を区切る記号で、話す手段にはならないので合わない。", "数式": "式や記号を指し、話し方の手段としては合わない。"}, "sentence_index": 0, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は分からない箇所を、先生にもう一度スポークンで求めました。", "explanation": "ここは〈質問〉の意味。分からない点は質問として尋ねるもので、話し方を表すスポークンを求める対象にはならないので合わない。"}, {"text": "会議の決定はスポークンで伝えられ、文書にはなりませんでした。", "explanation": "ここは〈口頭〉の意味。『口頭で伝える』は伝達の方法を表すが、スポークンは話し方を指す語で伝達の方法にはならないので合わない。"}, {"text": "英語のスポークンテストは、来月行われます。", "explanation": "ここは〈スピーキング〉の意味。試験の名称はスピーキングテストと言い、スポークンはこの名称には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41282, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "お客さんに「スポークンで気軽に話しかける」と続き、ふつうの会話のように話す意味でこの語が入る。"}, {"text": "電報", "is_correct": false, "explanation": "通信文の一種で、「電報で話しかける」とは言わないので合わない。"}, {"text": "暗号", "is_correct": false, "explanation": "秘密の符号を指し、話しかける手段としては合わない。"}, {"text": "公文書", "is_correct": false, "explanation": "役所などが出す書類で、話しかける手段にはならないので合わない。"}], "explanations": {"スポークン": "お客さんに「スポークンで気軽に話しかける」と続き、ふつうの会話のように話す意味でこの語が入る。", "電報": "通信文の一種で、「電報で話しかける」とは言わないので合わない。", "暗号": "秘密の符号を指し、話しかける手段としては合わない。", "公文書": "役所などが出す書類で、話しかける手段にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この古文はスポークンで書かれています。", "explanation": "ここは〈文語〉の意味。古文の書き方を表す語で、話し方を表すスポークンでは文体を示せないので合わない。"}, {"text": "スポークンで呼びかけると、遠くまで届きます。", "explanation": "ここは〈大声〉の意味。音量を表す語で、話し方の仕方を指すスポークンは音量を表せないので合わない。"}, {"text": "彼女はスポークンを込めて、気持ちを伝えました。", "explanation": "ここは〈感情〉の意味。気持ちを込めるのは感情で、話し方を表すスポークンは込める対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
