INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41282, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族との夕食では、スポークンが話すと、会話が弾みます。", "corrected_sentence": "家族との夕食では、スポークンで話すと、会話が弾みます。", "error_description": "誤: スポークンが話す。正: スポークンで話す。話し方を表すには〈で〉が必要で、〈が〉では話し言葉が話す主体になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41283, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「スポークンでは」で、話し言葉という範囲・場面を表す。スポークンに直接続く。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は動作の対象を表すので、「スポークンを〜は」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すが、話し言葉は方向になり得ないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「スポークンから」は話し方の様式を表せず不自然。"}], "correct_answer": "で", "explanations": {"で": "「スポークンでは」で、話し言葉という範囲・場面を表す。スポークンに直接続く。", "を": "〈を〉は動作の対象を表すので、「スポークンを〜は」では文が成り立たない。", "へ": "〈へ〉は方向を表すが、話し言葉は方向になり得ないので合わない。", "から": "「から」は起点を表すので、「スポークンから」は話し方の様式を表せず不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "書き言葉", "is_correct": true, "explanation": "話し言葉の対義語。文字で書かれた言葉の種類で、辞書でも対になる語として挙げられる。"}, {"text": "会話", "is_correct": false, "explanation": "話し言葉が使われる場面の一つで、対義語ではない。"}, {"text": "朗読", "is_correct": false, "explanation": "声に出して読む行為で、話し言葉とは対になっていない。"}, {"text": "演説", "is_correct": false, "explanation": "人前で話す行為を指し、話し言葉と対をなす語ではない。"}], "correct_answer": "書き言葉", "explanations": {"書き言葉": "話し言葉の対義語。文字で書かれた言葉の種類で、辞書でも対になる語として挙げられる。", "会話": "話し言葉が使われる場面の一つで、対義語ではない。", "朗読": "声に出して読む行為で、話し言葉とは対になっていない。", "演説": "人前で話す行為を指し、話し言葉と対をなす語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41283, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「スポークンでは」で、話し言葉という範囲・場面を表す。スポークンに直接続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すので、「スポークンを、〜」は主題として成り立たず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「スポークンへ、〜」は話し言葉を主題とする文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は所属や修飾を表すが、ここでは直後の助詞と続かず文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「スポークンでは」で、話し言葉という範囲・場面を表す。スポークンに直接続く。", "を": "「を」は対象を示すので、「スポークンを、〜」は主題として成り立たず不自然。", "へ": "「へ」は方向を示すので、「スポークンへ、〜」は話し言葉を主題とする文として不自然。", "の": "〈の〉は所属や修飾を表すが、ここでは直後の助詞と続かず文が成り立たない。"}, "error_tags": {"の": "所属", "を": "対象", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "書き言葉", "is_correct": true, "explanation": "話し言葉の対義語。文字で書かれた言葉の種類で、辞書でも対になる語として挙げられる。"}, {"text": "手紙", "is_correct": false, "explanation": "文章を送る手段で、言葉の種類ではないので対義語ではない。"}, {"text": "対話", "is_correct": false, "explanation": "二人以上が話し合う形式で、話し言葉と対になるものではない。"}, {"text": "独白", "is_correct": false, "explanation": "一人で話す形式で、話し言葉と対になる語ではない。"}], "correct_answer": "書き言葉", "explanations": {"書き言葉": "話し言葉の対義語。文字で書かれた言葉の種類で、辞書でも対になる語として挙げられる。", "手紙": "文章を送る手段で、言葉の種類ではないので対義語ではない。", "対話": "二人以上が話し合う形式で、話し言葉と対になるものではない。", "独白": "一人で話す形式で、話し言葉と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41283, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "話し言葉。日常会話で使われる、くだけた言い方。", "primary_collocate": null, "pronunciation": "すぽーくん", "ipa": "supoːkɯɴ", "syllable_count": 3, "sentences": [{"text": "友だちとの会話は、スポークンで十分です。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "友[とも]だちとの会話[かいわ]は、スポークンで十分[じゅうぶん]です。", "sentence_source": "generated"}, {"text": "スポークンでは、「しなければ」を「しなきゃ」と言うことが多いです。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンでは、「しなければ」を「しなきゃ」と言[い]うことが多[おお]いです。", "sentence_source": "generated"}, {"text": "手紙は丁寧に書きますが、スポークンはもっとくだけた言い方になります。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "手紙[てがみ]は丁寧[ていねい]に書[か]きますが、スポークンはもっとくだけた言[い]い方[かた]になります。", "sentence_source": "generated"}, {"text": "スポークンと書き言葉は違うので、レポートに「やっぱ」と書いてはいけません。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンと書[か]き言葉[ことば]は違[ちが]うので、レポートに「やっぱ」と書[か]いてはいけません。", "sentence_source": "generated"}, {"text": "この教科書は、スポークンでよく使う短い言い方を紹介しています。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "この教科書[きょうかしょ]は、スポークンでよく使[つか]う短[みじか]い言[い]い方[かた]を紹介[しょうかい]しています。", "sentence_source": "generated"}, {"text": "先生は授業で、スポークンと書き言葉の違いを何度も説明します。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]で、スポークンと書[か]き言葉[ことば]の違[ちが]いを何度[なんど]も説明[せつめい]します。", "sentence_source": "generated"}, {"text": "ドラマのせりふはスポークンに近いので、会話の勉強に役立ちます。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "ドラマのせりふはスポークンに近[ちか]いので、会話[かいわ]の勉強[べんきょう]に役立[やくだ]ちます。", "sentence_source": "generated"}, {"text": "スポークンでは「ら抜き言葉」がよく聞かれますが、試験の作文では使いません。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "スポークンでは「ら抜[ぬ]き言葉[ことば]」がよく聞[き]かれますが、試験[しけん]の作文[さくぶん]では使[つか]いません。", "sentence_source": "generated"}, {"text": "留学生は、教室で習う文よりスポークンのほうが速くて聞き取りにくいと言います。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]は、教室[きょうしつ]で習[なら]う文[ぶん]よりスポークンのほうが速[はや]くて聞[き]き取[と]りにくいと言[い]います。", "sentence_source": "generated"}, {"text": "友だちにはスポークンで話せますが、社長の前では敬語を使います。", "target_word": "スポークン", "complexity_tier": "T3", "furigana": "友[とも]だちにはスポークンで話[はな]せますが、社長[しゃちょう]の前[まえ]では敬語[けいご]を使[つか]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スポークン", "label": "基本形"}], "register": "polite", "sense_fingerprint": "書き言葉に対する、日常会話のくだけた話し言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41283, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "「スポークンワード」は、詩を声に出して演じる芸術を指す語の一部で、空所にはこの語が入る。"}, {"text": "スピーチ", "is_correct": false, "explanation": "「スピーチワード」という語はなく、演説の意味の語はワードと続かないので合わない。"}, {"text": "ナレーション", "is_correct": false, "explanation": "映像や朗読に添える語りの声を指す語で、「ナレーションワード」とは言わないので合わない。"}, {"text": "ライブ", "is_correct": false, "explanation": "生の演奏や公演を指す語で、「ライブワード」という言い方はなく、ここには合わない。"}], "explanations": {"スポークン": "「スポークンワード」は、詩を声に出して演じる芸術を指す語の一部で、空所にはこの語が入る。", "スピーチ": "「スピーチワード」という語はなく、演説の意味の語はワードと続かないので合わない。", "ナレーション": "映像や朗読に添える語りの声を指す語で、「ナレーションワード」とは言わないので合わない。", "ライブ": "生の演奏や公演を指す語で、「ライブワード」という言い方はなく、ここには合わない。"}, "sentence_index": 0, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先週の会議は、長いスポークンになりました。", "explanation": "ここは〈会話〉の意味。会話の出来事は会話と言い、話し言葉を指すスポークンは出来事の名称にはならないので合わない。"}, {"text": "会議の内容はスポークンで確認し、後でメールに残しました。", "explanation": "ここは〈口頭〉の意味。確認の方法は『口頭で』と言い、話し言葉を指すスポークンは方法を表せないので合わない。"}, {"text": "英語の授業では、毎回スポークンの試験があります。", "explanation": "ここは〈スピーキング〉の意味。試験の名称はスピーキングテストと言い、話し言葉を指すスポークンはこの名称には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41283, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スポークン", "is_correct": true, "explanation": "ドラマのせりふは話し言葉に近い、という意味になるので、空所にはこの語が入る。"}, {"text": "口笛", "is_correct": false, "explanation": "口で鳴らす音を指し、せりふの性質に近いとは言えないので合わない。"}, {"text": "余韻", "is_correct": false, "explanation": "音が消えたあとに残る響きを指し、せりふに近いとは言わないので合わない。"}, {"text": "静寂", "is_correct": false, "explanation": "物音がしない状態を指し、せりふの性質とは結びつかないので合わない。"}], "explanations": {"スポークン": "ドラマのせりふは話し言葉に近い、という意味になるので、空所にはこの語が入る。", "口笛": "口で鳴らす音を指し、せりふの性質に近いとは言えないので合わない。", "余韻": "音が消えたあとに残る響きを指し、せりふに近いとは言わないので合わない。", "静寂": "物音がしない状態を指し、せりふの性質とは結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "スポークン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女のスポークンは、遠くの山までよく響きました。", "explanation": "ここは〈声〉の意味。響くのは声で、言葉の種類を指すスポークンは音として響くものではないので合わない。"}, {"text": "スポークンは映像の内容を声で説明します。", "explanation": "ここは〈ナレーション〉の意味。映像を説明する語り手は人や役割で、話し言葉はそれを担えないので合わない。"}, {"text": "スポークンを変えると、印象が大きく変わります。", "explanation": "ここは〈話し方〉の意味。話し方は変えられるが、話し言葉は言葉の種類の名称で、変える対象としては使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41283, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちとの会話では、スポークンに話すのが自然です。", "corrected_sentence": "友だちとの会話では、スポークンで話すのが自然です。", "error_description": "誤: スポークンに話す。正: スポークンで話す。話す手段・様式を表すには〈で〉が必要で、〈に〉は方向を表すので不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41283, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生のあいだでは、スポークンが冗談を言うことが多いです。", "corrected_sentence": "学生のあいだでは、スポークンで冗談を言うことが多いです。", "error_description": "誤: スポークンが。正: スポークンで。冗談を言う手段を表すには〈で〉が必要で、〈が〉では話し言葉が言う主体になり意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41285, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。存在を表す「ある」の主語を示すので、「ワードが三つあります」になる。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は存在するものに「が」を使うため、「ワードを三つあります」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所などを示すので、存在するものを示す語には付かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、ここでは存在の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "正解。存在を表す「ある」の主語を示すので、「ワードが三つあります」になる。", "を": "「ある」は存在するものに「が」を使うため、「ワードを三つあります」は成り立たない。", "に": "「に」は場所などを示すので、存在するものを示す語には付かない。", "で": "「で」は場所や手段を表し、ここでは存在の主語にならない。"}, "error_tags": {"を": "目的語の誤用", "に": "場所の誤用", "で": "場所・手段の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41285, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。当てる対象を示す「を」で、「正しいワードを当てる」になる。"}, {"text": "に", "is_correct": false, "explanation": "「当てる」の対象には「を」を使うので、「に」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、当てる対象には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を示し、当てる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "正解。当てる対象を示す「を」で、「正しいワードを当てる」になる。", "に": "「当てる」の対象には「を」を使うので、「に」は合わない。", "が": "「が」は主語を示すので、当てる対象には使えない。", "と": "「と」は共同や引用を示し、当てる対象を表せない。"}, "error_tags": {"に": "目的語の誤用", "が": "主語の誤用", "と": "共同・引用の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41285, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "言語の単位の一つで、単語のこと。", "primary_collocate": null, "pronunciation": "わーど", "ipa": "waːdo", "syllable_count": 3, "sentences": [{"text": "辞書には、ワードごとに意味と例文が書かれています。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "辞書[じしょ]には、ワードごとに意味[いみ]と例文[れいぶん]が書[か]かれています。", "sentence_source": "generated"}, {"text": "この文には、知らないワードが三つあります。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "この文[ぶん]には、知[し]らないワードが三[みっ]つあります。", "sentence_source": "generated"}, {"text": "辞書でワードの意味を調べてから、例文を読みました。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "辞書[じしょ]でワードの意味[いみ]を調[しら]べてから、例文[れいぶん]を読[よ]みました。", "sentence_source": "generated"}, {"text": "この英語の文は、五つのワードでできています。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "この英語[えいご]の文[ぶん]は、五[いつ]つのワードでできています。", "sentence_source": "generated"}, {"text": "日本語の文では、ワードとワードの間に空白を入れません。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "日本語[にほんご]の文[ぶん]では、ワードとワードの間[あいだ]に空白[くうはく]を入れません。", "sentence_source": "generated"}, {"text": "覚えたワードの数が増えると、文章が読みやすくなります。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "覚[おぼ]えたワードの数[かず]が増[ふ]えると、文章[ぶんしょう]が読[よ]みやすくなります。", "sentence_source": "generated"}, {"text": "先生は黒板に、新しいワードを一つずつ書きました。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に、新[あたら]しいワードを一[ひと]つずつ書[か]きました。", "sentence_source": "generated"}, {"text": "このクイズは、ヒントから正しいワードを当てるゲームです。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "このクイズは、ヒントから正[ただ]しいワードを当[あ]てるゲームです。", "sentence_source": "generated"}, {"text": "長い文を短くするために、いらないワードを消しました。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "長[なが]い文[ぶん]を短[みじか]くするために、いらないワードを消[け]しました。", "sentence_source": "generated"}, {"text": "同じ意味のワードでも、場面によって使い方が変わります。", "target_word": "ワード", "complexity_tier": "T3", "furigana": "同[おな]じ意味[いみ]のワードでも、場面[ばめん]によって使[つか]い方[かた]が変[か]わります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ワード", "label": "基本形"}], "register": "polite", "sense_fingerprint": "言語の単位の一つとしての単語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41285, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ワード", "is_correct": true, "explanation": "正解。辞書の内容として、ワードごとに意味と例文が書かれているので、ここにはワードが入る。"}, {"text": "ボタン", "is_correct": false, "explanation": "ボタンごとに意味と例文が書かれているとは言えず、辞書の内容として合わない。"}, {"text": "ベンチ", "is_correct": false, "explanation": "ベンチごとに意味と例文が書かれているとは言えず、辞書の内容として合わない。"}, {"text": "カーテン", "is_correct": false, "explanation": "カーテンごとに意味と例文が書かれているとは言えず、辞書の内容として合わない。"}], "explanations": {"ワード": "正解。辞書の内容として、ワードごとに意味と例文が書かれているので、ここにはワードが入る。", "ボタン": "ボタンごとに意味と例文が書かれているとは言えず、辞書の内容として合わない。", "ベンチ": "ベンチごとに意味と例文が書かれているとは言えず、辞書の内容として合わない。", "カーテン": "カーテンごとに意味と例文が書かれているとは言えず、辞書の内容として合わない。"}, "sentence_index": 0, "correct_answer": "ワード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このレポートは、ワードで書いてから印刷しました。", "explanation": "ここは文書作成ソフトの〈ワード〉の意味。言語の最小単位の単語としては、ソフトで文章を書くという文にならない。"}, {"text": "先生は、ていねいなワードで話したので、生徒が安心しました。", "explanation": "ここは〈言葉遣い〉の意味。ワードは一つ一つの単語を指すので、話し方の丁寧さを表す用法としては合わない。"}, {"text": "ドアを開けるには、正しいワードを言ってください。", "explanation": "ここは〈合言葉〉の意味。言語の単位としての単語ではなく、秘密の言葉を指す用法なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41285, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ワード", "is_correct": true, "explanation": "正解。黒板に書く言葉の単位を指すので、ここにはワードが入る。"}, {"text": "ドア", "is_correct": false, "explanation": "ドアは書く対象にならず、「書きました」と合わない。"}, {"text": "ベッド", "is_correct": false, "explanation": "ベッドは書く対象にならず、黒板に書く内容として不自然。"}, {"text": "ゼリー", "is_correct": false, "explanation": "ゼリーは食べ物で、黒板に書く対象にはならない。"}], "explanations": {"ワード": "正解。黒板に書く言葉の単位を指すので、ここにはワードが入る。", "ドア": "ドアは書く対象にならず、「書きました」と合わない。", "ベッド": "ベッドは書く対象にならず、黒板に書く内容として不自然。", "ゼリー": "ゼリーは食べ物で、黒板に書く対象にはならない。"}, "sentence_index": 6, "correct_answer": "ワード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この漢字は、ワードの画数が十画です。", "explanation": "画数は一文字の漢字について数えるもの。〈ワード〉は言語の単位で文字の単位ではないので、画数の話には合わない。"}, {"text": "このワードは、一行ずつ丁寧に書かれています。", "explanation": "ここは〈詩〉の意味。一行ずつ書くのは詩の形式であり、言語の単位としての単語には当てはまらない。"}, {"text": "楽譜には、ワードを一つずつ音符で書きます。", "explanation": "ここは〈音符〉の意味。音符は楽譜の記号で、言語の単位を書き込むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41285, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この段落には、知らないワードを二つあります。", "corrected_sentence": "この段落には、知らないワードが二つあります。", "error_description": "「ある」は存在を表す動詞で、存在するものの主語には「が」を使う。ここの「を」が誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41285, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は黒板に、新しいワードへ一つ書きました。", "corrected_sentence": "先生は黒板に、新しいワードを一つ書きました。", "error_description": "書く対象を示すには「を」を使う。「へ」は方向を表すので、ここでは誤り。正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41288, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「読書は」と話題を示す。「読書は〜するのが好き」の主題として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や時を表すもので、「読書に静かな部屋で〜するのが好き」では文の主題にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すもので、主題の位置には入らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すもので、「読書から〜好き」の形では主題として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「読書は」と話題を示す。「読書は〜するのが好き」の主題として正しい。", "に": "「に」は場所や時を表すもので、「読書に静かな部屋で〜するのが好き」では文の主題にならない。", "へ": "「へ」は方向を表すもので、主題の位置には入らない。", "から": "「から」は起点を表すもので、「読書から〜好き」の形では主題として成り立たない。"}, "error_tags": {"に": "場所・時を表す「に」は主題の位置に入らない", "へ": "方向を表す「へ」は主題の位置に入らない", "から": "起点を表す「から」は主題の位置に入らない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41288, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「読書の時間」の「の」で、読書と時間を結びつける。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語を示すもので、「読書を時間」では読書と時間が結びつかない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すもので、「読書より時間に」では意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「読書が時間」では時間と結びつかず文が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「読書の時間」の「の」で、読書と時間を結びつける。正解。", "を": "「を」は動作の目的語を示すもので、「読書を時間」では読書と時間が結びつかない。", "より": "「より」は比較を表すもので、「読書より時間に」では意味が通らない。", "が": "「が」は主語を示すが、「読書が時間」では時間と結びつかず文が崩れる。"}, "error_tags": {"を": "目的語の「を」は「時間」と結びつかない", "より": "比較の「より」は名詞の結びつけには使わない", "が": "主語の「が」は「時間」と結びつかない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41288, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "本を読むことです。", "primary_collocate": null, "pronunciation": "どくしょ", "ipa": "dokɯɕo", "syllable_count": 3, "sentences": [{"text": "私の趣味は読書です。", "target_word": "読書", "complexity_tier": "T3", "furigana": "私[わたし]の趣味[しゅみ]は読書[どくしょ]です。", "sentence_source": "generated"}, {"text": "読書は静かな部屋でするのが好きです。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]は静[しず]かな部屋[へや]でするのが好[す]きです。", "sentence_source": "generated"}, {"text": "夜、寝る前に読書をします。", "target_word": "読書", "complexity_tier": "T3", "furigana": "夜[よる]、寝[ね]る前[まえ]に読書[どくしょ]をします。", "sentence_source": "generated"}, {"text": "弟は読書が好きで、毎日図書館へ行きます。", "target_word": "読書", "complexity_tier": "T3", "furigana": "弟[おとうと]は読書[どくしょ]が好[す]きで、毎日[まいにち]図書館[としょかん]へ行[い]きます。", "sentence_source": "generated"}, {"text": "雨の日は外に出ないで、読書を楽しみました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]に出[で]ないで、読書[どくしょ]を楽[たの]しみました。", "sentence_source": "generated"}, {"text": "読書をすると、新しい言葉をたくさん覚えられます。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]をすると、新[あたら]しい言葉[ことば]をたくさん覚[おぼ]えられます。", "sentence_source": "generated"}, {"text": "父は電車の中で読書をしています。", "target_word": "読書", "complexity_tier": "T3", "furigana": "父[ちち]は電車[でんしゃ]の中[なか]で読書[どくしょ]をしています。", "sentence_source": "generated"}, {"text": "読書の時間に、先生が絵本を読んでくれました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "読書[どくしょ]の時間[じかん]に、先生[せんせい]が絵本[えほん]を読[よ]んでくれました。", "sentence_source": "generated"}, {"text": "忙しくて、最近は読書ができません。", "target_word": "読書", "complexity_tier": "T3", "furigana": "忙[いそが]しくて、最近[さいきん]は読書[どくしょ]ができません。", "sentence_source": "generated"}, {"text": "彼女は読書のおかげで、物知りになりました。", "target_word": "読書", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は読書[どくしょ]のおかげで、物知[ものし]りになりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "読書", "label": "基本形"}, {"form": "読書する", "label": "サ変動詞"}, {"form": "読書した", "label": "過去形"}], "register": "中立（丁寧体）", "sense_fingerprint": "趣味や習慣として本を読むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95344bd9-fdcd-410b-94e3-d1adfb174457') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41288, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "読書", "is_correct": true, "explanation": "「趣味は〜です」の名詞として、趣味の内容を入れる語。正解。"}, {"text": "読んだ", "is_correct": false, "explanation": "動詞の過去形。「趣味は」と「です」の間に過去形の動詞は入らず、文が成り立たない。"}, {"text": "読める", "is_correct": false, "explanation": "可能形の動詞。名詞の位置には置けず、「趣味は読めるです」は不自然。"}, {"text": "読んで", "is_correct": false, "explanation": "動詞のて形。「です」の前に置くと文が途中で切れてしまう。"}], "explanations": {"読書": "「趣味は〜です」の名詞として、趣味の内容を入れる語。正解。", "読んだ": "動詞の過去形。「趣味は」と「です」の間に過去形の動詞は入らず、文が成り立たない。", "読める": "可能形の動詞。名詞の位置には置けず、「趣味は読めるです」は不自然。", "読んで": "動詞のて形。「です」の前に置くと文が途中で切れてしまう。"}, "sentence_index": 0, "correct_answer": "読書"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このアプリは、名刺を読書して連絡先を登録します。", "explanation": "ここは〈読み取り〉の意味。機器で文字を読み取って登録する作業を指し、本を読む読書とは違うので合わない。"}, {"text": "顕微鏡で細胞を読書して、形を記録しました。", "explanation": "ここは〈観察〉の意味。顕微鏡などで対象をよく見て調べることを指し、文字を読む読書とは違うので合わない。"}, {"text": "ドアの鍵を読書して、家に入りました。", "explanation": "ここは〈解錠〉の意味。鍵を開ける動作を指し、本を読む読書とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41288, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "読書", "is_correct": true, "explanation": "「父は電車の中で」の後に「をしています」で続く行為名詞。正解。"}, {"text": "読む", "is_correct": false, "explanation": "動詞の辞書形。「読むをしています」の形は成り立たない。"}, {"text": "読ませ", "is_correct": false, "explanation": "使役形の語幹。「読ませをしています」は文として不自然。"}, {"text": "読まれ", "is_correct": false, "explanation": "受身形の語幹。「をしています」に続かず、文が成り立たない。"}], "explanations": {"読書": "「父は電車の中で」の後に「をしています」で続く行為名詞。正解。", "読む": "動詞の辞書形。「読むをしています」の形は成り立たない。", "読ませ": "使役形の語幹。「読ませをしています」は文として不自然。", "読まれ": "受身形の語幹。「をしています」に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "読書"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美術館で絵画の読書をしました。", "explanation": "ここは〈鑑賞〉の意味。絵画を見て味わう行為を指すので、本を読む読書とは合わない。"}, {"text": "ホームページの読書に時間がかかりました。", "explanation": "ここは〈閲覧〉の意味。ウェブページを見ることを指し、本を読む行為の読書とは違う。"}, {"text": "私は毎月、この雑誌の読書を申し込んでいます。", "explanation": "ここは〈購読〉の意味。定期的に雑誌を買って読む契約を指し、読書という行為そのものは申し込めないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41288, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は家で読書に楽しみます。", "corrected_sentence": "週末は家で読書を楽しみます。", "error_description": "「楽しむ」は目的語に「を」を取る。「読書に楽しむ」は誤りで、正しくは「読書を楽しむ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41288, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "読書をやめるて、寝ました。", "corrected_sentence": "読書をやめて、寝ました。", "error_description": "「やめる」のて形は「やめて」。「やめるて」は活用を誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405b9007-2f6d-4980-b97d-529b26d9b94a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
